import java.io.{BufferedReader, IOException, InputStream, InputStreamReader}
import java.util.StringTokenizer

import scala.collection.mutable
import scala.util.Sorting
import math.{min, max, abs}

object Main {
  def solve(): Unit = {
    val sc = new InputReader(System.in)
    val N = sc.nextInt()
    val K = sc.nextInt()

    val c_x = Array.fill(N)((sc.nextLong(), sc.nextLong()))
    val c_y = c_x.clone()
    Sorting.quickSort(c_x)(Ordering.by((_: (Long, Long))._1)) // xのascでソート
    Sorting.quickSort(c_y)(Ordering.by((_: (Long, Long))._2)) // yのascでソート

    var ans = Long.MaxValue
    (0 to N - K) foreach { i =>
      val x = c_x(i + K - 1)._1 - c_x(i)._1
      val ys = (0 until K) map (j => c_x(i + j)._2)
      val y = ys.max - ys.min
      ans = min(ans, x * y)
    }

    (0 to N - K) foreach { i =>
      val y = c_y(i + K - 1)._2 - c_y(i)._2
      val xs = (0 until K) map (j => c_y(i + j)._1)
      val x = xs.max - xs.min
      ans = min(ans, x * y)
    }

    println(ans)
  }

  def main(args: Array[String]): Unit = {
    solve()
  }

  class InputReader(val stream: InputStream) {
    val reader = new BufferedReader(new InputStreamReader(stream), 32768)
    var tokenizer: StringTokenizer = null

    def next: String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = next.toInt
    def nextLong(): Long = next.toLong
    def nextChar(): Char = next.charAt(0)
  }

}

