object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  type IP = (Int, Int)

  def check(p: IP, ps: IP, pl: IP): Boolean = {
    val (nx, ny) = p
    ps._1 <= nx && nx <= pl._1 && ps._2 <= ny && ny <= pl._2
  }


  val N, K = in.next().toInt
  val pos = new Array[IP](N)
  var xs = new Array[Int](N)
  var ys = new Array[Int](N)

  for(i <- 0 until N) {
    val x, y = in.next().toInt
    pos(i) = (x, y)
    xs(i) = x
    ys(i) = y
  }

  xs = xs.sorted
  ys = ys.sorted


  // imos
  val imos: Array[Array[Int]] = Array.ofDim[Int](N+1, N+1)
  for((nx, ny) <- pos) {
    var xi = -1; var yi = -1

    for(i <- 0 until N) {
      if(xs(i) == nx)
        xi = i
      if(ys(i) == ny)
        yi = i
    }

    imos(yi)(xi) += 1
  }

  for(y <- 0 until N)
    for(x <- 0 until N)
      imos(y)(x+1) += imos(y)(x)
  for(x <- 0 until N)
    for(y <- 0 until N)
      imos(y+1)(x) += imos(y)(x)


  var ans: Long = Long.MaxValue

  def calc(p: IP): Int = {
    val (nx, ny) = p
    if(nx >= 0 && ny >= 0)
      imos(ny)(nx)
    else
      0
  }

  for(ix <- 0 until N; jx <- 0 until N; iy <- 0 until N; jy <- 0 until N) {
    val hoge = imos(jy)(jx) - calc((jx, iy-1)) - calc((ix-1, jy)) + calc((ix-1, iy-1))

    if(hoge >= K)
      ans = Math.min(ans, (xs(jx).toLong-xs(ix))*(ys(jy)-ys(iy)))
  }
  println(ans)
}


