          for(yj <- yi+1 to N-1){
            val lx = x(xi)
            val rx = x(xj)
            val by = y(yi)
            val uy = y(yj)

            var cnt = 0
            val br = new Breaks
            br.breakable{
              for(i <- 0 to N-1){
                if(lx<=x_(i) && x_(i)<=rx && by<=y_(i) && y_(i)<=uy) cnt = cnt + 1
                if(cnt >= K) br.break
              }
            }

            if(cnt >= K){
              ans = ans.min((rx-lx)*(uy-by))
            }
          }
        }
      }
    }
    println(ans)
  }
}

