    REP(i, N) {
        LCIN(X, Y);
        xy.emplace_back(X, Y);
    }
    ll bit = (1 << K) - 1;
    ll ans = LINF;
    for(; bit < (1 << N); bit = next_combination(bit)) {
        vector<V2> sel;
        REP(i, N) {
            if(bit & (1 << i)) {
                sel.emplace_back(xy[i]);
            }
        }
        auto conv = Graham(sel);
        double x1 = LINF, y1 = LINF, x2 = -LINF, y2 = -LINF;
        REP(i, conv.size()) {
            x1 = min(conv[i].x, x1);
            x2 = max(conv[i].x, x2);
            y1 = min(conv[i].y, y1);
            y2 = max(conv[i].y, y2);
        }
        ans = min(ll((x2 - x1) * (y2 - y1)), ans);
    }
    cout << ans << "\n";
}

