    i64 K; RD(K);

    vector<i64> X(N);
    vector<i64> Y(N);
    REP(i, N) {
        RD(X[i]);
        RD(Y[i]);
    }

    i64 ans = INF;
    REP(i, N) REP(j, N) REP(k, N) REP(l, N) {
        i64 x1 = X[i];
        i64 y1 = Y[j];
        i64 x2 = X[k];
        i64 y2 = Y[l];
        if(x1 >= x2) continue;
        if(y1 >= y2) continue;

        i64 cnt = 0;
        REP(m, N) {
            i64 x = X[m];
            i64 y = Y[m];
            if(x1 <= x && x <= x2 && y1 <= y && y <= y2)
                ++cnt;
        }
        if(cnt >= K)
            chmin(ans, (x2-x1)*(y2-y1));
