	}
	for(int i=1;i<xlen;i++){
		for(int j=1;j<ylen;j++){
			dp[i][j]+=dp[i-1][j]+dp[i][j-1]-dp[i-1][j-1];
		}
	}
	for(int L=1;L<xlen;L++){
		for(int R=L;R<xlen;R++){
			for(int i=1;i<xlen;i++)	a[i]=dp[R][i]-dp[L-1][i];
			for(int i=1;i<ylen;i++){
				int pos=lower_bound(a,a+ylen,a[i-1]+k)-a;
				if(pos!=ylen){
					ans=min(((ll)(cntx.find(pos)->second)-(cntx.find(i)->second))*((cnty.find(pos)->second)-(cnty.find(i))->second),ans);
