    for(int j = 1; j <= nn; j++){
      for(int k = 0; k < i; k++){
        for(int l = 0; l < j; l++){
          if(func(i, j, k, l) == K) chmin(ans, func2(i, j, k, l));
        }
      }
    }
  }
  cout << ans << endl;
}

