  std::sort(xy_arr2.begin(), xy_arr2.end(), [](const std::tuple<int,int>& l, const std::tuple<int,int>& r){ return std::get<1>(l)<std::get<1>(r);});

  long long min_rect = std::numeric_limits<long long>::max();
  for(int i1 = 0; i1 < N; i1++){
    long long x1 = std::get<0>(xy_arr1[i1]);
    for(int i2 = i1; i2 < N; i2++){
      long long x2 = std::get<0>(xy_arr1[i2]);
      for(int j1 = 0; j1 < N; j1++){
        long long y1 = std::get<1>(xy_arr2[j1]);
        for(int j2 = j1; j2 < N; j2++){
          long long y2 = std::get<1>(xy_arr2[j2]);
          int inner = 0;
          for(int j3 = j1; j3 <= j2; j3++){
            int x = std::get<0>(xy_arr2[j3]);
            if(x >= x1 && x <= x2) inner++;
          }
          if(inner >= K) min_rect = std::min(min_rect, (x2-x1)*(y2-y1));
        }
      }
    }
  }
  std::cout << min_rect << std::endl;

  return 0;
}

