#define REP(i,n) for(long long i=0; i < (n); ++i)
#define REPR(i,n) for(int i=(n); i >= 0; --i)
#define FOR(i, m, n) for(long long i = (m); i < (n); ++i)

using ll = long long;
#define INF 1e9

int N, K;
vector<int> x, y, use;
ll ans = 2*INF*2*INF+2;

void search(int k, int n){
  int maxx, maxy, minx, miny;
  if(k == 0){
    maxx = maxy = -INF-1;
    minx = miny = INF+1;
    REP(i, N){
      if(use[i] == 1){
        minx = min(minx, x[i]);
        miny = min(miny, y[i]);
        maxx = max(maxx, x[i]);
        maxy = max(maxy, y[i]);
      }
    }
    ll s = (ll)(maxx - minx)*(ll)(maxy-miny);
    ans = min(ans, s);
    return;
  }
  FOR(i, k-1, n){
    use[i] = 1;
    search(k-1, i);
    use[i] = 0;
  }
}

int main(){
  cin >> N >> K;
  x.resize(N), y.resize(N), use.resize(N);
  REP(i, N){
    cin >> x[i] >> y[i];
  }
  search(K, N);
  cout << ans << endl;
  return 0;
}

