bool checkOne(ll x1, ll x2, ll y1, ll y2)
{
	if (x1 > x2) {
		swap(x1, x2);
	}
	if (y1 > y2) {
		swap(y1, y2);
	}

	int incCnt = 0;
	REP(i, N) {
		if ((x1 <= X[i])&&(X[i] <= x2)) {
			if ((y1 <= Y[i])&&(Y[i] <= y2)){
				incCnt++;
			}
		}
	}

	return (K <= incCnt);
}

bool compExec(ull area)
{
	REP(xi, N) {
		REPN(xj, xi + 1, N) {
			REP(yi, N) {
				REPN(yj, yi + 1, N) {
					ull areaOne = abs((X[xi] - X[xj]) * (Y[yi] - Y[yj]));
					if (areaOne <= area) {
						if (checkOne(X[xi], X[xj], Y[yi], Y[yj])) {
							return true;
						}
					}
				}
			}
		}
	}
	return false;
}

