constexpr ll infl = 10000000000000007LL;
constexpr int inf = 1000000007;

int find_point(const vector<pair<ll, ll>> &p, ll x, ll y) {
    for (int i = 0; i < p.size(); ++i) {
        if (p[i].first == x || p[i].second == y)
            return i;
    }
    return -1;
}

ll rectangle(const vector<pair<ll, ll>> &p) {
    ll xmax = -infl, xmin = infl, ymax = -infl, ymin = infl;
    for (int i = 0; i < p.size(); ++i) {
        xmax = max(xmax, p[i].first);
        xmin = min(xmin, p[i].first);
        ymax = max(ymax, p[i].second);
        ymin = min(ymin, p[i].second);
    }
    return (xmax - xmin) * (ymax - ymin);
}

ll exclude_rec(const vector<pair<ll, ll>> &p, int i) {
    vector<pair<ll, ll>> copied(p);
    copied.erase(copied.begin() + i);
    return rectangle(copied);
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<ll> x(n), y(n);
    vector<pair<ll, ll>> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> y[i];
        p[i].first = x[i];
        p[i].second = y[i];
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    for (int i = 0; i < n - k; ++i) {
        vector<int> cand{find_point(p, x.front(), inf), find_point(p, x.back(), inf), find_point(p, inf, y.front()), find_point(p, inf, y.back())};
        int mins = inf, target = -1;
        for (int j = 0; j < cand.size(); ++j) {
            int s = exclude_rec(p, cand[j]);
            if (s < mins)
                mins = s, target = j;
        }

        if (target == 0)
            x.erase(x.begin());
        else if (target == 1)
            x.erase(x.end() - 1);
        else if (target == 2)
            y.erase(y.begin());
        else
            y.erase(y.end() - 1);
        p.erase(p.begin() + cand[target]);
    }

    cout << rectangle(p) << endl;
    return 0;
}

