ll S(set<ll>::iterator l, set<ll>::reverse_iterator r,
	set<ll>::iterator d, set<ll>::reverse_iterator u, ll k) {
	ll count = 0;
	REPC(p, v) {
		ll x = p.first;
		ll y = p.second;
		if (x >= *l&&x <= *r&&y >= *d&&y <= *u) { ++count; }
	}
	if (count < k) { return 1e20; }

	ll ans = (*r - *l)*(*u - *d);

	ans = std::min(ans, S((++l)--, r, d, u, k));
	ans = std::min(ans, S(l, (++r)--, d, u, k));
	ans = std::min(ans, S(l, r, (++d)--, u, k));
	ans = std::min(ans, S(l, r, d, (++u)--, k));

	return ans;
}

