lli area(rec r){
  lli x  = r.first.first,  y  = r.first.second;
  lli xx = r.second.first, yy = r.second.second;
  return abs((x - xx)*(y - yy));
}

bool isIn(rec r, pii p){
  if(not(r.first.first <= p.first and p.first <= r.second.first))
    return false;
  if(r.first.second < r.second.second){
    return (r.first.second <= p.second and p.second <= r.second.second);
  }
  return (r.second.second <= p.second and p.second <= r.first.second);
}

int main(){
  lli n, K;
  std::cin >> n >> K;
  vector<pii> p(n);
  set<lli> x, y;
  for (int i = 0; i < n; i++) {
    std::cin >> p[i].first >> p[i].second;
    x.insert(p[i].first);
    y.insert(p[i].second);
  }
  vector<pii> grid;
  for (auto a:x) {
    for (auto b:y) {
      grid.push_back(pii(a, b));
    }
  }
  lli ans = 7e18;
  for (int i = 0; i < grid.size(); i++) {
    for (int j = i + 1; j < grid.size(); j++) {
      int cnt = 0;
      rec r = rec(grid[i], grid[j]);
      for (int k = 0; k < n; k++) cnt += isIn(r, p[k]);
      if(cnt >= K)ans = min(ans, area(r));
    }
  }
  std::cout << ans << std::endl;
  return 0;
}

