						if (min(xf, xs) <= x[i] && max(xf, xs) >= x[i] && min(yf, ys) <= y[i] && max(yf, ys) >= y[i]) {
							count++;
						}
					}

					if (count >= k) {
						if (abs(xf - xs)*abs(yf - ys) < result) {
							result = abs(xf - xs)*abs(yf - ys);
						}
					}
				}
			}
		}
	}

	cout << result << endl;

	return 0;
}

