					ll min_y = min(y1, min(y2, y3));
					ll max_y = max(y1, max(y2, y3));

					int cnt = 0;
					for (int l=0; l<N; l++) {
						int x = p[l].first;
						int y = p[l].second;
						if (x >= min_x && x <= max_x && y >= min_y && y <= max_y) {
							cnt++;
						}
					}

					if (cnt >= K) ans = min(ans, (max_x - min_x) * (max_y - min_y));
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

