    for (int i = 0; i < n; i++)
    {
        scanf("%lld%lld", &points[i].x, &points[i].y);
    } 
    std::sort(points, points + n, [](const Coor& a, const Coor& b){ return a.x < b.x; });
    for (int left = 0; left + k <= n; left++)
    {
        for (int right = left + k; right <= n; right++)
        {
            int tmp_points[50]{};
            for (int i = left; i < right; i++) tmp_points[i] = i;
            std::sort(tmp_points + left, tmp_points + right,
                [&](const int& a, const int& b){ return points[a].y < points[b].y; }
            );
            for (int bottom_i = left; bottom_i <= right - k; bottom_i++)
            {
                long long tmp_min = points[tmp_points[bottom_i + k - 1]].y - points[tmp_points[bottom_i]].y;
                long long x_min = 2000000000000, x_max = -2000000000000;
                for (int j = left; j < right; j++)
                {
                    if (points[j].y < points[tmp_points[bottom_i]].y || points[j].y > points[tmp_points[bottom_i + k - 1]].y) continue;
                    x_min = std::min(x_min, points[j].x);
                    x_max = std::max(x_max, points[j].x);
                }
                tmp_min *= x_max - x_min;
                min = std::min(tmp_min, min);
            }
        }
    }
    printf("%lld\n", min);
}

