    vector<pair<int, int>> xy(n);
    for (int i = 0; i < n; i++) {
        cin >> xy[i].first >> xy[i].second;
    }
    sort(all(xy));
    lint ans = LLONG_MAX;
    // l:左
    for (int l = 0; l < n; l++) {
        // r:右
        for (int r = l + 1; r < n; r++) {
            // u:上
            for (int u = l; u <= r; u++) {
                // d:下
                for (int d = l; d <= r; d++) {
