void solve() {
  ll N, K;
  input(N, K);
  vecl x(N), y(N);
  for (auto &&i : range(N)) {
    input(x[i], y[i]);
  }
  auto contains = [&](ll const &xi, ll const &xj, ll const &yi, ll const &yj,
                      ll const &x, ll const &y) {
    return xi <= x && x <= xj && yi <= y && y <= yj;
  };
  auto area = [&](ll const &xi, ll const &xj, ll const &yi, ll const &yj) {
    return (xj - xi) * (yj - yi);
  };
  ll ans = 1e20;
