          dump(xi, xj, yi, yj);
          ll cnt = count_if(begin(), end(N), [&](auto const &i) {
            return contains(xi, xj, yi, yj, x[i], y[i]);
          });
          if (cnt >= K) {
            dump(xi, xj, yi, yj);
            ans = min(ans, area(xi, xj, yi, yj));
          }
        }
      }
    }
  }
  print(ans);
}

