//2次元累積和の配列をもとに領域内の和を求める。1basedな配列を入力とする
ll SumFromIntegral(vvll &integral, ll left, ll top, ll right, ll bottom) {
	ll result = 0;

	result += integral[bottom][right];
	result += integral[top - 1][left - 1];
	result -= integral[top - 1][right];
	result -= integral[bottom][left - 1];

	return result;
}

int main() {
	ll N;
	cin >> N;
	ll K;
	cin >> K;
	vector<ll> X(N);
	vector<ll> Y(N);
	rep(i, N) {
		cin >> X[i] >> Y[i];
	}

	//それぞれの軸でソートした座標値。indexからここを引いて元の座標値を知ることができる
	vll xSort(N);
	vll ySort(N);
	rep(i, N) {
		xSort[i] = X[i];
		ySort[i] = Y[i];
	}
	std::sort(xSort.begin(), xSort.end());
	std::sort(ySort.begin(), ySort.end());

	map<ll, ll> xIndex;
	map<ll, ll> yIndex;
	rep(i, N) {
		xIndex[xSort[i]] = i;
		yIndex[ySort[i]] = i;
	}

	//座標圧縮してNxNの配列に置き換える。このときindex+1しておき、累積和を扱いやすくする
	vvll integral(N + 1, vll(N + 1, 0));
	rep(i, N) {
		ll u = xIndex[X[i]] + 1;
		ll v = yIndex[Y[i]] + 1;
		integral[v][u] += 1;
	}

	//2次元累積和を求める
	reps(iY, 1, N) reps(iX, 1, N) {
		integral[iY][iX] += integral[iY - 1][iX];
		integral[iY][iX] += integral[iY][iX - 1];
		integral[iY][iX] -= integral[iY - 1][iX - 1];
	}

	//ll SumFromIntegral(vvll &integral, ll left, ll top, ll right, ll bottom);

	ll result = (ll)(1e18 * 5);

	//あり得る矩形を全探索
	reps(left, 1, N - 1) reps(top, 1, N - 1) reps(right, left + 1, N) reps(bottom, top + 1, N) {
		ll numPoint = SumFromIntegral(integral, left, top, right, bottom);
		if (numPoint >= K) {
			ll area = (xSort[right - 1] - xSort[left - 1]) * (ySort[bottom - 1] - ySort[top - 1]);
			chmin(result, area);
		}
	}

	cout << result << endl;

	return 0;
}

