using namespace std;

long ncr(int n, int r) {
    long a = 1;
    r = r > n - r ? n - r : r;
    for(int i = 1;  i <= r ; i++, n--) {
        if(n % i == 0) {
            a *= n / i;
        } else if (a % i == 0) {
            a = a / i * n;
        } else {
            a = (a * n) / i;
        }
    }
    return a;
}

void combination(vector<vector<int>> &v, int n, int r)
{
    std::string bit_mask(r, 1);
    bit_mask.resize((unsigned long)n, 0);

    int c = 0, j;
    do {
        j = 0;
        for (int i = 0; i < n; ++i)
        {
            if (bit_mask[i]) {
                v[c][j++] = i;
            }
        }
        c++;
    } while (std::prev_permutation(bit_mask.begin(), bit_mask.end()));
}

