    vector<ll> u(n), v(n);
    rep(i, n) {
        u[i] = lower_bound(all(dict), x[i]) - dict.begin();
        v[i] = lower_bound(all(dict), y[i]) - dict.begin();
    }

    ll m = dict.size();
    vector<vector<ll> > S(m, vector<ll>(m));

    rep(i, n) {
        S[v[i]][u[i]]++;
    }

    rep(y, m) {
        repi(x, m) {
            S[y][x] = S[y][x-1] + S[y][x];
        }
    }

    rep(x, m) {
        repi(y, m) {
            S[y][x] = S[y-1][x] + S[y][x];
        }
    }

