using namespace std;

typedef long long ll;

int main()
{
    int N, K;
    cin >> N >> K;
    ll X[N], Y[N];
    vector<ll> xVec, yVec;
    REP(i, N)
    {
        ll x, y;
        cin >> x >> y;
        X[i] = x;
        Y[i] = y;
        xVec.push_back(x);
        yVec.push_back(y);
    }

    sort(xVec.begin(), xVec.end());
    sort(yVec.begin(), yVec.end());

    // 全ての点を含む長方形の面積の最大値
    ll ans = (xVec[N - 1] - xVec[0]) * (yVec[N -1] - yVec[0]);

    // 長方形の辺となる候補を全探索
    // 右辺, 左辺 : x 座標の組
    // 上辺, 下辺 : y 座標の組
    // 辺の候補を決めたら、その長方形内に含まれる点の個数を数える
    // 全部でO(N^5) となるがN <= 50 なので間に合う
    for (int i = 0; i < N - 1; ++i)
    {
        for (int j = i + 1; j < N; ++j)
        {
            for (int k = 0; k < N - 1; ++k)
            {
                for (int l = k + 1; l < N; ++l)
                {
                    // 長方形に含まれる点の個数
                    int num = 0;
                    ll leftX = xVec[i];
                    ll rightX = xVec[j];
                    ll bottomY = yVec[k];
                    ll upperY = yVec[l];
                    for (int m = 0; m < N; ++m)
                    {
                        // 長方形の内部に点m が含まれるか判定
                        if (X[m] >= leftX && X[m] <= rightX && Y[m] >= bottomY && Y[m] <= upperY)
                        {
                            num++;
                        }
                    }
                    if (num >= K)
                    {
                        ans = min(ans, (rightX - leftX) * (upperY - bottomY));
                    }
                }   
            }
        }
    }

    cout << ans << endl;
}

