const long INF = 4000000000000000000;

typedef pair<long, long> P;
long n, a;
long x[50];
long y[50];

int main(){
	scanf("%ld%ld", &n, &a);
	for(long i = 0; i < n; i++){
		scanf("%ld%ld", &x[i], &y[i]);
	}
	//printf("%ld %ld\n", n, a);
	long xmin, xmax, ymin, ymax;
	long ans = INF;
	for(long i = 0; i < n-1; i++){
		for(long j = i; j < n; j++){
			xmin = min(x[i], x[j]);
			xmax = max(x[i], x[j]);
			ymin = min(y[i], y[j]);
			ymax = max(y[i], y[j]);
			for(long k = 0; k < n; k++){
				if(x[k] < xmin || x[k] > xmax/* || (y[k] >= ymin && y[k] <= ymax)*/){//順が関係するため不可
					continue;
				}
				ymin = min(ymin, y[k]);
				ymax = max(ymax, y[k]);
				for(long l = k; l < n-1; l++){
					if(x[l] < xmin || x[l] > xmax /*|| (y[l] >= ymin && y[l] <= ymax)*/){
						continue;
					}
					ymin = min(ymin, y[l]);
					ymax = max(ymax, y[l]);
					long count = 0;
					for(long m = 0; m < n; m++){
						if(x[m] >= xmin && x[m] <= xmax && y[m] >= ymin && y[m] <= ymax){
							count++;
						}
					}
					//printf("%ld\n", count);
					if(count == a){
						ans = min(ans, (xmax-xmin)*(ymax-ymin));
						//printf("%ld %ld %ld %ld\n", i, j, k, l);
					}
				}
			}
		}
	}
	printf("%ld\n", ans);
	return 0;
}

