ll mod_pow(ll a,ll b,ll m) 
{
    ll res = 1;
    while(b)	
    {
        if(b&1) 	
        {
        	res=(res*a) % m;
        }
        a=(a*a) % m;
        b>>=1;
    }
    return res;
}

ll mod_inverse(ll a) 
{
	return mod_pow(a , mod-2 , mod);
}

void solve()
{
	int n , k;

	cin >> n >> k;

	vector< pair<int,int> > a(n);

	for(int i = 0; i < n; ++i) {
		cin >> a[i].F >> a[i].S;
	}

	sort(ALL(a));

	int ans = inf;

	for(int i = 0; i < n-k+1; ++i) {
		int mx_x = -inf, mx_y = -inf , mi_x = inf, mi_y = inf;

		for(int j = i; j < i+k; ++j) {
			mx_x = max(mx_x , a[j].F);
			mi_x = min(mi_x , a[j].F);

			mx_y = max(mx_y , a[j].S);
			mi_y = min(mi_y , a[j].S);
		}

		ans = min(ans , (mx_x - mi_x)*(mx_y - mi_y));
	}

	cout << ans;
}

signed main() {
    fast;

    int t = 1;

	//cin >> t;

    while(t--) {
        solve();
    }

    return 0;
}

