using namespace std;

ll in_cnt(vector<pll>& point, ll x1, ll y1, ll x2, ll y2)
{
  ll res = 0;
  ll N = point.size();
  for (ll i = 0; i < N; ++i) {
    if ((min(x1, x2) <= point.at(i).first) && (point.at(i).first <= max(x1, x2)) && (min(y1, y2) <= point.at(i).second) && (point.at(i).second <= max(y1, y2))) {
      res += 1;
    }
  }
  return res;
}

ll calc(ll x1, ll y1, ll x2, ll y2)
{
  ll res = abs(x1 - x2) * abs(y1 - y2);
  return res;
}

int main()
{
  ll N, K;
  cin >> N >> K;
  vector<pll> point(N);
  vector<ll> x_list(N);
  vector<ll> y_list(N);
  for (ll i = 0; i < N; ++i) {
    ll x, y;
    cin >> x >> y;
    x_list.at(i) = x;
    y_list.at(i) = y;
    point.at(i) = {x, y};
  }
  ll ans = INF;
  for (ll x1 = 0; x1 < N - 1; ++x1) {
    ll px1 =  x_list.at(x1);
    for (ll x2 = 0; x2 < N; ++x2) {
      ll px2 = x_list.at(x2);
      for (ll y1 = 0; y1 < N - 1; ++y1) {
        ll py1 = y_list.at(y1);
        for (ll y2 = 0; y2 < N; ++y2) {
          ll py2 = y_list.at(y2);
          ll cnt = in_cnt(point, px1, py1, px2, py2);
