  for (ll i = 0; i < N; i++) {
    for (ll j = (i + 1); j < N; j++) {
      // ueに広げるパターン
      ll ue = y[j];
      ll si = y[i];
      ll mi = x[i];
      ll hi = x[j];
      if (ue < si) {
        swap(ue, si);  
      }  
      if (mi < hi) {
        swap(mi, hi);  
      }
      ll num = 0;
      vector<ll> up, bo;
      for (ll l = 0; l < N; l++) {
        if (l != i && l != j) {
          if (x[l] >= hi && x[l] <= mi) {
            if (y[l] > ue) {
              up.push_back(y[l] - ue);  
            }  
            if (y[l] < si) {
              bo.push_back(si - y[l]);  
            }
            if (y[l] < ue && y[l] > si) {
              num++;  
            }
          }
        }  
      }
