int main()
{
    int n, k, first, cell_cnt[51][51] = {0};
    long long small_area, area;

    cin >> n >> k;
    for (int i = 1; i <= n; ++i)
        cin >> x[i] >> y[i];
    sort(x + 1, x + n + 1);
    sort(y + 1, y + n + 1);

    for (int i = 1; i <= n; ++i)
    for (int j = 1; j <= n; ++j) {
        for (int o = 1; o <= n; ++o)
            if (x[o] <= x[i] && y[o] <= y[j])
                cell_cnt[i][j]++;
    }


    long long left_m, down_m, right_m, up_m;
    int left_i, down_i, right_i, up_i;
    first = 1;
    for (int i = 1; i <= n; ++i)
    for (int j = 1; j <= n; ++j)
    for (int o = 1; o <= n; ++o)
    for (int l = 1; l <= n; ++l) {
        left_m = min_3(x[i], x[j], x[o], x[l]);
        left_i = ind_x(left_m, i, j, o, l);

        down_m = min_3(y[i], y[j], y[o], y[l]);
        down_i = ind_y(down_m, i, j, o, l);

        right_m = max_3(x[i], x[j], x[o], x[l]);
        right_i = ind_x(right_m, i, j, o, l);

