    vector<pair<int64_t, int64_t>> x(n), y(n), xy(n);
    for (int i = 0; i < n; i++) {
        x[i].second = y[i].second = i;
        cin >> x[i].first >> y[i].first;
        xy[i].first = x[i].first, xy[i].second = y[i].first;
    }
    sort(begin(x), end(x));
    sort(begin(y), end(y));

    int64_t ans = INT64_MAX;
    for (int xi = 0; xi+1 < n-1; xi++) {
        for (int xj = n-1; xj-1 >= xi; xj--) {              
            for (int yi = 0; yi+1 < n-1; yi++) {
                for (int yj = n-1; yj-1 >= yi; yj--) {
