                        if (left <= xy[m].first && xy[m].first <= right && bottom <= xy[m].second && xy[m].second <= top) c++;
                    }
                    if (c >= k) ans = min(ans, (top - bottom) * (right - left));
                }
            }
        }
    }

    cout << ans << endl;
}

