  for (int i = 0; i < N; i++) {
    scanf("%lld %lld", &xs[i], &ys[i]);
  }

  long long area = LLONG_MAX;
  for (int xi = 0; xi < N; xi++){
    for (int xj = 0; xj < N; xj++) {
      if (xi == xj) continue;

      long long xl = min(xs[xi], xs[xj]);
      long long xr = max(xs[xi], xs[xj]);

      for (int yi = 0; yi < N; yi++) {
        for (int yj = 0; yj < N; yj++) {
          if (yi == yj) continue;

          long long yd = min(ys[yi], ys[yj]);
