            if ((x >= xl && x <= xr) && (y >= yd && y <= yu)) count++;
          }
          if (count == K) {
            long long new_area = (xr - xl) * (yu - yd);
            if (new_area < area) area = new_area;
          }
        }
      }
    }
  }
