template< typename T >
using Edges = vector< edge< T > >;
template< typename T >
using WeightedGraph = vector< Edges< T > >;
using UnWeightedGraph = vector< vector< int > >;
template< typename T >
using Matrix = vector< vector< T > >;

template< class T >
vector< T > dijkstra(WeightedGraph< T > &g, int s) {
  const auto INF = numeric_limits< T >::max();
  vector< T > dist(g.size(), INF);

  using Pi = pair< T, int >;
  priority_queue< Pi, vector< Pi >, greater< Pi > > que;
  dist[s] = 0;
  que.emplace(dist[s], s);
  while(!que.empty()) {
    T cost;
    int idx;
    tie(cost, idx) = que.top();
    que.pop();
    if(dist[idx] < cost) continue;
    for(auto &e : g[idx]) {
      auto next_cost = cost + e.w;
      if(dist[e.to] <= next_cost) continue;
      dist[e.to] = next_cost;
      que.emplace(dist[e.to], e.to);
    }
  }
  return dist;
}

template<class T,class F>
struct SegTree{
	V(T) seg;
	int size;
	const F f;
	const T e;

	SegTree(const V(T)& d,F f,T e):f(f),e(e){
		int n=d.size();
		size=1;
		while(size<n)size<<=1;
		seg.resize(size*2-1,e);
		rep(i,n)seg[i+size-1]=d[i];
		gnr(i,0,size-2)upd(i);
	}

	void upd(int i){
		seg[i]=f(seg[i*2+1],seg[i*2+2]);
	}

	void set(int i,T t){
		i+=size-1;
		seg[i]=t;
		while(i){
			i=(i-1)/2;
			upd(i);
		}
	}

	T get(int a,int b,int i,int l,int r){
		if(r<0)r=size;
		if(b<=l||r<=a)return e;
		if(a<=l&&r<=b)return seg[i];
		int mid=(l+r)/2;
		return f(get(a,b,i*2+1,l,mid),get(a,b,i*2+2,mid,r));
	}

	T get(int a,int b){
		return get(a,b,0,0,-1);
	}

  T operator[](const int &i)const{
    return seg[i+size-1];
  }
};
template<class T,class F>
SegTree<T,F> segtree(const V(T)& d,F f,T e){
	return SegTree<T,F>(d,f,e);
}

