ll area(int a,int b,int c,int d){
    ll len1,len2;//len1:縦 len2:横
    len1=v[d].first-v[a].first;
    ll A=v[a].second,B=v[b].second,C=v[c].second,D=v[d].second;
    len2=MAX(A,B,C,D)-MIN(A,B,C,D);
    return len1*len2;
}
bool in_area(int a,int b,int c,int d,int p){
    ll UNDER=MIN(v[a].second,v[b].second,v[c].second,v[d].second);
    ll TOP=MAX(v[a].second,v[b].second,v[c].second,v[d].second);
    ll LEFT=v[a].first,RIGHT=v[d].first;
    return (LEFT<=v[p].first && v[p].first<=RIGHT && UNDER<=v[p].second && v[p].second<=TOP);
}
