ll area(ll x_l, ll x_r, ll y_d, ll y_t){
	ll width, height;
	width = x_r - x_l;
	height = y_t - y_d;

	return width*height;
}

bool threshold(ll x_l, ll x_r, ll y_d, ll y_t, vector<Coordinate> v, int k){
	int l=0;
	for(auto p:v){
		ll px = p.first; ll py = p.second;
		if(x_l <= px && px <= x_r && y_d <= py && py <= y_t) l++;
	}

	return k <= l;
}


