        return y < p.y;
    }
};

int main()
{
    int n, k;
    cin >> n >> k;
    vector<Point> p(n);
    for(int i=0; i<n; ++i)
        cin >> p[i].x >> p[i].y;
    sort(p.begin(), p.end());

    long long ans = LLONG_MAX;
    for(int i=0; i<n; ++i){
        for(int j=0; j<i; ++j){
            int x1 = p[i].x;
            int x2 = p[j].x;
            if(x2 < x1)
                swap(x1, x2);

            int yMinDiff = INT_MAX;
            int b = 0;
            int cnt = 0;
            for(int a=0; a<n; ++a){
                if(x1 <= p[a].x && p[a].x <= x2)
                    ++ cnt;
                for(;;){
                    if(x1 <= p[b].x && p[b].x <= x2){
                        if(cnt <= k)
                            break;
                        -- cnt;
                    }
                    ++ b;
                }
                if(cnt >= k)
                    yMinDiff = min(yMinDiff, p[a].y - p[b].y);
            }

            if(yMinDiff < INT_MAX)
                ans = min(ans, (x2 - x1) * (long long) yMinDiff);
        }
    }
    cout << ans << endl;

    return 0;
}

