const int MAX_N=100+1;
II P[MAX_N];
int N,K;

void solve() {
  LL res=4e18;
  sort(P,P+N);
  VI xs;
  REP(i,N) xs.push_back(P[i].first);
  sort(ALL(xs)),xs.erase(unique(ALL(xs)), xs.end());
  int M=SZ(xs);
  REP(i,M)FOR(j,i,M) {
    VI ys;
    REP(k,N) if(xs[i]<=P[k].first&&P[k].first<=xs[j]) {
      ys.push_back(P[k].second);
    }
    sort(ALL(ys));
    //dump(xs[i],xs[j]);
    //dumpc(ys);
    int L=SZ(ys);
    LL dx=xs[j]-xs[i];
    REP(k,L-K+1) {
      SMIN(res,dx*(ys[k+K-1]-ys[k]));
    }
  }
  cout<<res<<endl;
}

