ll gao(vector<pii> &vu, int dx) {
	if (sz(vu) < m) return INF;
	rep(i, 0, sz(vu)) swap(vu[i].fi, vu[i].se);
	sort(all(vu));
	ll ret = INF;
	rep(l, 0, sz(vu) + 1 - m) ret = min(ret, 1ll * (vu[l + m - 1].fi - vu[l].fi) * dx);
