    ll ans = INF;

    sort(points.begin(), points.end());

    for (ll i = 0; i <= N - K; i++) {
        ll x1 = points[i].first;
        ll x2 = points[i + K - 1].first;
        ll y1 = INF;
        ll y2 = -INF;

        for (ll j = 0; j < K; j++) {
            p point = points[i + j];
            y1 = min(y1, point.second);
            y2 = max(y2, point.second);
        }

        if (K <= count_included_points(x1, y1, x2, y2)) {
            ans = min(ans, (y2 - y1) * (x2 - x1));
        }
    }

    cout << ans << endl;

    return 0;
}

