        for (auto it = sx.begin(); it != sx.end(); it++) {
            x2i[*it] = i;
            i2x[i] = *it;
            i++;
        }
    }
    {
        int i = 0;
        for (auto it = sy.begin(); it != sy.end(); it++) {
            y2i[*it] = i;
            i2y[i] = *it;
            i++;
        }
    }
    vector<vector<int>> c(sx.size(), vector<int>(sy.size(), 0));
    for (int i = 0; i < N; i++) {
        c[x2i[X[i]]][y2i[Y[i]]]++;
    }
    vector<vector<int>> s(sx.size(), vector<int>(sy.size(), 0));
    for (int i = 0; i < sx.size(); i++) {
        for (int j = 0; j < sy.size(); j++) {
            s[i][j] = c[i][j];
            if (i > 0) s[i][j] += s[i-1][j];
            if (j > 0) {
                s[i][j] += s[i][j-1];
                if (i > 0) {
                    s[i][j] -= s[i-1][j-1];
                }
            }
        }
    }

    ll ans = LLONG_MAX;
    for (int ixl = 0; ixl < sx.size()-1; ixl++) {
        for (int ixr = ixl+1; ixr < sx.size(); ixr++) {
