                    if (ixl > 0) pts -= s[ixl-1][iyr];
                    if (iyl > 0) {
                        pts -= s[ixr][iyl-1];
                        if (ixl > 0) {
                            pts += s[ixl-1][iyl-1];
                        }
                    }
