		{
			for (size_t b1 = 0; b1 < 2; b1++)
			{
				for (size_t b2 = 0; b2 < 2; b2++)
				{
					ll x1 = x[i] * pow(-1, b1);
					ll x2 = x[j] * pow(-1, b2);
					ll mi = min(x1, x2);
					ll hi = max(x1, x2);
					res = min(res, xcheck(mi, hi, i, j));
				}
			}
		}
	}

	cout << res  << endl;
}

