LL judge(LL minX, LL minY, LL maxX, LL maxY) {
	int count = 0;
	for (auto p : xy) {
		if (minX <= p[0] && p[0] <= maxX && minY <= p[1] && p[1] <= maxY) {
			count++;
		}
	}
	if (count >= K)return (maxX - minX)*(maxY - minY);
	else return INF;
}

//辺集合の生成する長方形の四辺を計算
LL calc(vector<vector<LL>> edges) {
	LL minX = INF;
	LL minY = INF;
	LL maxX = -INF;
	LL maxY = -INF;
	for (auto edge : edges) {
		if (edge[0] < minX)minX = edge[0];
		if (edge[0] > maxX)maxX = edge[0];
		if (edge[1] < minY)minY = edge[1];
		if (edge[1] > maxY)maxY = edge[1];
	}
	return judge(minX, minY, maxX, maxY);
}


//辺集合を作って、計算に回す
LL produceEdges(vector<vector<LL>> edges, int last) {
	if (edges.size() == min(4, K)) {
		return calc(edges);
	}
	LL ans = INF;
	FOR(i, last, N) {
		edges.push_back(xy[i]);
		ans = min(ans, produceEdges(edges, i + 1));
		edges.pop_back();
	}
	return ans;
}


