#include <bits/stdc++.h>
using namespace std;

int main() {
  int H,W;
  cin >> H >> W;
  vector<string> S(H);
  vector<string> T(H+2);
  for (int i = 0; i < H; i++){
    cin >> S.at(i);//まずSに世界を入力
  }

  //T.at[0]:0をW+2個
  T.at(0) = "";
  for (int i = 0; i < W + 2; i++){
    T.at(0) = T.at(0) + "0";
  }

  //T.at[1]~T.at[H]:0+(世界)+0
  for (int i = 1; i <= H; i++){
    T.at(i) = "0" + S.at(i - 1) + "0";
  }

  //T.at[H+1]:0をW+2個
  T.at(H+1) = "";
  for (int i = 0; i < W + 2; i++){
    T.at(H+1) = T.at(H+1) + "0";
  }

  //これで世界Sを0で囲ったTができた

  //Tで爆弾があれば、その周りに1を足していく
  vector<string> U(H);
  for (int i = 1; i <= H; i++){
    for (int j = 1; j <= W; j++){
      if (T.at(i).at(j) == '#'){
        for (int k = i - 1; k <= i + 1; k++){
          for (int l = j - 1; l <= j + 1; l++){
            if (T.at(k).at(l) == '.'){
              T.at(k).at(l) = '0' + 1;
            }
            else if (T.at(k).at(l) == '#'){
              continue;
            }
            else {
              T.at(k).at(l) += 1;
            }
          }
        }
      }
    }
  }

  //TからSを切り取る
  for (int i = 1; i <= H; i++){
    for (int j = 1; j <= W; j++){
      if (T.at(i).at(j) == '.'){
        T.at(i).at(j) = '0';
      }
      cout << T.at(i).at(j);
    }
    cout << "" <<endl;
  }
}

