		pts.pb({x, y});
		xp.insert(x);
		yp.insert(y);
	}
	vector<int> xxp, yyp;
	for(int u : xp) xxp.pb(u);
	for(int u : yp) yyp.pb(u);


	for(int i = 0; i < xxp.size(); i++){
		for(int j = i; j < xxp.size(); j++){
			for(int k = 0; k< yyp.size(); k++){
				for(int l = k; l<yyp.size(); l++){
					if(ct(xxp[i], xxp[j], yyp[k], yyp[l]) >= z){
						update(xxp[i], xxp[j], yyp[k], yyp[l]);
					}
				}
			}
		}
	}
	cout << minarea << endl;

	return 0;
}

