template <class T> inline bool chmax(T& a, T b){
    if(a < b){a = b; return true;}
    return false;
}
template <class T> inline bool chmin(T& a, T b){
    if(a > b){a = b; return true;}
    return false;
}


using Pii = std::pair<int, int>;

std::vector<Pii> A;
std::vector<int> Y;

int main(void){
    int n, k; scanf("%d%d", &n, &k);

    A.resize(n);
    REP(i, n){
        int x, y; scanf("%d%d", &x, &y);
        A[i] = Pii(x, y);
    }

    lli ans = LLONG_MAX;

    std::sort(A.begin(), A.end());

    for(int xS = 0; xS < n; ++xS){
        for(int t = k; xS + t <= n; ++t){
            int xE = xS + t;
            lli dX = A[xE-1].first - A[xS].first;

            for(int i = xS; i < xE; i++) Y.push_back(A[i].second);
            std::sort(Y.begin(), Y.end());

            const int m = Y.size();
            lli dY = LLONG_MAX;
            for(int yS = 0; yS + k <= m; ++yS){
                int dk = Y[yS + k - 1] - Y[yS];
                chmin(dY, (long long)dk);
            }

            Y.clear(); // 一旦クリア

            chmin(ans, dX*dY);

        }

    }

    printf("%lld\n", ans);    



    return 0;
}

