using namespace std;

template<class Iter>
bool next_partial_permutation(Iter first, Iter middle, Iter last) {
    reverse(middle, last);
    return next_permutation(first, last);
}

//combination nCr 組み合わせ
//first1・・最初の数
//last1==first2・・r(取り出す数)
//last2・・n(全体数)
template<class Iter>
bool next_combination(Iter first1, Iter last1, Iter first2,
                      Iter last2) {
    if ((first1 == last1) || (first2 == last2)) {
        return false;
    }
    Iter m1 = last1;
    Iter m2 = last2;
    --m2;
    while (--m1 != first1 && !(*m1 < *m2)) {
    }
    bool result = (m1 == first1) && !(*first1 < *m2);
    if (!result) {
        while (first2 != m2 && !(*m1 < *first2)) {
            ++first2;
        }
        first1 = m1;
        std::iter_swap(first1, first2);
        ++first1;
        ++first2;
    }
    if ((first1 != last1) && (first2 != last2)) {
        m1 = last1;
        m2 = first2;
        while ((m1 != first1) && (m2 != last2)) {
            std::iter_swap(--m1, m2);
            ++m2;
        }
        std::reverse(first1, m1);
        std::reverse(first1, last1);
        std::reverse(m2, last2);
        std::reverse(first2, last2);
    }
    return !result;
}

int main() {

    long long N, K;
    cin >> N >> K;

    vector<pair<long long, long long>> points(N);
    for (int i = 0; i < N; i++) {
        long long x, y;
        cin >> x >> y;
        points[i] = make_pair(x, y);
    }

    vector<long long> a(N);
    for (int i = 0; i < N; i++) a[i] = i;

    long long ans = LONG_LONG_MAX;

    do {

        long long minY = min(points[a[0]].second, points[a[1]].second);
        long long maxY = max(points[a[0]].second, points[a[1]].second);

        vector<long long> x;
        for (int i = 0; i < N; i++)
            if (minY <= points[i].second && points[i].second <= maxY)
                x.push_back(points[i].first);

        sort(x.begin(), x.end());

        if (x.size() >= K) {
            for (int i = 0; i < x.size() - K + 1; i++) {
                long long area = (x[i + K - 1] - x[i]) * (maxY - minY);
                ans = min(area, ans);
            }
        }

    } while (next_combination(a.begin(), a.begin() + 2, a.begin() + 2, a.end()));

    cout << ans << endl;

    return 0;
}

