	VL x(N), y(N);
	REP(i, N) cin >> x[i] >> y[i];
	vector<vector<pair<ll,int>>> r(N, vector<pair<ll,int>>(N));
	REP(i, N) {
		for (int j = 0; j <= i; j++) {
			if (i == j) r[i][j].first = r[j][i].first = (ll)9 * 1e18;
			else r[i][j].first = r[j][i].first = (x[i] - x[j])*(x[i] - x[j]) + (y[i] - y[j])*(y[i] - y[j]);
			r[i][j].second = j;
			r[j][i].second = i;
		}
