long long gcd(long long a, long long b){
    if(b == 0){
        return a;
    }
    return gcd(b, a % b);
}

long long lcm(long long a, long long b){
    return (a / gcd(a, b)) * b;
}

bool containsKPoints(vector<pair<ll, ll> >& points, pair<ll, ll>& point1, pair<ll, ll>& point2, int K) {
    int count = 0;
    ll xbig = max(point1.first, point2.first);
    ll xsmall = min(point1.first, point2.first);
    ll ybig = max(point1.second, point2.second);
    ll ysmall = min(point1.second, point2.second);
    for (int i = 0; i < points.size(); ++i) {
        pair<ll, ll> candidate = points[i];
        ll x = candidate.first;
        ll y = candidate.second;
        if (xsmall <= x && x <= xbig && ysmall <= y && y <= ybig) {
            count++;
        }
    }
    return K <= count;
}

long long computeArea(pair<ll, ll>& point1, pair<ll, ll>& point2) {
    ll area = (point1.first - point2.first) * (point1.second - point2.second);
    if (area < 0) {
        return area * -1;
    } else {
        return area;
    }
}

int main(){
    int N, K;
    cin >> N >> K;

    vector<pair<long long, long long> > points;
    long long x, y;
    repeat(i,N) {
        cin >> x >> y;
        pair<long long, long long> point(x, y);
        points.push_back(point);
    }

    long long area = 100000000000;
    for (int i = 0; i < points.size(); ++i) {
        for (int j = i + 1; j < points.size(); ++j) {
            long long tmpArea = computeArea(points[i], points[j]);
            if (containsKPoints(points, points[i], points[j], K) && tmpArea < area) {
                area = tmpArea;
            }
        }
    }
    cout << area << endl;
    return 0;
}

