LL solve() {
    LL ans = numeric_limits<LL>::max() / 2;
    REP(i, N - 1) {
        FOR(j, i + 1, N) {
            LL max_x = max(xs[i], xs[j]);
            LL min_x = min(xs[i], xs[j]);
