            LL min_y = min(ys[i], ys[j]);
            if (check(min_x, max_x, min_y, max_y)) {
                ans = min(ans, (max_x - min_x) * (max_y - min_y));
            }
        }
    }

    REP(i, N - 2) {
        FOR(j, i + 1, N - 1) {
            FOR(k, j + 1, N) {
                LL max_x = max(xs[k], max(xs[i], xs[j]));
                LL min_x = min(xs[k], min(xs[i], xs[j]));
                LL max_y = max(ys[k], max(ys[i], ys[j]));
                LL min_y = min(ys[k], min(ys[i], ys[j]));
                if (check(min_x, max_x, min_y, max_y)) {
                    ans = min(ans, (max_x - min_x) * (max_y - min_y));
                }
            }
        }
    }

    REP(i, N - 3) {
        FOR(j, i + 1, N - 2) {
            FOR(k, j + 1, N - 1) {
                FOR(l, k + 1, N) {
                    LL max_x = max(xs[i], max(xs[j], max(xs[k], xs[l])));
                    LL min_x = min(xs[i], min(xs[j], min(xs[k], xs[l])));
                    LL max_y = max(ys[i], max(ys[j], max(ys[k], ys[l])));
                    LL min_y = min(ys[i], min(ys[j], min(ys[k], ys[l])));
                    if (check(min_x, max_x, min_y, max_y)) {
                        ans = min(ans, (max_x - min_x) * (max_y - min_y));
                    }

                }
            }
        }
    }
    return ans;

}

