	ll l, r;
}w[3000], h[3000], d[50];

bool cmp1(node a, node b)
{
	return a.l < b.l;
}
bool cmp2(node a, node b)
{
	return a.r < b.r;
}
struct per{
	ll n, s, w, e;
	ull m;
	friend bool operator<(per a, per b)
	{
		return a.m < b.m;
	}
}dot[8000000];
ll n, k, hn, wn, dn, sum;
ull ans;
bool check(per a, node b)
{
	if (a.s <= b.r && b.r <= a.n && a.w <= b.l && b.l <= a.e)
		return true;
	return false;
}
int main()
{
	scanf("%lld%lld", &n, &k);
	if (k == 1)
	{
		printf("0\n");
		return 0;
	}
	for (int i = 0; i < n; i++)
		scanf("%lld%lld", &d[i].l, &d[i].r);
	sort(d, d + n, cmp1);
	for (int i = 0; i < n; i++)
		for (int j = i + 1; j < n; j++)
		{
			w[wn].l = d[i].l;
			w[wn].r = d[j].l;
			wn++;
		}
	sort(d, d + n, cmp2);
	for (int i = 0; i < n; i++)
		for (int j = i + 1; j < n; j++)
		{
			h[hn].l = d[i].r;
			h[hn].r = d[j].r;
			hn++;
		}
