			dot[dn].s = h[j].l;
			dot[dn].w = w[j].l;
			dot[dn].e = w[j].r;
			dot[dn].m = (h[j].r - h[j].l) * (w[j].r - w[j].l);
			//printf("%lld %lld %lld %lld %lld\n", dot[dn].n, dot[dn].s, dot[dn].w, dot[dn].e, dot[dn].m); 
			dn++;
		}
	}
	sort(dot, dot + dn);
	for (int i = 0; i < dn; i++)
	{
		sum = 0;
		for (int j = 0; j < n; j++)
		{
			if (check(dot[i], d[j]))
			{
				sum++;
			}
		}
		if (sum >= k)
		{
			ans = dot[i].m;
			break;
		}	
	}
	cout << ans << endl;
}

