    int ymin = p[i].second, ymax = p[i].second;
    for (int j = i + 1; j < i + k; j++) {
      ymin = min(ymin, p[j].second);
      ymax = max(ymax, p[j].second);
    }
    ans = min(ans, x * (ymax - ymin));
  }

  sort(p, p + n, comp2);
  for (int i = 0; i < n - k + 1; i++) {
