	for (int i = 0; i < n; ++i) {
		for (int j = i+1; j < n; ++j) {
			for (int k = 0; k < n; ++k) {
				for (int l = k+1; l < n; ++l) {
					int cur = 0;
					for (int m = 0; m < n && cur < z; ++m) {
						if (a[m].first >= xs[i] && a[m].first <= xs[j]
						 && a[m].second >= ys[k] && a[m].second <= ys[l]) ++cur;
					}
					if (cur >= z) {
						ans = min(ans, (long long)(xs[j]-xs[i])*(ys[l]-ys[k]));
					}
				}
			}
		}
	}
	printf("%lld", ans);
}

int main() {
	init();
	int t = 1; //scanf("%d", &t);
	while (t--) {
		solve();
	}
	return 0;
}

