#define rrep(i,n) for(int i = 1;i <= n;i++)

int a[52][52], disx[52], disy[52];
int ax[52], ay[52], h, w;
vector<int> x, y;
map<int,int> zipx, zipy;

void compress(){
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());
	x.erase(unique(x.begin(), x.end()), x.end());
	y.erase(unique(y.begin(), y.end()), y.end());
	for(int i = 0;i < x.size();i++){
		disx[i+1] = x[i]-x[0];
		zipx[x[i]] = i+1;
	}
	for(int i = 0;i < y.size();i++){
		disy[i+1] = y[i]-y[0];
		zipy[y[i]] = i+1;
	}
	w = x.size();
	h = y.size();
}

int solve(int yy1, int yy2, int xx1, int xx2){
	int s = a[yy2][xx2]+a[yy1][xx1];
	s -= a[yy2][xx1]+a[yy1][xx2];
	return s;
}

signed main(){
