		scanf("%lld%lld", &ax[i], &ay[i]);
		x.push_back(ax[i]);
		y.push_back(ay[i]);
	}
	compress();

	for(int i = 0;i < n;i++){
		a[zipx[ax[i]]][zipy[ay[i]]]++;
	}
	rrep(i,h)rrep(j,w){
		a[i][j] += a[i][j-1];
	}
	rrep(i,h)rrep(j,w){
		a[i][j] += a[i-1][j];
	}

	int ans = 1e18*4+7;
	rep(yy1,h)rep(yy2,h){
		if(yy1-1 >= yy2)continue;
		rep(xx1,w)rep(xx2,w){
			if(xx1-1 >= xx2)continue;
			int dis = disx[xx2]-disx[xx1+1];
			dis = dis*(disy[yy2]-disy[yy1+1]);
			int cnt = solve(yy1, yy2, xx1, xx2);
			if(cnt >= k){
				ans = min(ans, dis);
			}
		}
	}

	printf("%lld\n", ans);
	return 0;
}

