    int cnt[55][55];
    memset(cnt, 0, sizeof(cnt));
    rep(i, N) {
        rep(j, N) {
            cnt[i + 1][j + 1] = cnt[i][j + 1] + cnt[i + 1][j] - cnt[i][j] + res[i][j];
        }
    }
    unsinged long long ans = INF;
    rep(xmin, N) {
        Rep(xmax, xmin + 1, N) {
            rep(ymin, N) {
                Rep(ymax, ymin + 1, N) {
                    unsinged long long ret = (unsinged long long)(xs[xmax] - xs[xmin]) * (ys[ymax] - ys[ymin]);
                    if(cnt[xmax + 1][ymax + 1] - cnt[xmin][ymax + 1] - cnt[xmax + 1][ymin] + cnt[xmin][ymin] >= K) {
                        ans = min(ans, ret);
                    }
                }
            }
        }
    }
    cout << ans << endl;
	return 0;
}

