bool solve(ll x1, ll y1, ll x2, ll y2) {
	ll cnt = 0;
	REP(i, n) if (x[i] >= x1 && x[i] <= x2 && y[i] >= y1 && y[i] <= y2) ++cnt;
	return cnt >= k;
}

