int calk ( ll xh, ll xl, ll yh, ll yl )
{
  int ans = 0;
  if ( xh < xl ) swap(xh,xl);
  if ( yh < yl ) swap(yh,yl);
  for ( int i = 0; i < N; ++i ) {
    if ( A[i].x <= xh && A[i].x >= xl && A[i].y <= yh && A[i].y >= yl ) ++ans;
  }

  return ans;
}

ll axis ( void )
{
   ll min = INF;

   for ( int a = 0; a < N; ++a ) {
     for ( int b = 0; b < N; ++b ) {
       for ( int c = 0; c < N; ++c ) {
         for ( int d = 0; d < N; ++d ) {
           if ( calk( A[a].x, A[b].x, A[c].y, A[d].y ) >= K ) {
             ll tmp = abs( (A[a].x-A[b].x)*(A[c].y-A[d].y) );
             if ( tmp < min ) min = tmp;
           }
         }
       }
     }
   }

   return min;
}

