const double PI = 3.1415926535897;
typedef pair<ll,ll> P;

int main() {
    int N,K;
    cin >> N >> K;
    vector<P> vec(N);
    for(int i = 0;i < N;i++) {
        ll A,B;
        cin >> A >> B;
        vec.at(i) = make_pair(A,B);
    }
    sort(vec.begin(),vec.end());
    ll ret = INF;
    for(int i = 0;i < N - K + 1;i++) {
        ll a = vec.at(i).first;
        ll b = vec.at(i + K - 1).first;
        ll c = -INF;
        ll d = INF;
        for(int j = 0;j < K;j++) {
            c = max(c,vec.at(i + j).second);
            d = min(d,vec.at(i + j).second);
        }
        ret = min(ret,(b - a) * (c - d));
    }
    cout << ret << endl;
}

