int N, K;

bool ran(ll a, ll c, ll b)
{
  return a <= c && c <= b;
}

ll cnt(ll xmi, ll ymi, ll xma, ll yma)
{
  int c = 0;
  for (int i = 0; i < N; i++) {
    if (ran(xmi, x[i], xma) && ran(ymi, y[i], yma)) {
      c++;
    }
  }
  if (c >= K) {
    return (xma - xmi) * (yma - ymi);
  }
  return 8e18;
}

int main()
{
  cin >> N >> K;
  x.resize(N);
  y.resize(N);
  ll res = 8e18;
  for (int i = 0; i < N; i++) {
