#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using pii = pair<int, int>;

const ll INF = 1LL << 62;
int N, K;
int x[50], y[50];

ll calc(int l, int r, int d, int u) {
  int sum = 0;
  for (int i = 0; i < N; i++) {
    if (!(x[l] <= x[i] && x[i] <= x[r] && y[d] <= y[i] && y[i] <= y[u])) continue;
    sum++;
  }
  if (sum < K) return INF;
  return (ll)(x[r] - x[l]) * (y[u] - y[d]);
}

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  cin >> N >> K;
  for (int i = 0; i < N; i++) {
    cin >> x[i] >> y[i];
  }  
  ll ans = INF;
  for (int l = 0; l < N; l++) {
    for (int r = 0; r < N; r++) {
      for (int d = 0; d < N; d++) {
        for (int u = 0; u < N; u++) {
          if (!(x[l] <= x[r] && x[l] <= x[d] && x[l] <= x[u])) continue;
          if (!(x[r] >= x[l] && x[r] >= x[d] && x[r] >= x[u])) continue;
          if (!(y[d] <= y[l] && y[d] <= y[r] && y[d] <= y[u])) continue;
          if (!(y[u] >= y[l] && y[u] >= y[r] && y[u] >= y[d])) continue;
          ans = min(ans, calc(l, r, d, u));
        }
      }
    }
  }
  cout << ans << endl;

  return 0;
}

