ILL_TYPE Cal_Min_Area(LL k, LL up, LL down, vector<pair<LL, LL>> const& ls) {
	LL n = ls.size();

	ILL_TYPE ans = ILL_TYPE::plus_inf();

	for (LL i = 0; i < n; i++) {
		LL count = 0;

		for (LL j = i; j < n; j++) {
			if (down <= ls[j].second && ls[j].second <= up) {
				count++;
			}
			if (count == k) {
				ans = min(ans, ILL_TYPE(ls[j].first - ls[i].first));
				break;
			}
		}
	}

	MYCP::DebugPrintf((ans * (up - down)).ToString());

	if (ans == ILL_TYPE::plus_inf()) {
		return ILL_TYPE::plus_inf();
	}

	return ans * (up - down);
}

