	for (i = 0; i < n; i++) {
		for (j = 0; j < n; j++) {
			LL up, down;
			up = p[i].second;
			down = p[j].second;

			if (up < down)swap(up, down);

			ans = min(ans, Cal_Min_Area(k, up, down, p));
		}
	}

