  }
  sort(px.begin(), px.end());
  sort(py.begin(), py.end());

  REP(i, N){
    auto itr = lower_bound(px.begin(), px.end(), x[i]);
    x[i] = itr-px.begin()+1;
    itr = lower_bound(py.begin(), py.end(), y[i]);
    y[i] = itr-py.begin()+1;
  }
  vector<vector<ll>> sum(N+1, vector<ll>(N+1, 0));
  REP(i, N){
    sum[y[i]][x[i]]++;
  }
  REP(i, N+1){
    REP(j, N){
      sum[i][j+1] += sum[i][j];
    }
  }
  REP(j, N+1){
    REP(i, N){
      sum[i+1][j] += sum[i][j];
    }
  }
  ll ans = INF;
  REP(i, N+1){
