int main(){
    int n,k;
    int X[50],Y[50];
    unsigned long long rec;
    int Mxx=INT_MIN,mxx=INT_MAX,Myy=INT_MIN,myy=INT_MAX;

    cin>> n >> k ;

    int vex = n;

    int ans=0;
    for(int v=0;v<n;v++){
        cin>>X[v]>>Y[v];
        Mxx=max(Mxx,X[v]);
        Myy=max(Myy,Y[v]);
        mxx=min(mxx,X[v]);
        myy=min(myy,Y[v]);
    }
    rec=(Mxx-mxx)*(Myy-myy);

    int dels[50];
    int delsize=0;
    for(int i=0;i<n;i++){
        dels[i]=-1;
    }

    unsigned long long dec=rec;
    // cout<<dec<<endl;
    while(vex > k){
        int rem = delsize;    
        for(int i=0;i<vex;i++){
            // int tmX=X[k];
            // int tmY=Y[k];
            Mxx=INT_MIN,mxx=INT_MAX,Myy=INT_MIN,myy=INT_MAX;
            for(int v=0;v<n;v++){
                if(find(dels, dels+n, v) != dels+n){
                    // cout<<v<<":has removed"<<endl;
                    continue;
                }
                if(v==i)continue;
                Mxx=max(Mxx,X[v]);
                Myy=max(Myy,Y[v]);
                mxx=min(mxx,X[v]);
                myy=min(myy,Y[v]);

            }
            // cout<<(unsigned long long)(Mxx-mxx)*(Myy-myy)<<endl;
            if(dec > (unsigned long long)(Mxx-mxx)*(Myy-myy) ){
                dec = (unsigned long long)(Mxx-mxx)*(Myy-myy);
                rem=i;
                // cout<<"get:"<<dec<<endl;
            }
        }
        dels[delsize++]=rem;
        vex--;
        rec = dec;
    }
    for(int i=0;i<n;i++){
        cout<<dels[i]<<endl;
    }
    cout<<rec<<endl;
    return 0;
}

