    for (int i = 0; i < n; i++)
    {
        scanf("%lld%lld", &points[i].x, &points[i].y);
    } 
    std::sort(points, points + n, [](const Coor& a, const Coor& b){ return a.x < b.x; });
    for (int left = 0; left + k <= n; left++)
    {
        for (int right = left + k; right <= n; right++)
        {
            int tmp_points[50]{};
            for (int i = left; i < right; i++) tmp_points[i] = i;
            std::sort(tmp_points + left, tmp_points + right,
                [&](const int& a, const int& b){ return points[a].y < points[b].y; }
            );
            long long candi1 = points[tmp_points[right - 1]].y - points[tmp_points[right - k]].y;
            {
                long long x_min = 2000000000000, x_max = 0;
                for (int i = left; i < right; i++)
                {
                    if (tmp_points[i] < right - k) continue;
                    x_min = std::min(x_min, points[i].x);
                    x_max = std::max(x_max, points[i].x);
                }
                candi1 *= (x_max - x_min);
            }
            long long candi2 = points[tmp_points[left + k - 1]].y - points[tmp_points[left]].y;
            {
                long long x_min = 2000000000000, x_max = 0;
                for (int i = left; i < right; i++)
                {
                    if (tmp_points[i] >= left + k) continue;
                    x_min = std::min(x_min, points[i].x);
                    x_max = std::max(x_max, points[i].x);
                }
                candi2 *= (x_max - x_min);
            }
            min = std::min(min, std::min(candi1, candi2));
        }
    }
    printf("%lld\n", min);
  	return 0;
}

