    if(sa == a[l+1].first-a[l].first){

      REP(j,b.size()){
	if(b[j].first == a[l].second && b[j].second == b[l].first){
	  b.erase(b.begin()+j);
	  break;
	}
      }
      a.erase(a.begin()+l);
    }
    else if(sa == a[r].first-a[r-1].first){
      REP(j,b.size()){
	if(b[j].first == a[r].second && b[j].second == b[r].first){
	  b.erase(b.begin()+j);
	  break;
	}
      }
      a.erase(a.begin()+r);
    }
    else if(sa == b[u].first-b[u-1].first){
      REP(j,a.size()){
	if(a[j].first == b[u].second && a[j].second == b[u].first){
	  a.erase(a.begin()+j);
	  break;
	}
      }
      b.erase(b.begin()+u);
    }
    else if(sa == b[d+1].first-b[d].first){
       REP(j,a.size()){
	if(a[j].first == b[u].second && a[j].second == b[u].first){
	  a.erase(a.begin()+j);
	  break;
	}
      }
      b.erase(b.begin()+d);
    }


  }
  //cout << l << "  " << r << "  " << u << "  " << d << endl;
  cout << (a[a.size()-1].first-a[0].first)*(b[b.size()-1].first-b[0].first) << endl;
  return 0;
}

