int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    int n, ub;
    cin >> n >> ub;
    vector<pair<int, int>> p(n);
    for (int i = 0; i < n; ++i)
        cin >> p[i].first >> p[i].second;

    ll min_area = 4 * 1e9 * 1e9;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int k = 0; k < n; ++k) {
                for (int t = 0; t < n; ++t) {
                    ll u = max({p[i].first, p[j].first, p[k].first, p[t].first});
                    ll b = min({p[i].first, p[j].first, p[k].first, p[t].first});
                    ll r = max({p[i].second, p[j].second, p[k].second, p[t].second});
                    ll l = min({p[i].second, p[j].second, p[k].second, p[t].second});

                    int cnt = 0;
                    for (int s = 0; s < n; ++s) {
                        if (b <= p[s].first && p[s].first <= u
                            && l <= p[s].second && p[s].second <= r) ++cnt;
                    }
                    if (ub <= cnt) min_area = min(min_area, (u - b) * (r - l));
                }
            }
        }
    }

    cout << min_area << endl;

    return 0;
}

