using P=pair<ll,ll>;

bool check(P p,ll sx,ll gx,ll sy,ll gy){
  ll x=p.first;
  ll y=p.second;
  return sx<=x and x<=gx and sy<=y and y<=gy;
}

ll mycount(vector<P>&v,ll sx,ll gx,ll sy,ll gy){
  ll n=v.size();
  ll ret=0;
  rep(i,n){
    if(check(v[i],sx,gx,sy,gy))ret++;
  }
  return ret;
}

void solve(){
  ll n,k;cin>>n>>k;
  vector<P>v(n);
  ll ans=__LONG_LONG_MAX__;
  rep(i,n)cin>>v[i].first>>v[i].second;
  rep(a,n)rep(b,n)rep(c,n)rep(d,n){
    ll sx=v[a].first;
    ll gx=v[b].first;
    ll sy=v[c].second;
    ll gy=v[d].second;
    if(mycount(v,sx,gx,sy,gy)>=k){
      ans=min(ans,abs(sx-gx)*abs(sy-gy));
    }
  }
  cout<<ans<<endl;
}

