using namespace std;
typedef long long LL;
const int inf = 1 << 30;
const LL INF = 1LL << 62;

int n, k;
struct Point {
	LL x, y;
	bool friend operator < (const Point a, const Point b) {
		if(a.x == b.x) return a.y < b.y;
		else return a.x < b.x;
	}
}PP[55];

void solve() {
	LL ans = INF;
	for(int l = 1; l <= n; l++) {
		for(int r = l; r <= n; r++) {
			if(r - l + 1 >= k) {
				LL up = -INF, down = INF;
				LL L = INF, R = -INF;
				for(int i = l; i + k - 1 <= r; i++) {
					up = max(up, PP[i].y);
					down = min(down, PP[i].y);
					L = min(L, PP[i].x);
					R = max(R, PP[i].x);
				}
				//printf("up = %d down = %d L = %d R = %d\n", up, down, L, R);
				ans = min(ans, (up - down) * (R - L));
			}
		}
	}
	printf("%lld\n", ans);
}

int main()
{
	while(scanf("%d %d", &n, &k) != EOF)
	{
		for(int i = 1; i <= n; i++) {
			scanf("%lld %lld", &PP[i].x, &PP[i].y);
		}
		sort(PP + 1, PP + n + 1);
		//for(int i = 1; i <= n; i++)
		//	printf("%lld %lld\n", PP[i].x, PP[i].y);
		solve();
	}
	return 0;
}

