bool containsKPoints(vector<pair<ll, ll> >& points, pair<ll, ll>& point1, pair<ll, ll>& point2,
        pair<ll, ll>& point3, pair<ll, ll>& point4, int K) {
    int count = 0;
    ll xbig = max(max(max(point1.first, point2.first), point3.first), point4.first);
    ll xsmall = min(min(min(point1.first, point2.first), point3.first), point4.first);
    ll ybig = max(max(max(point1.second, point2.second), point3.second), point4.second);
    ll ysmall = min(min(min(point1.second, point2.second), point3.second), point4.second);
    for (int i = 0; i < points.size(); ++i) {
        pair<ll, ll> candidate = points[i];
        ll x = candidate.first;
        ll y = candidate.second;
        if (xsmall <= x && x <= xbig && ysmall <= y && y <= ybig) {
            count++;
        }
    }
    return K <= count;
}

long long computeArea(pair<ll, ll>& point1, pair<ll, ll>& point2, pair<ll, ll>& point3, pair<ll, ll>& point4) {
    ll xbig = max(max(max(point1.first, point2.first), point3.first), point4.first);
    ll xsmall = min(min(min(point1.first, point2.first), point3.first), point4.first);
    ll ybig = max(max(max(point1.second, point2.second), point3.second), point4.second);
    ll ysmall = min(min(min(point1.second, point2.second), point3.second), point4.second);

    ll area = (xbig - xsmall) * (ybig - ysmall);
    if (area < 0) {
        return area * -1;
    } else {
        return area;
    }
}

int main(){
    int N, K;
    cin >> N >> K;

    vector<pair<long long, long long> > points;
    long long x, y;
    repeat(i,N) {
        cin >> x >> y;
        pair<long long, long long> point(x, y);
        points.push_back(point);
    }

    long long area = 100000000000;
    for (int i = 0; i < points.size(); ++i) {
        for (int j = i + 1; j < points.size(); ++j) {
            for (int k = j + 1; k < points.size(); ++k) {
                for (int l = k + 1; l < points.size(); ++l) {
                    long long tmpArea = computeArea(points[i], points[j], points[k], points[l]);
                    if (containsKPoints(points, points[i], points[j], points[k], points[l], K) && tmpArea < area) {
                        area = tmpArea;
                    }
                }
            }
        }
    }
    cout << area << endl;
    return 0;
}

