                break;
            }
        }

        for (i = 0; i < n; i++) {
            if (!yMax[i]->isOut) {
                bottom = yMax[i]->y;

                break;
            }
        }

        width = _abs(right - left);
        height = _abs(bottom - top);
        area = width * height;

        if (k == num) {
            ans = area;

            break;
        }

        for (i = 0; i < len; i++) {
            if (!xMin[i]->isOut) {
                newLeft = xMin[i + 1]->x;
                area1 = _abs(right - newLeft) * height;
                xMin[i]->isOut = true;

                break;
            }
        }

        for (i = 0; i < len; i++) {
            if (!xMax[i]->isOut) {
                newRight = xMax[i + 1]->x;
                area2 = _abs(newRight - left) * height;
                xMax[i]->isOut = true;

                break;
            }
        }

        for (i = 0; i < len; i++) {
            if (!yMin[i]->isOut) {
                newTop = yMin[i + 1]->y;
                area3 = width * _abs(bottom - newTop);
                yMin[i]->isOut = true;

                break;
            }
        }

        for (i = 0; i < len; i++) {
            if (!yMax[i]->isOut) {
                newBottom = yMax[i + 1]->y;
                area4 = width * _abs(newBottom - top);
                yMax[i]->isOut = true;

                break;
            }
        }

        gap1 = area - area1;
        gap2 = area - area2;
        gap3 = area - area3;
        gap4 = area - area4;

        minArea = max(gap1, max(gap2, max(gap3, gap4)));

        if (minArea == gap1) {
            for (i = 0; i < len; i++) {
                if (xMax[i]->isOut && !xMax[i + 1]->isOut) xMax[i]->isOut = false;
                if (yMin[i]->isOut && !yMin[i + 1]->isOut) yMin[i]->isOut = false;
                if (yMax[i]->isOut && !yMax[i + 1]->isOut) yMax[i]->isOut = false;
            }

            ans = area1;
        } else if (minArea == gap2) {
            for (i = 0; i < len; i++) {
                if (xMin[i]->isOut && !xMin[i + 1]->isOut) xMin[i]->isOut = false;
                if (yMin[i]->isOut && !yMin[i + 1]->isOut) yMin[i]->isOut = false;
                if (yMax[i]->isOut && !yMax[i + 1]->isOut) yMax[i]->isOut = false;
            }

            ans = area2;
        } else if (minArea == gap3) {
            for (i = 0; i < len; i++) {
                if (xMin[i]->isOut && !xMin[i + 1]->isOut) xMin[i]->isOut = false;
                if (xMax[i]->isOut && !xMax[i + 1]->isOut) xMax[i]->isOut = false;
                if (yMax[i]->isOut && !yMax[i + 1]->isOut) yMax[i]->isOut = false;
            }

            ans = area3;
        } else if (minArea == gap4) {
            for (i = 0; i < len; i++) {
                if (xMin[i]->isOut && !xMin[i + 1]->isOut) xMin[i]->isOut = false;
                if (xMax[i]->isOut && !xMax[i + 1]->isOut) xMax[i]->isOut = false;
                if (yMin[i]->isOut && !yMin[i + 1]->isOut) yMin[i]->isOut = false;
            }

            ans = area4;
        }

        num--;
    }

    cout << ans << '\n';

    for (i = 0; i < n; i++) delete points[i];

    return 0;
}

