void solve(){
  // main algorithm
  ans = INFLL;
  for (int i = 0; i < N; ++i)
  {
    for (int j = i ; j < N; ++j)
    {
      for (int k = j; k < N; ++k)
      {
        for (int l = k; l < N ; ++l)
        {
          ll x1 = min(min(A[i], A[j]), min(A[k], A[l])),
          x2 = max(max(A[i], A[j]), max(A[k], A[l])),
          y1 = min(min(B[i], B[j]), min(B[k], B[l])),
          y2 = max(max(B[i], B[j]), max(B[k], B[l]));
          debug("count_inside(%d, %d, %d, %d) = %d\n", i, j, k, l, count_inside(x1, x2, y1, y2));
          if(count_inside(x1, x2, y1, y2) >= K){
            ll area = calc_area(x1, x2, y1, y2);
            debug("area(%d, %d, %d, %d) = %lld\n", i, j, k, l, area);
            if(area < ans) ans = area;
          }
        }
      }
    }
  }
}
void solve2(){
  // calc sum 2dim
  map<ll, int> ord_x, ord_y;
  for (int i = 0; i < N; ++i)
  {
    ord_x.insert(lp{A[i], 0});
    ord_y.insert(lp{B[i], 0});
  }
  int order = 0;
  for(auto&& p : ord_x) {
    p.second = order;
    ++order;
  }
  order = 0;
  for(auto&& p : ord_y) {
    p.second = order;
    ++order;
  }
  for (int i = 0; i < N; ++i)
  {
    sum[ord_x[A[i]] + 1][ord_y[B[i]] + 1]++; // 番兵法
  }

  #ifdef DEBUG
  debug("DEPLOYMENT:\n");
  for (int y = N; y > 0; --y)
  {
    for (int x = 1; x <= N; ++x)
    {
      printf("%c", sum[x][y] ? '*' : '.');
    }
    printf("\n");
  }
  #endif

  for (int i = 1; i <= N; ++i)
  {
    for (int j = 1; j <= N; ++j)
    {
      sum[i][j] += sum[i][j-1];
    }
  }
  for (int j = 1; j <= N; ++j)
  {
    for (int i = 1; i <= N; ++i)
    {
      sum[i][j] += sum[i-1][j];
    }
  }


  #ifdef DEBUG
  debug("SUM 2D:\n");
  for (int y = N; y > 0; --y)
  {
    for (int x = 1; x <= N; ++x)
    {
      printf("%d ", sum[x][y]);
    }
    printf("\n");
  }
  #endif

  // search
  ans = INFLL;
  for (int x1 = 0; x1 < N ; ++x1)
  {
    for (int x2 = x1; x2 < N; ++x2)
    {
      for (int y1 = 0; y1 < N ; ++y1)
      {
        for (int y2 = y1; y2 < N; ++y2)
        {
          ll xx1 = min(A[x1], A[x2]),
          xx2 = max(A[x1], A[x2]),
          yy1 = min(B[y1], B[y2]),
          yy2 = max(B[y1], B[y2]);
          int cnt = sum[ord_x[xx2] + 1][ord_y[yy2] + 1]
          - sum[ord_x[xx1]][ord_y[yy2] + 1]
          - sum[ord_x[xx2] + 1][ord_y[yy1]]
          + sum[ord_x[xx1]][ord_y[yy1]];
          // DUMP(sum[ord_x[xx2] + 1][ord_y[yy2] + 1]);
