int main(int argc, char const *argv[]) {
  int n, k;
  std::cin >> n >> k;

  std::vector<long> x;
  std::vector<long> y;

  for (size_t i = 0; i < n; i++) {
    long tmp_x, tmp_y;
    std::cin >> tmp_x >> tmp_y;

    x.push_back(tmp_x);
    y.push_back(tmp_y);
  }

  sort(x.begin(), x.end());
  sort(y.begin(), y.end());

  int min_x_idx = 0;
  int max_x_idx = x.size()-1;
  int min_y_idx = 0;
  int max_y_idx = y.size()-1;

  int count = n;
  long long area = (x.at(max_x_idx) - x.at(min_x_idx)) * 
                   (y.at(max_y_idx) - y.at(min_y_idx));

  while (count > k) {
    // 次の候補を探す
    long dxl = x.at(min_x_idx+1) - x.at(min_x_idx);
    long dxr = x.at(max_x_idx) - x.at(max_x_idx-1);
    long dyl = y.at(min_y_idx+1) - y.at(min_y_idx);
    long dyr = y.at(max_y_idx) - y.at(max_y_idx-1);

    long maximum = max({dxl, dxr, dyl, dyr});
    if (maximum == dxl) {
      min_x_idx++;
    } else if (maximum == dxr) {
      max_x_idx--;
    } else if (maximum == dyl) {
      min_y_idx++;
    } else if (maximum == dyr) {
      max_y_idx--;
    }
    count--;
    area = (x.at(max_x_idx) - x.at(min_x_idx)) * 
           (y.at(max_y_idx) - y.at(min_y_idx));
  }

  std::cout << area << '\n';

}

