  vector<ll> px(N), py(N);
  for (int i = 0; i < N; ++i) {
    scanf("%lld %lld", &X[i], &Y[i]);
    px[i] = X[i], py[i] = Y[i];
  }
  sort(X.begin(), X.end());
  sort(Y.begin(), Y.end());
  ll ans = numeric_limits<ll>::max();
  for (int i = 0; i < N; ++i) {
    for (int j = i + 1; j < N; ++j) {
      for (int k = 0; k < N; ++k) {
        for (int l = k + 1; l < N; ++l) {
          int cnt = 0;
          ll left = X[i], right = X[j];
          ll bottom = Y[k], top = Y[l];
          for (int p = 0; p < N; ++p) {
