using namespace std;
#define MOD 998244353
#define INF 0x3f3f3f3f3f3f3f3f
#define LL long long
#define MX 55
struct Node
{
    LL x, y;
    bool operator < (const Node &b)const{
        return x<b.x;
    }
}pt[MX];

int k, n;

bool check(LL xa ,LL xb ,LL ya, LL yb,int p)
{
    if (pt[p].x>=xa&&pt[p].x<=xb&&
        pt[p].y>=ya&&pt[p].y<=yb) return 1;
    return 0;
}

LL func(int u, int v)
{
    LL res = INF;
    for (int i=1;i<=n;i++)
    {
        for (int j=1;j<=n;j++)
        {
            LL minx = min( min( min(pt[u].x,pt[v].x), pt[i].x) ,pt[j].x);
            LL maxx = max( max( max(pt[u].x,pt[v].x), pt[i].x) ,pt[j].x);
            LL miny = min( min( min(pt[u].y,pt[v].y), pt[i].y) ,pt[j].y);
            LL maxy = max( max( max(pt[u].y,pt[v].y), pt[i].y) ,pt[j].y);
            int tot = 0;
            for (int z=1;z<=n;z++)
            {
                if (check(minx,maxx,miny,maxy,z)) tot++;
            }
            if (tot>=k)
                res = min(res, (maxy-miny)*(maxx-minx));
        }
    }
    return res;
}

int main()
{
    scanf("%d%d",&n,&k);
    for (int i=1;i<=n;i++)
    {
        scanf("%lld%lld",&pt[i].x, &pt[i].y);
    }
    sort(pt+1,pt+1+n);
    LL area = INF;
    for (int i=1;i<=n;i++)
        for (int j=1;j<=n;j++)
        {
            if (j==i) continue;
            area = min(area, func(i,j));
        }
    printf("%lld\n",area);
    return 0;
}

