typedef long long int ll;
ll N,K;

ll x[55];
ll y[55];


bool f(ll a,ll b, ll c, ll d){

  ll count = 0;

  for(ll i=0;i<N;i++){
    if(a<=x[i]&&
       x[i]<=b&&
       c<=y[i]&&
       y[i]<=d){
      count++;
    }
  }
  return count >=K;
}



int main() {

  cin>>N>>K;
  for( ll i = 0;i<N;i++)cin>>x[i]>>y[i];

  ll ret = 0x7fffffffffffffff;

  for( ll i=0;i<N;i++){
    for( ll j=0;j<N;j++){
      for( ll k=0;k<N;k++){
        for( ll l=0;l<N;l++){
          ll minx = min( min(x[i], x[j]), min(x[k], x[l]));
          ll maxx = max( max(x[i], x[j]), max(x[k], x[l]));
          ll miny = min( min(y[i], y[j]), min(y[k], y[l]));
          ll maxy = max( max(y[i], y[j]), max(y[k], y[l]));
          if(f(minx,maxx,miny,maxy)){

            ret = min(ret, (maxx-minx) * (maxy - miny));
          }
        }
      }
    }
  }

  cout << ret<<endl;


  return 0;
}

