template<class T>
struct compress{
  vector<T> xs;
  compress(const vector<T>& v){
    xs.reserve(v.size());
    for(T x : v) xs.push_back(x);
    sort(xs.begin(),xs.end());
    xs.erase(unique(xs.begin(),xs.end()) , xs.end());
  }

  int get(const T& x){
    return lower_bound(xs.begin(),xs.end(),x) - xs.begin();
  }
  int size(){
    return xs.size();
  }
  T& operator[](int i){
    return xs[i];
  }
};

template<typename T>
struct BIT2D{
  int H,W;
  vector<vector<T>> bit;
  BIT2D(int H,int W):H(H),W(W){
    bit.resize(H + 1 , vector<T>(W + 1 , 0));
  }
  // (a,b)にwを足す
  void add(int x,int y,T w){
    for(int a = (++y , ++x); a <= H; a += a & -a){
      for(int b = y ; b <= W; b += b & -b){
        bit[a][b] += w;
      }
    }
  }
  //  [(0,0) , (a,b)]の和　閉区間に注意！
  T sum(int x, int y){
    if(x < 0 || y < 0) return 0;
    if(x >= H) x = H - 1;
    if(y >= W) y = W - 1;
    T ret = 0;
    for(int a = (++y , ++x) ; a > 0; a -= a & -a){
      for(int b = y; b > 0; b -= b & -b){
        ret += bit[a][b];
      }
    }
    return ret;
  }

  // [(x1,y1) , (x2,y2)] の和 x1>x2の時はswap
  T sum(int x1,int y1, int x2, int y2){
    if(x1 > x2) swap(x1 , x2);
    if(y1 > y2) swap(y1 , y2);
    return sum(x2,y2)-sum(x2,y1-1)-sum(x1-1,y2)+sum(x1-1,y1-1);
  }
};

void solve(){
  ini(N , K);
  vp v(N); in(v);
  sort(all(v));
  ll ans = 5e18;
  vl x(N) , y(N);
  rep(i , N) x[i] = v[i].fi , y[i] = v[i].se;
  compress<ll> zipx(x) , zipy(y);
  BIT2D<ll> bit(N + 1 , N + 1);
  rep(i , N) {
    trc(i , v[i].fi,v[i].se,zipx.get(v[i].fi) , zipy.get(v[i].se));
    bit.add(zipx.get(v[i].fi) , zipy.get(v[i].se) , 1);
  }
  rep(u,N) rep(d,N) rep(l,N) rep(r,N){
    if(u > d || l > r) continue;
    if(bit.sum(u,l,d,r) >= K) amin(ans , 
      (zipx[d] - zipx[u]) * (zipy[r] - zipy[l])
    );
  }
  out(ans);
}

