using namespace std;

template <class T>
using lim = numeric_limits<T>;

typedef long long ll;
typedef long double ld;

struct Coord{
	ll x;
	ll y;

	Coord(){
		x = y = 0;
	}

	Coord(ll _x, ll _y){
		x = _x;
		y = _y;
	}
};

bool compareX(const Coord& a, const Coord& b){
	if (a.x == b.x) return a.y < b.y;
	else return a.x < b.x;
}

bool compareY(const Coord& a, const Coord& b){
	if (a.y == b.y) return a.x < b.x;
	else return a.y < b.y;
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n, k;
	cin >> n >> k;


	Coord points[n];

	for(int i = 0; i < n; i++){
		cin >> points[i].x >> points[i].y;
	}

	// sort lexicographically according to x
	sort(points, points+n, compareX);

	ll areaX = lim<ll>::max();
	for(int i = 0; i < n-k+1; i++){
		ll minX = lim<ll>::max();
		ll maxX = lim<ll>::min();
		ll minY = lim<ll>::max();
		ll maxY = lim<ll>::min();
		for (int j = i; j < i+k; j++){
			minX = min(minX, points[j].x);
			maxX = max(maxX, points[j].x);
			minY = min(minY, points[j].y);
			maxY = max(maxY, points[j].y);
		}
		areaX = min(areaX,(maxX-minX)*(maxY-minY));
	}

	// sort lexicographically according to y
	sort(points, points+n, compareY);

	ll areaY = lim<ll>::max();
	for(int i = 0; i < n-k+1; i++){
		ll minX = lim<ll>::max();
		ll maxX = lim<ll>::min();
		ll minY = lim<ll>::max();
		ll maxY = lim<ll>::min();
		for (int j = i; j < i+k; j++){
			minX = min(minX, points[j].x);
			maxX = max(maxX, points[j].x);
			minY = min(minY, points[j].y);
			maxY = max(maxY, points[j].y);
		}
		areaY = min(areaY,(maxX-minX)*(maxY-minY));
	}

	cout << min(areaX, areaY) << endl;
}

