	template<class T>auto get_combination_array(int max)
	{
		boost::multi_array<T, 2> ret(boost::extents[max + 1][max + 1]);
		ret[0][0] = 1;
		for (int i = 1; i <= max; ++i)
		{
			ret[i][0] = 1;
			for (int j = 1; j < i; ++j)
			{
				ret[i][j] = ret[i - 1][j - 1] + ret[i - 1][j];
			}
			ret[i][i] = 1;
		}
		return ret;
	}

	auto irange(int start, int last)
	{
		return boost::irange(start, last);
	}
