    i64 K; RD(K);

    vector<i64> X(N);
    vector<i64> Y(N);
    REP(i, N) {
        RD(X[i]);
        RD(Y[i]);
    }
    DBG(X);
    DBG(Y);

    i64 ans = numeric_limits<i64>::max();
    for(i64 x0 : X) for(i64 x1 : X) for(i64 y0 : Y) for(i64 y1 : Y) {
        if(x0 > x1) swap(x0,x1);
        if(y0 > y1) swap(y0,y1);

        i64 cnt = 0;
        REP(i, N) {
            i64 x = X[i];
