bool judge(ll xi,ll xj,ll yi,ll yj){
    int ct = 0;
    rep(k,N){
        if((x[k] - xi)*(x[k]- xj) <= 0 && (y[k] - yi)*(y[k]- yj) <= 0) ct++;
    }
    if(ct >= K) return true;
    else return false;
}


