bool inout(pair<LL, LL> p1, pair<LL, LL> p2, pair<LL, LL> p3, pair<LL, LL> p4, pair<LL, LL> x) {
	LL a, b, c, d;
	a = min({ p1.first, p2.first,p3.first,p4.first });
	b = min({ p1.second, p2.second,p3.second,p4.second });
	c = max({ p1.first, p2.first,p3.first,p4.first });
	d = max({ p1.second, p2.second,p3.second,p4.second });
	if (a <= x.first && x.first <= c) {
		if (b <= x.second && x.second <= d) {
			return true;
		}
	}
	return false;
}

LL menseki(pair<LL, LL> p1, pair<LL, LL> p2, pair<LL, LL> p3, pair<LL, LL> p4) {
	LL a, b, c, d;
	a = min({ p1.first, p2.first,p3.first,p4.first });
	b = min({ p1.second, p2.second,p3.second,p4.second });
	c = max({ p1.first, p2.first,p3.first,p4.first });
	d = max({ p1.second, p2.second,p3.second,p4.second });

	return (c - a) * (d - b);
}

