const vector<int> dy = { 0, -1, 0, 1 };
const vector<int> dx = { 1, 0, -1, 0 };

int count(LL y1, LL y2, LL x1, LL x2, vector<long long> &x, vector<long long> &y) {
    if (y1 > y2) {
        swap(y1, y2);
    }
    if (x1 > x2) {
        swap(x1, x2);
    }
    int num = 0;
    FOR(i, 0, y.size()) {
        num += (y1 <= y[i] and y[i] <= y2) and (x1 <= x[i] and x[i] <= x2);
    }
    return num;
}

void solve(long long N, long long K, vector<long long> &x, vector<long long> &y){
    LL ans = LONG_LONG_MAX;

    FOR(y1, 0, y.size()) {
        FOR(y2, y1 + 1, y.size()) {
            FOR(x1, 0, x.size()) {
                FOR(x2, x1 + 1, x.size()) {
                    int num = count(y[y1], y[y2], x[x1], x[x2], x, y);
                    if (num >= K) {
                        ans = min<LL>(ans, abs(y[y1] - y[y2]) * abs(x[x1] - x[x2]));
                    }
                }
            }
        }
    }

    print(ans);
}

