    vector<long long> x(N-1+1);
    scanf("%lld",&K);
    for(int i = 0 ; i <= N-1 ; i++){
        scanf("%lld",&x[i]);
        scanf("%lld",&y[i]);
    }
    solve(N, K, x, y);
    return 0;
}

