	long long res = LLONG_MAX;
	for (int i=0; i<N; i++) {
		for (int j=0; j<N; j++) {
			if (x[i]>=x[j]) continue;
			for (int k=0; k<N; k++) {
				for (int l=0; l<N; l++) {
					if (y[k]>=y[l]) continue;
					int count = 0;
					for (int m=0; m<N; m++) {
						if (x[i] <= x[m] && x[m] <= x[j] && y[k] <= y[m] && y[m] <= y[l]) count++;
						if (count >= K) res = min(res, (x[j]-x[i])*(y[l]-y[k]));
					}
				}
			}
		}
	}
	cout << res << endl;
}

