#define LOG4(w,x,y,z) if(DEBUG)cout<<TO_STRING(w)<<"="<<w<<" "<<TO_STRING(x)<<"="<<x<<" "<<TO_STRING(y)<<"="<<y<<" "<<TO_STRING(z)<<"="<<z<<endl;

template<class T>bool chmax(T & a, const T & b) { if (a < b) { a = b; return 1; } return 0; }
template<class T>bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }

void func(long long N, long long K, std::vector<long long> x, std::vector<long long> y){

    vector<pair<lli,lli>> v;
    REP(i,0,N)v.push_back({x[i],y[i]});

    SORT(v);

    lli ans = INF;
    REP(i,0,N-K+1){
        lli x1 = v[i].first;
        lli x2 = v[i+K-1].first;

        lli y1 = INF,y2=-INF;
        REP(j,i,i+K){
            chmin(y1,v[j].second);
            chmax(y2,v[j].second);
        }
        LOG4(x1,x2,y1,y2);
        chmin(ans,abs(x1-x2)*abs(y1-y2));
    }

    v.clear();
    REP(i,0,N)v.push_back({y[i],x[i]});

    SORT(v);
    REP(i,0,N-K+1){
        lli x1 = v[i].first;
        lli x2 = v[i+K-1].first;

        lli y1 = INF,y2=-INF;
        REP(j,i,i+K){
            chmin(y1,v[j].second);
            chmax(y2,v[j].second);
        }
        chmin(ans,abs(x1-x2)*abs(y1-y2));
    }

    cout<<ans<<endl;

}

int main(){
    // cout << fixed << setprecision(5);

    long long N;
    scanf("%lld",&N);
    long long K;
    scanf("%lld",&K);
    std::vector<long long> x(N);
    std::vector<long long> y(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&x[i]);
        scanf("%lld",&y[i]);
    }
    func(N, K, std::move(x), std::move(y));
    return 0;
}

