using namespace std;
typedef long long LL;
const int inf = 1 << 30;
const LL INF = 1LL << 62;

int n, k;
struct Point {
	LL x, y;
	bool friend operator < (const Point a, const Point b) {
		if(a.x == b.x) return a.y < b.y;
		else return a.x < b.x;
	}
}PP[55];
LL ans;

void solve(LL l, LL r) {
	int tot = 0;
	LL Y[55];
	for(int i = 1; i <= n; i++)
		if(PP[i].x >= l && PP[i].x <= r)
			Y[++tot] = PP[i].y;
	sort(Y + 1, Y + tot + 1);
	if(tot < k) return;
	for(int i = 1; i <= tot - k + 1; i++) {
		ans = min(ans, (r - l) * (Y[i + k - 1] - Y[i]));
	}
}

int main()
{
	while(scanf("%d %d", &n, &k) != EOF)
	{
		ans = INF;
		for(int i = 1; i <= n; i++)
			scanf("%lld %lld", &PP[i].x, &PP[i].y);
		sort(PP + 1, PP + n + 1);
		for(int i = 1; i <= n; i++) {
			for(int j = i; j <= n; j++) {
					solve(PP[i].x, PP[j].x);
			}
		}
		printf("%lld\n", ans);
	}
	return 0;
}

