typedef long long ll;

const int INF = 1e9;
const ll LLINF = 1e18;
const ll MOD = (ll)1e9 + 7;

ll cal(vector<pair<ll, ll>> v, int N, int K)
{
  sort(v.begin(), v.end());
  ll ret = numeric_limits<ll>::max();
  for (int i = 0; i + K <= N; ++i) {
    for (int j = i + K - 1; j < N; ++j) {
      ll l = v[i].first, r = v[j].first;
      ll top = -LLINF, bottom = LLINF;
      for (int k = i; k <= j; ++k) {
        top = max(top, v[k].second);
        bottom = min(bottom, v[k].second);
      }
      ret = min(ret, abs(r - l) * abs(top - bottom));
    }
  }
  return ret;
}

int main()
{
  int N, K; scanf("%d %d", &N, &K);
  vector<pair<ll, ll>> C(N), D(N);
  for (int i = 0; i < N; ++i) {
    scanf("%lld %lld", &C[i].first, &C[i].second);
    D[i] = make_pair(C[i].second, C[i].first);
  }
  ll ans = min(cal(C, N, K), cal(D, N, K));
  printf("%lld\n", ans);
  return 0;
}

