using namespace std;

template<typename T> struct Compress {
	map<T, int>mp;
	map<int, T>revmp;

	Compress(vector<T>vs) {
		setmp(vs);
	}

	Compress() :mp(), revmp() {

	}
	void setmp(vector<T>vs) {
		sort(vs.begin(), vs.end());
		vs.erase(unique(vs.begin(), vs.end()), vs.end());
		for (int i = 0; i < static_cast<int>(vs.size()); ++i) {
			mp[vs[i]] = i;
			revmp[i] = vs[i];
		}
	}

};

int main() {
	int N,K;cin>>N>>K;
	vector<pair<long long int, long long int>>ps;
	vector<long long int>xs, ys;
	for (int i = 0; i < N; ++i) {
		long long int x,y;cin>>x>>y;
		ps.emplace_back(x, y);
		xs.emplace_back(x);
		ys.emplace_back(y);
	}
	Compress<long long int> xcomp, ycomp;
	xcomp.setmp(xs);
	ycomp.setmp(ys);
	for (auto&p : ps) {
		p.first = xcomp.mp[p.first];
		p.second = ycomp.mp[p.second];
	}
	vector<vector<int>>plus(51, vector<int>(51));
	for (auto p : ps) {
		plus[p.second][p.first]++;
	}
	vector<vector<int>>sum(51, vector<int>(51));
	for (int i = 1; i <= 50; ++i) {
		for (int j = 1; j <= 50; ++j) {
			sum[i][j] = sum[i - 1][j] + sum[i][j - 1] 
				- sum[i - 1][j - 1] + plus[i - 1][j - 1];
		}
	}
	long long int ans = 5e18;
	for (int l = 0; l < xcomp.mp.size(); ++l) {
		for (int r = l+1; r <=xcomp.mp.size(); ++r) {
			for (int u = 0; u < ycomp.mp.size(); ++u) {
				for (int d = u+1; d <= ycomp.mp.size(); ++d) {
					int num = sum[d][r] - sum[d][l] - sum[u][r] + sum[u][l];
					if (num >= K) {
						long long int lx = xcomp.revmp[l];
						long long int rx = xcomp.revmp[r - 1];
						long long int uy = ycomp.revmp[u];
						long long int dy = ycomp.revmp[d - 1];
						ans = min(ans, (rx - lx)*(dy - uy));
					}
				}
			}
		}
	}
	cout << ans << endl;


	return 0;
}

