void solve() {
	int N, K; cin >> N >> K;
	set<int> xS, yS;
	vector<pii> ps;
	REP(i, N) {
		int x, y; cin >> x >> y;
		ps.emplace_back(x, y);
		xS.insert(x);
		yS.insert(y);
	}

	unordered_map<int, int> xmap, ymap;
	unordered_map<int, int> xdecode, ydecode;
	{
		int i = 0;
		for (auto &a : xS) {
			xmap[a] = i;
			xdecode[i] = a;
			i++;
		}
		i = 0;
		for (auto &a : yS) {
			ymap[a] = i;
			ydecode[i] = a;
			i++;
		}
	}
	vector<vector<int> > field(ymap.size(),vector<int>(xmap.size()));
	for (auto &p : ps) {
		field[ymap[p.second]][xmap[p.first]] = 1;
	}
	REP(y, field.size()) {
		REP(x, field[y].size()-1) {
			field[y][x + 1] = field[y][x] + field[y][x + 1];
		}
	}
	REP(y, field.size()-1) {
		REP(x, field[y].size()) {
			field[y+1][x] = field[y][x] + field[y+1][x];
		}
	}

	int res = inf;
	REP(ay, field.size()) REP(ax, field[ay].size()){
		FOR(by, ay + 1, field.size()) FOR(bx, ax + 1, field.size()) {
			int cnt = field[by][bx];
			if (ax - 1 >= 0) {
				cnt -= field[by][ax - 1];
			}
			if (ay - 1 >= 0) {
				cnt -= field[ay - 1][bx];
			}
			if (ax - 1 >= 0 and ay - 1 >= 0) {
				cnt += field[ay - 1][ax - 1];
			}
			if (cnt >= K) {
				res = min(res, (ydecode[by] - ydecode[ay])*(xdecode[bx] - xdecode[ax]));
			}
		}
	}
	cout << res << endl;
}

