ll mod_inv(ll a, ll m) {
    ll b = m, u = 0, v = 1;
    while(a) {
        ll t = b / a;
        swap(b -= t * a, a);
        swap(u -= t * v, v);
    }

    return (u % m + m) % m;
}

ll gcd(ll a, ll b) {
    if(b == 0) return a;
    return gcd(b, a%b);
}

struct RECT{
    ll l;
    ll r;
    ll t;
    ll b;

    RECT(){}
    RECT(ll x1, ll y1) :
    l(x1), r(x1), t(y1), b(y1) {}

    ll sq() {
        return (r - l) * (t - b);
    }

    void update(ll x, ll y) {
        if (x > r) r = x;

        if (x < l) l = x;

        if (y > t) t = y;

        if (y < b) b = y;
    }

    void print() {
        cout << l << " " << r << " " << t << " " << b << " " << endl;
    }
};

inline ll sq(ll r, ll l, ll t, ll b) {
    assert(r >= l);
    assert(t >= b);
    return (r - l) * (t - b);
}


