using namespace std;

const int maxn=60;
typedef long long LL;

struct Point
{
	int x, y;

	bool operator < (const Point tmp) const
	{
		return x<tmp.x;
	}
};

int n, m;
Point p[maxn];
int h[maxn];
LL ans;

void read()
{
	scanf("%d%d", &n, &m);
	for (int i=1; i<=n; ++i)
		scanf("%d%d", &p[i].x, &p[i].y);
	sort(p+1, p+1+n);
}
void solve()
{
	h[1]=1;
	for (int i=2; i<=n; ++i)
		if (p[i].x==p[i-1].x) h[i]=h[i-1];
		else h[i]=i;

	ans=LL(1e19);
	for (int i=1; i<=n; ++i)
		for (int j=1; j<=n; ++j)
			for (int k=1; k<=n; ++k) 
			{
				int s=0;
				for (int o=h[k]; o<=n; ++o)
				{
					if (p[i].y<=p[o].y && p[o].y<=p[j].y) ++s;
					if (s>=m)
					{
						ans=min(ans, (LL(p[j].y-p[i].y))*(LL(p[o].x-p[k].x)));
						break;
					}
				}
			}
	printf("%lld\n", ans);
}
int main()
{
	read();
	solve();
	return 0;
}

