signed main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
    int N, K; cin >> N >> K;
    pair<ll, ll> p[55];
    rep(i, N) {
        cin >> p[i].fr >> p[i].sc;
    }
    sort(p, p + N);
    int ans = INF;
    rep(i, N) {
        if(i + K - 1 < N - 1) break;
        int ymin = -inf, ymax = inf;
        for(int j = i; j <= i + K - 1; j++) {
            ymin = min(ymin, p[j].sc);
            ymax = max(ymax, p[j].sc);
        }
        ans = min(ans, (p[i + K - 1].fr - p[i].fr) * (ymax - ymin));
    }
    cout << ans << endl;
	return 0;
}

