const long long INF = 9223372036854775807;
const int MAX = 50;

int main() {
	int N, K;
	vector<pair<long long, long long>> point;
	long long ans = INF;

	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		long long x, y;
		cin >> x >> y;
		point.push_back(make_pair(x, y));
	}

	sort(point.begin(), point.end());

	for (int b = 0; b < N - 1; b++) {
		for (int e = b + 1; e < N; e++) {

			vector<long long> py;
			for (int i = b; i <= e; i++) {
				py.push_back(point[i].second);
			}

			sort(py.begin(), py.end());

			long long x = abs(point[b].first - point[e].first);
			long long y = INF;

			for (int i = 0; i < (int)py.size() - (K - 1) ; i++) {
				y = min(abs(py[i + (K - 1)] - py[i]), y);
			}

			if (y == INF)continue;
			ans = min(ans, x * y);
		}
	}

	cout << ans << endl;

	return 0;
}

