using namespace std;

int main()
{
    int64_t N, K;
    std::cin >> N >> K;

    struct P {
        int64_t x;
        int64_t y;
    };

    std::vector<P> p;
    for (decltype(N) i = 0; i < N; ++i) {
        int64_t x, y;
        std::cin >> x >> y;
        p.push_back({x, y});
    }

    std::sort(std::begin(p), std::end(p),
              [](const auto& a, const auto& b) {
                  return a.x < b.x;
              });

    int64_t S = INT64_MAX;

    for (size_t i = 0; i <= N - K; ++i) {
        // x方向にK個
        auto mm = std::minmax_element(p.begin()+i, p.begin()+i+K,
                                      [](auto a, auto b) {
                                          return a.y < b.y;
                                      });
        auto dd = (p[i+K-1].x - p[i].x) * (mm.second->y - mm.first->y);
        S = std::min(S, dd);
    }

    std::cout << S << std::endl;

    return 0;
}

