unordered_map<ll, ll> pr;
unordered_map<ll, ll> pr_;

ll S(set<ll>& w, set<ll>& h, ll k) {

	if (w.size() == k) {
		ll l = *w.begin();
		ll r = *w.rbegin();
		ll d = *h.begin();
		ll u = *h.rbegin();
		//cout << (r - l) << " " << (u - d) << "->" << (r - l)*(u - d)<< endl;
		return (r - l)*(u - d);
	}

	ll min = 1e20;
	{
		ll l_ = *w.begin();
		w.erase(w.begin());
		auto itr = h.find(pr[l_]);
		ll tmp = *itr;
		h.erase(itr);
		min = std::min(min, S(w, h, k));
		w.emplace(l_);
		h.emplace(tmp);
	}
	{
		ll r_ = *w.rbegin();
		w.erase(--w.end());
		auto itr = h.find(pr[r_]);
		ll tmp = *itr;
		h.erase(itr);
		min = std::min(min, S(w, h, k));
		w.emplace(r_);
		h.emplace(tmp);
	}
	{
		ll d_ = *h.begin();
		h.erase(h.begin());
		auto itr = w.find(pr_[d_]);
		ll tmp = *itr;
		w.erase(itr);
		min = std::min(min, S(w, h, k));
		w.emplace(tmp);
		h.emplace(d_);
	}
	{
		ll u_ = *h.rbegin();
		h.erase(--h.end());
		auto itr = w.find(pr_[u_]);
		ll tmp = *itr;
		w.erase(itr);
		min = std::min(min, S(w, h, k));
		w.emplace(tmp);
		h.emplace(u_);
	}

	return min;
}

