void solve() {
	int N,K;
	cin >> N >> K;
	vector<LL> X(N), Y(N);
	for (int i = 0; i < N; ++i) {
		cin >> X[i] >> Y[i];
	}
	LL ans = LINF;
	for (int x0 = 0; x0 < N; ++x0) {
		for (int x1 = 0; x1 < N; ++x1) {
			for (int y0 = 0; y0 < N; ++y0) {
				for (int y1 = 0; y1 < N; ++y1) {
					int cnt = 0;
					for (int i = 0; i < N; ++i) {
						if (X[x0] <= X[i] && X[i] <= X[x1] &&
							Y[y0] <= Y[i] && Y[i] <= Y[y1]) {
							++cnt;
						}
					}
					if (cnt >= K) {
						LL res = (X[x1] - X[x0]) * (Y[y1] - Y[y0]);
						if (ans > res) {
							ans = res;
						}
					}
				}
			}
		}
	}
	cout << ans << endl;
}

