	for (int i = 0; i < N; i++) {
		int x, y;
		cin >> x >> y;
		data[i] = make_pair(y, x);
		ys[i] = y;
		xs[i] = x;
	}
	sort(ys.begin(), ys.end());
	sort(xs.begin(), xs.end());
	ys.erase(unique(ys.begin(), ys.end()), ys.end());
	xs.erase(unique(xs.begin(), xs.end()), xs.end());

	ll ans = -1;
	for (int y1: ys) for (int y2 : ys) for (int x1 : xs) for (int x2 : xs) {
		if (y1 > y2 || x1 > x2) continue;
		int c = 0;
		for (int i = 0; i < N; i++) {
			if (data[i].first >= y1 && data[i].first <= y2 && data[i].second >= x1 && data[i].second <= x2) c++;
			if (c == K) break;
		}
		if (c < K) continue;
		ll temp = (ll)(y2 - y1) * (x2 - x1);
		if (ans == -1 || temp < ans) ans = temp;
	}
	cout << ans << endl;

	return 0;
}

