int K,N;
point A[MAXN];


int calk ( int xh, int xl, int yh, int yl )
{
  int ans = 0;
  if ( xh < xl ) swap(xh,xl);
  if ( yh < yl ) swap(yh,yl);
  //printf("%d, %d, %d, %d\n", xh, xl, yh, yl);
  for ( int i = 0; i < N; ++i ) {
    if ( A[i].x <= xh && A[i].x >= xl && A[i].y <= yh && A[i].y >= yl ) ++ans;
  }

  //cout << "ans = " << ans << "\n";
  return ans;
}

ll axis ( void )
{
   ll min = INF;

   for ( int i = 0; i < N; ++i ) {
     for ( int j = 0; j < N; ++j ) {
       if ( calk( A[i].x, A[j].x, A[i].y, A[j].y ) >= K ) {
         ll xdis, ydis;
         xdis = abs(A[i].x-A[j].x);
         ydis = abs(A[i].y-A[j].y);
         if ( min > xdis*ydis ) min = xdis*ydis;
       }
     }
   }

   return min;
}

int main()
{
  scanf("%d%d", &N,&K);
  for ( int i = 0; i < N; ++i ) {
    int x,y;
    scanf("%d%d", &x, &y);
    A[i] = { x,y};
  }

  cout << axis() << "\n";
}

