ll mycal(vl& cand) {
	sort(all(cand));
	ll ret = 1e18;
	for(int i=0; i+k<=sz(cand); ++i) {
		ret = min(ret, cand[i+k-1] - cand[i]);
	}
	return ret;
}

ll solve(int k) {
	vi order(n);
	rep(i,0,n) {
		order[i] = i;
	}
	sort(all(order), [&](int i, int j) {
		return px[i] < px[j];
	});
	ll ret = 4e18;
	for(int i=0; i+k<=n; ++i) {
		int idx = order[i];
		int jdx = order[i+k-1];
		ll w = px[jdx] - px[idx];
		vl cand;
		rep(j,i,i+k) {
			cand.pb(py[order[j]]);
		}
		ll h = mycal(cand);
		ret = min(ret, h * w);
	}
	sort(all(order), [&](int i, int j) {
		return py[i] < py[j];
	});
	for(int i=0; i+k<=n; ++i) {
		int idx = order[i];
		int jdx = order[i+k-1];
		ll h = py[jdx] - py[idx];
		vl cand;
		rep(j,i,i+k) {
			cand.pb(px[order[j]]);
		}
		ll w = mycal(cand);
		ret = min(ret, h * w);
	}
	return ret;
}

