using namespace std;
const long long INF = (1ull<<63) - 1;

struct P
{
	int x, y;
	P(int x=0, int y=0) : x(x), y(y) {}
	friend ostream &operator <<(ostream &os, const P &a) {
		return os << '(' << a.x << ',' << a.y << ')';
	}
	bool operator <(const P &r) const {
		if (x == r.x) return y < r.y;
		return x < r.x;
	}
};

int main() {
	int n, k;
	cin >> n >> k;
	vector<P> p(n);
	vector<int> x(n), y(n);
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
		p[i].x = x[i], p[i].y = y[i];
	}
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());
	long long ans = INF;
	for (int ix = 0; ix < n; ix++) {
		int xl = x[ix];
		for (int jx = ix; jx < n; jx++) {
			int xr = x[jx];
			for (int iy = 0; iy < n; iy++) {
				int yl = y[iy];
				for (int jy = iy; jy < n; jy++) {
					int yr = y[jy];
					int s = 0;
					for (P &e : p) {
						if (e.x >= xl && e.x <= xr && e.y >= yl && e.y <= yr) s++;
					}
					if (s >= k) {
						long long now = (long long)(xr - xl) * (yr - yl);
						ans = min(ans, now);
					}
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

