void solve() {
  int n, k;
  cin >> n >> k;
  vector<int> xs;
  vector<pii> v;
  for(int i = 0; i < n; i++) {
    int x, y;
    cin >> x >> y;
    v.emplace_back(x, y);
    xs.push_back(x);
  }
  sort(xs.begin(), xs.end());
  xs.resize(unique(xs.begin(), xs.end()) - xs.begin());
  ll ret = 4e18;
  for(int xR: xs) {
    for(int xL: xs) {
      if(xL > xR) continue;
      vector<int> ys;
      for(pii out: v) {
        if(out.first >= xL && out.first <= xR) ys.push_back(out.second);
