      sort(ys.begin(), ys.end());
      for(int i = k; i <= ys.size(); i++) {
        ll cand = xR - xL;
        cand *= (ys[i-1] - ys[i-k]);
        ret = min(ret, cand);
      }
    }
  }
  cout << ret << "\n";
}


