using namespace std;
#define LL long long

void solve(long long N, long long K, std::vector<long long> x, std::vector<long long> y){
    vector<pair<LL, LL>> xi(N), yi(N);
    for(LL i=0; i<N; i++)xi[i]=make_pair(x[i], i);
    for(LL i=0; i<N; i++)yi[i]=make_pair(y[i], i);
    sort(xi.begin(), xi.end());
    sort(yi.begin(), yi.end());

    vector<LL> invxi(N), invyi(N);
    for(LL i=0; i<N; i++)invxi[xi[i].second]=i+1;
    for(LL i=0; i<N; i++)invyi[yi[i].second]=i+1;

    // initialize
    vector<vector<LL>> tab(N+1, vector<LL>(N+1, 0));
    for(LL i=0; i<N; i++)tab[invxi[i]][invyi[i]]++;

    // accumulate
    for(LL i=0; i<=N; i++)for (LL j=1; j <=N; j++)tab[i][j]=tab[i][j-1]+tab[i][j];
    for(LL i=1; i<=N; i++)for (LL j=0; j <=N; j++)tab[i][j]=tab[i-1][j]+tab[i][j];

    x.emplace_back(LLONG_MIN); y.emplace_back(LLONG_MIN);
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    LL ans = (x[N]-x[1])*(y[N]-y[1]);
    for(LL x1=1; x1<=N; x1++){
        for(LL x2=x1; x2<=N; x2++) {
            for (LL y1=1; y1<=N; y1++) {
                for (LL y2=y1; y2<=N; y2++) {
                    LL k = tab[y2][x2]-tab[y2][x1-1]-tab[y1-1][x2]+tab[y1-1][x1-1];
                    if(k < K)continue;
                    LL area = (x[x2]-x[x1])*(y[y2]-y[y1]);
                    ans = min(ans, area);
                }
            }
        }
    }
    cout << ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long K;
    scanf("%lld",&K);
    std::vector<long long> x(N);
    std::vector<long long> y(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&x[i]);
        scanf("%lld",&y[i]);
    }
    solve(N, K, std::move(x), std::move(y));
    return 0;
}

