struct point { ll x, y; };

ll f(point a, point b, point c, point d, point e) {
  ll l = min({a.x, b.x, c.x, d.x});
  ll r = max({a.x, b.x, c.x, d.x});
  ll dn = min({a.y, b.y, c.y, d.y});
  ll u = max({a.y, b.y, c.y, d.y});
  if(e.x < l || e.x > r) return 0LL;
  if(e.y < dn || e.y > u) return 0LL;
  return (r - l) * (u - dn);
}

int main() {
  int N, K;
  cin >> N >> K;
  vector<point> p(N);
  rep(i, 0, N) {
    ll x, y;
    cin >> x >> y;
    p[i].x = x;
    p[i].y = y;
  }
  ll ans = 4e18;
  rep(i, 0, N-1) rep(j, i+1, N) rep(k, 0, N-1) rep(l, k+1, N)  {
    int cnt = 0;
    ll mn = 4e18;
    rep(m, 0, N) {
      ll tmp = f(p[i], p[j], p[k], p[l], p[m]);
      if(tmp) {
        cnt++;
        mn = min(mn, tmp);
      }
    }
    if(cnt >= K) ans = min(ans, mn);
  }
  cout << ans << endl;
  return 0;
}

