const ll MD = 10000000000;

/* sample input

*/
bool pairCompare(const P& A, const P& B)
{
	bool ret =false ;
	if (A.first > B.first) {
		ret = true;
	}
	else if(A.first == B.first){
		if (A.first > B.second) {
		ret = true;
		}
	}

	return ret;
}

int main()
{
	int n, k;
	vector<P> v;
	cin >> n >> k;
	v.resize(n+1);
	for (int i = 1; i <= n; i++) {
		P p;
		cin >> p.first >> p.second;
		v[i]=p;
	}

	sort(v.begin()+1, v.end(), pairCompare);

	ll w, h;

	ll answer = MD*MD;

	for (int i = 1; i <= n-k+1; i++) {
		w = v[i].first - v[i+k-1].first;
		ll miny, maxy;
		miny = MD;
		maxy = -MD;
		for (int j = i; j <= i + k - 1; j++) {
			miny = min(miny, v[j].second);
			maxy = max(maxy, v[j].second);
		}
		h = maxy - miny;
		answer = min(answer, w*h);
	}
	cout << answer;

	return 0;
}

