int main()
{
	int k, n;
	std::cin >> k >> n;

	long long int x[60], y[60];
	for (int i = 0; i < n; ++i)
	{
		std::cin >> x[i] >> y[i];
		x[i] += 1000000000;
		y[i] += 1000000000;
	}

	long long int max = LLONG_MAX;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			for (int ii = 0; ii < n; ++ii)
			{
				for (int jj = 0; jj < n; ++jj)
				{
					long long int left = std::min(std::min(x[i], x[j]), std::min(x[ii], x[jj])),
								  right = std::max(std::max(x[i], x[j]), std::max(x[ii], x[jj])),
								  top = std::max(std::max(y[i], y[j]), std::max(y[ii], y[jj])),
								  bottom = std::min(std::min(y[i], y[j]), std::min(y[ii], y[jj]));

					int count = 0;
					bool flag = false;
					for (int c = 0; c < n; ++c)
					{
						if (x[c] >= left && x[c] <= right && y[c] >= bottom && y[c] <= top)
							++count;

						if (count >= k)
						{
							flag = true;
							break;
						}
					}

					if (flag)
					{
						long long int value = abs(left - right) * abs(top - bottom);

						if (value < max)
							max = value;
					}
				}
			}
		}
	}

	std::cout << max;
}

