}
inline void InputF(double& v) {
	double dp = 1; int k = 1; bool adp = false; v = 0; char c; InputF(c);
	if (c == '-') { k = -1; c = gc(); }
	for (; isdigit(c) || c == '.'; c = gc()) {
		if (c == '.')adp = true;
		else if (adp)v += (c - '0') * (dp *= 0.1);
		else v = v * 10 + (c - '0');
	}
	v *= k;
}
