int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int N, K; cin >> N >> K;
  vpl dot(N);
  rep(i, 0, N) {
    cin >> dot[i].first >> dot[i].second;
  }

  sort(All(dot));

  ll ans = 4*LINF;
  rep(l, 0, N-1) {
    rep(i, 0, N) {
      rep(j, 0, N) {
        auto left = dot[l], i_dot = dot[i], j_dot = dot[j];
        int tmp = 0;
        ll minx = left.first;
        ll miny = min<ll>(min<ll>(i_dot.second, j_dot.second), left.second);
        ll maxy = max<ll>(max<ll>(i_dot.second, j_dot.second), left.second);
        int includes = 0;
        rep(k, l, N) {
          int x = dot[k].first, y = dot[k].second;
          if (minx <= x && miny <= y && y <= maxy) {
            includes++;
          }
          if (includes >= K) {
            ll area = (x - minx) * (maxy - miny);
            chmin(ans, area);
          }
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
};

