                if(x1<=x[k]&&x[k]<=x2)Y.emplace_back(y[k]);
            }
            sort(Y.begin(), Y.end());
            if(Y.size()<K)continue;
            ll H=INF;
            for(ll i=0;i<Y.size()-K+1;++i)chmin(H,Y[i+K-1]-Y[i]);
            chmin(ans,(x2-x1)*H);
        }
    }
    prt(ans)

    return 0;
}

