int compress(vector<int> x, map<int, int> &zip, vi &unzip) {
	sort(x.begin(), x.end());
	x.erase(unique(x.begin(), x.end()), x.end());
	for (int i = 0; i < x.size(); i++) {
		zip[x[i]] = i;
		unzip[i] = x[i];
	}
	return x.size();
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, K;
	cin >> N >> K;
	vi x(N), y(N);
	rep(i, N) {
		cin >> x[i] >> y[i];
	}

	map<int, int> xzip, yzip;
	vi xunzip(N), yunzip(N);

	int X = compress(x, xzip, xunzip);
	int Y = compress(y, yzip, yunzip);

	vvi cum(X+1, vi(Y+1,0));
	rep(i, N) {
		cum[xzip[x[i]]+1][yzip[y[i]]+1]++;
	}
	repr(i, 1, X + 1) rep(j, Y + 1){
		cum[i][j] += cum[i - 1][j];
	}
	rep(i, X + 1)repr(j, 1, Y + 1) {
		cum[i][j] += cum[i][j - 1];
	}
	ll ans = INFL;
	repr(x1, 1, X + 1)repr(x2, x1, X+1)repr(y1, 1, Y + 1)repr(y2, y1, Y+1) {
		if (cum[x2][y2] - cum[x1-1][y2] - cum[x2][y1-1] + cum[x1-1][y1-1] >= K) {
			ans = min(ans, ((ll)xunzip[x2 - 1] - xunzip[x1 - 1])*((ll)yunzip[y2 - 1] - yunzip[y1 - 1]));
		}
	}
	cout << ans << endl;

	return 0;
}

