int main()
{
	int N,K,i,a[2][50];
	long long int area;
	scanf("%d %d",&N,&K);
	for(i=0;i<N;i++) {
		scanf("%d %d",&a[0][i],&a[1][i]);
	}
	quicksort(a,0,N-1,0);
	int xa,xb,xi,xj,ya,yb,yi,yj;
	for(i=1,xa=a[0][0],xi=a[0][0],ya=a[1][0],yi=a[1][0],xb=xa,xj=xi,yb=ya,yj=yi;i<K;i++) {
		if(a[0][i]>xa) {
			xb=xa;
			xa=a[0][i];
		}
		if(a[0][i]<xi) {
			xj=xi;
			xi=a[0][i];
		}
		if(a[1][i]>ya) {
			yb=ya;
			ya=a[1][i];
		}
		if(a[1][i]<yi) {
			yj=yi;
			yi=a[1][i];
		}
	}
	area=(long long)(xa-xi)*(long long)(ya-yi);
	int j;
	for(j=K;j<N;j++) {
		if((a[0][j-K]==xa)&&(xb!=xa)) xa=xb;
		if((a[0][j-K]==xi)&&(xj!=xi)) xi=xj;
		if((a[1][j-K]==ya)&&(yb!=ya)) ya=yb;
		if((a[1][j-K]==yi)&&(yj!=yi)) yi=yj;
		if(a[0][j]>xa) {
			xb=xa;
			xa=a[0][j];
		}
		if(a[0][j]<xi) {
			xj=xi;
			xi=a[0][j];
		}
		if(a[1][j]>ya) {
			yb=ya;
			ya=a[1][j];
		}
		if(a[1][j]<yi) {
			yj=yi;
			yi=a[1][j];
		}
		if((long long)(xa-xi)*(long long)(ya-yi)<area) {
			area=(long long)(xa-xi)*(long long)(ya-yi);
		}
	}
	printf("%lld\n",area);
	return 0;
}

void quicksort(int a[2][50],int left,int right,int xory)
{
	if(left<right) {
		int i=left,j=right,tmp1,tmp2,nxy,pivot=a[xory][i];
		if(xory==0) {
			nxy=1;
		}else {
			nxy=0;
		}
		while(1) {
		while(a[xory][i]<pivot) i++;
		while(pivot<a[xory][j]) j--;
		if(i>=j)break;
		tmp1=a[xory][i];
		tmp2=a[nxy][i];
		a[xory][i]=a[xory][j];
		a[nxy][i]=a[nxy][j];
		a[xory][j]=tmp1;
		a[nxy][j]=tmp2;
		i++;
		j--;
		}
		quicksort(a,left,i-1,xory);
		quicksort(a,j+1,right,xory);
	}
}

