const ll INFTY = 4e18+1;

struct coord {ll x; ll y;};

int main() {
  int N, K;
  cin >> N >> K;
  coord point[N];
  rep(i,N) cin >> point[i].x >> point[i].y;

  ll ans = INFTY;

  /* width fixed */
  rep(i,N) {
    rep(j,i) {
      ll w = abs(point[i].x - point[j].x);
      ll h = abs(point[i].y - point[j].y);
      int count = 0;  // number of points in the rectangle
      vector<ll> high;
      vector<ll> low;

      rep(k,N) {
        if (point[k].x > max(point[i].x, point[j].x)) continue;  // out of range
        if (point[k].x < min(point[i].x, point[j].x)) continue;  // out of range
        if (point[k].y > max(point[i].y, point[j].y)) {
          high.push_back(point[k].y - max(point[i].y, point[j].y));
          continue;
        }
        if (point[k].y < min(point[i].y, point[j].y)) {
          low.push_back(min(point[i].y, point[j].y) - point[k].y);
          continue;
        }
        count++;
      }

      if (count >= K) {
        if (w*h < ans) ans = w*h;
        continue;
      }

      int res = K-count;
      if (high.size() + low.size() < res) continue;

      while (high.size() < res) high.push_back(INFTY);
      while (low.size() < res) low.push_back(INFTY);
      high.push_back(0);
      low.push_back(0);
      sort(high.begin(), high.end());
      sort(low.begin(), low.end());
      ll add_h = INFTY;

      rep(k,res+1) {
        if (high[k] + low[res-k] < add_h) {
          add_h = high[k] + low[res-k];
        }
      }

      if (w*(h+add_h) < ans) ans = w*(h+add_h);
    }
  }

  cout << ans << endl;
  return 0;
}

