int count(ll x0,ll y0,ll x1,ll y1){
    int D=lower_bound(All(pos),P(x0,y0))-pos.begin();
    int U=upper_bound(All(pos),P(x1,y1))-pos.begin();
    int ret=0;
    rep(i,D,U){
        if(y0<=pos[i].second&&pos[i].second<=y1) ret++;
    }
    return ret;
}

