unsigned int onesComplement(unsigned int n) 
{ 
   // Find number of bits in the given integer 
   int number_of_bits = floor(log2(n))+1; 

   // XOR the given integer with poe(2,  
   // number_of_bits-1 and print the result  
   return ((1 << number_of_bits) - 1) ^ n; 
}

void solve()
{   
    int n,k;
    cin>>n>>k;
    vector<pair<ll,ll>> points(n);
    for(auto &it : points)
        cin>>it.first>>it.second;
    sort(points.begin(),points.end(),comp);
    int ymin=0;
    int ymax=n-1;
    ull area=9999999999999999999;
    while(ymax>=ymin){
        vector<pair<ll,ll>> px(ymax-ymin+1);
        for(int i=0;i<px.size();++i)
            px[i]=points[i+ymin];
        sort(px.begin(),px.end());
        debug(px);
        ll maxy=INT_MIN;
        ll miny=INT_MAX;
        for(int i=0;i<k;++i){
            maxy=max(maxy,px[i].second);
            miny=min(miny,px[i].second);
        }
        for(int i=0;i<=px.size()-k;++i){
            for(int i=0;i<k;++i){
                maxy=max(maxy,px[i].second);
                miny=min(miny,px[i].second);
            }
            if(maxy==miny) maxy+=1;
            area=min(area,(ull)(maxy-miny)*(px[i+k-1].first-px[i].first));
        }
        while(ymax>0 && points[ymax]==points[ymax-1])
            --ymax;
        --ymax;
        while(ymin<n-1 && points[ymin]==points[ymin+1])
            ++ymin;
        ++ymin;
        if(ymax-ymin+1<k) break;

    }
    cout<<area;
}

