void solve(long long N, long long K, std::vector<long long> x, std::vector<long long> y){
    vector<pair<LL, LL> > points;
    REP(i, N) points.PB({x[i], y[i]});

    sort(ALL(points));
    sort(ALL(x));
    sort(ALL(y));

    LL ans = INFL;
    REP(lx, N) REP2(rx, lx+1, N) REP(uy, N) REP(dy, N) {
        LL res = (x[rx]-x[lx]) * (y[dy]-y[uy]);
