            if(x[lx] <= points[i].first && points[i].first <= x[rx] && y[uy] <= points[i].second && points[i].second <= y[dy]) {
                cnt++;
            }
        }

        if(K <= cnt) ans = min(ans, res);
    }

    cout << ans << endl;
}

