}

int main()
{
    cin >> N >> K;
    for(int i = 0; i < N; ++i) 
        cin >> dot[i].first >> dot[i].second;

    map<ll, int> x_index, y_index;
    sort(dot, dot + N);
    int xcnt = 0;
    for(int i = 0; i < N; ++i) {
        if(xcnt > 0 && X[xcnt-1] < dot[i].first) {
            X[xcnt] = dot[i].first;
            x_index[dot[i].first] = xcnt;
            ++xcnt;
        }
        else {
            X[xcnt] = dot[i].first; 
            x_index[dot[i].first] = xcnt;
            ++xcnt;
        }
    }
    sort(dot, dot + N, 
        [](pair<ll, ll> &x, pair<ll, ll> &y){ return x.second < y.second; });
    int ycnt = 0;
    for(int i = 0; i < N; ++i) {
        if(ycnt > 0  && Y[ycnt-1] < dot[i].second) {
            Y[ycnt] = dot[i].second;
            y_index[dot[i].second] = ycnt;
            ++ycnt;
