    for(int i = 0; i < xcnt; ++i) {
        for(int j = 0; j < ycnt; ++j) {
            cout << mp[i][j] << " ";
        }
        cout << endl;
    }
    */

    //2次元累積和
    for(int i = 0; i < xcnt; ++i) {
        for(int j = 1; j < ycnt; ++j) 
            mp[i][j] += mp[i][j-1];
    }
    for(int j = 0; j < ycnt; ++j) {
        for(int i = 1; i < xcnt; ++i)
            mp[i][j] += mp[i-1][j];
