typedef long long ll;
struct point {
    ll x,y;
    bool operator < (const point& t) const {
	if( x == t.x )
	    return y < t.y;
	return x < t.y;
    }
};

ll k_in(int xmin,int xmax,int ymin,int ymax,const vector<point>& ps, ll K) {
    ll in = 0;
    for(auto& e : ps) {
	if( xmin <= e.x and e.x <= xmax and ymin <= e.y and e.y <= ymax )
	    in++;
    }
    if(K <= in)
	return (xmax-xmin)*(ymax-ymin);
    return 1e+18;
}

int main () {
