    vector<point> ps;
    for(int i=0; i<N; i++) {
	ll a,b; cin >> a >> b;
	x.push_back(a);
	y.push_back(b);
	ps.push_back(point{a,b});
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    ll ans = 1e+18;
    for(int i=0; i<N; i++) {
	for(int j=i+1; j<N; j++) {
	    for(int k=0; k<N; k++) {
		for(int l=k+1; l<N; l++) {
		    ans = min(k_in(x[i],x[j],y[k],y[l],ps,K),ans);
		}
	    }
	}
    }
    cout << ans << endl;
    return 0;
}

