ll mini(ll a, ll b, ll c, ll d){ return min(a ,min(b ,min(c, d))); }
ll maxi(ll a, ll b, ll c, ll d){ return max(a ,max(b ,max(c, d))); }

int main(void){
    ll N, K;
    cin >> N >> K;
    vector<pair<ll, ll>> v(N);
    for(auto& it : v) cin >> it.first >> it.second;

    ull ans = 1L << 63;

    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            for(int k=0;k<N;k++){
                for(int l=0;l<N;l++){
                    pair<ll, ll> ul(mini(v[i].first, v[j].first, v[k].first, v[l].first), maxi(v[i].second, v[j].second, v[k].second, v[l].second));
                    pair<ll, ll> br(maxi(v[i].first, v[j].first, v[k].first, v[l].first), mini(v[i].second, v[j].second, v[k].second, v[l].second));
                    int c=0;
                    for(int a=0;a<N;a++){
                        if(ul.first <= v[a].first && v[a].first <= br.first
                        && ul.second >= v[a].second && v[a].second >= br.second) c++;
                    }

                    if(c >= K) ans = min(ans, (ull)abs(ul.first-br.first) * (ull)abs(ul.second-br.second));
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

