struct TPoint {
  int x;
  int y;
};

istream& operator >>(istream& in, TPoint& p) {
  in >> p.x >> p.y;
  return in;
}

int main() {
  auto start = high_resolution_clock::now();

  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  size_t n, k;
  cin >> n >> k;

  vector<TPoint> v(n);
  for (size_t i = 0; i < n; ++i)
    cin >> v[i];

  long long ans = (1LL << 63) - 1;
  for (size_t i1 = 0; i1 < n; ++i1) {
    for (size_t i2 = 0; i2 < n; ++i2) {
      for (size_t i3 = 0; i3 < n; ++i3) {
        int lx = min(v[i1].x, min(v[i2].x, v[i3].x));
        int rx = max(v[i1].x, max(v[i2].x, v[i3].x));
        int dy = min(v[i1].y, min(v[i2].y, v[i3].y));
        int uy = max(v[i1].y, max(v[i2].y, v[i3].y));

        vector<int> x;
        for (const TPoint& it : v) {
          if (lx <= it.x && it.x <= rx && dy <= it.y && it.y <= uy) {
            x.push_back(it.x);
          }
        }

        if (x.size() >= k) {
          ans = min(ans, 1LL * (x[k - 1] - lx) * (uy - dy));
        }
      }
    }
  }

  cout << ans << endl;

  cerr << "Total execution time : " << duration_cast<milliseconds>(high_resolution_clock::now() - start).count() << " ms" << endl;

  return 0;
}

