/* -----  2018/02/15  Problem: 075_abc_d / Link: https://abc075.contest.atcoder.jp/tasks/abc075_d?lang=en  ----- */
/* ------問題------

2次元座標上に N 個の点があります。
i(1≦i≦N) 番目の点の座標は (xi,yi) です。
長方形の内部に N 点のうち K 個以上の点を含みつつ、それぞれの辺がX軸かY軸に平行な長方形を考えます。
このとき、長方形の辺上の点は長方形の内部に含みます。
それらの長方形の中で、最小の面積となるような長方形の面積を求めてください。

-----問題ここまで----- */
/* -----解説等-----

O(N^5)、すき


----解説ここまで---- */

LL N,K;

LL ans = 0LL;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N>>K;
	VL x(N), y(N);
	VL xc(N), yc(N);
	FOR(i, 0, N) {
		cin >> x[i] >> y[i];
		xc[i] = x[i];
		yc[i] = y[i];
	}

	SORT(xc);
	SORT(yc);
	ans = (xc[N-1]- xc[0])*(yc[N - 1] - yc[0]);
	FOR(u1, 0, N) {
		FOR(u2, u1+1, N) {
			FOR(d1, 0, N) {
				FOR(d2, d1+1, N) {
					LL X = xc[u2] - xc[u1];
					LL Y = yc[d2] - yc[d1];
					int cnt = 0;
					FOR(i, 0, N) {
						if (xc[u1] <= x[i]
							&& x[i] <= xc[u2]
							&&yc[d1] <= y[i]
							&& y[i] <= yc[d2]
							)
							cnt++;
					}

					if (cnt >= K) {
						ans = min(ans, X*Y);
					}



				}
			}
		}
	}

	cout << ans << "\n";

	return 0;
}

