}Node2[200];
bool cmp1(struct node1 a,struct node1 b)
{
    return a.x<b.x;
}
bool cmp2(struct node2 a,struct node2 b)
{
    return a.y<b.y;
}
int main()
{
    int N,M;
    scanf("%d %d",&N,&M);
    for(int i=0;i<N;i++)
    {
        scanf("%lld %lld",&Node[i].x,&Node[i].y);
        Node2[i].x=Node[i].x;
        Node2[i].y=Node[i].y;
    }
    sort(Node,Node+N,cmp1);
    sort(Node2,Node2+N,cmp2);
    LL qqq1=MaxValue;
    LL qqq2=MaxValue;
    for(int i=0;i+M-1<N;i++)
    {
        int star=i;
        int end=i+M-1;
        LL maxx=-MaxValue;
        LL minn=MaxValue;
        for(int k=star;k<=end;k++)
        {
            maxx=max(maxx,Node[k].y);
            minn=min(minn,Node[k].y);
        }
        LL a=maxx-minn;
        LL b=Node[end].x-Node[star].x;
        LL flag1=((a%Mo)*b)/Mo;
        LL s2=((a%Mo)*b)%Mo;
        LL s1=flag1+a/Mo*b;
        if(qqq1>s1 ||(qqq1==s1 && qqq2>s2))
        {
            qqq1=s1;
            qqq2=s2;
        }
        maxx=-MaxValue;
        minn=MaxValue;
        for(int k=star;k<=end;k++)
        {
            maxx=max(maxx,Node2[k].x);
            minn=min(minn,Node2[k].x);
        }
        a=maxx-minn;
        b=Node2[end].y-Node2[star].y;
        flag1=((a%Mo)*b)/Mo;
        s2=((a%Mo)*b)%Mo;
        s1=flag1+a/Mo*b;
        if(qqq1>s1 ||(qqq1==s1 && qqq2>s2))
        {
            qqq1=s1;
            qqq2=s2;
        }
    }
    if(qqq1)
