        cin >> x[i] >> y[i];
    }
    for(int i=0;i<n;i++){
        for(int j=i+1;j<n;j++){
            int xmn = min(x[i], x[j]);
            int xmx = max(x[i], x[j]);
            int ymn = min(y[i], y[j]);
            int ymx = max(y[i], y[j]);
            int zs;
            long long X = xmx - xmn;
