    ll s = (x[i + K - 1].first - x[i].first) * (ymax - ymin);
    if (s != 0) ans = min(ans, s);
  }
  for (int i = 0; i < N - K + 1; i++) {
    ll xmin = INF, xmax = -INF;
    for (int j = 0; j < K; j++) {
      xmin = min(xmin, p[y[i + j].second].first);
      xmax = max(xmax, p[y[i + j].second].first);
    }
    ll s = (y[i + K - 1].first - y[i].first) * (xmax - xmin);
    if (s != 0) ans = min(ans, s);
  }

  cout << ans << endl;
}

