void build(bool xx, map<int, int> &id, map<int, int> &rev) {
    set<int> all;
    for(auto p : points) {
        int x, y;
        tie(x, y) = p;
        if(xx) {
            all.insert(x);
        }
        else {
            all.insert(y);
        }
    }

    int av = 0;
    for(int k : all) {
        id[k] = av;
        rev[av] = k;
        av++;
    }
}

map<int, int> idx, revx;
map<int, int> idy, revy;

vector<int> adj[N];
void init() {
    build(true, idx, revx);
    build(false, idy, revy);

    for(auto p : points) {
        int x = idx[p.first];
        int y = idy[p.second];
        adj[x].push_back(y);
    }
    fori(i, 0, N) {
        sort(adj[i].begin(), adj[i].end());
    }
}

inline int many(int x, int y1, int y2) {
    auto ata = lower_bound(adj[x].begin(), adj[x].end(), y1);
    if(ata == adj[x].end() or (ata != adj[x].end() and *ata > y2)) return 0;

    int a = ata - adj[x].begin();

    auto atb = lower_bound(adj[x].begin(), adj[x].end(), y2);
    if(atb == adj[x].end() or (atb != adj[x].end() and *atb > y2)) {
        --atb;
    }
    int b = atb - adj[x].begin();
    int res = b - a + 1;
    return max(0, res);
}

inline int many(int x1, int x2, int y1, int y2) {
    int res = 0;
    fori(i, x1, x2 + 1) {
        res += many(i, y1, y2);
    }
    return res;
}

