inline ll solve() {
    ll ans = 1LL << 62;
    fori(x1, 0, N) {
        if(revx.find(x1) == revx.end()) continue;

        fori(x2, x1, N) {
            if(revx.find(x2) == revx.end()) continue;

            fori(y1, 0, N) {
                if(revy.find(y1) == revy.end()) continue;

                fori(y2, y1, N) {
                    if(revy.find(y2) == revy.end()) continue;

                    int cont = many(x1, x2, y1, y2);
                    if(cont >= k) {
                        ll area = ((ll) revx[x2] - revx[x1]) * ((ll) revy[y2] - revy[y1]);

                        ans = min(ans, area);
                    }
                }
            }
        }
    }
    return ans;
}

