int main() {
    int N, K;
    cin >> N >> K;

    vector<point> P;
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        P.push_back((point){x, y});
    }
    ll ans = 2e9 * 2e9 + 1;
    for (int l = 0; l < N; l++) {
        for (int r = 0; r < N; r++) {
            if (l == r) continue;
            if (P[l].x >= P[r].x) continue;
            for (int u = 0; u < N; u++) {
