ll calc_S(int i, int j, int k){
    ll x[3] = {point[i].first, point[j].first, point[k].first};
    ll y[3] = {point[i].second, point[j].second, point[k].second};
    ll *x_min, *x_max, *y_min, *y_max;
    x_min = min_element(x, x+3);
    x_max = max_element(x, x+3);
    y_min = min_element(y, y+3);
    y_max = max_element(y, y+3);

    int count=0;
    rep(l, N){
        if (point[l].first >= *x_min && point[l].first <= *x_max)
            if (point[l].second >= *y_min && point[l].second <= *y_max) count++;
    }

    if (count >= K) return (*x_max-*x_min) * (*y_max-*y_min);
    else return INF;
}

