    rep(i, N){
        cin >> point[i].first >> point[i].second;
    }

    rep(i, N){
        rep(j, N){
            rep(k, N){
                if (ans > calc_S(i,j,k)) ans = calc_S(i,j,k);
            }
        }
    }

    cout << ans << endl;

}

