//.data
pii points[55];
int n, k;

inline bool bw(ll a, ll l, ll r) {
    return l <= a && a <= r;
}

bool check(ll h, ll w) {
    int res = 0;
    fori(i, 0, n) {
        int cnt1 = 0;
        int cnt2 = 0;
        int cnt3 = 0;
        int cnt4 = 0;
        ll x = points[i].first;
        ll y = points[i].second;
        fori(j, 0, n) {
            ll xi = points[j].first;
            ll yi = points[j].second;
            if (bw(xi, x, x + w) && bw(yi, y, y + h)){
                ++cnt1;
            }
            if (bw(xi, x, x + w) && bw(yi, y - h, y)) {
                ++cnt4;
            }
            if (bw(xi, x - w, x) && bw(yi, y, y + h)) {
                ++cnt2;
            }
            if (bw(xi, x - w, x) && bw(yi, y - h, y)) {
                ++cnt3;
            }
        }
        res = max(res, max(max(cnt1, cnt2), max(cnt3, cnt4)));
    }
    return res >= k;
}

