int N, K;

void input() {
	cin >> N >> K;
	for (int i = 0; i < N; i++) cin >> x[i] >> y[i];
}

void solve() {
	ll ans = LLINF;
	ll x1, x2, y1, y2;

	for (int i = 0; i < N; i++) { // x
		for (int j = 0; j < N; j++) { // x
			for (int k = 0; k < N; k++) { // y
				for (int l = 0; l < N; l++) { // y
					x1 = min(x[i], x[j]);
					x2 = max(x[i], x[j]);
					y1 = min(y[k], y[l]);
					y2 = max(y[k], y[l]);
					int cnt = 0;

					for (int m = 0; m < N; m++) if (x1 <= x[m] && x[m] <= x2 && y1 <= y[m] && y[m] <= y2) cnt++;
					if (cnt >= K) ans = min(ans, (x2 - x1)*(y2 - y1));
				}
			}
		}
	}

	cout << ans << endl;
}

int main() {
	input();
	solve();

	return 0;
}

