		xs.erase(unique(all(xs)), xs.end());
		sort(all(ys));
		ys.erase(unique(all(ys)), ys.end());
		ans = xs.back() - xs.front();
		ans *= (ys.back() - ys.front());
		xa = xs.size();
		ya = ys.size();

		rep(i, n) {
			int x = lower_bound(all(xs), ax[i].first) - begin(xs)+1;
			int y = lower_bound(all(ys), ax[i].second) - begin(ys)+1;
			num[x][y]++;
		}
		FOR(i, n) FOR(j, n){
			area[i][j] = (ll)(ys[i-1] - ys[0]);
			area[i][j] *= (ll)(xs[j-1] - xs[0]);
			num[i][j] +=num[i-1][j]+num[i][j-1]-num[i-1][j-1];
