int count_point(const vector<long long> &x, const vector<long long> &y, long long x0, long long y0, long long x1, long long y1)
{
	int ans = 0;
	const int N = x.size();
	for (int i = 0; i < N; ++i) {
		if (x0 <= x[i] && x[i] <= x1 && y0 <= y[i] && y[i] <= y1) {
			++ans;
		}
	}
	return ans;
}

int main()
{
	int N, K;
	cin >> N >> K;
	vector<long long> x(N), y(N);
	for (int i = 0; i < N; ++i) {
		cin >> x[i] >> y[i];
	}

	long long ans = numeric_limits<long long>::max();

	sort(x.begin(), x.end());
	sort(y.begin(), y.end());

	for (int a = 0; a < N; a++) {
		for (int b = a + 1; b < N; b++) {
			for (int c = 0; c < N; c++) {
				for (int d = c + 1; d < N; d++) {
					if (count_point(x, y, x[a], y[c], x[b], y[d]) >= K) {
						ans = min(ans, (x[b] - x[a]) * (y[d] - y[c]));
					}
				}
			}
		}

	}
	cout << ans << endl;
}

