int main() {
    int N, K;
    IN(N);IN(K);
    auto xys = vector<PII>(N);;
    REP(i, N) {
        IN(xys[i].first);IN(xys[i].second);
    }
    u64 ans = (u64)-1;
    REP(i, N)REP(j, N)REP(k, N)REP(l, N) {
        i32 x1, x2, y1, y2;
        x1 = x2 = xys[i].first;
        y1 = y2 = xys[i].second;
        amax(x1, xys[j].first);
        amax(x1, xys[k].first);
        amax(x1, xys[l].first);
