long long int x[52]={0}, y[52]={0};

int main(){
    int n, k;
    cin >> n >> k;
    for(int i=0;i<n;++i){
        cin >> x[i] >> y[i];
    }

    long long int ans = LLONG_MAX;
    if(k == 2){
        for(int i=0;i<n;++i){
            for(int j=i+1;j<n;++j){
                long long int area = (max(x[i],x[j]) - min(x[i], x[j])) * (max(y[i],y[j]) - min(y[i],y[j]));
                ans = min(ans, area);
            }
        }
    }else{
        for(int i=0;i<n;++i){
            for(int j=i+1;j<n;++j){
                for(int l=j+1;l<n;++l){
                    long long int left = min(x[i], min(x[j], x[l]));
                    long long int right = max(x[i], max(x[j], x[l]));
                    long long int bottom = min(y[i], min(y[j], y[l]));
                    long long int top = max(y[i], max(y[j], y[l]));
                    int cnt = 0;
                    for(int m=0;m<n;++m){
                        if(x[m] >= left && x[m] <= right && y[m] >= bottom && y[m] <= top)cnt++;
                    }
                    if(cnt >= k){
                        long long int area = (right - left) * (top - bottom);
                        ans = min(ans, area);
                    }
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

