struct PT{ INT x, y; } p[100];
INT n, k, ans = (INT)6e18;
int main()
{
    ios::sync_with_stdio(false);
    cin>>n>>k;
    for(int i = 0 ; i < n ; i++ ) cin>>p[i].x>>p[i].y;
    sort( p, p+n, [](PT a, PT b){ return a.x < b.x; });
    for(int i = 0, j ; i < n-k+1 ; i++ )
    {
        for( j = i ; j < n ; j++ )
            if( j-i+1 >= k and p[j].x != p[j+1].x ) break;
        if( j-i+1 < k ) continue;
        INT w = p[j].x - p[i].x;
        INT mn = 1e10, mx = -1e10;
        for(int ii = 0 ; ii < n ; ii++ )
            if( p[i].x <= p[ii].x and p[ii].x <= p[j].x )
