      for(int l=i;l<=j;l++){
        min_y=min(min_y,xy[l].second);
        max_y=max(max_y,xy[l].second);
      }
      tmp *=abs(min_y-max_y);
      if(min_ans==-1) min_ans=tmp;
      else min_ans=min(min_ans,tmp);
