        bottom = y[i]; b_i = i;
      }
      if (top <= y[i]) {
        top2 = top;
        top = y[i]; t_i = i;
      }
    }
    ll tmp = 1e18;
    int id = 0;
    chmin(tmp, 1LL * (r2 - l) * (top - bottom));
    if (chmin(tmp, 1LL * (r - l2) * (top - bottom))) id = 1;
    if (chmin(tmp, 1LL * (r - l) * (top2 - bottom))) id = 2;
    if (chmin(tmp, 1LL * (r - l) * (top - bottom2))) id = 3;
    if (id == 0) deleted.insert(r_i);
    if (id == 1) deleted.insert(l_i);
    if (id == 2) deleted.insert(t_i);
    if (id == 3) deleted.insert(b_i);
  }
  cout << 1LL * (r-l) * (top - bottom) << endl;

  return 0;
}

