		x = _x;
		y = _y;
	}
};

bool compare(const Coord& a, const Coord& b){
	if (a.x == b.x) return a.y < b.y;
	else return a.x < b.x;
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n, k;
	cin >> n >> k;


	Coord points[n];

	for(int i = 0; i < n; i++){
		cin >> points[i].x >> points[i].y;
	}

	// sort lexicographically
	sort(points, points+n, compare);

	ll area = lim<ll>::max();
	for(int i = 0; i < n-k+1; i++){
		ll minX = lim<ll>::max();
		ll maxX = lim<ll>::min();
		ll minY = lim<ll>::max();
		ll maxY = lim<ll>::min();
		for (int j = i; j < i+k; j++){
			minX = min(minX, points[j].x);
			maxX = max(maxX, points[j].x);
			minY = min(minY, points[j].y);
			maxY = max(maxY, points[j].y);
		}
		area = min(area,(maxX-minX)*(maxY-minY));
	}

	cout << area << endl;
}

