int main() {

	LL n, k; cin >> n >> k;

	vector<LL> x(n);
	vector<LL> y(n);

	vector<LL> xb(n);
	vector<LL> yb(n);


	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];

		xb[i] = x[i];
		yb[i] = y[i];
	}

	sort(xb.begin(), xb.end());
	sort(yb.begin(), yb.end());

	LL ans = INF2;

	for (int x1 = 0; x1 < n; x1++) {
		for (int x2 = x1+1; x2 < n; x2++) {

			for (int y1 = 0; y1 < n; y1++) {
				for (int y2 = y1+1; y2 < n; y2++) {

					LL xl = xb[x1];
					LL xr = xb[x2];

					LL ys = yb[y1];
					LL yu = yb[y2];

					LL cnt = 0;

					for (int i = 0; i < n; i++) {
						if (xl <= x[i] && x[i] <= xr) {
							if (yu >= y[i] && y[i] >= ys) {
								cnt++;
							}
						}
					}

					if (cnt >= k) {
						LL area = abs((LL)(xr - xl)*(LL)(yu - ys));

						ans = min(ans, area);
					}
				}

			}
		}
	}

	cout << ans << endl;



	return 0;
}

