int count(vector<pair<int, int> > xy, int i, int j, int k, int l){
	int count = 0;
	for(auto p: xy){
		if(p.first >= i && p.first <= j && p.second >= k && p.second <= l) {
			count++;
		}
	}
	return count;
}

int main(){
	int n, K;
	cin >> n >> K;
	pair<int, int> p;
	vector<pair<int, int> > xy;
	vector<int> x;
	vector<int> y;
	long min = LONG_MAX;
	long area;
	for(int I=0; I<n; I++){
		cin >> p.first >> p.second;
		xy.push_back(p);
		x.push_back(p.first);
		y.push_back(p.second);
	}
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());
	for(auto i=x.begin(); i<x.end() - 1; i++){
		for(auto j=i+1; j<x.end(); j++){
			for(auto k=y.begin(); k<y.end() - 1; k++){
				for(auto l=k+1; l<y.end(); l++){
					area = ((long)*j - *i) * (*l - *k);
					if(count(xy, *i, *j, *k, *l) >= K && area < min) {
						min = area;
					}
				}
			}
		}
	}
	cout << min;
	return 0;
}

