int main(){
	int n, k;
	cin >> n >> k;
	vector<pair<ll, ll>> v;
	vector<pair<ll, ll>> w;
	for( int i = 0; i < n; ++i ){
		ll x, y;
		cin >> x >> y;
		v.emplace_back(x, y);
		w.emplace_back(x, y);
	}
	ll ans = -1;
	// v から横向きの部分連続区間を，w から縦向きの部分連続区間をとる
	// 連続区間の列挙は O(N^2) でできるので O(N^4)
	sort( v.begin(), v.end() );
	sort( w.begin(), w.end(), []( auto &x, auto &y ){ return x.second < y.second; } );
	for( int rangex = 1; rangex < n; ++rangex ){
		for( int ix = 0; ix + rangex < n; ++ix ){
			// 横向きの部分連続区間の左端と右端
			ll a = v.at(ix).first;
			ll b = v.at(rangex+ix).first;
			for( int rangey = 1; rangey < n; ++rangey ){
				for( int iy = 0; iy + rangey < n; ++iy ){
					// 縦向きの部分連続区間の下端と上端
					ll c = w.at(iy).second;
					ll d = w.at(rangey+iy).second;
					// 縦の区間と横の区間が交わっていない場合は長方形でないので除外
					if(
						a <= w.at(iy).first && w.at(iy).first <= b
						&&
						a <= w.at(rangey+iy).first && w.at(rangey+iy).first <= b
						&&
						c <= v.at(ix).second && v.at(ix).second <= d
						&&
						c <= v.at(rangex+ix).second && v.at(rangex+ix).second <= d
					){
						// 長方形に含まれる点の数が k 個以上か確認する
						// N 個の点を線形探索するので O(N)
						int cnt = 0;
						for( int i = 0; i < n; ++i ){
							ll x = v.at(i).first;
							ll y = v.at(i).second;
							if( a <= x && x <= b && c <= y && y <= d ) ++cnt;
						}
						if( cnt >= k ){
							ans = ( ( ans == -1 ) ? (b-a) * (d-c) : min( ans, (b-a) * (d-c) ) );
						}
					}
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

