i64 INF = 3999999996000000002LL;

i64 ans(vector<i64>& X,vector<i64>& Y,int f = 0){
  if(X.size() == 4){
    i64 MINx = *min_element(X.begin(),X.end());
    i64 MAXx = *max_element(X.begin(),X.end());
    i64 MINy = *min_element(Y.begin(),Y.end());
    i64 MAXy = *max_element(Y.begin(),Y.end());

    int cou = 0;
    rep(i,0,N - 1){
      if(MINx <= x[i] && x[i] <= MAXx && MINy <= y[i] && y[i] <= MAXy){
        cou++;
      }
    }

    if(cou >= K){
      return (MAXx - MINx) * (MAXy - MINy);
    }
    else return INF;
  }
  i64 res = INF;
  rep(i,f,N - 1){
    X.push_back(x[i]);
    Y.push_back(y[i]);
    res = min(res,ans(X,Y));
    X.pop_back();
    Y.pop_back();
  }
  return res;
}

