vector<T> zaatsu(vector<T> &c1){
  vector<T> vals;
  int n=(int)c1.size();
  for(int i=0;i<n;i++){
    for(T d=0;d<=1;d++){
      vals.push_back(c1[i]+d);
    }
  }
  sort(vals.begin(),vals.end());
  vals.erase(unique(vals.begin(),vals.end()),vals.end());
  for(int i=0;i<n;i++){
    c1[i]=lower_bound(vals.begin(),vals.end(),c1[i])-vals.begin();
  }
  return vals;
}
