int main(void) {
    lint n, k;
    cin >> n >> k;
    vector<pair<lint, lint>> p(n);
    repeat(i, n) cin >> p[i].fst >> p[i].snd;

    auto filter = [](vector<pair<lint, lint>> p, lint ymin, lint ymax) {
        vector<pair<lint, lint>> v;
        for (auto e: p) {
            if (ymin <= e.snd and e.snd <= ymax) {
                v.emplace_back(e);
            }
        }
        sort(v.begin(), v.end(), [](const pair<lint, lint> p, const pair<lint, lint> q) {
            return p.fst < q.fst;
        });
        return v;
    };

    lint ans = numeric_limits<lint>::max();
    repeat(i, n) repeat(j, n) {
        if (i == j) continue;
        vector<pair<lint, lint>> v = filter(p, min(p[i].snd, p[j].snd), max(p[i].snd, p[j].snd));
        lint xmin = v[0].fst;
        lint xdif = 0;
        lint ymin = v[0].snd;
        lint ymax = v[0].snd;
        lint ydif = 0;
        lint cnt = 0;
        for (auto e: v) {
            ++cnt;
            xdif = e.fst - xmin;
            ymin = min(ymin, e.snd);
            ymax = max(ymax, e.snd);
            ydif = ymax - ymin;
            if (cnt >= k) {
                ans = min(ans, xdif * ydif);
            }
        }   
    }
    cout << ans << endl;
}

