    {
        return max(max(max(a, b), c), d);
    }

    int ind_x(int border, int i, int j, int o, int l)
    {
        if (border == x[i])
            return i;
        if (border == x[j])
            return j;
        if (border == x[o])
            return o;
        if (border == x[l])
            return l;
        return 0;
    }

    int ind_y(int border, int i, int j, int o, int l)
    {
        if (border == y[i])
            return i;
        if (border == y[j])
            return j;
        if (border == y[o])
            return o;
        if (border == y[l])
            return l;
        return 0;
    }

