class UnionFind {
    vector<int> par;
public:
    explicit UnionFind(int n) : par(n, -1) {}

    int root(int a) {
        if (par[a] < 0) {
            return a;
        }
        return par[a] = root(par[a]);
    }

    int size(int a) {
        return -par[root(a)];
    }

    void unite(int a, int b) {
        a = root(a);
        b = root(b);
        if (a != b) {
            if (size(a) < size(b)) {
                swap(a, b);
            }
            par[a] += par[b];
            par[b] = a;
        }
    }
};

