#include<bits/stdc++.h>
using namespace std;
typedef long long int ll;

bool between(ll a, ll b, ll c){
	if(a <= b && b <= c) return true;
	if(a >= b && b >= c) return true;
	return false;
}

ll long_abs(ll a){
	if(a < 0) return -a;
	return a;
}

int main(void){
	int N, K;
	ll x[50], y[50];
	scanf("%d %d", &N, &K);
	for(int i = 0; i < N; i++) scanf("%lld %lld", &x[i], &y[i]);
	ll ans = LONG_MAX;
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			ll width = long_abs(x[i] - x[j]);
			for(int k = 0; k < N; k++){
				for(int l = 0; l < N; l++){
					ll height = long_abs(y[k] - y[l]);
					int num_inside_point = 0;
					for(int m = 0; m < N; m++){
						if(between(x[i], x[m], x[j]) && between(y[k], y[m], y[l])) num_inside_point++;
					}
					if(num_inside_point >= K && width * height < ans) ans = width * height;
				}
			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

