                for(int j2=j1+1;j2<N;j2++){
                    int x1 = x[i1], x2 = x[i2];
                    int y1 = y[i1], y2 = y[i2];
                    unsigned long long area = 1ull * (x2-x1) * (y2-y1);
                    int cnt = 0;
                    for(int i=0;i<N;i++){
                        if(x1 <= P[i].first && P[i].first <= x2 && y1 <= P[i].second && P[i].second <= y2) cnt++;
                    }
                    if(cnt >= K){
                        ans = min(ans, area);
                    }
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

