			for (int yi = 0; yi < n; yi++) {
				for (int yj = yi + 1; yj < n; yj++) {
					int num = 0;
					ll left = xx[xi], right = xx[xj];
					ll bottom = yy[yi], top = yy[yj];

					for (int i = 0; i < n; i++) {
						if (left <= x[i] && x[i] <= right && bottom <= y[i] && y[i] <= top) {
							num++;
						}
					}

					if (num >= k) {
						res = min(res, (right - left) * (top - bottom));
					}
				}
			}
		}
	}

	cout << res << endl;
	return 0;
}

