template<typename T> class CumulativeSum2D
{
   private:
      vector<vector<T>> s;
   public:
      CumulativeSum2D(const vector<vector<T>>& v) {
         int M = v.size(), N = v[0].size();
         s.resize(M+1, vector<int>(N+1));
         for (int i = 0; i < M; i++) {
            for (int j = 0; j < N; j++) {
               s[i+1][j+1] = s[i+1][j] + v[i][j];
            }
         }
         for (int i = 0; i < M; i++) {
            for (int j = 0; j < N; j++) {
               s[i+1][j+1] += s[i][j+1];
            }
         }
      }
      int sum(int i, int j, int k, int l) {
         return s[k+1][l+1] - s[i][l+1] - s[k+1][j] + s[i][j];
      }
};

