		int32_t minY = p[0].second;
		int32_t min2Y = p[1].second;
		int32_t maxY = p[p.size() - 1].second;
		int32_t max2Y = p[p.size() - 2].second;

		candidate[0].x = minX;
		candidate[0].y = numeric_limits<int32_t>::max();
		candidate[0].space = (int64_t)(maxX - min2X) * (int64_t)(maxY - minY);

		candidate[1].x = maxX;
		candidate[1].y = numeric_limits<int32_t>::max();
		candidate[1].space = (int64_t)(max2X - minX) * (int64_t)(maxY - minY);

