		candidate[3].y = maxY;
		candidate[3].space = (int64_t)(maxX - minX) * (int64_t)(max2Y - minY);

		sort(candidate.begin(), candidate.end(), [](struct candidate left, struct candidate right) -> bool { return left.space < right.space; });

		if (candidate[0].x != numeric_limits<int32_t>::max()) {
			for (size_t i = 0; i < p.size(); i++) {
				if (p[i].first == candidate[0].x) {
					p.erase(p.begin() + i);
