void _main()
{
    ll n; llin(n);
    ll k; llin(k);
    V<t2> xylist; llinl2(xylist, n);

    set<ll> xs, ys;
    for (auto xy : xylist) {
        ll x = get<0>(xy);
        ll y = get<1>(xy);
        xs.insert(x);
        ys.insert(y);
    }

    map<ll, ll> xmap, rxmap;
    ll xidx = 0;
    for (auto x : xs) {
        xmap[x] = xidx;
        rxmap[xidx] = x;
        xidx++;
    }

    map<ll, ll> ymap, rymap;
    ll yidx = 0;
    for (auto y : ys) {
        ymap[y] = yidx;
        rymap[yidx] = y;
        yidx++;
    }

    ll sums[60][60];
    memset(sums, 0, sizeof(sums));
    srep (xcnt, 1, n+1) srep (ycnt, 1, n+1) {
        sums[xcnt][ycnt] += sums[xcnt-1][ycnt];
        sums[xcnt][ycnt] += sums[xcnt][ycnt-1];
        sums[xcnt][ycnt] -= sums[xcnt-1][ycnt-1];
        for (auto xy : xylist) {
            ll x = get<0>(xy);
            ll y = get<1>(xy);
            if (xmap[x] == xcnt-1 && ymap[y] == ycnt-1) {
                sums[xcnt][ycnt]++;
                break;
            }
        }
    }

    debug_printf("---- sums\n");
    rep (xx, n+1) {
        rep (yy, n+1) debug_printf("%lld ", sums[xx][yy]);
        debug_printf("\n");
    }

    ll ans = 5 * 1e18;
    debug_printf("---- %lld\n", ans);

    rep (x0, n) srep (x1, x0+1, n) rep (y0, n) srep (y1, y0+1, n) {
        ll cnt = sums[x1+1][y1+1];
        cnt -= sums[x0][y1+1];
        cnt -= sums[x1+1][y0];
        cnt += sums[x0][y0];
        if (cnt < k) continue;
        ll lans = (rxmap[x1] - rxmap[x0]) * (rymap[y1] - rymap[y0]);
        ans = min(lans, ans);
    }

    debug_printf("---- ans\n");
    cout << ans << endl;
}

