using namespace std;

typedef long long ll;
typedef pair<int, int> pi;

const ll INF = (ll)9e18;
int N, K;
vector<int> X, Y;
vector<pi> P;

int cnt_point(int xl, int xr, int yu, int yd) {
	int cnt = 0;
	for (int i = 0; i < N; ++i) {
		if ((P[i].first >= X[xl] && P[i].first <= X[xr])
			&& (P[i].second >= Y[yd] && P[i].second <= Y[yu]))
			++cnt;
		if (cnt >= K)
			break;
	}
	return cnt;
}

ll solve(void) {
	ll min_s = INF;
	for (int xl = 0; xl <= N - 2; ++xl) {
		for (int xr = xl + 1; xr <= N - 1; ++xr) {
			for (int yd = 0; yd <= N - 2; ++yd) {
				for (int yu = yd + 1; yu <= N - 1; ++yu) {
					int cnt = cnt_point(xl, xr, yu, yd);
					if (cnt >= K) {
						ll s = (ll)(X[xr] - X[xl]) * (Y[yu] - Y[yd]);
						min_s = min(s, min_s);
					}
				}
			}
		}
	}
	return min_s;
}

int main(void) {
	cin >> N >> K;
	X.resize(N);
	Y.resize(N);
	P.resize(N);
	for (int i = 0; i < N; ++i) {
		int x, y;
		cin >> x >> y;
		X[i] = x;
		Y[i] = y;
		P[i] = make_pair(x, y);
	}

	sort(X.begin(), X.end());
	sort(Y.begin(), Y.end());
	ll ans = solve();

	cout << ans << '\n';
	return 0;
}

