#define rr(e, v) for(auto&& (e) : (v))

#define MIN -2000000000
#define MAX 2000000000

using namespace std;

long ncr(int n, int r) {
    long a = 1;
    r = r > n - r ? n - r : r;
    for(int i = 1;  i <= r ; i++, n--) {
        if(n % i == 0) {
            a *= n / i;
        } else if (a % i == 0) {
            a = a / i * n;
        } else {
            a = (a * n) / i;
        }
    }
    return a;
}

void combination(vector<vector<int>> &v, int n, int r)
{
    std::string bit_mask(r, 1);
    bit_mask.resize((unsigned long)n, 0);

    int c = 0, j;
    do {
        j = 0;
        for (int i = 0; i < n; ++i)
        {
            if (bit_mask[i]) {
                v[c][j++] = i;
            }
        }
        c++;
    } while (std::prev_permutation(bit_mask.begin(), bit_mask.end()));
}

int main() {
    ios::sync_with_stdio(false);

    int n, r;
    cin >> n >> r;
    vector<vector<int>> vp((unsigned long)n, vector<int>(2,0));
    r(i, 0, n) {
        cin >> vp[i][0] >> vp[i][1];
    }

    long c = ncr(n, r);
    vector<vector<int>> vc((unsigned long)c, vector<int>((unsigned long)r));

    combination(vc, n, r);

    bool nocontain;
    int maxx, maxy, minx, miny;
    long long maxa = MIN;
    r(i, 0, c) {
        nocontain = true;
        maxx = maxy = MIN;
        minx = miny = MAX;

        r(j, 0, r) {
            int cp = vc[i][j];
            maxx = max(maxx, vp[cp][0]);
            minx = min(minx, vp[cp][0]);
            maxy = max(maxy, vp[cp][1]);
            miny = min(miny, vp[cp][1]);
        }

        r(k, 0, n) {
            if(any_of(vc[i].begin(), vc[i].end(), [&](int x) { return x == k; })) continue;
            if ( (minx <= vp[k][0] && vp[k][0] <= maxx) ||
                 (miny <= vp[k][1] && vp[k][1] <= maxy) ){
                nocontain = false;
                break;
            }
        }

        if(!nocontain) continue;
        maxa = max(maxa, 1LL * (maxx - minx) * (maxy - miny));
    }

    cout << maxa;

    return 0;
}

