ull area(vector<pair<ll, ll>> p){
  ll x_max, x_min, y_max, y_min;
  x_max = x_min = p[0].first;
  y_max = y_min = p[0].second;
  for(int i=1;i<k;i++){
    ll x = p[i].first;
    ll y = p[i].second;
    cout << x << " " << y << endl;
    if (x > x_max){
      x_max = x;
    }else if(x < x_min){
      x_min = x;
    }
    if (y > y_max){
      y_max = y;
    }else if(y < y_min){
      y_min = y;
    }
  }
  cout << x_max << x_min << y_max << y_min << endl;
  return (x_max - x_min) * (y_max - y_min);
}

ull search(int ind, vector< pair<ll, ll> > p, int total){
  if (total == k){
    return area(pairs);
  }
  if ((n - ind + total) < k){
    return LLONG_MAX;
  }
  ull ans1, ans2;
  ans1 = search(ind+1, p, total);
  p.push_back(pairs[ind]);
  ans2 = search(ind+1, p, total+1);
  return min( ans1, ans2);
}

