ll cnts[51][51][51][51] = {};


void solve() {
    ll N, K;
    cin >> N >> K;
    vector<Pll> ps(N);
    Vl xs(N), ys(N);
    for (ll i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        ps[i] = {x, y};
        xs[i] = x;
        ys[i] = y;
    }
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    ll nx = (ll)xs.size();
    ll ny = (ll)ys.size();

    for (ll i = 0; i < nx; i++) {
        for (ll j = 0; j < ny; j++) {
            for (ll k = i; k < nx; k++) {
                for (ll l = j; l < ny; l++) {
                    for (ll m = 0; m < N; m++) {
                        auto [a, b] = ps[m];
                        if (xs[i] <= a && a <= xs[k] && ys[j] <= b && b <= ys[l]) {
                            ++cnts[i][j][k][l];
                        }
                    }
                }
            }
        }
    }

    ll ans = L_INF;
    for (ll i = 0; i < nx; i++) {
        for (ll j = 0; j < ny; j++) {
            for (ll k = 0; k < nx; k++) {
                for (ll l = 0; l < ny; l++) {
                    if (cnts[i][j][k][l] >= K) {
                        ans = min(ans, (xs[k] - xs[i]) * (ys[l] - ys[j]));
                    }
                }
            }
        }
    }

    cout << ans << "\n";
}

