typedef vector<pll> vll;
typedef priority_queue<ll> pq;

const int MOD = 1e9+7;
const int INF = (1<<30);
const ll INFL = (1L<<62);

int n, k;

ll calc(vll xys) {
  sort(all(xys));
  ll res = INFL;
  for (int i = 0; i < n-k+1; i++) {
    ll x1 = INFL, x2 = -INFL;
    ll y1 = INFL, y2 = -INFL;
    for (int j = 0; j < k; j++) {
      x1 = min(x1, xys[j].ff);
      y1 = min(y1, xys[j].ss);
      x2 = max(x2, xys[j].ff);
      y2 = max(y2, xys[j].ss);
    }
    ll area = (x2 - x1) * (y2 - y1);
    // cout << area << endl;
    res = min(res, area);
  }
  return res;
}

int main() {
  cin >> n >> k;
  vll xys, yxs;
  rep(i,n) {
    ll x, y; cin >> x >> y;
    xys.pb(mp(x,y));
    yxs.pb(mp(y,x));
  }

  ll ans = INFL;
  ans = min(ans, calc(xys));
  ans = min(ans, calc(yxs));
  cout << ans << endl;
  return 0;
}

