        BSort(n);

        for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            for (int o = 1; o <= n; ++o)
                if (x[o] <= x[i] && y[o] <= y[j])
                    cell_cnt[i][j]++;
        }

        long long left_m, down_m, right_m, up_m;
        int left_i, down_i, right_i, up_i;
        first = 1;
        for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
        for (int o = 1; o <= n; ++o)
        for (int l = 1; l <= n; ++l) {
