            left_i = ind_x(left_m, i, j, o, l);

            down_m = min_3(y[i], y[j], y[o], y[l]);
            down_i = ind_y(down_m, i, j, o, l);

            right_m = max_3(x[i], x[j], x[o], x[l]);
