void quicksort(int a[2][50],int left,int right,int xory)
{
	if(left<right) {
		int i=left,j=right,tmp1,tmp2,nxy,pivot=a[xory][i];
		if(xory==0) {
			nxy=1;
		}else {
			nxy=0;
		}
		while(1) {
		while(a[xory][i]<pivot) i++;
		while(pivot<a[xory][j]) j--;
		if(i>=j)break;
		tmp1=a[xory][i];
		tmp2=a[nxy][i];
		a[xory][i]=a[xory][j];
		a[nxy][i]=a[nxy][j];
		a[xory][j]=tmp1;
		a[nxy][j]=tmp2;
		i++;
		j--;
		}
		quicksort(a,left,i-1,xory);
		quicksort(a,j+1,right,xory);
	}
}

