int main() {
    int n, k;
    cin >> n >> k;
    vector<ll> x(n), y(n);
    vector<ll> xv(n), yv(n);
    for(int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        xv[i] = x[i];
        yv[i] = y[i];
    }
    xv.erase(unique(xv.begin(), xv.end()), xv.end());
    yv.erase(unique(yv.begin(), yv.end()), yv.end());

    sort(xv.begin(), xv.end());
    sort(yv.begin(), yv.end());

    // 座標を照準で何番目かに圧縮
    int h = xv.size() + 1;
    int w = yv.size() + 1;
    vector<vector<int> > fld(h, vector<int>(w, 0));
    for(int i = 0; i < n; i++) {
        int idx_x = (int)(lower_bound(xv.begin(), xv.end(), x[i]) - xv.begin());
        int idx_y = (int)(lower_bound(yv.begin(), yv.end(), y[i]) - yv.begin());
        ++idx_x, ++idx_y;
        fld[idx_x][idx_y] = 1;;
    }

    // 累積和を計算
    for(int i = 1; i < h; i++) {
        for(int j = 1; j < w; j++) {
            fld[i][j] += fld[i-1][j] + fld[i][j-1] - fld[i-1][j-1];
        }
    }

    ll ans = __LONG_LONG_MAX__;
    for(int xi = 0; xi < h-1; xi++) {
        for(int xj = xi+1; xj < h-1; xj++) {
            for(int yi = 0; yi < w-1; yi++) {
                for(int yj = yi+1; yj < w-1; yj++) {
                    int num = fld[xi][yi] - fld[xj+1][yi] - fld[xi][yj+1] + fld[xj+1][yj+1];
                    if(num >= k) {
                        // cout << xj << " " << xi << ":: " << xv[xj]  << " " << xv[xi] << endl;
                        ans = min(ans, (xv[xj] - xv[xi]) * (yv[yj] - yv[yi]));
                    }
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

