typedef long long ll;
typedef pair<int, int> p;
ll res = LLONG_MAX;
int k, n;

void full_search(vector<p> v){
  for (int i = 0; i < n-1; i++) {
    for (int j = i+1; j < n; j++) {
      ll max_x = max(v[i].first, v[j].first);
      ll min_x = min(v[i].first, v[j].first);
      ll max_y = max(v[i].second, v[j].second);
      ll min_y = min(v[i].second, v[j].second);
      if(max_x == min_x || max_y == min_y) continue;
      int count = 0;
      ll area = (max_x - min_x) * (max_y - min_y);
      for (int k = 0; k < n; k++) {
        int nx = v[k].first;
        int ny = v[k].second;
        bool is_inner_point = (nx >= min_x && nx <= max_x && ny >= min_y && ny <= max_y);
        if(is_inner_point){
          count++;
        }
      }
      // cout << max_x-min_x << " : " << max_y-min_y << endl;
      // cout << area << endl;
      if(count >= k) res = min(area, res);
    }
  }
}

int main(){
  cin >> n >> k;
  vector<p> v(n);
  for (int i = 0; i < n; i++) {
    cin >> v[i].first >> v[i].second;
  }
  full_search(v);
  cout << res << endl;
}

