#define UQ(v) (v.erase(unique(ALL(v)), v.end()) - v.begin())

LL n, k, x[50], y[50], p[50][50], s[51][51];
vector<LL> vx, vy;
map<LL, LL> mx, my;

int main() {
	cin >> n >> k;
	inc(i, n) { cin >> x[i] >> y[i]; }

	inc(i, n) {
		vx.PB(x[i]);
		vy.PB(y[i]);
	}

	sort(ALL(vx));
	sort(ALL(vy));
	int xx = UQ(vx);
	int yy = UQ(vy);
	inc(i, xx) { mx[vx[i]] = i; }
	inc(i, yy) { my[vy[i]] = i; }

	inc(i, n) { p[mx[x[i]]][my[y[i]]]++; }

	// ----  s: p の２次元累積和
	inc1(i, xx) {
	inc1(j, yy) {
		s[i][j] = p[i - 1][j - 1];
	}
	}
	inc1(i, xx) {
	inc1(j, yy) {
		s[i][j] += s[i - 1][j];
	}
	}
	inc1(i, xx) {
	inc1(j, yy) {
		s[i][j] += s[i][j - 1];
	}
	}
	// ----

	LL ans = 4e18;
	inc(xh, xx) {
	inc(xl, xh) {
	inc(yh, yy) {
	inc(yl, yh) {
		#define R(xl, xh, yl, yh) (s[xh][yh] - s[xh][yl] - s[xl][yh] + s[xl][yl])
		int c = R(xl, xh + 1, yl, yh + 1);
		LL v = (vx[xh] - vx[xl]) * (vy[yh] - vy[yl]);
		if(c >= k) { setmin(ans, v); }
	}
	}
	}
	}

	cout << ans << endl;

	return 0;
}

