    void BSort(int n)
    {
        int ok = 0;
        while (!ok) {
            ok = 1;
            for (int i = 1; i < n; ++i)
            if (x[i] > x[i + 1]) {
                swap(x[i], x[i + 1]);
                swap(y[i], y[i + 1]);
                ok = 0;
            }
        }
    }

    int min_3(int a, int b, int c, int d)
    {
        return min(min(min(a, b), c), d);
    }

    int max_3(int a, int b, int c, int d)
    {
        return max(max(max(a, b), c), d);
    }

    int ind_x(int border, int i, int j, int o, int l)
    {
        if (border == x[i])
            return i;
        if (border == x[j])
            return j;
        if (border == x[o])
            return o;
        if (border == x[l])
            return l;
        return 0;
    }

    int ind_y(int border, int i, int j, int o, int l)
    {
        if (border == y[i])
            return i;
        if (border == y[j])
            return j;
        if (border == y[o])
            return o;
        if (border == y[l])
            return l;
        return 0;
    }

