                    cell_cnt[i][j]++;
        }

        int left_m, down_m, right_m, up_m;
        int left_i, down_i, right_i, up_i;
        first = 1;
        for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
        for (int o = 1; o <= n; ++o)
        for (int l = 1; l <= n; ++l) {
            left_m = min_3(x[i], x[j], x[o], x[l]);
            left_i = ind_x(left_m, i, j, o, l);

            down_m = min_3(y[i], y[j], y[o], y[l]);
            down_i = ind_y(down_m, i, j, o, l);

            right_m = max_3(x[i], x[j], x[o], x[l]);
            right_i = ind_x(right_m, i, j, o, l);

            up_m = max_3(y[i], y[j], y[o], y[l]);
            up_i = ind_y(up_m, i, j, o, l);

            if (cell_cnt[right_i][up_i] - cell_cnt[left_i - 1][up_i] - cell_cnt[right_i][down_i] + cell_cnt[left_i - 1][down_i] + 1 >= k) {
