inline bool chmax(T &a, T b) {
    if(a < b) {
        a = b;
        return true;
    }
    return false;
}

template<class T>
inline bool chmin(T &a, T b) {
    if(a > b) {
        a = b;
        return true;
    }
    return false;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(0);
    cout<<fixed<<setprecision(20);

    int N,K; cin >> N >> K;
    int X[N],Y[N];
    rep(i,N) cin >> X[i] >> Y[i];
    bool ok[N]; rep(i,N) ok[i] = true;
    bool ok2[N]; rep(i,N) ok2[i] = true;
    int cnt=0;
    while(cnt!=N-K){
        int msum=INF*INF*5;
        int pos;
        rep(i,N){
            if(!ok[i]) continue;
            ok2[i] = false;
            int mnx=INF+1,mny=INF+1,mxx=-INF-1,mxy=-INF-1;
            rep(j,N){
                if(!ok[j]||!ok2[j]) continue;
                chmin(mnx,X[j]);
                chmin(mny,Y[j]);
                chmax(mxx,X[j]);
                chmax(mxy,Y[j]);
            }
            int sum=(mxx-mnx)*(mxy-mny);
            if(msum>sum){
                msum = sum;
                pos=i;
            }
            ok2[i] = true;
        }
        cnt++;
        ok[pos]=false;
    }
    int mnx=INF+1,mny=INF+1,mxx=-INF-1,mxy=-INF-1;
    rep(j,N){
        if(!ok[j]) continue;
        chmin(mnx,X[j]);
        chmin(mny,Y[j]);
        chmax(mxx,X[j]);
        chmax(mxy,Y[j]);
    }
    int sum=(mxx-mnx)*(mxy-mny);
    cout << sum << endl;
}

