struct V{
    int x;
    int y;
    int r;
    bool operator<( const V& right ) const {
        return (r == right.r) ? (r < right.r) : (r < right.r);
    }
};
void func(void)
{
//DEBUG_OUT("----\n");
    int N, K;
    cin >> N >> K;
    vector<V> v(N);
    int centerX = 0;
    int centerY = 0;
    for(int i=0; i<N; i++){
        int x, y;
        cin >> x >> y;
        v[i].x = x;
        v[i].y = y;
        centerX += x;
        centerY += y;
    }
    centerX = centerX / N;
    centerY = centerY / N;
    for(int i=0; i<N; i++){
        int64 difX = v[i].x - centerX;
        int64 difY = v[i].y - centerY;
        v[i].r = (int)abs( sqrt(difX*difX + difY*difY) );
    }

    sort(v.begin(), v.end());

    int minX = INT32_MAX;
    int maxX = INT32_MIN;
    int minY = INT32_MAX;
    int maxY = INT32_MIN;
    for(int i=0; i<K; i++){
        if(minX > v[i].x){ minX = v[i].x; }
        if(maxX < v[i].x){ maxX = v[i].x; }
        if(minY > v[i].y){ minY = v[i].y; }
        if(maxY < v[i].y){ maxY = v[i].y; }
    }

    uint64 lenX = (uint64)(abs(maxX - minX));
    uint64 lenY = (uint64)(abs(maxY - minY));

    uint64 a = lenX * lenY;

    DEBUG_OUT("----\n");
    cout << a << endl;
    return;
}

