pair<long long, long long> p[51],P[51];

int main(){

    cin.sync_with_stdio(0); cin.tie(0); cout.tie(0);

    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n, k;
    cin >> n >> k;

    for(int i = 0; i < n; ++i)
        cin >> p[i].first >> p[i].second;
    for(int i = 0; i < n; ++i)
        P[i] = make_pair(p[i].second, p[i].first);

    sort(p, p + n); sort(P, P + n);

    long long area = -1;
    for(int a = 0; a < n; ++a){
        for(int b = a; b < n; ++b){
            for(int c = 0; c < n; ++c){
                for(int d = c; d < n; ++d){
                    long long lx = p[a].first;
                    long long rx = p[b].first;
                    long long ly = P[c].first;
                    long long ry = P[d].first;
                    if(area != -1 && (rx - lx) * (ry - ly) >= area)
                        continue;
                    long long cnt = 0;
                    for(int i = 0; i < n && cnt < k; ++i){
                        if(lx > p[i].first || p[i].first > rx)
                            continue;
                        if(ly > p[i].second || p[i].second > ry)
                            continue;
                        ++cnt;
                    }
                    if(cnt == k)
                        area = (rx - lx) * (ry - ly);
                }
            }
        }
    }

    cout << area;

    return 0;
}

