int main() {
  // 入力
  int N, K;
  cin >> N >> K;
  int x[N], y[N];
  for (int i = 0; i < N; i++) cin >> x[i] >> y[i];

  ll ans = 9 * 1e18;
  for (int i = 0; i < N; i++) { // x座標の左端
    for (int j = 0; j < N; j++) { // x座標の右端
      for (int k = 0; k < N; k++) { // y座標の下端
        for (int l = 0; l < N; l++) { // y座標の上端
          if (x[i] > x[j]) continue;
          if (y[k] > y[l]) continue;
          // 4点で作られる長方形に囲まれる点の数を数える
          int cnt = 0;
          for (int m = 0; m < N; m++) {
            if (x[i] <= x[m] && x[m] <= x[j] && y[k] <= y[m] && y[m] <= y[l]) cnt++;
          }

          if (cnt >= K) ans = min(ans, 1LL * (x[j] - x[i]) * (y[l] - y[k]));
        }
      }
    }
  }

  // 解答
  cout << ans << endl;

  return 0;
}

