  vll x(n), y(n);
  map<ll, ll> xmap, ymap;
  ll X, Y;
  REP(i, n){
    cin >> X >> Y;
    x[i] = X;
    y[i] = Y;
    xmap[X] = Y;
    ymap[Y] = X;
  }

  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  vll d(n+1, 0);
  while(x.size() >= 2 && y.size() >= 2){
    ll s = x.size();
    ll width = x[s-1]-x[0];
    ll height = y[s-1]-y[0];
    d[s] = width*height;

    ll reduce_by_x = max(x[s-1]-x[s-2], x[1]-x[0]);
    ll reduce_by_y = max(y[s-1]-y[s-2], y[1]-y[0]);

    if((width-reduce_by_x)*height < width*(height-reduce_by_y)){
      if(x[s-1]-x[s-2] > x[1]-x[0]){
        auto it = lower_bound(y.begin(), y.end(), xmap[x[s-1]]);
        y.erase(it);
        x.erase(x.begin()+s-1);
      }
      else{
        auto it = lower_bound(y.begin(), y.end(), xmap[x[0]]);
        y.erase(it);
        x.erase(x.begin()+0);
      }
    }
    else{
      if(y[s-1]-y[s-2] > y[1]-y[0]){
        auto it = lower_bound(x.begin(), x.end(), ymap[y[s-1]]);
        x.erase(it);
        y.erase(y.begin()+s-1);
      }
      else{
        auto it = lower_bound(x.begin(), x.end(), ymap[y[0]]);
        x.erase(it);
        y.erase(y.begin()+0);
      }
    }


  }


  cout << d[k] << endl;


}

