void solve(){
    int N,K;
    cin >> N >> K;

    vector<int> x(N),y(N),xs(N),ys(N);
    rep(i,0,N){
        cin >> x[i] >> y[i];
        xs.push_back(x[i]);
        ys.push_back(y[i]);
    }

    sort(begin(xs),end(xs));
    sort(begin(ys),end(ys));

    i64 ans=inf64;
    rep(i,0,xs.size()) rep(j,i+1,xs.size()) rep(k,0,ys.size()) rep(l,k+1,ys.size()){
