class point {
private:
  std::int_fast64_t m_x;
  std::int_fast64_t m_y;

public:
  constexpr point() noexcept :
    point(0, 0) {
  }
  constexpr point(const std::int_fast64_t x, const std::int_fast64_t y) noexcept :
    m_x(x),
    m_y(y) {
  }

  constexpr std::int_fast64_t x() const noexcept {
    return this->m_x;
  }
  constexpr std::int_fast64_t y() const noexcept {
    return this->m_y;
  }

  friend std::istream& operator>>(std::istream& is, point& self) {
    return is >> self.m_x >> self.m_y;
  }
};

int main() {
  std::int_fast64_t n, threshold;
  std::cin >> n >> threshold;
  std::vector<point> points;
  points.reserve(n);
  std::copy_n(std::istream_iterator<point>(std::cin), n, std::back_inserter(points));

  std::vector<std::int_fast64_t> possible_xs;
  std::vector<std::int_fast64_t> possible_ys;
  {
    std::unordered_set<std::int_fast64_t> possible_x_set;
    std::unordered_set<std::int_fast64_t> possible_y_set;
    for (const point& point : points) {
      possible_x_set.insert(point.x());
      possible_y_set.insert(point.y());
    }
    std::copy(possible_x_set.begin(), possible_x_set.end(), std::back_inserter(possible_xs));
    std::copy(possible_y_set.begin(), possible_y_set.end(), std::back_inserter(possible_ys));
  }
  std::sort(possible_xs.begin(), possible_xs.end());
  std::sort(possible_ys.begin(), possible_ys.end());
  const std::int_fast64_t possible_x_count = possible_xs.size();
  const std::int_fast64_t possible_y_count = possible_ys.size();

  std::vector<std::vector<std::int_fast64_t>> cumsum(possible_x_count + 1, std::vector<std::int_fast64_t>(possible_y_count + 1, 0));
  for (std::int_fast64_t i = 0; i < possible_x_count; ++i) {
    const std::int_fast64_t possible_x = possible_xs[i];
    for (std::int_fast64_t j = 0; j < possible_y_count; ++j) {
      const std::int_fast64_t possible_y = possible_ys[j];
      cumsum[i][j] = std::count_if(points.begin(), points.end(), [&possible_x, &possible_y](const point& point) {
        return possible_x <= point.x() && possible_y <= point.y();
      });
    }
  }

  std::int_fast64_t answer = std::numeric_limits<std::int_fast64_t>::max();
  for (std::int_fast64_t i = 0; i < possible_x_count; ++i) {
    const std::int_fast64_t left = possible_xs[i];
    for (std::int_fast64_t j = i + 1; j < possible_x_count; ++j) {
      const std::int_fast64_t right = possible_xs[j];
      for (std::int_fast64_t k = 0; k < possible_y_count; ++k) {
        const std::int_fast64_t bottom = possible_ys[k];
        for (std::int_fast64_t l = k + 1; l < possible_y_count; ++l) {
          const std::int_fast64_t top = possible_ys[l];
          const std::int_fast64_t included_point_count = cumsum[i][k] - cumsum[i][l + 1] - cumsum[j + 1][k] + cumsum[j + 1][l + 1];
          if (included_point_count >= threshold) {
            answer = std::min(answer, (right - left) * (top - bottom));
          }
        }
      }
    }
  }

  std::cout << answer << std::endl;
  return 0;
}

