int n, k;
LL ans;

struct point{
	int x, y;
}a[55];

int xx[55];

bool cmp(point a, point b){
	return a.y < b.y;
}

void solve(int l, int r){
	vector<point> tmp;
	for(int i = 1; i <= n; i++)
		if(a[i].x >= l && a[i].x <= r) tmp.push_back(a[i]);
	sort(tmp.begin(), tmp.end(), cmp);
	if(tmp.size() < k) return;
	for(int i = 0; i <= tmp.size() - k; i++){
		LL are = (LL)(r - l) * (LL)(tmp[i+k-1].y - tmp[i].y);
		ans = min(ans, are);
	}
}


