using namespace std;

int N, K;
int X[50];
int Y[50];

int cnt_map[50][50];
vector<int> grid_x;
vector<int> grid_y;

signed main()
{
	cin >> N >> K;
	REP(i, N)
	{
		cin >> X[i] >> Y[i];
		if (!CONTAINS(grid_x, X[i])) grid_x.push_back(X[i]);
		if (!CONTAINS(grid_y, Y[i])) grid_y.push_back(Y[i]);
	}
	SORT(grid_x);
	SORT(grid_y);

	for (int x = 0; x < grid_x.size(); x++)
	{
		for (int y = 0; y < grid_y.size(); y++)
		{
			for (int i = 0; i < N; i++)
			{
				if (X[i] == grid_x[x] && Y[i] == grid_y[y])
				{
					for (int j = y; j < grid_y.size(); j++)
					{
						cnt_map[x][j]++;
					}
				}
			}
		}
	}


	int ans = LLONG_MAX;

	for (int y1 = 0; y1 < grid_y.size(); y1++)
	{
		for (int y2 = y1; y2 < grid_y.size(); y2++)
		{
			for (int x1 = 0; x1 < grid_x.size(); x1++)
			{
				int cnt = 0;
				for (int x2 = x1; x2 < grid_x.size(); x2++)
				{
					int upper = (y1 == 0) ? 0 : cnt_map[x2][y1 - 1];
					cnt += (cnt_map[x2][y2] - upper);

					if (cnt >= K)
					{
						int dx = grid_x[x2] - grid_x[x1];
						int dy = grid_y[y2] - grid_y[y1];
						ans = MIN(ans, dx * dy);
					}
				}
			}
		}
	}

	cout << ans << endl;
}

