  vvi s(N,vi(N));
  rep(i,N){
    int idx1 = int(lower_bound(posx.begin(),posx.end(),x[i])-posx.begin());
    int idx2 = int(lower_bound(posy.begin(),posy.end(),y[i])-posy.begin());
    s[idx1][idx2]++;
  }
  rep(i,N) rep(j,N-1) s[i][j+1] += s[i][j];
  rep(i,N-1) rep(j,N) s[i+1][j] += s[i][j];
  dump(s);
  auto rsum = [&](int x1,int y1,int x2,int y2){
    int a2 = (y1!=0 ? s[x2][y1-1] : 0);
    int a3 = (x1!=0 ? s[x1-1][y2] : 0);
    int a4 = ((x1!=0 && y1!=0) ? s[x1-1][y1-1] : 0);
    return s[x2][y2] - a2 - a3 + a4;
  };
  unsigned long long ansx,ansy;
  using ld = long double;
  ld anss = 4e20;
  rep(x1,N-1) REP(x2,x1+1,N) rep(y1,N-1) REP(y2,y1+1,N) {
    dump(x1,y1,x2,y2,rsum(x1,y1,x2,y2));
    if(rsum(x1,y1,x2,y2)<K) continue;
    if(ld(posx[x2]-posx[x1])*ld(posy[y2]-posy[y1])>anss) continue;
    ansx = posx[x2] - posx[x1];
    ansy = posy[y2] - posy[y1];
    anss = ld(posx[x2]-posx[x1])*ld(posy[y2]-posy[y1]);
  }
  cout << ansx * ansy << endl;
  return 0;
}

