      if (i > 0 && j > 0) cnt[i][j] += cnt[i-1][j] + cnt[i][j-1] - cnt[i-1][j-1];
    }
  } 
  ll res = INF;

  for (int xi = 0; xi < n; xi++) for (int xj = xi + 1; xj < n ; xj++) {
    for (int yi = 0; yi < n; yi++) for (int yj = yi + 1; yj < n; yj++) {
