int main(){
  int n,K;
  cin >> n >> K;
  int common[n][n],common2[n][n],left[n],under[n];
  for(int i = 0;i < n;i++){
    for(int j = 0;j < n;j++){
      common[i][j] = 0;
      common2[i][j] = 0;
      left[i] = 0;
      under[j] = 0;
    }
  }
  vector<long> x(n),y(n);
  for(int i = 0;i < n;i++){
    cin >> x.at(i) >> y.at(i);
  }
  for(int i = 0;i < n;i++){
    for(int j = 0;j < n;j++){
      for(int k = 0;k < n;k++){
        if(x.at(k) < x.at(i) && y.at(k) < y.at(j)){
          common[i][j] += 1;
        }
      }
    }
  }
  for(int i = 0;i < n;i++){
    for(int j = 0;j < n;j++){
      for(int k = 0;k < n;k++){
        if(x.at(k) <= x.at(i) && y.at(k) <= y.at(j)){
          common2[i][j] += 1;
        }
      }
    }
  }
  for(int i = 0;i < n;i++){
    for(int j = 0;j < n;j++){
      if(x.at(j) < x.at(i)){
        left[i]++;
      }
    }
  }
  for(int i = 0;i < n;i++){
    for(int j = 0;j < n;j++){
      if(y.at(j) < y.at(i)){
        under[i]++;
      }
    }
  }
  long result = 4000000000000000000;
  for(int i = 0;i < n;i++){
    for(int j = 0;j < n;j++){
      for(int k = 0;k < n;k++){
        for(int l = 0;l < n;l++){
          int num = common2[l][i] - left[k] - under[j] + common[k][j];
          if(num >= K && x.at(k) <= x.at(l) && y.at(j) <= y.at(i)){
            long area = (x.at(l) - x.at(k)) * (y.at(i) - y.at(j)); 
            //cout << num << ' ' << area << ' ' << y.at(i) << ' ' << y.at(j) << ' ' << x.at(k) << ' ' << x.at(l) << endl;
            //cout << "info" << common2[l][i] << ' ' << left[k] << ' ' << under[j] << ' ' << common[k][j] << endl;
            result = min(result,area);
          }
        }
      }
    }
  }
  cout << result << endl;
}

