ll N, K;

ll solve(vector<PII> P)
{
    ll ans = INFLL;
    for (int i=0; i<=N-K; i++) {
        ll min_x = INFLL, max_x = -INFLL, min_y = INFLL, max_y = -INFLL;
        rep(j, K) {
            min_x = min(min_x, P[i + j].first);
            max_x = max(max_x, P[i + j].first);
            min_y = min(min_y, P[i + j].second);
            max_y = max(max_y, P[i + j].second);
        }
        ans = min(ans, (max_x - min_x) * (max_y - min_y));
    }
    return ans;
}

int compress(vector<ll> x, map<ll,ll> &zip, vector<ll> &unzip)
{
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    unzip.resize(x.size());

    for (int i=0; i<x.size(); i++) {
        zip[x[i]] = i;
        unzip[i] = x[i];
    }
    return x.size();
}

int main()
{
    ios::sync_with_stdio(false);

    cin >> N >> K;
    vector<PII> P(N);
    vector<ll> X(N), Y(N);
    rep(i, N) {
        cin >> P[i].first >> P[i].second;
        X[i] = P[i].first;
        Y[i] = P[i].second;
    }

    map<ll, ll> zip_x, zip_y;
    vector<ll> unzip_x, unzip_y;

    int W = compress(X, zip_x, unzip_x);
    int H = compress(Y, zip_y, unzip_y);

    vector<vector<bool>> Q(H, vector<bool>(W));
    rep(i, N) {
        Q[zip_y[P[i].second]][zip_x[P[i].first]] = true;
    }

    vector<vector<int>> sum(H+1, vector<int>(W+1));
    rep(y, H) rep(x, W) {
        sum[y+1][x+1] = sum[y][x+1] + sum[y+1][x] - sum[y][x] + Q[y][x];
    }

    ll ans = INFLL;
    rep(ay, H) rep(by, H) rep(ax, W) rep(bx, W) {
        if (ax > bx || ay > by) continue;
        int num = sum[by+1][bx+1] - sum[ay][bx+1] - sum[by+1][ax] + sum[ay][ax];
        if (num >= K) ans = min(ans, ((ll)unzip_x[bx] - unzip_x[ax]) * ((ll)unzip_y[by] - unzip_y[ay]));
    }

    cout << ans << endl;
}

