#include <bits/stdc++.h>
using namespace std;
int64_t C[50][2];
int N, K;
bool inner(int64_t l, int64_t r, int64_t u, int64_t b, int64_t x, int64_t y) {
	return l <= x && x <= r && b <= y && y <= u;
}

int solve(int l, int r, int u, int b) {
	int k = 0;
	for(int i = 0; i < N; i++) {
		if(inner(l, r, u, b, C[i][0], C[i][1])) {
			k++;
		}
	}
	return k;
}

int main() {
	cin >> N >> K;
	for(int i = 0; i < N; i++) {
		cin >> C[i][0] >> C[i][1];
	}
	int64_t S = -1;
	int64_t L, R, U, B;
	for(int l = 0; l < N; l++) {
		for(int r = 0; r < N; r++) {
			for(int u = 0; u < N; u++) {
				for(int b = 0; b < N; b++) {
					L = C[l][0]; R = C[r][0];
					U = C[u][1]; B = C[b][1];
					if(R < L || U < B) continue;
					int k = solve(L, R, U, B);
					if(k >= K) {
						int64_t tmp = (R - L) * (U - B);
						if(tmp < 0) tmp *= -1;
						if(tmp < S || S < 0) S = tmp;
					}
				}
			}
		}
	}
	cout << S << endl;
	return 0;
}

