int includes(const std::vector<intmax_t> &x,
             const std::vector<intmax_t> &y, int xi, int xj, int yi, int yj) {

  intmax_t XL=x[xi], XR=x[xj];
  intmax_t YL=y[yi], YR=y[yj];
  if (XL > XR) std::swap(XL, XR);
  if (YL > YR) std::swap(YL, YR);

  int res=0;
  for (size_t i=0; i<x.size(); ++i)
    if (XL <= x[i] && x[i] <= XR && YL <= y[i] && y[i] <= YR) {
      //fprintf(stderr, "%jd, %jd\n", x[i], y[i]);
      ++res;
    }

  ///fprintf(stderr, "%d\n", res);
  return res;
}

int main() {
  int N, K;
  scanf("%d %d", &N, &K);

  std::vector<intmax_t> x(N), y(N);
  for (int i=0; i<N; ++i) {
    scanf("%jd %jd", &x[i], &y[i]);
  }

  intmax_t res=std::numeric_limits<intmax_t>::max();
  for (int xi=0; xi<N; ++xi)
    for (int xj=xi; xj<N; ++xj)
      for (int yi=0; yi<N; ++yi)
        for (int yj=yi; yj<N; ++yj) {
          int cur=includes(x, y, xi, xj, yi, yj);
          if (cur < K) continue;

          res = std::min(res, std::abs(x[xi]-x[xj])*std::abs(y[yi]-y[yj]));
        }

  printf("%jd\n", res);
  return 0;
}

