struct Pair{
    ll min_x;
    ll max_x;
    ll min_y;
    ll max_y;
};

ll area(Pair p){
    ll x=p.max_x-p.min_x;
    ll y=p.max_y-p.min_y;
    return x*y;
}

Pair dp[55][55];

int main(){
