    rep(i,n){
        rep(j,i){
            for(int k=j+1;k<=i;k++){
                Pair p=(Pair){min(x[j],x[k]),max(x[j],x[k]),min(y[j],y[k]),max(y[j],y[k])};
                if(area(p)<area(dp[i+1][2])) dp[i+1][2]=p;
            }
        }
    }
    for(int i=0;i<n;i++){
        for(int j=3;j<=i+1;j++){
            for(int k=2;k<=i;k++){
                Pair p=dp[k][j-1];
