ll count(ll left, ll right, ll under, ll up, vector<pair<ll, ll>> &v) {
    if (left > right | under > up) {
        return 0;
    }
    ll ans = 0;
    rep(i, v.size()) {
        if (left <= v[i].first && v[i].first <= right) {
            if (under <= v[i].second && v[i].second <= up) {
                ans++;
            }
        }
    }
    return ans;
}

