int main(){
  int n,k;
  cin >> n >> k;
  vector<ll> x(n);
  vector<ll> y(n);
  vector<ll> tx(n); //copy
  vector<ll> ty(n); //copy ソート用に使う
  rep(i, n){
    int w;
    cin >> w;
    x[i] = w;
    tx[i] = w;
    int h;
    cin >> h;
    y[i] = h;
    ty[i] = h;
  }
  //sort
  rep(i, n){
    for(int j = n - 1; j > i; j--){
      if(tx[j] < tx[j - 1]){
        int temp = tx[j];
        tx[j] = tx[j - 1];
        tx[j - 1] = temp;
      }
    }
  }
  rep(i, n){
    for(int j = n - 1; j > i; j--){
      if(ty[j] < ty[j - 1]){
        int temp = ty[j];
        ty[j] = ty[j - 1];
        ty[j - 1] = temp;
      }
    }
  }
  //sort end
  ll square = 0;
  bool first = true;
  rep(w, n - 1){
    for(int dw = w + 1; dw < n; dw++){
      rep(h, n - 1){
        for(int dh = h + 1; dh < n; dh++){
          int cnt = min(dw - w, dh - h) + 1;
          if(cnt == k){
            if(first){
              square = (tx[dw]-tx[w]) * (ty[dh]-ty[h]);
              first = false;
              continue;
            }
            square = min(square, (tx[dw]-tx[w]) * (ty[dh]-ty[h]));
          }
        }
      }
    }
  }
  cout << square << endl;
  return 0;
}

