ll sqrd(pii a, pii b)
{
    int dx = a.fst - b.fst;
    int dy = a.sec = b.sec;
    return ((ll)dx * dx + dy * dy);
}

signed main()
{
    int n = in(), k = in();
    vec<pii> point;
    REP(i, n){
        int x = in(), y = in();
        point.pb(x, y);
    }

    set<pair<ll, pii>> distance;
    REP(i, n){
        pair<ll, pii> d(0, point[i]);
        REP(j, n){
            if (i == j){ continue; }
            d.fst += sqrd(point[i], point[j]);
        }
        distance.insert(d);
    }

    int minx = INF;
    int miny = INF;
    int maxx = 0;
    int maxy = 0;
    for (auto& i : distance){
        minx = min(minx, i.sec.fst);
        miny = min(miny, i.sec.sec);
        maxx = max(maxx, i.sec.fst);
        maxy = max(maxy, i.sec.sec);
        if (--k == 0){ break; }
    }
    print(ll(maxx - minx) * (maxy - miny));

    return 0;
}

