bool has_enough(ll xmin, ll xmax, ll ymin, ll ymax, vector<P> &xy){
  int cnt = 0;
  for (int i = 0; i < n; ++i) {
    ll x = xy[i].first;
    ll y = xy[i].second;
    if (x >= xmin && x <= xmax && y >= ymin && y <= ymax)
      cnt++;
  }
  return cnt >= k;
}
