set<int> all;
map<int, int> id, rev;
vector<ii> points;
vector<int> adj[N];

void init() {
    int av = 0;
    for(int k : all) {
        id[k] = av;
        rev[av] = k;
        av++;
    }
    for(auto p : points) {
        int x = id[p.first];
        int y = id[p.second];
        adj[x].push_back(y);
    }
    fori(i, 0, N) {
        sort(adj[i].begin(), adj[i].end());
    }
}

inline int many(int x, int y1, int y2) {
    auto ata = lower_bound(adj[x].begin(), adj[x].end(), y1);
    if(ata == adj[x].end() or (ata != adj[x].end() and *ata > y2)) return 0;

    int a = ata - adj[x].begin();

    auto atb = lower_bound(adj[x].begin(), adj[x].end(), y2);
    if(atb == adj[x].end() or (atb != adj[x].end() and *atb > y2)) {
        --atb;
    }
    int b = atb - adj[x].begin();
    int res = b - a + 1;
    return max(0, res);
}

inline int many(int x1, int x2, int y1, int y2) {
    int res = 0;
    fori(i, x1, x2 + 1) {
        res += many(i, y1, y2);
    }
    return res;
}

int n, k;

inline ll solve() {
    ll ans = 1LL << 62;
    fori(x1, 0, N) {
        if(rev.find(x1) == rev.end()) continue;

        fori(x2, x1, N) {
            if(rev.find(x2) == rev.end()) continue;

            fori(y1, 0, N) {
                if(rev.find(y1) == rev.end()) continue;

                fori(y2, y1, N) {
                    if(rev.find(y2) == rev.end()) continue;

                    int cont = many(x1, x2, y1, y2);
                    if(cont >= k) {
                        ll area = ((ll) rev[x2] - rev[x1]) * ((ll) rev[y2] - rev[y1]);

                        ans = min(ans, area);
                    }
                }
            }
        }
    }
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);

    cin >> n >> k;
    fori(i, 0, n) {
        int x, y;
        cin >> x >> y;
        all.insert(x);
        all.insert(y);
        points.push_back({x, y});
    }
    init();

    ll ans = solve();
    cout << ans << '\n';

    return 0;
}

