using ll = long long;
using uint = unsigned int;

int main() {
    ll N, K;
    cin >> N >> K;
    vector<ll> xs(N, 0), ys(N, 0);
    for (auto &&i: boost::irange(0LL, N)) {
        cin >> xs.at(i) >> ys.at(i);
    }
    ll min_square = numeric_limits<ll>::max();
    vector<ll> xs_sorted(xs), ys_sorted(ys);
    sort(xs_sorted.begin(), xs_sorted.end());
    sort(ys_sorted.begin(), ys_sorted.end());

    for (auto &&i_x_min: boost::irange(0LL, N)) {
        ll x_min{xs_sorted.at(i_x_min)};
        for (auto &&i_x_max: boost::irange(i_x_min, N)) {
            ll x_max{xs_sorted.at(i_x_max)};
            for (auto &&i_y_min: boost::irange(0LL, N)) {
                ll y_min{ys_sorted.at(i_y_min)};
                for (auto &&i_y_max: boost::irange(i_y_min, N)) {
                    ll y_max{ys_sorted.at(i_y_max)};
                    ll count = 0;
                    for (auto &&i: boost::irange(0LL, N)) {
                        ll x{xs.at(i)};
                        ll y{ys.at(i)};
                        if (x_min <= x && x <= x_max && y_min <= y && y <= y_max) {
                            count++;
                        };
                    }
                    if (count > K){
                        min_square = min(min_square, (x_max - x_min) * (y_max - y_min));
                    }
                }
            }
        }
    }
    cout << min_square;
}

