using namespace std;

struct BinaryIndexedTree {
  BinaryIndexedTree(int h, int w) : h(h), w(w), v(h + 1, vector<int>(w + 1, 0)) {}
  BinaryIndexedTree(int n) : h(n), w(n), v(n + 1, vector<int>(n + 1, 0)) {}

  int h, w;
  vector<vector<int>> v;

  long long sum(int y, int x) {
    long long ret = 0;
    for (int i = y; i; i -= i & -i) {
      for (int j = x; j; j -= j & -j) {
        ret += v[i][j];
      }
    }

    return ret;
  }

  long long sum(int y1, int x1, int y2, int x2) {
    return sum(y1, x1) - sum(y1, x2) - sum(y2, x1) + sum(y2, x2);
  }

  void add(int y, int x) {
    for (int i = y; i <= n; i += i & -i) {
      for (int j = x; j <= n; j += j & -j) {
        v[i][j]++;
      }
    }
  }
};

int main() {
  int n, K;
  cin >> n >> K;

  vector<long long> x, y, a, b;
  map<long long, int> X, Y;
  for (int i = 0; i < n; ++i) {
    int s, t;
