    x.push_back(s);
    y.push_back(t);
  }

  a = x;
  b = y;

  sort(a.begin(), a.end());
  sort(b.begin(), b.end());
  for (int i = 0; i < n; ++i) {
    X[a[i]] = i + 1;
    Y[b[i]] = i + 1;
  }

  BinaryIndexedTree bit(n);
  for (int i = 0; i < n; ++i) {
    bit.add(Y[y[i]], X[x[i]]);
  }

  long long ans = 5001001001001001001;
  for (int i = 0; i < n; ++i) {
    for (int j = i + 1; j < n; ++j) {
      for (int k = 0; k < n; ++k) {
        for (int l = k + 1; l < n; ++l) {
          if (bit.sum(Y[b[l]], X[a[j]], Y[b[k]] - 1, X[a[i]] - 1) >= K) {
            ans = min(ans, (b[l] - b[k]) * (a[j] - a[i]));
          }
        }
      }
    }
  }

