const ll INF=1e18;
const int mx=200005;

struct Pair{
    ll min_x;
    ll max_x;
    ll min_y;
    ll max_y;
};

ll area(Pair p){
    ll x=p.max_x-p.min_x;
    ll y=p.max_y-p.min_y;
    return x*y;
}

Pair dp[55][55];

int main(){
    cin.tie(0);ios::sync_with_stdio(false);
    ll n,K;
    cin>>n>>K;
    V<ll> x(n),y(n);
    rep(i,n) cin>>x[i]>>y[i];
    ll tmp=ll(1e9);
    for(int i=0;i<=50;i++) for(int j=0;j<=50;j++) dp[i][j]=(Pair){-tmp,tmp,-tmp,tmp};
    //dp[2][2]=(Pair){min(x[0],x[1]),max(x[0],x[1]),min(y[0],y[1]),max(y[0],y[1])};
    rep(i,n) dp[i+1][1]=(Pair){x[i],x[i],y[i],y[i]};
    for(int i=1;i<n;i++){
        for(int j=2;j<=n;j++){
            for(int k=1;k<=i;k++){
                Pair p=dp[k][j-1];
                chmin(p.min_x,x[i]);
                chmax(p.max_x,x[i]);
                chmin(p.min_y,y[i]);
                chmax(p.max_y,y[i]);
                if(area(p)<area(dp[i+1][j])) dp[i+1][j]=p;
            }
        }
    }
    ll ans=4*INF+1;
    for(int i=2;i<=n;i++) chmin(ans,area(dp[i][K]));
    out(ans);
}

