int dp[55][55];
int a[55];
int xlen=1,ylen=1;
ll ans=5e18;

ll FIND(bool flag,int value){
	if(flag==0){
		for(auto it=cntx.begin();it!=cntx.end();it++){
			if(it->second==value)	return it->first;
		}
	}
	else {
		for(auto it=cnty.begin();it!=cnty.end();it++){
			if(it->second==value)	return it->first;
		}
	}
}

int main(){
	memset(dp,0,sizeof(dp));
	int n,k;	scanf("%d%d",&n,&k);
	for(int i=0;i<n;i++)	scanf("%lld%lld",&node[0][i],&node[1][i]);
	for(int i=0;i<n;i++){
		x.push_back(node[0][i]);
		y.push_back(node[1][i]);
	}
	sort(x.begin(),x.end());
	sort(y.begin(),y.end());
	x.erase(unique(x.begin(),x.end()),x.end());
	y.erase(unique(y.begin(),y.end()),y.end());
	for(int i=0;i<x.size();i++){
		cntx[xlen]=x[i];
		x[i]=xlen++;
	}
	for(int i=0;i<y.size();i++){
		cnty[ylen]=y[i];
		y[i]=ylen++;
	}
	for(int i=0;i<n;i++){
		dp[FIND(0,node[0][i])][FIND(1,node[1][i])]++;
	}
	for(int i=1;i<xlen;i++){
		for(int j=1;j<ylen;j++){
			dp[i][j]+=dp[i-1][j]+dp[i][j-1]-dp[i-1][j-1];
		}
	}
	for(int L=1;L<xlen;L++){
		for(int R=L;R<xlen;R++){
			for(int i=1;i<xlen;i++)	a[i]=dp[R][i]-dp[L-1][i];
			for(int i=1;i<ylen;i++){
				int pos=lower_bound(a,a+ylen,a[i-1]+k)-a;
				if(pos!=ylen){
					ans=min(((ll)(cntx.find(pos)->second)-(cntx.find(i)->second))*((cnty.find(pos)->second)-(cnty.find(i))->second),ans);
				}
			}
		}
	}
	printf("%lld\n",ans);
	return 0;
}

