P ps[60];
int cs[60][60];

int main(void) {
  int n, k;
  scanf("%d%d", &n, &k);
  REP(i, n) {
    scanf("%lld%lld", &ps[i].x, &ps[i].y);
    id2x[i] = ps[i].x;
    id2y[i] = ps[i].y;
  }
  id2x[n+1] = 1000000000 + 1;
  id2y[n+1] = 1000000000 + 1;
  sort(id2x, id2x + n+1);
  sort(id2y, id2y + n+1);
  REP(ix, n+1) {
    REP(iy, n+1) {
      ll x = id2x[ix];
      ll y = id2y[iy];
      int cnt = 0;
      REP(i, n) {
        if(ps[i].x <= x && ps[i].y <= y) {
          ++cnt;
        }
      }
      cs[ix+1][iy+1] = cnt;
    }
  }
  ll res = 4e18;
  REP(ix2, n+1) {
    REP(ix1, ix2) {
      REP(iy2, n+1) {
