#define MAXN 55
int n, k;
int x[MAXN], y[MAXN];
vector<int> xx, yy;

unordered_map<int, int> mapx, mapy;

int bit[MAXN][MAXN];

int lowbit(int x) {return x & -x;}

void add(int p, int q, int v) {
    for (int i = p; i < MAXN; i += lowbit(i)) {
        for (int j = q; j < MAXN; j += lowbit(j)) {
            bit[i][j] += v;
        }
    }
}

int sum(int p, int q) {
    int res = 0;
    for (int i = p; i; i -= lowbit(i)) {
        for (int j = q; j; j -= lowbit(j)) {
            res += bit[i][j];
        }
    }
    return res;
}

int range(int x1, int y1, int x2, int y2) {
    int res = sum(x2, y2) - sum(x2, y1 - 1) - sum(x1 - 1, y2) + sum(x1 - 1, y1 - 1);
    return res;
}

int main() {
    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", x + i, y + i);
        xx.pb(x[i]);
        yy.pb(y[i]);
    }
    sort(all(xx));
    sort(all(yy));
    xx.resize(distance(xx.begin(), unique(all(xx))));
    yy.resize(distance(yy.begin(), unique(all(yy))));

    memset(bit, 0, sizeof(bit));
    for (int i = 0; i < n; ++i) {
        int ind = lower_bound(all(xx), x[i]) - xx.begin() + 1;
        mapx[ind] = x[i];
        x[i] = ind;
        ind = lower_bound(all(yy), y[i]) - yy.begin() + 1;
        mapy[ind] = y[i];
        y[i] = ind;
        add(x[i], y[i], 1);
    }

    ll res = LLONG_MAX;
    for (int l = 0; l < xx.size(); ++l) {
        for (int r = l; r < xx.size(); ++r) {
            for (int d = 0; d < yy.size(); ++d) {
                for (int u = d; u < yy.size(); ++u) {
                    if (range(l + 1, d + 1, r + 1, u + 1) >= k) {
                        res = min(res, 1LL * (mapx[r + 1] - mapx[l + 1]) * (mapy[u + 1] - mapy[d + 1]));
                    }
                }
            }
        }
    }
    cout << res;

    return 0;
}

