bool Inside(int n,int k,int i,int j,vector<long long> x,vector<long long> y,bool flag) {
    int count = 0;
    if(flag){
        for(int a = 0;a < n;a++) {
            if(x[a] >= x[i] && x[a] <= x[j] && y[a] >= y[i] && y[a] <= y[j]){
                count++;
            }
        }
    }else{
        for(int a = 0;a < n;a++) {
            if(x[a] <= x[i] && x[a] >= x[j] && y[a] >= y[i] && y[a] <= y[j]){
                count++;
            }
        }
    }
    if (count == k) return true;
    else return false;

}

int main() {
    int n,k;
    vector<long long> x,y;
    long long sub;
    bool flag;
    long long min = 9223372036854775807;
    long long S;

    cin >> n >> k;

    for(int i = 0;i < n;i++) {
        cin >> sub;
        x.push_back(sub);
        cin >> sub;
        y.push_back(sub);
    }

    for(int i = 0;i < n;i++) {
        for(int j = 0;j < n;j++) {
            if(x[i] <= x[j]) flag = true;
            else flag = false;
            if(y[i] > y[j]) swap(i,j);
            if(Inside(n,k,i,j,x,y,flag)){
                S = abs(x[i] - x[j]) * abs(y[i] - y[j]);
                if(S < min) min = S;
            }

        }
    }

    cout << min << endl;

    return 0;

}

