ll N, K;

ll solve(vector<PII> P)
{
    ll ans = INFLL;
    for (int i=0; i<=N-K; i++) {
        ll min_x = INFLL, max_x = -INFLL, min_y = INFLL, max_y = -INFLL;
        rep(j, K) {
            min_x = min(min_x, P[i + j].first);
            max_x = max(max_x, P[i + j].first);
            min_y = min(min_y, P[i + j].second);
            max_y = max(max_y, P[i + j].second);
        }
        ans = min(ans, (max_x - min_x) * (max_y - min_y));
    }
    return ans;
}

