typedef long long ll;

int N, K;
int xy[55][2];
int x[55], y[55];

int f[60][60];
int dp[60][60];

ll ans = INF, area;

map<int, int> map_x, map_y, rmap_x, rmap_y;

void solve() {
    sort(x, x + N); // 制約より重複なし
    sort(y, y + N); // 制約より重複なし
    for (int i = 0; i < N; i++) {
        map_x[x[i]] = i + 1;
        map_y[y[i]] = i + 1;
        rmap_x[i + 1] = x[i];
        rmap_y[i + 1] = y[i];
    }
    for (int i = 0; i < N; i++) {
        int c_x = map_x[xy[i][0]];
        int c_y = map_y[xy[i][1]];
        f[c_y][c_x] = 1;
    }
    for (int i = 0; i < 55; i++) {
        for (int j = 0; j < 55; j++) {
            dp[i + 1][j + 1] = f[i + 1][j + 1] + dp[i][j + 1] + dp[i + 1][j] - dp[i][j];
        }
    }
    for (int a = 0; a < N; a++) {
        for (int b = a + 1; b < N; b++) {
            for (int c = 0; c < N; c++) {
                for (int d = c + 1; d < N; d++) {
                    int x1 = min(min(xy[a][0], xy[b][0]), min(xy[c][0], xy[d][0]));
                    int x2 = max(max(xy[a][0], xy[b][0]), max(xy[c][0], xy[d][0]));
                    int y1 = min(min(xy[a][1], xy[b][1]), min(xy[c][1], xy[d][1]));
                    int y2 = max(max(xy[a][1], xy[b][1]), max(xy[c][1], xy[d][1]));

                    int c_x1 = map_x[x1];
                    int c_x2 = map_x[x2];
                    int c_y1 = map_y[y1];
                    int c_y2 = map_y[y2];

                    ll area = ((ll)x2 - (ll)x1) * ((ll)y2 -(ll)y1);
                    int cnt = dp[c_y2][c_x2] - dp[c_y2][c_x1 - 1] - dp[c_y1 - 1][c_x2] + dp[c_y1 - 1][c_x1 - 1];

                    if (cnt >= K) {
                        ans = min(ans, area);
                    }
                }
            }
        }
    }
    #if 0
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            cout << dp[i][j] << " ";
        }
        cout << endl;
    }
    #endif

    cout << ans << endl;
}

