int main() {
	int n, need;
	cin >> n >> need;
	int64_t x[n], y[n];
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
	}
	int64_t ans = numeric_limits<int64_t>::max();
	if (need == 2) {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (i == j) continue;
				ans = min(ans, (max(x[i], x[j]) - min(x[i], x[j])) * (max(y[i], y[j]) - min(y[i], y[j])));
			}
		}
	} else {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				for (int k = 0; k < n; k++) {
					if (i == j || j == k || i == k) continue;
					int count = 0;
					int64_t left = min({x[i], x[j], x[k]});
					int64_t right = max({x[i], x[j], x[k]});
					int64_t down = min({y[i], y[j], y[k]});
					int64_t up = max({y[i], y[j], y[k]});
					for (int l = 0; l < n; l++) {
						if (left <= x[l] && x[l] <= right && down <= y[l] && y[l] <= up) {
							count++;
						}
					}
					if (need <= count) {
						ans = min(ans, (right - left) * (up - down));
					}
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

