bool isInclude(pair<lli,lli> left, pair<lli,lli> right,pair<lli,lli> target){
	if(left.first <= target.first && target.first <= right.first){
		if(left.second <= target.second && target.second <= right.second){
			if(DEBUG)cout<<"include!"<<endl;
			return true;
		}
	}
	return false;
}

int main(){

	lli n,k;
	cin>>n>>k;
	vector<pair<lli,lli>> v(n);
	REP(i,n)cin>>v[i].first>>v[i].second;

	/*2点選んで、そこでできた長方形の中に点が何個含まれているかを数える。*/
	/*条件を満たしている場合のみカウントする*/

	lli ans = 8000000000000000000;
	REP(ix,n)REP(jx,n)REP(iy,n)REP(jy,n){
		pair<lli,lli> left;
		pair<lli,lli> right;
		left.first  = min(v[ix].first,v[jx].first);
		left.second = min(v[iy].second,v[jy].second);
		right.first = max(v[ix].first,v[jx].first);
		right.second= max(v[iy].second,v[jy].second);

		if(DEBUG)cout<<"leftF = "<<left.first<<"leftS="<<left.second;
		if(DEBUG)cout<<"rightF= "<<right.first<<"right.S="<<right.second;
		lli space = abs(right.first-left.first)*abs(left.second-right.second);

		/*条件判定*/
		lli cnt=0;
		REP(target,n){
			if(DEBUG)cout<<"target="<<target<<endl;
			if(isInclude(left,right,v[target]))cnt++;
		}
		if(cnt>=k)ans = min(ans,space);
	}
	cout<<ans<<endl;

	return 0;
}

