int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, k; cin >> n >> k;
    vector<int> x(n), y(n);
    for(int i= 0; i < n; i++) cin >> x[i] >> y[i];

    ll ans = 9001001001001001001;
    for(int ix = 0 ; ix < n; ix++){
        for(int jx = ix+1; jx < n; jx++){
            int l = x[ix]; int r = x[jx];
            if(l > r) swap(l, r);
            for(int iy = 0; iy < n; iy++){
                for(int jy = iy+1; jy < n; jy++){
                    int t = y[iy]; int b = y[jy];
                    if(t < b) swap(t,b);
                    int cnt = 0;
                    for(int a = 0; a < n; a++){
                        if(l <= x[a] && x[a] <= r && b <= y[a] && y[a]<=t) cnt++;
                        if(cnt == k) ans = min(ans, (ll)(r-l)*(t-b));
                    }
                }
            }
        }
    }

    cout << ans << endl;
    return 0;
}

