using namespace std;

void solve(int n, int k, vector< pair<int, int> > xy) {
    sort(xy.begin(), xy.end());
    unsigned long long ret = 0;
    for (int i = 0; i < n-k+1; i++) {
        int ymax = xy[i].second, ymin = xy[i].second;
        for (int j = 0; j < k; j++) {
            if (xy[i+j].second < ymin) {
                ymin = xy[i+j].second;
            }
            if (xy[i+j].second > ymax) {
                ymax = xy[i+j].second;
            }
        }
        if (ret == 0) {
            ret = (unsigned long long)(ymax - ymin) * (xy[i+k-1].first - xy[i].first);
        }
        if ((unsigned long long)(ymax - ymin) * (xy[i+k-1].first - xy[i].first) < ret) {
            ret = (unsigned long long)(ymax - ymin) * (xy[i+k-1].first - xy[i].first);
        }
    }
    std::cout << ret << std::endl;
}

int main() {
    struct timeval start,end;
    long long span;
    int n, k;

    gettimeofday(&start,NULL);

    std::cin >> n >> k;
    vector< pair<int, int> > xy(n);
    for (int i = 0; i < n; i++) {
        std::cin >> xy[i].first >> xy[i].second;
    }
    solve(n, k, xy);

    gettimeofday(&end,NULL);
    span = (end.tv_sec -start.tv_sec)*1000000LL + (end.tv_usec - start.tv_usec);
    std::cerr << "--Total Time: " << span/1000 << "ms" << endl;
    return 0;
}

