int main(){
  int n, k;
  cin >> n >> k;

  vector<pair <long, long> > height;
  vector<pair <long, long> > width;

  for (int i = 0; i < n; i++){
    long long x, y;
    scanf("%lld %lld", &x, &y);
    width.push_back(make_pair(x, y));
    height.push_back(make_pair(y, x));
  }
  sort(height.begin(), height.end());
  sort(width.begin(), width.end());

  long long w;
  long long h;

  while (n != k) {
    w = width[n - 1].first - width[0].first;
    h = height[n - 1].first - height[0].first;
    pair <long, long> u[4];
    u[0] = width[0];
    u[1] = width[n-1];
    u[2] = make_pair(height[0].second, height[0].first);
    u[3] = make_pair(height[n-1].second, height[n-1].first);
    long long diff[4];
    diff[0] = width[1].first - width[0].first;
    diff[1] = width[n-1].first - width[n-2].first;
    diff[2] = height[1].first - height[0].first;
    diff[3] = height[n-1].first - height[n-2].first;
    long long sub[4];
    sub[0] = (diff[0]) * h;
    sub[1] = (diff[1]) * h;
    sub[2] = (diff[2]) * w;
    sub[3] = (diff[3]) * w;
    for (int i = 0; i < 4; i++){
      for (int j = i; j < 4; j++){
        if (u[i].first == u[j].second){
          sub[i] += sub[j] - diff[i] * diff[j];
        }
      }
    }
    int imax = -1;
    long long ma = 0;
    for (int i = 0; i < 4; i++){
      if (ma < sub[i]){
        ma = sub[i];
        imax = i;
      }
    }
    width.erase(lower_bound(width.begin(), width.end(), u[imax]));
    height.erase(lower_bound(height.begin(), height.end(), make_pair(u[imax].second, u[imax].first)));
    n--;
  }

  w = width[n - 1].first - width[0].first;
  h = height[n - 1].first - height[0].first;
  cout << w * h << "\n";

  return 0;
}

