#define int long long

vector<int> x, y;

bool ok(int yy1, int yy2, int xx1, int xx2, int u){
	if(x[u] < x[xx1] || x[xx2] < x[u])return 0;
	if(y[u] < y[yy1] || y[yy2] < y[u])return 0;
	return 1;
}

signed main(){
	int n, k, t1, t2;
	scanf("%lld%lld", &n, &k);
	for(int i = 0;i < n;i++){
		scanf("%lld%lld", &t1, &t2);
		x.push_back(t1);
		y.push_back(t2);
	}
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());

	int ans = (x[n-1]-x[0])*(y[n-1]-y[0]);
	for(int yy1 = 0;yy1 < n;yy1++){
		for(int yy2 = yy1+1;yy2 < n;yy2++){
			for(int xx1 = 0;xx1 < n;xx1++){
				for(int xx2 = xx1+1;xx2 < n;xx2++){
					int dis = x[xx2]-x[xx1];
					dis *= y[yy2]-y[yy1];
					int cnt = 0;
					for(int i = 0;i < n;i++){
						if(ok(yy1, yy2, xx1, xx2, i))cnt++;
					}
					if(cnt >= k)ans = min(ans, dis);
				}
			}
		}
	}

	printf("%lld\n", ans);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
const int maxn=100;
const LL inf=(4*1e9)*(4*1e9);
LL x[maxn], y[maxn];
int n, k;

int check(LL px1, LL py1, LL px2, LL py2){
    int cnt=0;
    for(int i=0;i<n;i++){
        bool bx=1, by=1;
        if((x[i]>px1&&x[i]>px2)||(x[i]<px1&&x[i]<px2))bx=0;
        if((y[i]>py1&&y[i]>py2)||(y[i]<py1&&y[i]<py2))by=0;
        if(bx&&by)cnt++;
    }
    return cnt;
}

LL pd(LL x1, LL x2){
    return max(x1, x2)-min(x1, x2);
}

int main(){
    while(~scanf("%d%d", &n, &k)){
        LL maxx=-inf,maxy=-inf,minx=inf,miny=inf;
        for(int i=0;i<n;i++){
            scanf("%lld%lld", &x[i], &y[i]);
            maxx=max(maxx, x[i]);
            maxy=max(maxy, y[i]);
            minx=min(minx, x[i]);
            miny=min(miny, y[i]);
        }
        LL ans=inf;
        for(int i=0;i<n;i++){
            for(int j=i+1;j<n;j++){
                if(check(x[i], y[i], x[j], y[j])>=k){
                    ans=min(ans, pd(x[i],x[j])*pd(y[i], y[j]));
                }
                for(int a=j+1;a<n;a++){
                    LL upx=a[x], lowx=a[x], upy=a[y], lowy=a[y];
                    upx=max(upx, x[i]),upx=max(upx, x[j]);
                    lowx=min(lowx, x[i]),lowx=min(lowx,x[j]);
                    upy=max(upy, y[i]),upy=max(upy, y[j]);
                    lowy=min(lowx, x[i]),lowy=min(lowy,y[j]);
                    if(check(upx, upy, lowx, lowy)>=k){
                        ans=min(ans, pd(upx,lowx)*pd(upy, lowy));
                    }
                }
            }
        }
        if(ans==inf)ans=pd(maxx, minx)*pd(maxy, miny);
        printf("%lld\n", ans);
    }
    return 0;
}

