bool Inside(int n,int k,int i,int j,vector<long long> x,vector<long long> y,bool flag) {
    int count = 0;
    if(flag){
        for(int a = 0;a < n;a++) {
            if(x[a] >= x[i] && x[a] <= x[j] && y[a] >= y[i] && y[a] <= y[j]){
                count++;
            }
        }
    }else{
        for(int a = 0;a < n;a++) {
            if(x[a] <= x[i] && x[a] >= x[j] && y[a] >= y[i] && y[a] <= y[j]){
                count++;
            }
        }
    }
    if (count == k) return true;
    else return false;

}

