ll *x;
ll *y;
vector<ll> indexs;
vector<ll> selectX;
vector<ll> selectY;
long long answer;

void select(ll count, int beforeIndex)
{
	if (count == K)
	{
		ll minX = N;
		ll maxX = 0;
		ll minY = N;
		ll maxY = 0;
		for (int i = 0; i < K; i++)
		{
			if (minX > selectX[i])
				minX = selectX[i];
			if (maxX < selectX[i])
				maxX = selectX[i];
			if (minY > selectY[i])
				minY = selectY[i];
			if (maxY < selectY[i])
				maxY = selectY[i];
		}

		ll h = maxX - minX;
		ll w = maxY - minY;
		answer = (answer > h * w) ? h * w : answer;
	}
	else
	{
		for (int i = beforeIndex; i < indexs.size(); i++)
		{
			selectX.push_back(x[i]);
			selectY.push_back(y[i]);

			select(count + 1,i + 1);

			selectX.pop_back();
			selectY.pop_back();
		}
	}
}

