ull MakeRectangle(vector<pair<ll,ll>> vec){
    vector<ll> x(vec.size()), y(vec.size());
    for(int i=0; i<vec.size(); i++){
        x.at(i) = vec.at(i).first;
        y.at(i) = vec.at(i).second;
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    return (y.back() - y.at(0)) * (x.back() - x.at(0));
}

int main(void){
    int n, k;
