    vector<pair<ll,ll>> vec(n);
    for(int i=0; i<n; i++){
        cin >> vec.at(i).first >> vec.at(i).second;
    }

    ull ans = MakeRectangle(vec);

    while(vec.size() > k){
        int p = -1;
        for(int i=0; i<vec.size(); i++){
            vector<pair<ll,ll>> v = vec;
            v.erase(v.begin() + i);
            ull area = MakeRectangle(v);
            if(area < ans){
                ans = area;
                p = i;
            }
        }
        vec.erase(vec.begin() + p);
    }

    cout << ans << endl;

    return 0;
}

