int subsum(int x_min, int y_min, int x_max, int y_max) {
    return f[x_max][y_max] - f[x_max][y_min-1] - f[x_min-1][y_max] + f[x_min-1][y_min-1];
}

ll solve() {
    map<int, int> mx, my;
    map<int, int> mxr, myr;
    for (int i = 0; i < n; i++) {
        mx[x[i]] = 0;
        my[y[i]] = 0;
    }

