        mxr[idx] = v.first;
        idx++;
    }
    idx = 1;
    for (auto v : my) {
        my[v.first] = idx;
        myr[idx] = v.first;
        idx++;
    }

    for (int i = 0; i < n; i++) {
        f[mx[x[i]]][my[y[i]]]++;
    }
    for (int i = 1; i < 55; i++) {
        for (int j = 1; j < 55; j++) {
            f[i][j] += f[i-1][j] + f[i][j-1] - f[i-1][j-1];
        }
    }

    ll res = 9e18;
    for (int i0 = 0; i0 < n; i0++) {
