struct pos {
    ll x, y;
};

bool comp_x(pos& p1, pos& p2) {
    return p1.x < p2.x;
}

bool comp_y(pos& p1, pos& p2) {
    return p1.y < p2.y;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll n, k;
    cin >> n >> k;
    pos p[n];
    rep(i, n) cin >> p[i].x >> p[i].y;

    ll Min = LINF;

    rep(i1, n) REP(i2, i1, n) REP(i3, i2, n) REP(i4, i3, n) {
        vector<pos> v = {p[i1], p[i2], p[i3], p[i4]};
        sort(v.begin(), v.end(), comp_x);
        ll left = v[0].x;
        ll right = v[3].x;
        sort(v.begin(), v.end(), comp_y);
        ll down = v[0].y;
        ll up = v[3].y;

        int cnt = 0;

        rep(i, n) {
            if (p[i].x >= left && p[i].x <= right
                    && p[i].y <= up && p[i].y >= down) cnt++;
        }

        if (cnt >= k) {
            Min = min(Min, (right - left) * (up - down));
        }
    }

    cout << Min << endl;
    return 0;
}

