int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k; cin >> n >> k;
    int64 x[n], y[n], tx[n], ty[n]; 
    rep(i, n) {
      cin >> x[i] >> y[i];
      tx[i] = x[i]; ty[i] = y[i];
    }

    sort(x, x + n); sort(y, y + n);

    int64 ans = (x[n - 1] - x[0]) * (y[n - 1] - y[0]);  // largest rectangle

    for (int64 xleft = 0; xleft < n; ++xleft){
        for (int64 xright = xleft + 1; xright < n; ++xright){
            for (int64 ybottom = 0; ybottom < n; ++ybottom){
                for (int64 yupper = ybottom + 1; yupper < n; ++yupper){
                    int cnt = 0;
                    int64 left = x[xleft], right = x[xright], upper = y[yupper], bottom = y[ybottom];
                    for (int i = 0; i < n; ++i){
                        if (tx[i] >= left && tx[i] <= right && ty[i] >= bottom && ty[i] <= upper) ++cnt;
                    }

                    if (cnt >= k) ans = min(ans, (right - left) * (upper - bottom));
                }
            }
        }
    }

    print(ans);

    return 0;
}

