void myqsort( int begin, int end, int *v) {
  int aux, b = begin, e = end,
    pivot = v[(begin + end) / 2];

  while ( b <= e ) {
    while ( v[b] < pivot ) b++;
    while ( v[e] > pivot ) e--;
    if ( b <= e ) {
      aux = l[b]; l[b] = l[e]; l[e] = aux;
      aux = c[b]; c[b] = c[e]; c[e] = aux;
      b++; e--;
    }
  }
  if ( begin < e ) myqsort( begin, e ,v);
  if ( b < end ) myqsort( b, end, v);
}
