pair<int, int> xy[51];
int main()
{
	int N, K;
	cin >> N >> K;
	REP(i, N)
	{
		cin >> xy[i].first >> xy[i].second;
	}

	sort(xy, xy + N, [](pair<int, int> a, pair<int, int> b) {return a.first > b.first; });
	ll minS = (ll)2000000000 * (ll)2000000000;
	REP(l, N - 1)
	{
		if (l > 0 && xy[l].first == xy[l - 1].first)continue;
		for (int r = N - 1; r > l; r--)
		{
			if (r < N - 1 && xy[r].first == xy[r + 1].first)continue;
			int k = r + 1 - l;
			vector< pair<int, int> > y;
			FOR(i, r + 1, l)
			{
				y.push_back(xy[i]);
			}
			sort(y.begin(), y.end(), [](pair<int, int> a, pair<int, int> b) {return a.second > b.second; });
			REP(t, y.size() - 1)
			{
				if (t > 0 && y[t].second == y[t - 1].second)continue;
				for (int u = y.size() - 1; u > t; u--)
				{
					if (u < y.size() - 1 && y[u].second == y[u + 1].second)continue;
					k -= t + (y.size() - 1) - u;
					if (k >= K)
					{
						ll lx = abs(xy[r].first - xy[l].first);
						ll ly = abs(y[t].second - y[u].second);
						minS = std::min(minS, lx*ly);
					}
				}
			}
		}
	}

	cout << minS << endl;
	return 0;
}

