// Factorial
// need init
ll factorial_memo[5001];
ll factorial(ll n) {
  factorial_memo[0] = 1;
  if(factorial_memo[n] != -1) return factorial_memo[n];
  factorial_memo[n] = (factorial(n-1) * n) % MOD;
  return factorial_memo[n];
}

// Combination(nCr)
// need init
ll nCr_memo[5001][5001];
ll nCr(ll n, ll r) {
  if(r*2 > n) r = n-r;
  if(r == 1) return n;
  if(r == 0) return 1;
  if(nCr_memo[n][r] != -1) return nCr_memo[n][r];
  nCr_memo[n][r] = (nCr(n-1, r) + nCr(n-1, r-1)) % MOD;
  return nCr_memo[n][r];
}

void solve() {
  ll N, K;
  cin >> N >> K;
  vector<ll> x(N), y(N);
  vector<ll> xlst(0), ylst(0);
  REP(i, N) {
    cin >> x[i] >> y[i];
    xlst.push_back(x[i]);
    ylst.push_back(y[i]);
  }
  SORT(xlst);
  SORT(ylst);
  ll ans = (xlst[N-1] - xlst[0]) * (ylst[N-1] - ylst[0]);
  REP(xl, N) FOR(xr, xl+1, N) REP(yl, N) FOR(yr, yl+1, N) {
    int cnt = 0;
    REP(i, N) {
      if(xlst[xl]<=x[i] && x[i]<=xlst[xr] && ylst[yl]<=y[i] && y[i]<=ylst[yr]) cnt++;
    }
    if(K <= cnt) {
      ans = min(ans, (xlst[xr]-xlst[xl]) * (ylst[yr]-ylst[yl]));
    }
  }
  cout << ans << "\n";
}

int main() {
  // init
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

