class point_t {
public:
  int x;
  int y;

public:
  bool operator<(const point_t& p) const {
    if (x != p.x)
      return x < p.x;

    return y < p.y;
  };
};



int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);

  int N, K;

  std::cin >> N >> K;

  std::vector<point_t> pts(N);

  for (int i = 0; i < N; i ++)
    std::cin >> pts[i].x >> pts[i].y;

  std::sort(ALL(pts));

  long long Am = INF;

  for (int i = 0; i < N; i ++)
    for (int j = i; j < N; j ++) {
      int size = j + 1 - i;

      if (size >= K) {
        std::vector<point_t> pts2(std::begin(pts) + i, std::begin(pts) + j + 1);

        assert(pts2.size() == size);

        long long w = std::abs(pts[j].x - pts[i].x);

        for (int k = 0; k < size; k ++)
          for (int l = k; l < size; l ++)
            if (l + 1 - k >= K) {
              auto mp = std::minmax_element(std::begin(pts2) + k,
                                            std::begin(pts2) + l + 1,
                                            [](const point_t& a, const point_t& b) {
                  if (a.y != b.y)
                    return a.y < b.y;

                  return a.x < b.x;
                });

              Am = std::min(w * (mp.second->y - mp.first->y), Am);
            }
      }
    }

  std::cout << Am << std::endl;

  return 0;
}

