    vector<ll> x(n), y(n);
    rep(i, n) cin >> x[i] >> y[i];

    ll ans = infll;

    // 全探索
    vector<ll> lefts(n);
    vector<ll> rights(n);
    vector<ll> tops(n);
    vector<ll> bottoms(n);
    rep(i, n) {
        lefts[i] = x[i];
        rights[i] = x[i];
        tops[i] = y[i];
        bottoms[i] = y[i];
    }

    sort(allof(lefts));
    sort(allof(rights), greater<ll>());
    sort(allof(bottoms));
    sort(allof(tops), greater<ll>());

    CulSum2D<ll> sum(n, n);
    rep(i, n) {
        ll tx = lefts[i];
        // これを基にyを求める
        int xi = 0;
        rep(j, n) if (x[j] == tx) {
            xi = j;
            break;
        }
        ll ty = y[xi];
        int yi = 0;
        rep(j, n) if (bottoms[j] == ty) {
            yi = j;
            break;
        }
        sum.add(yi, i, 1);
    }

    sum.build();

    // どこまで縮めるか
    rep(xi, n) {
        rep(xj, n - xi - 1) {
            rep(yi, n) {
                rep(yj, n - yi - 1) {
                    ll left = lefts[xi];
                    ll right = rights[xj];
                    ll bottom = bottoms[yi];
                    ll top = tops[yj];

                    // 何点含まれているか
                    int cnt = 0;
                    cnt = sum.get(yi, xi, n - yj, n - xj);
                    //cout << "cnt : " << cnt << " left : " << left << ", right : " << right;
                    //cout << ", bottom : " << bottom << ", top : " << top << ", mes : " << (right - left) * (top - bottom) << endl;

                    if (cnt >= K) {
                        chmin(ans, (right - left)* (top - bottom));
                    }
                }
            }
        }
    }

    Cout(ans);

    return 0;
}

