        accum[pX[i]][pY[i]]++;
    }

    for (int i = 0; i <= N; i++)
    {
        for (int j = 0; j <= N; j++)
        {
            accum[i + 1][j] += accum[i][j];
        }
    }
    for (int i = 0; i <= N; i++)
    {
        for (int j = 0; j <= N; j++)
        {
            accum[i][j + 1] += accum[i][j];
        }
    }

    ll minX = LLINF;
    ll minY = LLINF;
    ll maxX = -LLINF;
    ll maxY = -LLINF;
    for (int i = 0; i < N; i++)
    {
        chmin(minX, X[i]);
        chmin(minY, Y[i]);
        chmax(maxX, X[i]);
        chmax(maxY, Y[i]);
    }

    ll ans = (maxY - minY) * (maxX - minX);

    for (int gx = 0; gx < N; gx++)
    {
        for (int gy = 0; gy < N; gy++)
        {
            if (accum[gx][gy] >= K)
            {
                ll dx = ppX.rev[gx] - minX;
                ll dy = ppY.rev[gy] - minY;
                chmin(ans, abs(dx * dy));
            }
        }
    }


    for (int sx = 1; sx < N; sx++)
    {
        for (int sy = 1; sy < N; sy++)
        {
            for (int gx = sx; gx < N; gx++)
            {
                for (int gy = sy; gy < N; gy++)
                {
                    ll count = accum[gx][gy] + accum[sx - 1][sy - 1] - accum[sx - 1][gy] - accum[gx][sy - 1];

                    if (count >= K)
                    {
                        ll dx = ppX.rev[gx] - ppX.rev[sx];
                        ll dy = ppY.rev[gy] - ppY.rev[sy];
                        chmin(ans, abs(dx * dy));
                    }
                }
            }
        }
    }


    cout << ans << endl;

}

