int main()
{
    ll N, K;
    cin >> N >> K;
    ll xi, yi;
    vector<ll> X, Y;
    for(int i=0;i<N;i++){
        cin >> xi >> yi;
        X.push_back(xi);
        Y.push_back(yi);
    }
    auto Xs = X;
    auto Ys = Y;
    sort(Xs.begin(), Xs.end());
    sort(Ys.begin(), Ys.end());
    vector<vector<ll>> sum(Xs.size(), vector<ll>(Ys.size(), 0));
    for(int i=0;i<N;i++){
        auto x = distance(Xs.begin(), lower_bound(Xs.begin(), Xs.end(), X[i]));
        auto y = distance(Ys.begin(), lower_bound(Ys.begin(), Ys.end(), Y[i]));
        sum[x][y]++;
    }
    for(int i=0;i<Xs.size();i++){
        for(int j=0;j<Ys.size();j++){
            if(i>0) sum[i][j] += sum[i-1][j];
            if(j>0) sum[i][j] += sum[i][j-1];
            if(i>0 && j>0) sum[i][j] -= sum[i-1][j-1];
        }
    }

    ll res = LLONG_MAX;
    for(int i1=0;i1<Xs.size();i1++){
        for(int i2=i1+1;i2<Xs.size();i2++){
            for(int j1=0;j1<Ys.size();j1++){
                for(int j2=j1+1;j2<Ys.size();j2++){
                    ll c = sum[i2][j2];
                    if(i1>0) c -= sum[i1-1][j2];
                    if(j1>0) c -= sum[i2][j1-1];
                    if(i1>0 && j1>0) c -= sum[i1-1][j1-1];
                    if(c >= K){
                        res = min(res, (Xs[i2]-Xs[i1]) * (Ys[j2]-Ys[j1]));
                    }
                }
            }
        }
    }

    cout<<res<<endl;

    return 0;
}

