int N, K;
LP p[50];

bool comp1(LP &lhs, LP &rhs){
    if(lhs.fi < rhs.fi) return true;
    else if(lhs.fi == rhs.fi){
        return lhs.se < rhs.se;
    }
    return false;
}

bool comp2(LP &lhs, LP &rhs){
    if(lhs.se < rhs.se) return true;
    else if(lhs.se == rhs.se){
        return lhs.fi < rhs.fi;
    }
    return false;
}

void solve()
{
    ll ans = LINF;
    sort(p, p+N, comp1);
    REP(i, max(1, N-K)){
        ll x1 = LINF, x2 = -LINF, y1 = LINF, y2 = -LINF;
        REP(j, K){
            x1 = min(x1, p[i+j].fi);
            x2 = max(x2, p[i+j].fi);
            y1 = min(y1, p[i+j].se);
            y2 = max(y2, p[i+j].se);
        }
        ans = min(ans, (x2-x1)*(y2-y1));
    }
    sort(p, p+N, comp2);
    REP(i, max(1, N-K)){
        ll x1 = LINF, x2 = -LINF, y1 = LINF, y2 = -LINF;
        REP(j, K){
            x1 = min(x1, p[i+j].fi);
            x2 = max(x2, p[i+j].fi);
            y1 = min(y1, p[i+j].se);
            y2 = max(y2, p[i+j].se);
        }
        ans = min(ans, (x2-x1)*(y2-y1));
    }
    cout << ans << endl;
}

