#include <cstdio>
using namespace std;

struct point {
	int x, y;
};

bool ismid(int mid, int x, int y) {
	return (x <= mid && mid <= y) || (y <= mid && mid <= x);
}

int abs(int x) {
	if (x < 0) {
		return -x;
	} else {
		return x;
	}
}

int min(int x, int y) {
	if (x > y) {
		return y;
	}
	else {
		return x;
	}
}

int main() {
	int n,k,i,j,s,cnt,ymin,ymax,height;
	scanf("%d %d",&n,&k);
	point p[50],q;
	for (i = 0; i < n; i++) {
		scanf("%d %d", &(p[i].x) ,&(p[i].y));
	}
	for (i = 1; i < n; i++) {
		j = i;
		while( j>0 && p[j].y < p[j - 1].y) {
			q = p[j];
			p[j] = p[j - 1];
			p[j - 1] = q;
			j--;
		}
	}
	long long area = (long long)2000000000 * 2000000000;
	for (i = 0; i < n; i++) {
		for (j = 0; j < i; j++) {
			cnt = 0;
			for (s = 0; s < n; s++) {
				if (ismid(p[s].x, p[i].x, p[j].x)) {
					cnt++;
				}
			}
			if (cnt >= k) {
				height = 2000000000;
				ymin = 0;
				ymax = 0;
				cnt = 0;
				while (ymin < n && ymax < n) {
					while (cnt < k&&ymax<n) {
						if (ismid(p[ymax].x, p[i].x, p[j].x)) {
							cnt++;
						}
						ymax++;
					}
					while (cnt >= k&&ymin<n) {
						if (ymax >= n) {
							ymax = n - 1;
						}
						height = min(height, p[ymax].y - p[ymin].y);
						if ((long long)height * abs(p[i].x - p[j].x) < area) {
							area = (long long)height * abs(p[i].x - p[j].x);
						}
						if (ismid(p[ymin].x, p[i].x, p[j].x)) {
							cnt--;
						}
						ymin++;
					}
					if (ymax >= n-1) {
						break;
					}
				}
			}
		}
	}
	printf("%lld", area);

	return 0;
}

