struct Pair{
    ll min_x;
    ll max_x;
    ll min_y;
    ll max_y;
};

ll area(Pair p){
    ll x=p.max_x-p.min_x;
    ll y=p.max_y-p.min_y;
    return x*y;
}

Pair dp[55][55];

int main(){
    cin.tie(0);ios::sync_with_stdio(false);
    ll n,K;
    cin>>n>>K;
    V<ll> x(n),y(n);
    rep(i,n) cin>>x[i]>>y[i];
    ll tmp=ll(1e9);
    for(int i=0;i<=50;i++) for(int j=0;j<=50;j++) dp[i][j]=(Pair){-tmp,tmp,-tmp,tmp};
    rep(i,n){
        rep(j,i){
            for(int k=j+1;k<=i;k++){
                Pair p=(Pair){min(x[j],x[k]),max(x[j],x[k]),min(y[j],y[k]),max(y[j],y[k])};
                if(area(p)<area(dp[i+1][2])) dp[i+1][2]=p;
            }
        }
    }
    for(int i=0;i<n;i++){
        for(int j=3;j<=i+1;j++){
            for(int k=2;k<=i;k++){
                Pair p=dp[k][j-1];
                chmin(p.min_x,x[i]);
                chmax(p.max_x,x[i]);
                chmin(p.min_y,y[i]);
                chmax(p.max_y,y[i]);
                if(area(p)<area(dp[i+1][j])) dp[i+1][j]=p;
                if(area(dp[i][j])<area(dp[i+1][j])) dp[i+1][j]=dp[i][j];
            }
        }
    }
    ll ans=4*INF+1;
    for(int i=2;i<=n;i++) chmin(ans,area(dp[i][K]));
    out(ans);
}

