typedef long long ll;
#define INF (1LL<<62)

struct point {
	ll x;
	ll y;
	ll n;
};

ll N, K;
vector<point> pt(51);

bool comp_x(const point &a, const point &b) {
	return a.x < b.x;
}
bool comp_y(const point &a, const point &b) {
	return a.y < b.y;
}

ll findMinArea(vector<point> p, ll k, ll A) {
	//cout << p[0].n <<" "<< k <<" "<< A << endl;
	if (k == K) {
		//cout <<"  "<< A << endl;
		return A;
	}

	point r;

	ll minArea=INF;
	for (ll i = 0; i < N; i++) {
		vector<point> q=p;
		bool f=true;
		for (ll j = 0; j < p.size(); j++) {
			if(p[j].n == i) f=false;
		}
		if(!f) continue;

		q.push_back(point{ pt[i].x,pt[i].y,pt[i].n });
		sort(q.begin(),q.end(),comp_x);
		ll X = q[q.size()-1].x - q[0].x;
		sort(q.begin(),q.end(),comp_y);
		ll Y = q[q.size()-1].y - q[0].y;
		ll area = X*Y;

		if (minArea > area) {
			minArea = area;
			r.x = pt[i].x;
			r.y = pt[i].y;
			r.n = pt[i].n;
		}
	}
	//cout << r.n << endl;
	p.push_back(r);
	return findMinArea(p, k+1, minArea);
}

int main() {
	cin >> N >> K;
	for (ll i = 0; i < N; i++) {
		cin >> pt[i].x >> pt[i].y;
		pt[i].n = i;
	}
	ll ans=INF;
	for (ll i = 0; i < N; i++) {
		vector<point> q;
		q.push_back(point{ pt[i].x,pt[i].y,pt[i].n });
		ans = min(ans, findMinArea(q, 1, 0));
	}

	cout << ans << endl;
}

