    map<int, int> x2xid; REP(i, xs.size()) x2xid[xs[i]] = i;
    map<int, int> y2yid; REP(i, ys.size()) y2yid[ys[i]] = i;
    for (auto p : points) {
        FOR(y, y2yid[p.y], ys.size()) FOR(x, x2xid[p.x], xs.size()) S[y][x]++;
