int n, k;
vector<vector<int>> combinations;


void comb(int depth, const vector<int> temp){
  //cout << "comb("<<depth<<", temp.size() = " << temp.size() << ")" << endl;
  if(depth==k){
    combinations.push_back(temp);
    return;
  }
  for(int v = temp[temp.size()-1]+1; v <= n-k+depth; ++v){
    auto vec = temp;
    vec.push_back(v);
    comb(depth+1, vec);
  }
}

void comb(){
  //cout << "comb()" << endl;
  int depth=0;
  for(int v = 0; v <= n-k; ++v){
    vector<int> vec(1);
    vec[0]=v;
    comb(depth+1, vec);
  }
}

