struct Graph{
  int n;//頂点数
  vector<Edge>es;//辺集合
  //クラスカル法で無向最小全域木のコストの和を計算する
  //グラフが非連結の時は最小全域森のコストの和になる
  int kruskal(){
    //コストが小さい順にソーと
    sort(es.begin(),es.end());
    UnionFind uf(n);
    int min_cost=0;
    for(int ei=0;ei<es.size();ei++){
      Edge& e=es[ei];
      if(!uf.same(e.a,e.b)){
        //その辺によって2つの木が連結される
        min_cost+=e.cost;
        uf.unite(e.a,e.b);

      }
    }
    return min_cost;
  }
};
