ll N, K;
vector<P> v;
int main(void)
{
    cin >> N >> K;
    rep(i, N)
    {
        ll x, y;
        cin >> x >> y;
        v.push_back({x, y});
    }
    //N^4で全探索
    //区間内の点をどうカウントするか?
    //
    ll ans = INF;
    for (int i = 0; i < N; ++i)
    {
        for (int j = 0; j < N; ++j)
        {
            for (int k = 0; k < N; ++k)
            {

                for (int l = 0; l < N; ++l)
                {
                    ll max_x = -INF, max_y = -INF;
                    ll min_x = INF, min_y = INF;
                    max_x = max({v[i].first, v[j].first, v[k].first, v[l].first});
                    min_x = min({v[i].first, v[j].first, v[k].first, v[l].first});

                    max_y = max({v[i].second, v[j].second, v[k].second, v[l].second});
                    min_y = min({v[i].second, v[j].second, v[k].second, v[l].second});

                    int cnt = 0;
                    for (int m = 0; m < N; ++m)
                    {
                        if (v[m].first <= max_x && min_x <= v[m].first &&
                            v[m].second <= max_y && v[m].second >= min_y)
                            cnt++;
                    }
                    if (cnt >= K)
                        ans = min(ans, (max_x - min_x) * (max_y - min_y));
                }
            }
        }
    }
    cout << ans << endl;

    return 0;
}

