template <class T> inline bool chmin(T &a, T b) { /* {{{ */
  if (a > b) {
    a = b;
    return true;
  }
  return false;
} /* }}} */

int main() {
  int N, K;
  cin >> N >> K;
  vector<int> X(N), Y(N);
  set<int> xs, ys;
  for (int i = 0; i < N; i++) {
    cin >> X[i] >> Y[i];
    xs.insert(X[i]);
    xs.insert(X[i] - 1);
    ys.insert(Y[i]);
    ys.insert(Y[i] - 1);
  }
  unordered_map<int, unordered_map<int, int>> m;
  for (auto x : xs) {
    m[x] = unordered_map<int, int>();
    for (auto y : ys) {
      for (int i = 0; i < N; i++) {
        if (X[i] <= x and Y[i] <= y) m[x][y]++;
      }
    }
  }
  long long ans = 9 * 1e18;
  sort(X.begin(), X.end());
  sort(Y.begin(), Y.end());
  for (int i1 = 0; i1 < N; i1++) {
    int x1 = X[i1];
    for (int i2 = i1 + 1; i2 < N; i2++) {
      int x2 = X[i2];
      for (int j1 = 0; j1 < N; j1++) {
        int y1 = Y[j1];
        for (int j2 = j1 + 1; j2 < N; j2++) {
          int y2 = Y[j2];
          int cnt = m[x2][y2] - m[x2][y1 - 1] - m[x1 - 1][y2] + m[x1 - 1][y1 - 1];
          if (cnt >= K) {
            long long s = (long long)(x2 - x1) * (y2 - y1);
            chmin(ans, s);
          }
        }
      }
    }
  }
  cout << ans << endl;

  return 0;
}
