bool in(ll yt, ll xt, ll y1, ll x1, ll y2, ll x2) {
	return (y1 <= yt && yt <= y2 && x1 <= xt && xt <= x2);
}

ll dfs(ll y1i, ll x1i, ll y2i, ll x2i) {
	static ll memo[50][50][50][50];
	if (memo[y1i][x1i][y2i][x2i] > 0) { return memo[y1i][x1i][y2i][x2i]; }

	ll count = 0;
	REPC(x, p) {
		if (in(x.first, x.second, h[y1i], w[x1i], h[y2i], w[x2i])) { ++count; }
	}
	if (count < k) { return (1LL << 63) - 1; }

	ll ans = (w[x2i] - w[x1i])*(h[y2i] - h[y1i]);
	MIN(ans, dfs(y1i + 1, x1i, y2i, x2i));
	MIN(ans, dfs(y1i, x1i + 1, y2i, x2i));
	MIN(ans, dfs(y1i, x1i, y2i - 1, x2i));
	MIN(ans, dfs(y1i, x1i, y2i, x2i - 1));
	memo[y1i][x1i][y2i][x2i] = ans;
	return ans;
}

