void calcSum2D(int H, int W) {
    for(int i = 1; i <= H; i++) {
        for(int j = 0; j <= W; j++) {
            sum[i][j] += sum[i-1][j];
        }
    }
    for(int i = 0; i <= H; i++) {
        for(int j = 1; j <= W; j++) {
            sum[i][j] += sum[i][j-1];
        }
    }
}

