typedef long long LL;
int N,K;
LL x[51];
LL y[51];
typedef pair<LL,LL>P;

LL check(int a,int b){
   LL ay=min(y[a],y[b]);
   LL by=max(y[a],y[b]);
   vector<P>v;
   REP(i,N){
       if(ay<=y[i]&&y[i]<=by){
          v.push_back(P(x[i],y[i]));
       }
   }
   sort(v.begin(),v.end());
   if(v.size()<K)return 5*1e18;
   LL ans=5*1e18;
   for(int i=0;i+K-1<v.size();i++){
       LL ax=v[i].first;
       LL bx=v[i+K-1].first;
       ans=min(ans,(bx-ax)*(by-ay));
   }
   return ans;
}

int main(){
    cin>>N>>K;
    REP(i,N){
        cin>>x[i]>>y[i];
    }
    LL ans=5*1e18;
    REP(i,N){
        REP(j,i){
            ans=min(ans,check(i,j));
        }
    }
    cout<<ans<<endl;
    return(0);
}

