ll ans=(ll)INF*INF*4;

void solve(){
	REP(i, n-k+1){
		int mx=INF,Mx=-INF,my=INF,My=-INF;
		REP(j, k){
			mx = min(mx, ps[i+j].first);
			Mx = max(Mx, ps[i+j].first);
			my = min(my, ps[i+j].second);
			My = max(My, ps[i+j].second);
		}
		ans=min(ans, (ll)(Mx-mx) * (My-my));
	}
}

// O(N^2)
int main() {
	cin >> n >> k;
	REP(i, n){cin>>x[i]>>y[i];}
	REP(i, n)REP(j, n)REP(m, n)if(i!=j&&i!=m){
		int x1 = min(x[i], min(x[j], x[m])), x2 = max(x[i], max(x[j], x[m]));
		int y1 = min(y[i], min(y[j], y[m])), y2 = max(y[i], max(y[j], y[m]));
		int c = 0;
		REP(l, n){
			if(x1<=x[l] && x[l]<=x2 && y1<=y[l] && y[l]<=y2)
				c++;
		}
		if(c>=k){
			ans = min(ans, (ll)(x2-x1)*(y2-y1));
		}
		if(c==k-1){
			REP(l, n){
				if(!(x1<=x[l] && x[l]<=x2 && y1<=y[l] && y[l]<=y2)){
					ans = min(ans, (ll)
						(max(x2, x[l])-min(x1, x[l])) *
						(max(y2, y[l])-min(y1, y[l]))
					);
				}
			}
		}
	}
	cout << ans << endl;
}

