		cin >> coor [i].first >> coor [i].second;
	}
	sort(coor,coor + N);

	ll ans = INF;
	FOR(i,0,N) FOR(j,0,N) FOR(k,0,N){
		ll y1 = min(coor [i].second,coor [j].second),y2 = max(coor [i].second,coor [j].second);
		ll x1 = coor [k].first,x2 = coor [k].first;
		int idx = lower_bound(coor,coor + N,make_pair(x1,-INF)) - coor;
		int cnt = 0;
