const int MAXN = 60;
static int cumsum[MAXN][MAXN];

int calc(int x1, int x2, int y1, int y2) {
    int res = cumsum[x2][y2];
    if (x1 - 1 >= 0) res -= cumsum[x1 - 1][y2];
    if (y1 - 1 >= 0) res -= cumsum[x2][y1 - 1];
    if (x1 - 1 >= 0 and y1 - 1 >= 0) res += cumsum[x1 - 1][y1 - 1];
    return res;
}

int main() {
    int N, K;
    cin >> N >> K;

    int64 X[MAXN], Y[MAXN];
    map<int64, int> xmp, ymp;
    for (int i = 0; i < N; i++) {
        cin >> X[i] >> Y[i];
        xmp[X[i]] = 0;
        ymp[Y[i]] = 0;
    }

    static int64 xrev[MAXN], yrev[MAXN];

    int xid = 0, yid = 0;
    for (auto p : xmp) { xmp[p.first] = xid; xrev[xid++] = p.first; }
    for (auto p : ymp) { ymp[p.first] = yid; yrev[yid++] = p.first; }


    for (int i = 0; i < N; i++) {
        cumsum[xmp[X[i]]][ymp[Y[i]]]++;
    }

    for (int x = 0; x < xid; x++) {
        for (int y = 1; y < yid; y++) {
            cumsum[x][y] += cumsum[x][y - 1];
        }
        if (x == 0) continue;
        for (int y = 0; y < yid; y++) {
            cumsum[x][y] += cumsum[x - 1][y];
        }
    }

    int64 ans = (1LL << 62);
    for (int x1 = 0; x1 < xid; x1++) {
        for (int x2 = x1 + 1; x2 < xid; x2++) {
            for (int y1 = 0; y1 < yid; y1++) {
                for (int y2 = y1 + 1; y2 < yid; y2++) {
                    if (calc(x1, x2, y1, y2) < K) continue;
                    ans = min(ans, (xrev[x2] - xrev[x1]) * (yrev[y2] - yrev[y1]));
                }
            }
        }
    }
    cout << ans << endl;

    return 0;
}

