int main()
{
    int64_t N, K;
    std::cin >> N >> K;

    std::map<int64_t, std::set<int64_t>> points;

    for (decltype(N) i = 0; i < N; ++i) {
        int64_t x, y;
        std::cin >> x >> y;
        points[x].insert(y);
    }


    int64_t ans = INT64_MAX;

    auto left = points.begin();
    auto right = left;
    right++;

    auto count = left->second.size() + right->second.size();

    while (left != points.end() && right != points.end()) {
        int64_t xl = right->first - left->first;

        int64_t ymin = INT64_MAX;
        int64_t ymax = INT64_MIN;
        auto end = right;
        end++;
        for (auto i = left; i != end; ++i) {
            ymin = std::min(ymin, *i->second.begin());
            ymax = std::max(ymax, *i->second.rbegin());
        }
        //std::cerr << right->first << " " << left->first << " " << ymin << " " << ymax << " " << count << endl ;
        int64_t yl = ymax - ymin;
        int64_t S = xl * yl;
        if (count >= K) {
            ans = std::min(ans, S);
        }

        if (count < K) {
            right++;
            if (right == points.end()) {
                break;
            }
            count += right->second.size();
        }
        else {
            count -= left->second.size();
            left++;
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

