    sort(p.begin(),p.end());
    rep(i,n-k+1){
        ll x=p[i+k-1].first-p[i].first;
        ll miniy=1e+10,maxiy=0;
        rep(j,k){
            chmin(miniy,p[i+j].second);chmax(maxiy,p[i+j].second);
        }
        ll y=maxiy-miniy;
        //cout<<x*y<<endl;
        chmin(res,x*y);
    }
    }
    cout<<res<<endl;
}

