template<typename T> struct Sum2 {
	typedef vector<vector<T>> A;
	A s;
	int X, Y;

	Sum2() { X = Y = -1; }
	Sum2(A & p) { init(p); }
	void init(A & p) {
		X = p.size();
		Y = p[0].size();
		s = A(X + 1, vector<T>(Y + 1, 0));

		inc1(x, X) {
		inc1(y, Y) {
			s[x][y] = p[x - 1][y - 1];
		}
		}
		inc1(x, X) {
		inc1(y, Y) {
			s[x][y] += s[x - 1][y];
		}
		}
		inc1(x, X) {
		inc1(y, Y) {
			s[x][y] += s[x][y - 1];
		}
		}
	}
	T sum(int xl, int xh, int yl, int yh) { // [xl, xh) × [yl, yh)
		assert(inII(xl, 0, X));
		assert(inII(xh, 0, X));
		assert(inII(yl, 0, Y));
		assert(inII(yh, 0, Y));
		assert(xl <= xh);
		assert(yl <= yh);
		return s[xh][yh] - s[xh][yl] - s[xl][yh] + s[xl][yl];
	}
};

