  vector<long long> x(n);
  vector<long long> y(n);
  int i,j;
  for(i=0;i<n;i++)cin>>x.at(i)>>y.at(i);
  vector<vector<square>> dp(n+1,vector<square>(n+1));
  long long xlow=x.at(0);
  long long xhigh=x.at(0);
  long long ylow=y.at(0);
  long long yhigh=y.at(0);
  for(i=1;i<=n;i++)
  {
    dp.at(i).at(1)={x.at(i-1),y.at(i-1),x.at(i-1),y.at(i-1)};
    xlow=min(xlow,x.at(i-1));
    xhigh=max(xhigh,x.at(i-1));
    ylow=min(ylow,x.at(i-1));
    yhigh=max(yhigh,y.at(i-1));
    dp.at(i).at(i)={xlow,ylow,xhigh,yhigh};
  }
  for(i=2;i<=n;i++)
  {
    for(j=2;j<i;j++)
    {
      long long nadd=(dp.at(i-1).at(j).maxx-dp.at(i-1).at(j).minx)*(dp.at(i-1).at(j).maxy-dp.at(i-1).at(j).miny);
      long long kxlow=min(x.at(i-1),dp.at(i-1).at(j-1).minx);
      long long kxhigh=max(x.at(i-1),dp.at(i-1).at(j-1).maxx);
      long long kylow=min(y.at(i-1),dp.at(i-1).at(j-1).miny);
      long long kyhigh=max(y.at(i-1),dp.at(i-1).at(j-1).maxy);
      if((kxhigh-kxlow)*(kyhigh-kylow)<nadd)dp.at(i).at(j)={kxlow,kylow,kxhigh,kyhigh};
      else dp.at(i).at(j)=dp.at(i-1).at(j);
    }
  }
  long long ans=4000000000000000001;
  for(i=k;i<=n;i++)
  {
    long long kxlow=dp.at(i).at(k).minx;
    long long kxhigh=dp.at(i).at(k).maxx;
    long long kylow=dp.at(i).at(k).miny;
    long long kyhigh=dp.at(i).at(k).maxy;
    if((kxhigh-kxlow)*(kyhigh-kylow)<ans)ans=(kxhigh-kxlow)*(kyhigh-kylow);
  }
  cout<<ans<<endl;
}

