#include <bits/stdc++.h>
using namespace std;
#define int long long
#define rep(i,n) for(int i = 0;i <= n;i++)
#define rrep(i,n) for(int i = 1;i <= n;i++)

int a[52][52], disx[52], disy[52];
int ax[52], ay[52], h, w;
vector<int> x, y;
map<int,int> zipx, zipy;

void compress(){
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());
	x.erase(unique(x.begin(), x.end()), x.end());
	y.erase(unique(y.begin(), y.end()), y.end());
	for(int i = 0;i < x.size();i++){
		disx[i+1] = x[i]-x[0];
		zipx[x[i]] = i+1;
	}
	for(int i = 0;i < y.size();i++){
		disy[i+1] = y[i]-y[0];
		zipy[y[i]] = i+1;
	}
	w = x.size();
	h = y.size();
}

int solve(int yy1, int yy2, int xx1, int xx2){
	int s = a[yy2][xx2]+a[yy1][xx1];
	s -= a[yy2][xx1]+a[yy1][xx2];
	return s;
}

signed main(){
	int n, k;
	scanf("%lld%lld", &n, &k);
	for(int i = 0;i < n;i++){
		scanf("%lld%lld", &ax[i], &ay[i]);
		x.push_back(ax[i]);
		y.push_back(ay[i]);
	}
	compress();

	for(int i = 0;i < n;i++){
		a[zipx[ax[i]]][zipy[ay[i]]]++;
	}
	rrep(i,h)rrep(j,w){
		a[i][j] += a[i][j-1];
	}
	rrep(i,h)rrep(j,w){
		a[i][j] += a[i-1][j];
	}

	int ans = 1e18*4+7;
	rep(yy1,h)rep(yy2,h){
		if(yy1 >= yy2)continue;
		rep(xx1,w)rep(xx2,w){
			if(xx1 >= xx2)continue;
			int dis = disx[xx2]-disx[xx1+1];
			dis = dis*(disy[yy2]-disy[yy1+1]);
			int cnt = solve(yy1, yy2, xx1, xx2);
			if(cnt >= k){
				ans = min(ans, dis);
			}
		}
	}

	printf("%lld\n", ans);
	return 0;
}

