				ymin = min(ymin, y[k]);
				ymax = max(ymax, y[k]);
				for(long l = k+1; l < n-1; l++){
					if(x[l] < xmin || x[l] > xmax /*|| (y[l] >= ymin && y[l] <= ymax)*/){
						continue;
