    };

    std::vector<P> points;
    std::vector<int64_t> xaxis;
    std::vector<int64_t> yaxis;
    for (size_t i = 0; i < N; ++i) {
        int64_t x, y;
        std::cin >> x >> y;
        points.push_back({x, y});
        xaxis.push_back(x);
        yaxis.push_back(y);
    }

    // 重複点捨てておく
    xaxis.erase(std::unique(std::begin(xaxis), std::end(xaxis)), std::end(xaxis));
    yaxis.erase(std::unique(std::begin(yaxis), std::end(yaxis)), std::end(yaxis));

    int64_t m = INT64_MAX;
    combination(xaxis, 2, [&m, K, &points, &yaxis](auto& xx) {
            combination(yaxis, 2, [&m, K, &xx, &points](auto& yy) {
                    int inCount = 0;
                    const auto xmin = std::min(xx[0], xx[1]);
                    const auto ymin = std::min(yy[0], yy[1]);
                    const auto xmax = std::max(xx[0], xx[1]);
                    const auto ymax = std::max(yy[0], yy[1]);
