                        if (xmin <= p.x && p.x <= xmax &&
                            ymin <= p.y && p.y <= ymax)
                        {
                            inCount++;
                        }
                    }
                    if (inCount >= K) {
                        m = std::min(m, (xmax - xmin)*(ymax - ymin));
                    }
                });
        });

