  for (int i = 0; i < N; i++)
  {
    for (int j = 0; j < N; j++)
    {
      int X1,X2,Y1,Y2;

      for (int k = 0; k < N; k++)
      {
        if((i != k && j != k ) || true)
        {
          X1 = min(min(DATA[i].first,DATA[j].first),DATA[k].first);
          Y1 = min(min(DATA[i].second,DATA[j].second),DATA[k].second);
          X2 = max(max(DATA[i].first,DATA[j].first),DATA[k].first);
          Y2 = max(max(DATA[i].second,DATA[j].second),DATA[k].second);
