long long min(long long x1,long long x2,long long x3,long long x4){
    long long a=x1<x2?x1:x2;
    long long b=x3<x4?x3:x4;
    return a<b?a:b;
}

long long max(long long x1,long long x2,long long x3,long long x4){
    return -min(-x1,-x2,-x3,-x4);
}

long long* cor(P x1,P x2,P x3,P x4){
    long long *c=new long long[4];
    c[U]=min(x1.second,x2.second,x3.second,x4.second);
    c[D]=max(x1.second,x2.second,x3.second,x4.second);
    c[L]=min(x1.first,x2.first,x3.first,x4.first);
    c[R]=max(x1.first,x2.first,x3.first,x4.first);

    return c;
}

