using namespace std;

const int MAXN = 110;
const unsigned long long MAX_INF = 0x3fffffff;

struct tnode
{
    unsigned long long x, y;
}a[MAXN];

bool cmp_x (tnode a, tnode b)
{
    if (a.x == b.x)
    {
        return a.y < b.y;
    }
    return a.x < b.x;
}

bool cmp_y (tnode a, tnode b)
{
    if (a.y == b.y)
    {
        return a.x < b.x;
    }
    return a.y < b.y;
}

int main ()
{
    int n, k;
    scanf ("%d%d", &n, &k);
    for (int i = 1; i <= n; i ++)
    {
        scanf ("%lld%lld", &a[i].x, &a[i].y);
    }
    sort (a + 1, a + n + 1, cmp_x);
    unsigned long long ans = (long long) 1 << 63;
    for (int i = 1; i <= n - k + 1; i ++)
    {
        unsigned long long maxs = 0, mins = MAX_INF;
        for (int j = 0; j < k; j ++)
        {
            if (a[i + j].y < mins)
            {
                mins = a[i + j].y;
            }
            if (a[i + j].y > maxs)
            {
                maxs = a[i + j].y;
            }
        }
        unsigned long long len = a[i + k - 1].x - a[i].x;
        unsigned long long tmp = len * (maxs - mins);
        if (tmp < ans)
        {
            ans = tmp;
        }
    }
    sort (a + 1, a + n + 1, cmp_y);
    for (int i = 1; i <= n - k + 1; i ++)
    {
        unsigned long long maxs = 0, mins = MAX_INF;
        for (int j = 0; j < k; j ++)
        {
            if (a[i + j].x < mins)
            {
                mins = a[i + j].x;
            }
            if (a[i + j].x > maxs)
            {
                maxs = a[i + j].x;
            }
        }
        unsigned long long len = a[i + k - 1].y - a[i].y;
        unsigned long long tmp = len * (maxs - mins);
        if (tmp < ans)
        {
            ans = tmp;
        }
    }
    printf ("%lld\n", ans);
    return 0;
}

