#include <bits/stdc++.h>
using namespace std;

typedef unsigned long long ull;
typedef long long ll;

struct point {
    ll x,y;
    bool operator < (const point& t) const {
	if( x == t.x )
	    return y < t.y;
	return x < t.x;
    }
};

ull k_in(ll xmin,ll xmax,ll ymin,ll ymax,vector<point> ps, ll K) {
    ll in = 0;
    for(auto& e : ps) {
	if( xmin <= e.x and e.x <= xmax and ymin <= e.y and e.y <= ymax )
	    in++;
    }
    if(K <= in){
	return (ull)(xmax-xmin)*(ull)(ymax-ymin);
    }
    return 18446744073709551610ULL;
}

int main () {
    ll N,K; cin >> N >> K;
    vector<ll> x;
    vector<ll> y;

    vector<point> ps;
    for(ll i=0; i<N; i++) {
	ll a,b; cin >> a >> b;
	x.push_back(a);
	y.push_back(b);
	ps.push_back(point{a,b});
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    sort(ps.begin(), ps.end());

    ull ans = 18446744073709551610ULL;
    for(int i=0; i<N; i++) {
	for(int j=i+1; j<N; j++) {
	    for(int k=0; k<N; k++) {
		for(int l=k+1; l<N; l++) {
		    ans = min(k_in(x[i],x[j],y[k],y[l],ps,K),ans);
		}
	    }
	}
    }
    cout << ans << endl;
    return 0;
}

