vector<pair<long long, long long>> points;

int dsu[51], ranks[51];

int find(int node){
    if(dsu[node] == node)
        return node;
    return dsu[node] = find(dsu[node]);
}

void combine(int a, int b){
    a = find(a); b = find(b);
    if(a == b) return;
    if(ranks[a] < ranks[b]){
        dsu[a] = b;
    } else if(ranks[b] < ranks[a]){
        dsu[b] = a;
    } else {
        dsu[a] = b;
        ++ranks[b];
    }
}

