ll minarea = -1;

void update(int x1, int x2, int y1, int y2){
	ll area = (x2 - x1) * 1ll * (y2 - y1);
	if(minarea == -1) minarea = area;
	else minarea = min(minarea, area);
}

int main(){
	int z, n;
	cin >> n >> z;

	set<int> xp, yp;
	for(int i=0; i<n; i++){
		int x, y;
