		pts.pb({x, y});
		xp.insert(x);
		yp.insert(y);
	}
	vector<int> xxp, yyp;
	for(int u : xp) xxp.pb(u);
	for(int u : yp) yyp.pb(u);


	for(int i = 0; i < xxp.size(); i++){
		for(int j = i; j < xxp.size(); j++){
			for(int k = 0; k< yyp.size(); k++){
					int most = ct(xxp[i], xxp[j], yyp[k], yyp.back());
					if(most < z) continue;
					int lo = k, hi = yyp.size() - 1;
					while(lo <= hi){
						int mid = (lo + hi)/2;
						int c = ct(xxp[i], xxp[j], yyp[k], yyp[mid]);
						if(c >= z){
							update(xxp[i], xxp[j], yyp[k], yyp[mid]);
							hi = mid - 1;
						}
						else{
							lo = mid + 1;
						}
					}
			}
		}
	}
	cout << minarea << endl;

	return 0;
}

