int fls(unsigned n) {
    int res = 0;
    while (n) {
        res++;
        n >>= 1;
    }
    return res;
}

void build_sparse_table() {
    rep(i, n) { tb_max[i][0] = tb_min[i][0] = p[i].Y; }

    int idx_sz = fls(n);
    repse(k, 1, idx_sz) {
        rep(i, n) {
            tb_min[i][k] = min(tb_min[i][k - 1], tb_min[i + (1 << (k - 1))][k - 1]);
            tb_max[i][k] = max(tb_max[i][k - 1], tb_max[i + (1 << (k - 1))][k - 1]);
        }
    }
}

int range_min(int i, int j) {
    int idx = fls(j - i + 1) - 1;
    return min(tb_min[i][idx], tb_min[j - (1 << idx) + 1][idx]);
}

int range_max(int i, int j) {
    int idx = fls(j - i + 1) - 1;
    return max(tb_max[i][idx], tb_max[j - (1 << idx) + 1][idx]);
}

