#define wrln(x) cout << x << endl

ll N, K, ans = 4 * 1000000000000000000 + 10;
ll x[55], y[55], Psum[55][55];
map<ll, ll> Pmap;//Pmap[x]=y

ll calcPsum(ll x1, ll x2, ll y1, ll y2) {
	if (x1 == 0 && y1 == 0) return Psum[x2][y2];
	else if (x1 == 0) return Psum[x2][y2] - Psum[x2][y1 - 1];
	else if (y1 == 0) return Psum[x2][y2] - Psum[x1 - 1][y2];
	else return Psum[x2][y2] - Psum[x2][y1 - 1] - Psum[x1 - 1][y2] + Psum[x1 - 1][y1 - 1];
}

void buildPsum() {
	repi(i, 0, N) {
		repi(j, 0, N) {
			if (i == 0 && j == 0);
			else if (i == 0) Psum[i][j] = Psum[i][j - 1];
			else if (j == 0) Psum[i][j] = Psum[i - 1][j];
			else Psum[i][j] = Psum[i][j - 1] + Psum[i - 1][j] - Psum[i - 1][j - 1];
			if (Pmap[x[i]] == y[j]) Psum[i][j]++;
		}
	}
}

int main() {
	cin >> N >> K;
	repi(i, 0, N) {
		ll p, q;
		cin >> p >> q;
		x[i] = p, y[i] = q;
		Pmap[p] = q;
	}
	sort(x, x + N);
	sort(y, y + N);

	buildPsum();

	repi(x1, 0, N) {
		repi(x2, x1 + 1, N) {
			repi(y1, 0, N) {
				repi(y2, y1 + 1, N) {
					if (calcPsum(x1, x2, y1, y2) == K) ans = min(ans, (x[x2] - x[x1])*(y[y2] - y[y1]));
				}
			}
		}
	}

	wrln(ans);

	return 0;
}

