using namespace std;

int N,K;
long long x[50],y[50];
long long sortX[50],sortY[50];
bool LargeThanK(int i,int j,int k,int l){
    int tmp=0;
    for(int t=0;t<N;t++){
        if(x[t]>=sortX[i] && x[t]<=sortX[j]){
            if(y[t]>=sortY[k] && y[t]<=sortY[l]){
                tmp++;
            }
        }
    }
    if(tmp>=K){
        return true;
    }else{
        return false;
    }
}

int main(){
    cin>>N>>K;
    for(int i=0;i<N;i++){
        cin>>x[i]>>y[i];
        sortX[i]=x[i];
        sortY[i]=y[i];
    }
    sort(sortX,sortX+N); sort(sortY,sortY+N);
    long long ans = 4*1e18+1;
    for(int i=0;i<N;i++){
        for(int j=i+1;j<N;j++){
            for(int k=0;k<N;k++){
                for(int l=k;l<N;l++){
                    if(LargeThanK(i,j,k,l)){
                        long long area=(sortX[j]-sortX[i])*(sortY[l]-sortY[k]);
                        ans=min(ans,area);
                    }
                }
            }
        }
    }
    cout<<ans<<endl;
    return 0;
}

