			if (x[i] <= x[j]) {
				int cntx, cnty;
				cntx = x[j];
				x[j] = x[i];
				x[i] = cntx;
				cnty = y[j];
				y[j] = y[i];
				y[i] = cnty;
			}
		}
	}

	for (int i = 0; i < N; i++) {
		int check = 0;
		for (int j=i+1; j < i+K-1; j++) {
			if (y[i] <= y[j] && y[j] <= y[i + K - 1]) {
				check++;
			}
		}
