typedef pair<long, long> P;

int main(){
  int n, K; cin >> n >> K;
  P p[n];
  rep(i, n){
    long x, y; cin >> x >> y;
    p[i] = P(x, y);
  }
  int cnt[n][n][4]; rep(i, n)rep(j, n)rep(k, 4) cnt[i][j][k] = 0;
  rep(i, n)rep(j, n)rep(k, n){
    if(p[k].first>p[i].first && p[k].second>p[j].second) cnt[i][j][0]++;
    if(p[k].first<p[i].first && p[k].second>p[j].second) cnt[i][j][1]++;
    if(p[k].first<p[i].first && p[k].second<p[j].second) cnt[i][j][2]++;
    if(p[k].first>p[i].first && p[k].second<p[j].second) cnt[i][j][3]++;
  }
  long ans = LONG_MAX;
  rep(i, n)rep(j, n)rep(k, n)rep(l, n){
    if(p[i].second>p[j].second && p[k].first<p[l].first){
