inline auto iota(int n) {
  auto ret = std::vector< int >(n);
  std::iota(ret.begin(), ret.end(), 0);
  return ret;
}

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n, k; std::cin >> n >> k;
  std::vector< int > x(n), y(n);
  rep(i, 0, n) std::cin >> x.at(i) >> y.at(i);
  auto ord = iota(n);
  std::sort(all(ord), [&x](auto i, auto j){ return x.at(i) < x.at(j); });
  auto cal = [&] (auto&& z) {
    std::sort(all(z));
    assert((int)z.size() >= k);
    auto it = z.begin(), jt = z.begin() + k - 1;
    int ret = 2e9;
    while (jt != z.end()) {
      cmn(ret, *jt - *it);
      it++, jt++;
    }
    return ret;
  };
  lint ret = 4e18;
  rep(l, 0, n) rep(r, l + k, n + 1) {
    auto width = x.at(ord.at(r - 1)) - x.at(ord.at(l));
    auto z = std::vector< int >(r - l);
    std::transform(ord.begin() + l, ord.begin() + r, z.begin(), [&y](auto x)
      { return y.at(x); });
    cmn(ret, (lint)width * cal(z));
  }
  std::cout << ret << std::endl;
  return 0;
}

