void solve(int n, int k, vector< pair<long long, long long> > xy, vector< pair<long long, long long> > xy2) {
    long long ret = 0;
    for (int i = 0; i < n-1; i++) {
        for (int j = 0; j < n-1-i; j++) {
            int count = 0;
            int a = i + j + 1;
            long long xmin = min(xy[i].first, xy[a].first);
            long long xmax = max(xy[i].first, xy[a].first);
            long long ymin = min(xy[i].second, xy[a].second);
            long long ymax = max(xy[i].second, xy[a].second);
            for (int l = 0; l < n; l++) {
                long long x = xy[l].first;
                long long y = xy[l].second;
                if (x >= xmin && x <= xmax && y >= ymin && y <= ymax) {
                    count++;
                }
            }
            if (count >= k) {
                long long S = (ymax - ymin) * (xmax - xmin);
                if (ret > S || ret == 0) {
                    ret = S;
                }
            }
        }
    }
    std::cout << ret << std::endl;
}


