                swap(X[0],X[1]);
            if (Y[0] > Y[1])
                swap(Y[0],Y[1]);
            const LL A = 1LL*(X[1]-X[0])*(Y[1]-Y[0]);
            if (0 < A) {
                int cnt = 0;
