int N, K; 
vector<int> x, y;
int cnt(int x1, int y1, int x2, int y2){
  int ret = 0;
  REP(i, N){
    if(IN(x1, x[i], x2+1) && IN(y1, y[i], y2+1)) ret++;
  }
  return ret;
}

signed main() {
  cin >> N >> K;

  x.resize(N);
  y.resize(N);
  REP(i, N) cin >> x[i] >> y[i];

  int ans = 4*INF;
  int x1, x2, y1, y2;
  REP(i, N) REP(j, N){
    if(i == j) continue;
    if(x[i] == x[j] || y[i] == y[j]) continue;
    x1 = min(x[i], x[j]);
    y1 = min(y[i], y[j]);
    x2 = max(x[i], x[j]);
    y2 = max(y[i], y[j]);
    if(cnt(x1, y1, x2, y2) >= K) chmin(ans, (x2-x1)*(y2-y1));
  }
  REP(i, N) REP(j, N) REP(k, N){
    if(i == j || j == k || k == i) continue;
    x1 = min(min(x[i], x[j]), x[k]);
    y1 = min(min(y[i], y[j]), y[k]);
    x2 = max(max(x[i], x[j]), x[k]);
    y2 = max(max(y[i], y[j]), y[k]);
    if(cnt(x1, y1, x2, y2) >= K) chmin(ans, (x2-x1)*(y2-y1));
  }

  cout << ans << endl;

