struct Vertex
{
    i64 x, y;
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int N, K;
    cin >> N >> K;

    Vertex vertices[50];
    for (int i = 0; i < N; i++)
        cin >> vertices[i].x >> vertices[i].y;

    sort(vertices, vertices + N, [](auto& lhs, auto& rhs) { return make_pair(lhs.x, lhs.y) < make_pair(rhs.x, rhs.y); });

    i64 min_area = numeric_limits<i64>::max();
    for (int i = 0; i < N; i++)
    {
        for (int j = i; j < N; j++)
        {
            const int m = j - i + 1;
            Vertex middle_vertices[50];
            for (int k = i; k <= j; k++)
                middle_vertices[k - i] = vertices[k];

            sort(middle_vertices, middle_vertices + m, [](auto& lhs, auto& rhs) { return make_pair(lhs.y, lhs.x) < make_pair(rhs.y, rhs.x); });

            for (int i1 = 0; i1 < m; i1++)
            {
                for (int j1 = i1; j1 < m; j1++)
                {
                    i64 y0 = middle_vertices[i1].y;
                    i64 y1 = middle_vertices[j1].y;

                    const int verts_in_rect = j1 - i1 + 1;
                    bool good_range = vertices[i].y >= y0 && vertices[i].y <= y1;
                    good_range |= vertices[j].y >= y0 && vertices[j].y <= y1;

                    if (good_range && verts_in_rect >= K)
                    {
                        i64 x0 = vertices[i].x;
                        i64 x1 = vertices[j].x;

                        i64 dx = x1 - x0;
                        i64 dy = y1 - y0;

                        i64 rect_area = dx * dy;

                        min_area = min(min_area, rect_area);
                    }
                }
            }
        }
    }

    cout << min_area;
}

