template<typename T> 
void chmax(T &a, T b){ a = max(a, b); };
template<typename T> 
void chmin(T &a, T b){ a = min(a, b); };

typedef long long ll;
typedef pair<ll, ll> P;
const int INF = 100000000;
const ll LINF = 8000000000000000000;
const int MOD = 1000000007;
const int dx[9] = { 0, 1,  0, -1, 1,  1, -1, -1, 0};
const int dy[9] = { 1, 0, -1,  0, 1, -1, -1,  1, 0};
//--------------------------------------//
int N, K;
ll x[50], y[50];
P px[50], py[50];

void solve(){
	sort(px, px + N);
	sort(py, py + N);
	ll ans = LINF;
	rep(i, N){
		ll lx = px[i].first;
		int n;
		rep(j, N){
			if(py[j].first == px[i].second){
				n = j;
				break;
			}
		}
		for(int top = n; top >= 0; top--){
			if(py[top].second < lx) continue;
			for(int under = n; under < N; under++){
				if(py[under].second < lx) continue;
				ll ty = py[top].first;
				ll uy = py[under].first;
				ll rx = max(py[top].second, py[under].second);
				int c = 0;
				rep(j, N){
					if(px[j].first < lx or px[j].second < ty or px[j].second > uy) continue;
					c++;
					if(c == K){
						chmax(rx, px[j].first);
						chmin(ans, (rx - lx) * (uy - ty));
					}
				}
			}
		}
	}
	cout << ans << endl;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> N >> K;
	rep(i, N) {
		cin >> x[i] >> y[i];
		px[i] = P(x[i], y[i]);
		py[i] = P(y[i], x[i]);
	}
		solve();
	return 0;
}

