using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define ITR(c,it)  for(auto it = c.begin(); it != c.end(); it++)

typedef long long ll;

const int N_MAX = 50;

int N, K;
int x[N_MAX];
int y[N_MAX];

int H, W;
ll rx[N_MAX];
ll ry[N_MAX];
int acc[N_MAX + 1][N_MAX + 1];

void compress(int *z, ll *rz, int *n) {
  map<int, int> mp;
  REP(i, N) mp[z[i]] = 1;
  int k = 0;
  ITR(mp, it) {
    it->second = k;
    rz[k] = it->first;
    k++;
  }
  REP(i, N) z[i] = mp[z[i]];
  *n = mp.size();
}

void solve() {
  compress(x, rx, &W);
  compress(y, ry, &H);
  REP(i, N) acc[y[i] + 1][x[i] + 1] = 1;
  REP(i, H + 1) REP(j, W) acc[i][j + 1] += acc[i][j];
  REP(i, H) REP(j, W + 1) acc[i + 1][j] += acc[i][j];
  ll ans = 4e18;
  FOR(i2, 1, H) REP(i1, i2) FOR(j2, 1, W) REP(j1, j2) {
    int cnt = acc[i2][j2] - acc[i2][j1] - acc[i1][j2] + acc[i1][j1];
    if (cnt >= K) {
      ll dx = max(1LL, rx[j2 - 1] - rx[j1]);
      ll dy = max(1LL, ry[i2 - 1] - ry[i1]);
      ans = min(ans, dx * dy);
    }
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%d%d", &N, &K);
  REP(i, N) scanf("%d%d", x + i, y + i);
}

int main() {
  input();
  solve();
  return 0;
}

