/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = power_normal(10, 18) * 4 + 1;
ll n, k;
vpl xy;
vl xx;
mll cntx;
vpl xn;

void solve(){
    rep(i, n){
        ll a, b; in2(a, b);
        xy.pb(mp(a, b)); xx.pb(a);
        cntx[a]++;
    }

    items(kv, cntx) xn.pb(mp(kv.e1, kv.e2));
    sort(all(xn));
    sort(all(xy));
    sort(all(xx));

    ll xn_size = xn.size();
    ll xsum[xn_size];
    rep(i, xn_size) xsum[i] = 0;
    rep(i, xn_size) xsum[i + 1] = xsum[i] + xn[i].e2;

    rep(i, xn_size) For(j, i, xn_size){
        if (xsum[j + 1] - xsum[i] < k) continue;
        ll start = lower_bound(all(xx), xn[i].e1) - xx.begin();
        ll end = upper_bound(all(xx), xn[j].e1) - xx.begin() - 1;

        mll cnty; vpl yn; vl yv;
        For(k, start, end + 1) {yv.pb(xy[k].e2); cnty[xy[k].e2]++;}
        items(kv, cnty) yn.pb(mp(kv.e1, kv.e2));
        sort(all(yn));

        ll yn_size = yn.size(); ll ysum[yn_size];
        rep(k, yn_size) ysum[k] = 0;
        rep(k, yn_size) ysum[k + 1] = ysum[k] + yn[k].e2;

        rep(i2, yn_size) For(j2, i2, yn_size){
            if (ysum[j2 + 1] - ysum[i2] < k) continue;
            ll sp = (xn[j].e1 - xn[i].e1) * (yn[j2].e1 - yn[i2].e1);
            answer = min(sp, answer);
        }
    }

    prl(answer);
}

int main(void){
    in2(n, k);
    solve();

    return 0;
}

