struct coord {
	int x, y;
	bool operator<(const coord &right) const {
		return y == right.y ? x < right.x : y < right.y;
	}
	bool operator==(const coord &right) const {
		return y == right.y && x == right.x;
	}
	bool operator<=(const coord &right) const {
		return *this == right || *this < right;
	}
};

int main(void) {
	int N, K;
	vector<coord> ps;
	set<int> xset;
	set<int> yset;
	cin >> N >> K;
	ps.resize(N);
	REP(i, N) {
		cin >> ps[i].x >> ps[i].y;
		xset.insert(ps[i].x);
		yset.insert(ps[i].y);
	}
	sort(ps.begin(), ps.end());
	vector<int> xs, ys;
	for (auto x : xset) {
		xs.push_back(x);
	}
	for (auto y : yset) {
		ys.push_back(y);
	}
	sort(xs.begin(), xs.end());
	sort(ys.begin(), ys.end());
	vector<vector<int>> dp;
	dp.resize(ys.size());
	REP(i, dp.size()) dp[i].resize(ys.size(), 0);
	int idx = 0;

	for (int i = 0; i < ys.size(); i++) {
		for (int j = 0; j < xs.size(); j++) {
			coord c = { xs[j], ys[i] };
			bool inc = false;
			if (idx < ps.size() && ps[idx] == c) inc = true;
			if (inc) idx++;
			dp[i][j] = (j - 1 >= 0 ? dp[i][j - 1] : 0)
				+ (i - 1 >= 0 ? dp[i - 1][j] : 0)
				- (i - 1 >= 0 && j - 1 >= 0 ? dp[i - 1][j - 1] : 0) + (inc ? 1 : 0);
		}
	}
	LONG minS = (LONG)2000000000 * (LONG)2000000000;
	for (int xmin = 0; xmin < xs.size() - 1; xmin++) {
		for (int xmax = xmin + 1; xmax < xs.size(); xmax++) {
			for (int ymin = 0; ymin < ys.size() - 1; ymin++) {
				for (int ymax = ymin + 1; ymax < ys.size(); ymax++) {
					int num = dp[ymax][xmax]
						+ (ymin - 1 >= 0 && xmin - 1 >= 0 ? dp[ymin-1][xmin-1] : 0)
						- (ymin - 1 >= 0 ? dp[ymin-1][xmax] : 0)
						- (xmin - 1 >= 0 ? dp[ymax][xmin - 1] : 0);
					if (num >= K) {
						minS = min(minS, (LONG)(xs[xmax] - xs[xmin]) * (LONG)(ys[ymax] - ys[ymin]));
					}
				}
			}
		}
	}
	cout << minS << endl;
	return 0;
}

