void solve()
{
    ll N, K;
    in(N, K);
    vector<pll> po;
    vll xx;
    for1 (i, N) {
        ll x, y;
        in(x, y);
        po.emplace_back(x, y);
        xx.push_back(x);
    }
    sort(all(po));
    sort(all(xx));
    ll ans = INF * 4;
    for1 (i2, N) {
        for1 (i1, i2) {
            vll yy;
            for1 (i, N) {
                ll x, y;
                tie(x, y) = po[i];
                if (xx[i1] <= x && x <= xx[i2]) {
                    yy.push_back(y);
                }
            }
            sort(all(yy));
            ll cnt = yy.size();
            for1 (i, cnt - K + 1) {
                chmin(ans, (yy[i + K - 1] - yy[i]) * (xx[i2] - xx[i1]));
            }
        }
    }
    print(ans);
}
