void build_sparse_table() {
    rep(i, n) { tb_max[i][0] = tb_min[i][0] = p[i].Y; }

    int idx_sz = fls(n);
    repse(k, 1, idx_sz) {
        rep(i, n) {
            tb_min[i][k] = min(tb_min[i][k - 1], tb_min[i + (1 << (k - 1))][k - 1]);
            tb_max[i][k] = max(tb_max[i][k - 1], tb_max[i + (1 << (k - 1))][k - 1]);
        }
    }
