    int idx = fls(j - i + 1) - 1;
    return min(tb_min[i][idx], tb_min[j - (1 << idx) + 1][idx]);
}

int range_max(int i, int j) {
    int idx = fls(j - i + 1) - 1;
    return max(tb_max[i][idx], tb_max[j - (1 << idx) + 1][idx]);
}

