		x[i] += 1000000000;
		y[i] += 1000000000;
	}

	long long int max = LLONG_MAX;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			for (int ii = 0; ii < n; ++ii)
