bool cmp_x (tnode a, tnode b)
{
    if (a.x == b.x)
    {
        return a.y < b.y;
    }
    return a.x < b.x;
}

bool cmp_y (tnode a, tnode b)
{
    if (a.y == b.y)
    {
        return a.x < b.x;
    }
    return a.y < b.y;
}

int main ()
{
