using ll = long long;

constexpr int MAX_N = 50;

int N, K;
ll x[MAX_N], y[MAX_N];

int main()
{
    scanf( "%d%d", &N, &K );
    rep( i, N )
        scanf( "%lld%lld", x+i, y+i );

    std::sort( x, x+N );
    std::sort( y, y+N );

    ll ans = 6e18;

    rep( i, N ) rep( j, N ) rep( k, N ) rep( l, N ) if( i != j && k != l && x[i] < x[j] && y[k] < y[l])
    {
        //[i,j] [k,l]
        int cnt = 0;

        if( k <= i && j <= l )
            cnt = j-i+1;
        else if( i <= k && l <= j )
            cnt = l-k+1;
        else if( k <= j && j <= l )
            cnt = j-k+1;
        else if( k <= i && i <= l )
            cnt = l-i+1;

        if( cnt >= K )
            ans = std::min( ans, (x[j]-x[i])*(y[l]-y[k]) );
    }

    printf( "%lld\n", ans );

    return 0;
}

