using P = pair<ll, ll>;
const ll LLINF = 9223372036854775807;

ll calc(P a, P b)
{
    ll p = llabs(a.first - b.first);
    ll q = llabs(a.second - b.second);
    return p * p + q * q;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, k;
    cin >> n >> k;
    vector<P> p(n);
    for (int i = 0; i < n; i++)
    {
        cin >> p[i].first >> p[i].second;
    }
    ll ans = LLINF;
    for (int i = 0; i < n; i++)
    {
        vector<pair<P, ll>> tmp;
        for (int j = 0; j < n; j++)
        {
            tmp.push_back(make_pair(p[j], calc(p[i], p[j])));
        }
        sort(ALL(tmp), [](const auto &a, const auto &b) { return a.second < b.second; });
        ll mn[2];
        ll mx[2];
        for (int j = 0; j < 2; j++)
        {
            mn[j] = LLINF;
            mx[j] = -LLINF;
        }
        for (int j = 0; j < k; j++)
        {
            auto rec = tmp[j].first;
            // cout << "dbg:" << rec.first << ' ' << rec.second << endl;
            chmin(mn[0], rec.first);
            chmin(mn[1], rec.second);
            chmax(mx[0], rec.first);
            chmax(mx[1], rec.second);
            // cout << mn[0] << ' ' << mn[1] << endl;
        }
        chmin(ans, (mx[0] - mn[0]) * (mx[1] - mn[1]));
    }
    cout << ans << endl;
}

