vector<pii> g[51];

void dfs(int from, int i, vector<bool>& v)
{
    for(auto e: g[from])
    {
        if(e.second == i)
        {
            continue;
        }
        if(v[e.first])
        {
            continue;
        }
        v[e.first] = true;
        dfs(e.first, i, v);
    }
}
