int calcarea(int x1, int x2, int y1, int y2, int N, vector<int> &x, vector<int> &y, int K){
    int xm = min(x1, x2);
    int xM = max(x1, x2);
    int ym = min(y1, y2);
    int yM = max(y1, y2);

    int num = 0;
    REP(i, N){
        if(xm <= x[i] && x[i] <= xM && ym <= y[i] && y[i] <= yM) num++;
    }
    if(num >= K) return (xM - xm) * (yM - ym);
    return -1;
}

