using namespace std;

using ll = long long;

int N, K;
ll INF = 1 << 30;
vector<pair<ll, ll>> points;
vector<pair<ll, ll>> width;
vector<pair<ll, ll>> height;

int count(ll lx, ll rx, ll ly, ll hy) {
    int res = 0;
    for (auto& p : points) {
        if (p.first >= lx && p.first <= rx && p.second >= ly && p.second <= hy) {
            res++;
        }
    }

    return res;
}

int main() {
    cin >> N >> K;

    points.reserve(N);
    width.reserve(N);
    height.reserve(N);
    for (int i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        points.push_back(pair<ll, ll>(x, y));
    }

    for (int i = 0; i < N; i++) {
        for (int j = i; j < N; j++) {
            ll xl = points[i].first;
            ll xr = points[j].first;

            if (xl > xr) swap(xl, xr);

            width.push_back(pair<ll, ll>(xl, xr));
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = i; j < N; j++) {
            ll yl = points[i].second;
            ll yh = points[j].second;

            if (yl > yh) swap(yl, yh);

            height.push_back(pair<ll, ll>(yl, yh));
        }
    }

    ll res = INF;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            ll xa = width[i].first; ll xb = width[i].second;
            ll ya = height[j].first; ll yb = height[j].second;

            if (count(xa, xb, ya, yb) == K) {
                ll S = abs((xb - xa) * (yb - ya));
                res = min(res, S);
            }
        }
    }

    cout << res << endl;

    return 0;
}

