			ans = min(ans,abs(x[1]-x[2])*abs(y[1]-y[2]));
		}else{
			ans = abs(min({x[0],x[1],x[2]})-max({x[0],x[1],x[2]}));
			ans *= abs(min({y[0],y[1],y[2]})-max({y[0],y[1],y[2]}));
		}
	}else{
		if(K==2){
			rep(a,N)rep(b,N){
				if(a==b)continue;
				ans = min(ans,abs(x[a]-x[b])*abs(y[a]-y[b]));
			}
		}else{
			rep(a,N)rep(b,N)rep(c,N){
				if(a==b||b==c||a==c)continue;
