int	main() {
	int N, K;
	cin >>N >>K;
	vector<long> x(N+1, 0), y(N+1, 0);
	for (int i=1; i<=N; i++)
		cin >>x.at(i) >>y.at(i);
	vector<long> X=x, Y=y;
	sort(X.begin()+1, X.end());
	sort(Y.begin()+1, Y.end());
	// Table of dots, 1=dot, 0=no_dot
	vector<vector<int>> p(N+1, vector<int> (N+1, 0));
	for (int i=1; i<=N; i++) {
		int XX=lower_bound(X.begin()+1, X.end(), x.at(i))-X.begin();
		int YY=lower_bound(Y.begin()+1, Y.end(), y.at(i))-Y.begin();
		p.at(XX).at(YY)=1;
	}
	// Table of number of dots in the rectangle with the point at right top corner
	vector<vector<int>> r(N+1, vector<int> (N+1, 0));
	for (int i=1; i<=N; i++)
		for (int j=1, D=0; j<=N; j++) {
			if (1==p.at(i).at(j))
				D++;
			r.at(i).at(j)=r.at(i-1).at(j)+D;
		}
	long S=2000000000;
	S *=S;
	for (int i=1; i<=N; i++) {
		for (int j=1; j<=N; j++) {
			int ii=N;
			int jj=1;
			while((ii>=1)&&(jj<=N)) {
				int Dots=r.at(ii).at(jj)+r.at(i-1).at(j-1)-r.at(ii).at(j-1)-r.at(i-1).at(jj);
				if (K>Dots)
					jj++;
				else {
					if (K==Dots)
						S=min(S, (X.at(ii)-X.at(i))*(Y.at(ii)-Y.at(i)));
					ii--;
				}
			}
		}
	}
	cout <<S <<endl;
	return 0;
}

