        cin >> points[i].first >> points[i].second;
    sort(points.begin(),points.end());
    long long minArea = 1e19;
    for(int i = 0;i < n && i+k <= n;i++)
    {
        long long lowestX = 1e9 + 1;
        long long highestX = -1e9 - 1;
        long long lowestY = 1e9 + 1;
        long long highestY = -1e9 - 1;
        for(int j = i;j <= i+k-1;j++)
        {
            lowestX = min(lowestX,points[j].first);
            highestX = max(highestX,points[j].first);
            lowestY = min(lowestY,points[j].second);
            highestY = max(highestY,points[j].second);
        }
        //cout << lowestX << " " << highestX << " " << lowestY << " " << highestY << endl;
        minArea = min(minArea,(highestX - lowestX) * (highestY - lowestY));
    }
    for(int i = 0;i < n;i++)
        swap(points[i].first,points[i].second);
    sort(points.begin(),points.end());
    for(int i = 0;i < n && i+k <= n;i++)
    {
        long long lowestX = 1e9 + 1;
        long long highestX = -1e9 - 1;
        long long lowestY = 1e9 + 1;
