ll pow_mod(ll a, ll p) {
    ll res = 1;
    while(p) {
        if (p & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        p >>= 1;
    }

    return res;
}


ll mod_inv(ll a, ll m) {
    ll b = m, u = 0, v = 1;
    while(a) {
        ll t = b / a;
        swap(b -= t * a, a);
        swap(u -= t * v, v);
    }

    return (u % m + m) % m;
}

ll gcd(ll a, ll b) {
    if(b == 0) return a;
    return gcd(b, a%b);
}

struct RECT{
    ll l;
    ll r;
    ll t;
    ll b;
    ll f;

    RECT(){}
    RECT(ll x1, ll y1, int id) :
    l(x1), r(x1), t(y1), b(y1), f(1LL << id) {}

    ll sq() {
        return (r - l) * (t - b);
    }

    void update(ll x, ll y) {
        if (x > r) r = x;

        if (x < l) l = x;

        if (y > t) t = y;

        if (y < b) b = y;
    }

    void print() {
        cout << l << " " << r << " " << t << " " << b << " " << endl;
        cout << bitset<50>(f) << endl << endl;
    }
};


