vector<PAIR> v;


ll S(vector<ll>::iterator& l, vector<ll>::reverse_iterator& r,
	vector<ll>::iterator& d, vector<ll>::reverse_iterator& u, ll k) {
	ll count = 0;
	REPC(p, v) {
		if (p.first >= *l&&p.first <= *r&&p.second >= *d&&p.second <= *u) { ++count; }
	}
	if (count < k) { return (ll)1e20; }

	ll ans = (*r - *l)*(*u - *d);

	ans = std::min(ans, S((++l)--, r, d, u, k));
	ans = std::min(ans, S(l, (++r)--, d, u, k));
	ans = std::min(ans, S(l, r, (++d)--, u, k));
	ans = std::min(ans, S(l, r, d, (++u)--, k));

	return ans;
}

