template<typename A,typename B>inline void chmax(A &a,B b){if(a<b)a=b;}

int N,K;
int x[55],y[55];


int solve(int l,int r){
    vint v;
    rep(i,N){
        if(x[i]<l||r<x[i])continue;
        v.pb(y[i]);
    }

    sort(all(v));

    int ret=LLONG_MAX;
    rep(i,v.size()){
        if(i+K>v.size())break;
        chmin(ret,(r-l)*(v[i+K-1]-v[i]));
    }
    if(ret==0)return (r-l);
    return ret;
}

