#define LL long long
struct point{LL x; LL y;};

void solve(long long N, long long K, std::vector<long long> x, std::vector<long long> y){
    vector<point> p(N);
    for(LL i=0; i<N; i++)p[i]=point{x[i], y[i]};
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    LL ans = (x[N-1]-x[0])*(y[N-1]-y[0]);
    for(LL x1=0; x1<N; x1++){
        for(LL x2=x1; x2<N; x2++) {
            for (LL y1=0; y1<N; y1++) {
                for (LL y2=y1; y2<N; y2++) {
                    LL cnt = 0;
                    for(LL i=0; i<N; i++)
                        if(p[i].x >= x[x1] && p[i].x <= x[x2] && p[i].y >= y[y1] && p[i].y <= y[y2])
                            cnt++;
                    if(cnt < K)continue;
                    LL area = (x[x2]-x[x1])*(y[y2]-y[y1]);
                    ans = min(ans, area);
                }
            }
        }
    }
    cout << ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long K;
