const ll INF = (1e20);

struct SegmentTree {
	int init_val;
	int n;
	vector<int> dat;

	SegmentTree(int _n) {
		init_val = INF;
		n = 1;
		while (n < _n) n *= 2;
		dat.clear();
		dat.resize(2 * n - 1, init_val);
	}

	void update(int k, int a) {
		k += n - 1;
		dat[k] = min(dat[k], a);

		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}

	int query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return dat[k];
		return min(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	int query(int a, int b) {
		return query(a, b, 0, 0, n);
	}
};

typedef SegmentTree Seg;

int main() {
	int n, k;
	cin >> n >> k;
	vector<pi> xy(n);
	rep(i, n) {
		int x, y;
		cin >> x >> y;
		xy[i].first = x;
		xy[i].second = y;
	}
	sort(xy.begin(), xy.end());

	Seg up(n), down(n), right(n), left(n);
	rep(i, n) {
		int x = xy[i].first;
		int y = xy[i].second;

		up.update(i, -y);
		down.update(i, y);
		right.update(i, -x);
		left.update(i, x);
	}

	int st = 0, en = 0;
	ll ans = INF;

	while (st < n) {
		if (en - st >= k-1) {
			ll area = (ll)(-up.query(st, en + 1) - down.query(st, en + 1))
				* (-right.query(st, en + 1) - left.query(st, en + 1));
			ans = min(ans, area);

			if (en == n - 1)st++;
			else en++;
		}
		else if(en < n-1)en++;
		else st++;
	}
	cout << ans << endl;

	return 0;
}

