int main(){
  int N,K;
  cin >> N >> K;
  vector<P>points;
  set<int> set_y;
  set<int> set_x;
  for(int i = 0 ; i < N ; i++){
    int x,y;
    cin >> x >> y;
    points.push_back(P(x,y));
    set_x.insert(x);
    set_y.insert(y);
  }

  vector<int>vec_y = vector<int>(set_y.begin(), set_y.end());
  vector<int>vec_x = vector<int>(set_x.begin(), set_x.end());

  vector<P> candidates;
  for(int i = 0 ; i < vec_y.size() ; i++){
    for(int j = 0 ; j < vec_x.size() ; j++){
      candidates.push_back(P(vec_x[j],vec_y[i]));
    }
  }

  ull area = 1e19;

  for(int i = 0 ; i < candidates.size() ; i++){
    for(int j = 0 ; j < candidates.size() ; j++){
      if(i == j)continue;
      P p1 = candidates[i];
      P p2 = candidates[j];

      P sp = P(min(p1.X, p2.X), min(p1.Y, p2.Y));
      P ep = P(max(p1.X, p2.X), max(p1.Y, p2.Y));

      int count = 0;

      for(int k = 0 ; k < points.size() ; k++){
        P p = points[k];
        if(!(sp.X <= p.X && p.X <= ep.X))continue;
        if(!(sp.Y <= p.Y && p.Y <= ep.Y))continue;

        count++;
        if(count == K){

          ull a = ull(ep.X - sp.X) * ull(ep.Y - sp.Y);
          area = min(area,a);
          break;
        }
      }
    }
  }
  cout << area << endl;
  return 0;
}

