			{ if( l.second < r.second ) return true; else return false; }
			else return false; } );
	sort( vy.begin(), vy.end(), [=]( P l, P r )
		{ if( l.second < r.second ) return true; else if( l.second == r.second )
			{ if( l.first < r.first ) return true; else return false; }
			else return false; } );

	long long min_x = vx[0].first;
	long long max_x = vx[vx.size()-1].first;
	long long min_y = vy[0].second;
	long long max_y = vy[vy.size()-1].second;

