const double pi = 3.14159265358979323846264;

int main()
{
    ll n;
    cin >> n;
    ll in_k;
    cin >> in_k;
    ll x[n];
    ll y[n];
    ll ans = 4000000000000000000;
    for (ll i = 0; i < n; i++)
    {
        cin >> x[i] >> y[i];
    }
    for (ll i = 0; i < n; i++)
    {
        for (ll j = i; j < n; j++)
        {
            for (ll k = j; k < n; k++)
            {
                for (ll l = k; l < n; l++)
                {
                    ll right = max({x[i], x[j], x[k], x[l]});
                    ll left = min({x[i], x[j], x[k], x[l]});
                    ll up = max({y[i], y[j], y[k], y[l]});
                    ll down = min({y[i], y[j], y[k], y[l]});
                    //cout << right << " " << left << " ; " << up << " " << down << " ";

                    ll cnt = 0;
                    for (ll m = 0; m < n; m++)
                    {
                        if (x[m] >= left && x[m] <= right)
                        {
                            if (y[m] >= down && y[m] <= up)
                            {
                                cnt++;
                            }
                        }
                    }
                    //cout << "; " << cnt << endl;
                    if (cnt >= in_k)
                    {
                        ll menseki = (right - left) * (up - down);
                        //cout << " ; " << menseki << endl;
                        if (menseki > 0)
                        {
                            chmin(ans, menseki);
                        }
                    }
                }
            }
        }
    }
    cout << ans << endl;
}

