int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<P> table(n);
    for(int i = 0; i < n; ++i)  cin >> table[i];
    sort(table.begin(), table.end());
    ll ans = 4e+18 + 5;
    for(int i = 0; i + k <= n; ++i){
        ll S = table[i + k - 1].first - table[i].first;
        int maxy = -INF, miny = INF;
        for(int j = i; j < i + k; ++j){
            chmax(maxy, table[j].second);
            chmin(miny, table[j].second);
        }
        S *= (ll)maxy - miny;
        chmin(ans, S);
    }
    sort(table.begin(), table.end(), [](const P& p1, const P& p2){
        if(p1.second == p2.second){
            return p1.first < p2.first;
        }
        return p1.second < p2.second;
    });
    for(int i = 0; i + k <= n; ++i){
        ll S = table[i + k - 1].second - table[i].second;
        int maxx = -INF, minx = INF;
        for(int j = i; j < i + k; ++j){
            chmax(maxx, table[j].first);
            chmin(minx, table[j].first);
        }
        S *= (ll)maxx - minx;
        chmin(ans, S);
    }
    cout << ans << endl;
}

