int main(){
	vector<pair<ll,ll> >xiyi;

	ll N,K; SCLLD2(N,K);
	ll count[N] = {};
	ll countl[N] = {};
	ll countd[N] = {};
	ll ans = INF;

	REP(i,N){
		ll x,y;
		SCLLD2(x,y);
		xiyi.PB(MP(x,y));
	}

	REP(i,N){
		REP(j,N){
			if ((xiyi[i].fst <= xiyi[j].fst) && (xiyi[i].snd <= xiyi[j].snd)){
				count[j]++;
			}
			if (xiyi[i].fst <= xiyi[j].fst){
				countl[j]++;
			}
			if (xiyi[i].snd <= xiyi[j].snd){
				countd[j]++;
			}

		}
	}

	REP(i,N){
		REP(j,N){
			if (i == j) continue;
			ll ink = 2;
			REP(k,N){ //2
				if ((i-k)*(j-k) == 0) continue;
				if ((xiyi[j].fst <= (xiyi[k].fst)) && (xiyi[j].snd <= (xiyi[k].snd))
					&& (xiyi[k].fst <= (xiyi[i].fst)) && (xiyi[k].snd <= (xiyi[i].snd))){
					ink++;
				}
			}

			if (ink >= K){

				ans = min(ans,abs((xiyi[j].fst-xiyi[i].fst) * (xiyi[j].snd-xiyi[i].snd)) ); 
			}

			// 3
				REP(k,N){
				ink = 3;
				if ((i-k) * (j-k) == 0) continue;
				ll xmax,xmin,ymax,ymin;
				xmax = max({xiyi[i].fst,xiyi[j].fst,xiyi[k].fst});
				xmin = min({xiyi[i].fst,xiyi[j].fst,xiyi[k].fst});
				ymax = max({xiyi[i].snd,xiyi[j].snd,xiyi[k].snd});
				ymin = min({xiyi[i].snd,xiyi[j].snd,xiyi[k].snd});

					REP(l,N){//count
						if ((i-k) * (j-k) * (l-k) * (k-l) * (l-i) * (l-j) == 0) continue;

						if ((xiyi[l].fst <= xmax) && (xiyi[l].snd <= ymax) && 
						(xiyi[l].fst >= xmin) && (xiyi[l].snd >= ymin) ){
							ink++;
						}
					}

				if (ink >= K) {
					ll nans = (xmax-xmin) * (ymax-ymin);
					ans = min(ans,nans);
/* 					printf("(xmax-xmin) * (ymax-ymin) = %lld\n",nans);
