int count(vector<ll>&lx, vector<ll>&ly, ll xl, ll xr, ll yl, ll yr) {
  int ret = 0;
  int size = lx.size();
  for (int i = 0; i < size; ++i) {
    ll x = lx[i];
    ll y = ly[i];
    if (x < xl || x > xr) continue;
    if (y < yl || y > yr) continue;
    ++ret;
  }
  return ret;
}

