struct CombiTbl {
	mints fac;
	mints ifac;

	CombiTbl(int N) : fac(N), ifac(N) {
		fac[0] = 1;
		ifac[0] = 1;
		FOR(i, 1, N) {
			fac[i] = fac[i - 1] * i;
			ifac[i] = fac[i].inv();
		}
}

	mint Combi(int a, int b) const {
		return fac(a) * ifac(b) * ifac(a - b);
	}

	// N*2のテーブルが無いとだめ
	mint RepCombi(int a, int b) const {
		return Combi(a + b - 1, b);
	}
};

