struct Compress {
private:
	ints comp2org;
	dic<int, int> org2cmp;

public:
	Compress(int N, function<bool(int a, int b)> predicate) {
		comp2org.init(N);
		REP(i, N) {
			comp2org[i] = i;
		}
		comp2org.sort(predicate);

		REP(i, N) {
			org2cmp[comp2org[i]] = i;
		}
	}

	int Comp2Oorg(int compIndex) const {
		return comp2org[compIndex];
	}

	int Org2Comp(int orgIndex) const {
		return org2cmp.at(orgIndex);
	}
};

