	pint orgPoint;
	int orgIndex;
};

struct MyMain {
	int N = in;
	int K = in;
	pints P = in(N);

	void Run() {
		Compress compX(N, [&](int a, int b) {
			return P[a].x < P[b].x;
		});
		Compress compY(N, [&](int a, int b) {
			return P[a].y < P[b].y;
		});

		Imos2 imos(N, N);
		REP(i, N) {
			int cx = compX.Org2Comp(i);
			int cy = compY.Org2Comp(i);
			imos.Add(cx, cy, 1);
		}
		imos.Calc();

		int ans = INF;
		REP(y1, N) {
			REP(x1, N) {
				FOR(y2, y1 + 1, N) {
					FOR(x2, x1 + 1, N) {
						int left = x1;
						int right = x2;
						int top = y1;
						int bottom = y2;
						if (right < left) {
							swap(left, right);
						}
						if (bottom < top) {
							swap(top, bottom);
						}
						right++;
						bottom++;

						int cnt = imos.Get(left, top, right, bottom);
						if (cnt < K) {
							continue;
						}

						int orgX1 = compX.Comp2Oorg(x1);
						int orgY1 = compY.Comp2Oorg(y1);
						int orgX2 = compX.Comp2Oorg(x2);
						int orgY2 = compY.Comp2Oorg(y2);

						int area = abs(P[orgX1].x - P[orgX2].x) * abs(P[orgY1].y - P[orgY2].y);
						chmin(ans, area);
					}
				}
			}
		}

		out << ans;
	}
};

