                    ll b = vs[i];
                    ll t = vs[j];
                    ll cnt = S[t][r] - S[b-1][r] - S[t][l-1] + S[b-1][l-1];

                    if (cnt >= K) {
                        ll L = dict[l];
                        ll R = dict[r];
                        ll B = dict[b];
                        ll T = dict[t];
                        ll area = (R - L) * (T - B);
                        res = min(area, res);
                    }

                }
            }
        }
    }

    put(res);
}
