signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.setf(ios_base::fixed);
    cout.precision(10);
    var(size_t, N, K);
    vector<pair<intmax_t, intmax_t>> p(N);
    rep(i, 0, N) {
        var(intmax_t, x, y);
        p[i] = {x, y};
    }
    vector<pair<intmax_t, intmax_t>> choose;
    const auto rec = makeFixPoint([&](auto rec, size_t i, size_t C) -> intmax_t {
        if (i == N) {
            if (choose.size() != C) return LINF;
            intmax_t min_x, max_x, min_y, max_y;
            min_x = min_y = LINF;
            max_x = max_y = -LINF;
            for (const auto point: choose) {
                intmax_t x, y;
                tie(x, y) = point;
                chmin(min_x, x);
                chmax(max_x, x);
                chmin(min_y, y);
                chmax(max_y, y);
            }
            intmax_t cnt = 0;
            for (const auto point: p) {
                intmax_t x, y;
                tie(x, y) = point;
                cnt += (min_x <= x && x <= max_x && min_y <= y && y <= max_y);
            }
            return ((cnt >= K) ? diff(min_x, max_x) * diff(min_y, max_y) : LINF);
        }
        intmax_t ret = LINF;
        if (choose.size() == C) {
            chmin(ret, rec(i + 1, C));
        } else {
            choose.emplace_back(p[i]);
            chmin(ret, rec(i + 1, C));
            choose.pop_back();
            chmin(ret, rec(i + 1, C));
        }
        return ret;
    });
    output(min(rec(0, 2), rec(0, 3)));
    return 0;
}

