            return;
        }

        int last;
        if (d.size() == 0) {
            last = 0;
        } else {
            last = d.back() + 1;
        }
        for (int i = last; i < N; ++i) {
            d.push_back(i);
            dfs(d);
            d.pop_back();
        }
        return;
    };

    dfs(vec<int>());

