template<typename T> class CumulativeSum2D
{
   private:
      vector<vector<T>> s;
   public:
      CumulativeSum2D(const vector<vector<T>>& v) {
         int M = v.size(), N = v[0].size();
         s.resize(M+1, vector<int>(N+1));
         for (int i = 0; i < M; i++) {
            for (int j = 0; j < N; j++) {
               s[i+1][j+1] = s[i+1][j] + v[i][j];
            }
         }
         for (int i = 0; i < M; i++) {
            for (int j = 0; j < N; j++) {
               s[i+1][j+1] += s[i][j+1];
            }
         }
      }
      int sum(int i, int j, int k, int l) {
         return s[k+1][l+1] - s[i][l+1] - s[k+1][j] + s[i][j];
      }
};

signed main()
{
   int N, K; cin >> N >> K;
   V<int> x(N), y(N);
   REP(i, N) {
      cin >> x[i] >> y[i];
   }

   V<int> X(N), Y(N);
   COPY(x, X); COPY(y, Y);
   UNIQUE(X); UNIQUE(Y);
   V<V<int>> cnt(X.size(), V<int>(Y.size()));
   REP(i, N) {
      cnt[LB(X, x[i])][LB(Y, y[i])]++;
   }

   CumulativeSum2D<int> cum(cnt);
   int MIN = INF;
   FOR(i, 0, X.size()) {
      FOR(j, 0, Y.size()) {
         FOR(k, i, X.size()) {
            FOR(l, j, Y.size()) {
               if (cum.sum(i,j,k,l) >= K) {
                  chmin(MIN, (X[k] - X[i]) * (Y[l] - Y[j]));
               }
            }
         }
      }
   }
   cout << MIN << endl;

   return 0;
}

