int miny(int K, vi& ys) {
    int m = ys.size();
    if (m < K) return -1;
    int best = 0x7fffffff;
    for (int i=0; i<=m-K; ++i) {
        for (int j=i+K-1; j<m; ++j) {
            int d = ys[j] - ys[i];
            best = min(best, d);
        }
    }
    return best;
}

ll solve(int N,int K,vi& x,vi& y) {
    vector<ii> xy(N);

    rep(i,N) xy[i] = ii(x[i], y[i]);
    sort(ALL(xy));

    ll best = 0x7fffffffffffffffLL;
    repC2(i,j,N) {
        int x0 = xy[i].first, x1 = xy[j].first, dx = x1 - x0;
        vi ys;
        for (int u=i; u<=j; ++u) ys.pb(xy[u].second);
        sort(ALL(ys));

        int dy = miny(K, ys);
#ifdef DEBUG
        fprintf(stderr, "(%d,%d): %d-%d=%d; ", i,j, x0,x1,dx);
        cerr << ys << ",K=" << K << " -> " << dy << endl;
#endif
        if (dy < 0) continue;

        ll area = (ll)dx * dy;
        best = min(best, area);
    }
    return best;
}

