const int N_MAX=50;
const ll INF=1e20;
pair<int, int> point[N_MAX];
int N, K;

ll calc_S(int i, int j, int k, int l){
    ll x[4] = {point[i].first, point[j].first, point[k].first, point[l].first};
    ll y[4] = {point[i].second, point[j].second, point[k].second, point[l].second};
    ll *x_min, *x_max, *y_min, *y_max;
    x_min = min_element(x, x+3);
    x_max = max_element(x, x+3);
    y_min = min_element(y, y+3);
    y_max = max_element(y, y+3);

    int count=0;
    rep(m, N){
        if (point[m].first >= *x_min && point[m].first <= *x_max)
            if (point[m].second >= *y_min && point[m].second <= *y_max) count++;
    }

    if (count >= K) return (*x_max-*x_min) * (*y_max-*y_min);
    else return INF;
}

int main(){
    ll ans = INF;
    cin >> N >> K;

    rep(i, N){
        cin >> point[i].first >> point[i].second;
    }

    rep(i, N){
        rep(j, N){
            rep(k, N){
                rep(l, N)
                    if (ans > calc_S(i,j,k,l)) ans = calc_S(i,j,k,l);
            }
        }
    }

    cout << ans << endl;

}

