	if(num == 4)return ret;

	for(int i = at;i<N;i++){
		ll nx = x[i];
		ll ny = y[i];
		ll v = saiki(num+1,i+1,min(lx,nx),min(ly,ny),max(rx,nx),max(ry,ny));
		ret = min(ret,v);
	}
	return ret;
}

