    int64 n, k; cin >> n >> k;
    int64 x[n], y[n];
    rep(i, n) cin >> x[i] >> y[i];

    sort(x, x + n); sort(y, y + n);

    int64 ans = (x[n - 1] - x[0]) * (y[n - 1] - y[0]);  // largest rectangle

    for (int64 xleft = 0; xleft < n; ++xleft){
        for (int64 xright = xleft + 1; xright < n; ++xright){
            for (int64 ybottom = 0; ybottom < n; ++ybottom){
