int main () {
  ll N, k;
  cin >> N >> k;
  ll x[N], y[N];
  ll distance[N];
  for (ll i = 0; i < N; i++) {
    cin >> x[i] >> y[i]; 
  }  
  ll min = -1;
  for (ll i = 0; i < N; i++) {
    for (ll j = i + 1; j < N; j++) {
      // まずは i, jの関係性を調べる
      if (x[i] == x[j]) {
        // tate
        ll ue = y[i];
        ll si = y[j];
        if (ue < y[j]) {
          swap(ue, si);    
        }
        vector<ll> migi, hidari;
        for (ll l = 0; l < N; l++) {
          if (l != i && l != j) {
            if (y[l] >= si && y[l] <= ue) {
              if (x[l] > x[i]) {
                migi.push_back(x[l] - x[i]);  
              }  
              if (x[l] < x[i]) {
                hidari.push_back(x[i] - x[l]);    
              }
              if (x[l] == x[i]) {
                migi.push_back(0);
                hidari.push_back(0);  
              }
            }    
          }  
        }

        // minについての評価
        if (migi.size() >= k - 2) {
          if (min > (ue - si) * migi[k - 3]|| min == - 1) {
            min = (ue - si) * migi[k - 3];    
          }  
        }
        if (hidari.size() >= k - 2) {
          if (min > (ue - si) * hidari[k - 3] || min == -1) {
            min = (ue - si) * hidari[k - 3];  
          }  
        } 
      }    

      if (x[i] != x[j] && y[i] != y[j]) {
        ll migi = x[j];
        ll hidari = x[i];
        ll ue = y[i];
        ll si = y[j];
        if (ue < si) {
          swap(ue, si);  
        }
        if (migi < hidari) {
          swap(migi, hidari);  
        }
        ll num = 0;
        for (ll l = 0; l < N; l++) {
          if (l != i && l != j) {
            if (x[l] >= hidari && x[l] <= migi) {
              if (y[l] >= si && y[l] <= ue) {
                num++;  
              }  
            }    
          }  
        }  
        if (num >= k - 2) {
          if (min == -1 || min > (ue - si) * (migi - hidari)) {
            min = (ue - si) * (migi - hidari);  
          }  
        }
      }
      if (y[i] == y[j]) {
        // tate
        ll migi = x[i];
        ll hidari = x[j];
        if (migi < hidari) {
          swap(migi, hidari);    
        }
        vector<ll> ue, si;
        for (ll l = 0; l < N; l++) {
          if (l != i && l != j) {
            if (x[l] >= hidari && y[l] <= migi) {
              if (y[l] > y[i]) {
                ue.push_back(y[l] - y[i]);  
              }  
              if (y[l] < y[i]) {
                si.push_back(y[i] - y[l]);    
              }
              if (y[l] == y[i]) {
                ue.push_back(0);
                si.push_back(0);  
              }
            }    
          } 
        }
        if (ue.size() >= k - 2) {
          if (min > (migi - hidari) * ue[k - 3]|| min == - 1) {
            min = (migi - hidari) * ue[k - 3];    
          }  
        }
        if (si.size() >= k - 2) {
          if (min > (migi - hidari) * si[k - 3] || min == -1) {
            min = (migi - hidari) * si[k - 3];  
          }  
        } 
      }
    }  
  }
  cout << min << endl;
}

