#define INF 4000000000000000123LL
#define MOD 1000000007
#define ALL(x) std::begin(x), std::end(x)


class point_t {
public:
  int x;
  int y;

public:
  bool operator<(const point_t& p) const {
    if (x != p.x)
      return x < p.x;

    return y < p.y;
  };
};


bool ycomp(const point_t& a, const point_t& b) {
  if (a.y != b.y)
    return a.y < b.y;

  return a.x < b.x;
}


int N, K;


long long test(std::vector<point_t> pts)
{
  long long Am = INF;

  std::sort(ALL(pts));

  for (int i = 0; i < N; i ++)
    for (int j = i; j < N; j ++) {
      int size = j + 1 - i;

      if (size < K)
        continue;

      long long w = pts[j].x - pts[i].x;

      std::vector<point_t> pts2(std::begin(pts) + i, std::begin(pts) + j + 1);

      assert(pts2.size() == size);

      std::sort(ALL(pts2), ycomp);

      for (int k = 0; k < size; k ++)
        for (int l = k; l < size; l ++) {
          if (l + 1 - k < K)
            continue;

          long long h = pts2[l].y - pts2[k].y;

          Am = std::min(w * h, Am);
        }
    }

  return Am;
}


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);

  std::cin >> N >> K;

  std::vector<point_t> pts(N);

  for (int i = 0; i < N; i ++)
    std::cin >> pts[i].x >> pts[i].y;

  long long Am = INF;

  Am = std::min(test(pts), Am);

  for (int i = 0; i < N; i ++)
    std::swap(pts[i].x, pts[i].y);

  Am = std::min(test(pts), Am);

  std::cout << Am << std::endl;

  return 0;
}

