int main() {

    int n, K;
    cin >> n >> K;
    vector<ll> x(n), y(n);
    rep(i, n) cin >> x[i] >> y[i];

    ll ans = infll;

    // 二点選んで長方形を作る 全探索
    if (K == 2) {
        rep(i, n) {
            Rep(j, i + 1, n) {
                ll left, right, bottom, top;
                if (x[i] < x[j]) {
                    left = x[i];
                    right = x[j];
                }
                else {
                    left = x[j];
                    right = x[i];
                }
                if (y[i] < y[j]) {
                    bottom = y[i];
                    top = y[j];
                }
                else {
                    bottom = y[j];
                    top = y[i];
                }

                chmin(ans, (right - left) * (top - bottom));
            }
        }
    }
    else { // k >= 3
        rep(i, n) {
            Rep(j, i + 1, n) {
                Rep(k, j + 1, n) {
                    ll left, right, bottom, top;
                    left = min({ x[i], x[j], x[k] });
                    right = max({ x[i], x[j], x[k] });
                    bottom = min({ y[i], y[j], y[k] });
                    top = max({ y[i], y[j], y[k] });

                    int cnt = 3;
                    rep(l, n) {
                        if (l == i || l == j || l == k) continue;

                        if (x[l] < left || x[l] > right) continue;
                        if (y[l] < bottom || y[l] > top) continue;

                        ++cnt;
                    }
                    if (cnt >= K) {
                        ll width = right - left;
                        ll height = top - bottom;
                        ll measure = width * height;
                        if (ans > measure) {
                            ans = measure;
                        }
                    }
                }
            }
        }
    }

    Cout(ans);

    return 0;
}

