using namespace std;

using ll = long long;

int main()
{
    int N, K; cin >> N >> K;
    vector<int> X(N), Y(N);
    for (int i = 0; i < N; i++) {
        cin >> X[i] >> Y[i];
    }
    set<int> sx(X.begin(), X.end());
    set<int> sy(Y.begin(), Y.end());
    map<int,int> x2i, i2x, y2i, i2y;

    {
        int i = 0;
        for (auto it = sx.begin(); it != sx.end(); it++) {
            x2i[*it] = i;
            i2x[i] = *it;
            i++;
        }
    }
    {
        int i = 0;
        for (auto it = sy.begin(); it != sy.end(); it++) {
            y2i[*it] = i;
            i2y[i] = *it;
            i++;
        }
    }
    vector<vector<int>> c(sx.size(), vector<int>(sy.size(), 0));
    for (int i = 0; i < N; i++) {
        c[x2i[X[i]]][y2i[Y[i]]]++;
    }
    vector<vector<int>> s(sx.size(), vector<int>(sy.size(), 0));
    for (int i = 0; i < sx.size(); i++) {
        for (int j = 0; j < sy.size(); j++) {
            s[i][j] = c[i][j];
            if (i > 0) s[i][j] += s[i-1][j];
            if (j > 0) {
                s[i][j] += s[i][j-1];
                if (i > 0) {
                    s[i][j] -= s[i-1][j-1];
                }
            }
        }
    }

    ll ans = LLONG_MAX;
    for (int ixl = 0; ixl < sx.size()-1; ixl++) {
        for (int ixr = ixl+1; ixr < sx.size(); ixr++) {
            for (int iyl = 0; iyl < sy.size()-1; iyl++) {
                for (int iyr = iyl+1; iyr < sy.size(); iyr++) {
                    int pts = s[ixr][iyr];
                    if (ixl > 0) pts -= s[ixl-1][iyr];
                    if (iyl > 0) {
                        pts -= s[ixr][iyl-1];
                        if (ixl > 0) {
                            pts += s[ixl-1][iyl-1];
                        }
                    }
                    if (pts >= K) {
                        int w = i2x[ixr] - i2x[ixl];
                        int h = i2y[iyr] - i2y[iyl];
                        ll a = (ll)w * h;
                        if (a < ans) ans = a;
                    }
                }
            }
        }
    }
    cout << ans << endl;
}

