	std::sort(data_y, data_y + N);

	for (int a = 0; a < N; ++a)
	{

		for (int b = 0; b < N; ++b)
		{
			if (data_x[a] == data[b][0])
			{
				XtoY[a].first = data[b][0];
				XtoY[a].second = data[b][1];
			}
		}

	}


	for (long long int x = 0; x < N; ++x)
	{
		check_s = 0;

		if (x + K > N) break;
		max_height = -9000000000000000000;
		min_height = 9000000000000000000;
		max_width = -9000000000000000000;
		min_width = 9000000000000000000;
		for (long long int a = 0; a < K; ++a)
		{
			max_height = std::max(max_height, XtoY[a + x].second);
			min_height = std::min(min_height, XtoY[a + x].second);
			max_width = std::max(max_width, data_x[x + a]);
			min_width = std::min(min_width, data_x[x + a]);
		}

		min_s = std::min(min_s, (max_width - min_width) * (max_height - min_height));


	}



	for (int a = 0; a < N; ++a)
	{

		for (int b = 0; b < N; ++b)
		{
			if (data_y[a] == data[b][1])
			{
				XtoY[a].first = data[b][0];
				XtoY[a].second = data[b][1];
			}
		}

	}


	for (long long int y = 0; y < N; ++y)
	{
		check_s = 0;

		if (y + K > N) break;
		max_height = -9000000000000000000;
		min_height = 9000000000000000000;
		max_width = -9000000000000000000;
		min_width = 9000000000000000000;

		for (long long int a = 0; a < K; ++a)
		{
			max_height = std::max(max_height, XtoY[a + y].first);
			min_height = std::min(min_height, XtoY[a + y].first);
			max_width = std::max(max_width, data_y[y + a]);
			min_width = std::min(min_width, data_y[y + a]);
		}

		min_s = std::min(min_s, (max_width - min_width) * (max_height - min_height));


	}

	printf("%lld\n", min_s);

	return 0;
}

