    vector<ll> xaray, yaray;

    for (int i = 0; i < n;i++)
    {
        cin >> x[i] >> y[i];

        xaray.push_back(x[i]);
        yaray.push_back(y[i]);
    }

    sort(xaray.begin(), xaray.end());
    sort(yaray.begin(), yaray.end());

    ll ans = (ll)(xaray[n - 1] - xaray[0]) * (yaray[n - 1] - yaray[0]);

    for (int xi = 0; xi < n;xi++)
    {
        for (int xj = xi + 1; xj < n;xj++)
        {
            for (int yi = 0; yi < n;yi++)
            {
                for (int yj = yi + 1; yj < n;yj++)
                {
                    ll l = xaray[xi];
                    ll r = xaray[xj];
                    ll d = xaray[yi];
                    ll u = xaray[yj];

                    // check the number of points in the rectangle.
                    int cnt = 0;
                    for (int i = 0; i < n; i++)
                    {
                        if(l <= x[i] && x[i] <= r && d <= y[i] && y[i] <= u)
                        {
                            cnt++;
                        }
                    }

                    if(cnt >= k)
                    {
                        ans = min(ans, (ll)(r - l) * (u - d));
                    }
                }
            }
        }
    }
    cout << ans << endl;

    return 0;
}

