    vector<pair<ll, ll>> a;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        a.push_back({x, y});
    }
    sort(a.begin(), a.end());

    int enclosed = n;
    while (enclosed != k) {
        // Leftmost, Rightmost, Topmost, Bottommost
        // Index of the point, second one is second place
        ll dir[4][2];
        dir[0][0] = 0;
        dir[0][1] = 1;
        dir[1][0] = a.size() - 1;
        dir[1][1] = a.size() - 2;
        for (int i = 2; i < 4; i++) {
            dir[i][0] = 0;
            dir[i][1] = -1;
        }

        for (int i = 1; i < (int)a.size(); i++) {
            // Topmost  
            if (a[i].second > a[dir[2][0]].second) {
                dir[2][1] = dir[2][0];
                dir[2][0] = i;
            } else if (dir[2][1] == -1 || a[i].second > a[dir[2][1]].second) {
                dir[2][1] = i;
            }

            // Bottom
            if (a[i].second < a[dir[3][0]].second) {
                dir[3][1] = dir[3][0];
                dir[3][0] = i;
            } else if (dir[3][1] == -1 || a[i].second < a[dir[3][1]].second) {
                dir[3][1] = i;
            }
        }

        ll height = abs(a[dir[2][0]].second - a[dir[3][0]].second);
        ll width = abs(a[dir[1][0]].first - a[dir[0][0]].first);

        ll totChanges[50] = { 0 };
        totChanges[dir[0][0]] += abs(a[dir[0][0]].first - a[dir[0][1]].first) * height;
        totChanges[dir[1][0]] += abs(a[dir[1][0]].first - a[dir[1][1]].first) * height;
        totChanges[dir[2][0]] += abs(a[dir[2][0]].second - a[dir[2][1]].second) * width;
        totChanges[dir[3][0]] += abs(a[dir[3][0]].second - a[dir[3][1]].second) * width;

        // Remove overlapping area if it's a corner       
        if (dir[0][0] == dir[2][0]) {
            totChanges[dir[0][0]] -= abs(a[dir[0][0]].first - a[dir[0][1]].first) * abs(a[dir[2][0]].second - a[dir[2][1]].second);
        }
        if (dir[0][0] == dir[3][0]) {
            totChanges[dir[0][0]] -= abs(a[dir[0][0]].first - a[dir[0][1]].first) * abs(a[dir[3][0]].second - a[dir[3][1]].second);
        }
        if (dir[1][0] == dir[2][0]) {
            totChanges[dir[1][0]] -= abs(a[dir[1][0]].first - a[dir[1][1]].first) * abs(a[dir[2][0]].second - a[dir[2][1]].second);

        }
        if (dir[1][0] == dir[3][0]) {
            totChanges[dir[1][0]] -= abs(a[dir[1][0]].first - a[dir[1][1]].first) * abs(a[dir[3][0]].second - a[dir[3][1]].second);
        }

        // for (int i = 0; i < 4; i++) {
            // cout << dir[i][0] << ' ' << dir[i][1] << '\n';
        // }

        int index = 0;
        for (int i = 0; i < (int)a.size(); i++) {
            if (totChanges[i] > totChanges[index]) index = i;
            // cout << i << ' ' << totChanges[i] << '\n';
        }

        a.erase(a.begin() + index);
        sort(a.begin(), a.end());
        enclosed--;
    }

    sort(a.begin(), a.end());
    ll mxheight = -INF, mnheight = INF;
    for (auto& i : a) {
        mxheight = max(i.second, mxheight);
        mnheight = min(i.second, mnheight);
    }

