int main(){
  int N,K;
  VP V;
  cin>>N>>K;
  FOR(i,0,N){
    int x,y;
    cin>>x>>y;
    V.PB(MA(x,y));
  }
  sort(V.begin(),V.end());
  ll ans=INF;
  FOR(i,0,N){
    FOR(j,i+1,N){
      ll ax=V[i].FI,bx=V[j].FI;
      ll ay=V[i].SE,by=V[j].SE;
      if(ay>by){
        swap(ay,by);
      }
      int c=0;
      ll my=ay,ny=by;
      FOR(k,0,N){
        if(ay<=V[k].SE&&V[k].SE<=by){
          c++;
          if(my>V[k].SE){
            my=V[k].SE;
          }
          if(ny<V[k].SE){
            ny=V[k].SE;
          }
        }
      }
      if(c>=K){
        ans=min(ans,abs(ax-bx)*abs(my-ny));
      }
    }
  }
  cout<<ans<<endl;
	return 0;
}

