unsigned long long powInt(long long val){return val * val;}


int main() {
	int n,k;
	cin >> n >> k;
	long long pos[n][2];//後ろが0→x 1ならy
	for(int i = 0;i < n;i++){
		cin >> pos[i][0] >> pos[i][1];
	}
	unsigned long long result = -1;

	for(int i = 0; i < n;i++){//起点を選ぶ
		long long start[2] = { pos[i][0],pos[i][1] };
		unsigned long long distance[n];
		distance[i] = -1;
		for(int j = 0; j < n;j++){//距離を計算しておく
			if(i == j){continue;}
			distance[j] = powInt(abs(pos[j][0] - start[0])) + powInt(abs(pos[j][1] - start[1]));
		}
		uint32_t distRank[k - 1];//posの何番目の要素か
		for(int j = 0; j < k - 1;j++){
			uint32_t min = 0;//posの何番目の要素か
			for(int l = 1; l < n;l++){
				if(distance[l] >= 0 && distance[l] < distance[min]){
					min = l;
				}
			}
			distRank[j] = min;
			distance[min] = -1;
		}
		vector<long long> nearPosX(k);
		vector<long long> nearPosY(k);
		for(int j = 0;j < k - 1;j++){//座標の配列を作る
			nearPosX.at(j) = pos[distRank[j]][0];
			nearPosY.at(j) = pos[distRank[j]][1];
		}
		nearPosX.at(k - 1) = start[0];
		nearPosY.at(k - 1) = start[1];
		sort(nearPosX.begin(),nearPosX.end());
		sort(nearPosY.begin(),nearPosY.end());
		unsigned long long square = (unsigned long long)abs(nearPosX.at(0)- nearPosX.at(k-1)) *
			(unsigned long long)abs(nearPosY.at(0) - nearPosY.at(k-1));
		if(result == -1 || square < result)result = square;
	}
	cout << result << endl;
	return 0;
}

