struct SummedAreaTable{
  static const int SIZE_N = 55;
  static const int SIZE_M = 55;
  int n, m;
  int I[SIZE_N][SIZE_M];
public:
  int table[SIZE_N][SIZE_M];
  SummedAreaTable(int n_, int m_){
    n = n_;
    m = m_;
  }
  void init(){
    for(int y=0; y<n; y++){
      for(int x=0; x<m; x++){
        I[y][x] = table[y][x];
        if(y-1>=0) I[y][x] += I[y-1][x];
        if(x-1>=0) I[y][x] += I[y][x-1];
        if(x-1>=0 && y-1>=0) I[y][x] -= I[y-1][x-1];
      }
    }
  }
  int sum(int y, int x){
    if(y < 0 || x < 0) return 0;
    return I[y][x];
  }
};

