  rep(i, 0, N) { p[i] = Pii(i + 1, p[i].second); }

  sort(p, p + N, [](Pii &a, Pii &b) { return a.second < b.second; });

  rep(i, 0, N) { p[i] = Pii(p[i].first, i + 1); }

  sort(p, p + N);

  sort(praw, praw + N);

  repe(i, 1, N) {
    repe(j, 1, N) {
      int add = 0;
      if (p[i - 1].second == j) {
        add = 1;
      }
      csum[i][j] = csum[i - 1][j] + csum[i][j - 1] - csum[i - 1][j - 1] + add;
    }
  }

  ll ans = numeric_limits<ll>::max();
  rep(i, 0, N) {
    rep(j, 0, N) {
      rep(k, 0, N) {
        rep(l, k + 1, N) {
