          ll left = praw[k].first;
          ll right = praw[l].first;
          if (right < left) continue;

          if (cntincluded(i, j, l, k) >= K) {
            chmin(ans, (top - bottom) * (right - left));
          }
        }
      }
    }
  }

  cout << ans << endl;
}

