	REP(i, x.size()+1){
		REP(j, y.size()+1){
			XY[i][j] = 0;
		}
	}	




	REP(i, x.size()){
		REP(j, y.size()){
			ll tmp = XY[i+1][j] + XY[i][j+1] - XY[i][j];
			if (xy[0].first==x[i] & xy[0].second==y[j]){
