int main(){
    int N,K;
    cin >> N >> K;
    LL x[N],y[N];
    vector<P> vec;
    for(int i=0;i<N;i++){
        cin >> x[i] >> y[i];
        vec.push_back(make_pair(x[i],y[i]));
    }
    sort(x,x+N);
    sort(y,y+N);
    LL ans=LINF;
    for(int i=0;i<N;i++){
        for(int j=N-1;j>=0;j--){
            if(i==j) break;
            for(int u=0;u<N;u++){
                for(int v=N-1;v>=0;v--){
