const ll INF = 4e18;

int main()
{
    int n, k;
    cin >> n >> k;
    ll x[51], y[51];
    P p[51];
    for(int i = 0; i < n; i++){
        cin >> x[i] >> y[i];
        p[i] = P(x[i], y[i]);
    }
    sort(p, p + n);
    ll ans = INF;
    for(int l = 0; l <= n - k; l++){
        ll ls = INF;
        for(int r = l + k - 1; r < n; r++){
            ll dx = p[r].first - p[l].first;
            P plr[51];
            for(int i = 0; i <= r - l; i++){
                plr[i] = P(p[i + l].second, p[i + l].first);
            }
            sort(plr, plr + r - l + 1);
            ll dy = plr[k - 1].first - plr[0].first;
            ll now = dy;
            for(int i = 0; i <= r - l - k; i++){
                now += (plr[k + i].first - plr[k + i - 1].first - plr[i + 1].first + plr[i].first);
                dy = min(dy, now);
            }
            ls = min(ls, dx * dy);
        }
        ans = min(ans, ls);
    }
    cout << ans << endl;
}

