	rep(i,n-k+1) {
		long long dx=P[i+k-1].first-P[i].first;
		long long dy,y_max=-INFL,y_min=INFL;
		rep(j,k) {
			y_max=max(y_max,P[i+j].second);
			y_min=min(y_min,P[i+j].second);
		}
		dy=y_max-y_min;
		ans=min(ans,dx*dy);
	}
	cout<<ans<<endl;
}

