        int x = lower_bound(b.begin(), b.end(), i.first) - b.begin();
        int y = lower_bound(c.begin(), c.end(), i.second) - c.begin();
        zb[x][y]++;
    }
    for (int i = 1; i <= w; i++) {
        for (int j = 1; j <= h; j++) {
            qzh[i][j] = qzh[i][j - 1] + zb[i - 1][j - 1];
        }
    }
    for (int j = 1; j <= h; j++) {
        for (int i = 1; i <= w; i++) {
            qzh[i][j] += qzh[i - 1][j];
        }
    }
    LL ans = numeric_limits<LL>::max();
