bool checkOne(ll x1, ll x2, ll y1, ll y2)
{
	if (x1 > x2) {
		swap(x1, x2);
	}
	if (y1 > y2) {
		swap(y1, y2);
	}

	int incCnt = 0;
	REP(i, N) {
		if ((x1 <= X[i])&&(X[i] <= x2)) {
			if ((y1 <= Y[i])&&(Y[i] <= y2)){
				incCnt++;
			}
		}
	}

	return (K <= incCnt);
}

ull compExec()
{
