class point_t {
public:
  int x;
  int y;

public:
  bool operator<(const point_t& p) const {
    if (x != p.x)
      return x < p.x;

    return y < p.y;
  };
};


int N, K;


long long test(std::vector<point_t> pts)
{
  long long Am = INF;

  std::sort(ALL(pts));

  for (int i = 0; i < N; i ++)
    for (int j = i; j < N; j ++) {
      int size = j + 1 - i;

      if (size >= K) {
        std::vector<point_t> pts2(std::begin(pts) + i, std::begin(pts) + j + 1);

        assert(pts2.size() == size);

        long long w = pts[j].x - pts[i].x;

        for (int k = 0; k < size; k ++)
          for (int l = k; l < size; l ++)
            if (l + 1 - k >= K) {
              auto mp = std::minmax_element(std::begin(pts2) + k,
                                            std::begin(pts2) + l + 1,
                                            [](const point_t& a, const point_t& b) {
                                              if (a.y != b.y)
                                                return a.y < b.y;

                                              return a.x < b.x;
                                            });

              long long h = mp.second->y - mp.first->y;

              Am = std::min(w * h, Am);
            }
      }
    }

  return Am;
}


