  for (int i = 0; i < N; i ++)
    std::cin >> pts[i].x >> pts[i].y;

  long long Am = INF;

  Am = std::min(test(pts), Am);

  for (int i = 0; i < N; i ++)
    std::swap(pts[i].x, pts[i].y);

  Am = std::min(test(pts), Am);

  std::cout << Am << std::endl;

  return 0;
}

