  std::vector<std::pair<int64_t, int64_t>> xy(n);
  std::vector<int64_t> x, y;
  x.reserve(n);
  y.reserve(n);

  for (auto &i : xy) {
    std::cin >> i.first >> i.second;
    x.push_back(i.first);
    y.push_back(i.second);
  }

  std::map<std::pair<int64_t, int64_t>, int> c, c_x, c_y, c_xy;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      const auto x = xy[i].first;
      const auto y = xy[j].second;
      int co = 0, co_x = 0, co_y = 0, co_xy = 0;
      for (int k = 0; k < n; k++) {
        if (xy[k].first <= x && xy[k].second <= y) {
          co++;
        }
        if (xy[k].first < x && xy[k].second <= y) {
          co_x++;
        }
        if (xy[k].first <= x && xy[k].second < y) {
          co_y++;
        }
        if (xy[k].first < x && xy[k].second < y) {
          co_xy++;
        }
      }
      c[{x, y}] = co;
      c_x[{x, y}] = co_x;
      c_y[{x, y}] = co_y;
      c_xy[{x, y}] = co_xy;
    }
  }

  std::sort(x.begin(), x.end());
  std::sort(y.begin(), y.end());
  uint64_t w = static_cast<uint64_t>(x.back() - x.front())
    * static_cast<uint64_t>(y.back() - y.front());

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      for (int k = i + 1; k < n; k++) {
        for (int l = j + 1; l < n; l++) {
          const auto x_min = x[i], x_max = x[k], y_min = y[j], y_max = y[l];
          const auto count = c[{x_max, y_max}] - c_x[{x_min, y_max}]
            - c_y[{x_max, y_min}] + c_xy[{x_min, y_min}];
          if (ks <= count) {
            const uint64_t x_len = x_max - x_min;
            const uint64_t y_len = y_max - y_min;
            w = std::min(w, x_len * y_len);
          }
        }
      }
    }
  }

  std::cout << w << std::endl;
  return 0;
}

