                    int cnt = count(x,i,y,j);
                    if (cnt >= k) {
                        long area = (Mx[i] - Mx[x]) * (My[j] - My[y]);
                        ans = min(ans, area);
                    }
                }
            }
        }
    }
    cout << ans << endl;
}

