ll solve(ll k, multiset<ll>& y) {
  ll ans = INF;
  auto l = y.begin();
  auto r = next(y.begin(), k - 1);
  while (r != y.end()) {
    chmin(ans, *r - *l);
    l++;
    r++;
  }
  return ans;
}

