        Repe(j,i+1,i-k+1){
            temp1 = max( temp1 , d[j].y );
            temp2 = min( temp2 , d[j].y );
        }
        lengy = temp1 - temp2;
        ans = min(ans , lengx * lengy);
    }

    sort(d, d+n, compay);
    Repe(i,n,k-1){
        lengy = d[i].y - d[i-k+1].y;
        temp1 = -INF;
        temp2 = INF * INF;
        Repe(j,i+1,i-k+1){
            temp1 = max( temp1 , d[j].x );
            temp2 = min( temp2 , d[j].x );
        }
        lengx = temp1 - temp2;
        ans = min(ans , lengx * lengy);
    }

    printf ("%lld\n", ans);

    return 0;
}

