        for (int x2 = x1; x2 < n; ++x2) {
            for (int y1 = 0; y1 < n; ++y1) {
                for (int y2 = y1; y2 < n; ++y2) {
                    int lx = xmp[xs[x1]], rx = xmp[xs[x2]];
                    int ly = ymp[ys[y1]], ry = ymp[ys[y2]];
                    int cnt = sum[rx + 1][ry + 1] - sum[rx + 1][ly] - sum[lx][ry + 1] + sum[lx][ly];
                    if (cnt >= k) {
                        ans = min(ans, (xs[x2] - xs[x1]) * (ys[y2] - ys[y1]));
                    }
                }
            }
        }
    }

    cout << ans << endl;
}

