#define ll long long
#define Coordinate pair<ll,ll>
const ll sup = 1000000000000;
const ll inf = -1000000000000;
int N,K;
vector<Coordinate> xy; 



ll right_most(vector<Coordinate> v){
	ll ans = inf;
	for(auto p:v){
		ans = max(ans,p.first);
	}
	return ans;
}

ll left_most(vector<Coordinate> v){
	ll ans = sup;
	for(auto p:v){
		ans = min(ans,p.first);
	}
	return ans;
}

ll top_most(vector<Coordinate> v){
	ll ans = inf;
	for(auto p:v){
		ans = max(ans,p.second);
	}
	return ans;
}

ll down_most(vector<Coordinate> v){
	ll ans = sup;
	for(auto p:v){
		ans = min(ans,p.second);
	}
	return ans;
}

ll area(vector<Coordinate> v){
	ll width, height;
	width = right_most(v) - left_most(v);
	height = top_most(v) - down_most(v);

	return width*height;
}

vector<Coordinate> remove(vector<Coordinate> v, string S){
	int s;
	if(S == "right") s = 1;
	else if(S == "left") s = 2;
	else if(S == "top") s = 3;
	else if(S == "down") s = 4;
	else s = 0;

	switch(s){
		case 1:
			for(int i=0;i<v.size();i++){
				if(v[i].first == right_most(v)){
					v.erase(v.begin()+i);
					return v;
				}
			}
		case 2:
			for(int i=0;i<v.size();i++){
				if(v[i].first == left_most(v)){
					v.erase(v.begin()+i);
					return v;
				}
			}
		case 3:
			for(int i=0;i<v.size();i++){
				if(v[i].second == top_most(v)){
					v.erase(v.begin()+i);
					return v;
				}
			}
		case 4:
		for(int i=0;i<v.size();i++){
				if(v[i].second == down_most(v)){
					v.erase(v.begin()+i);
					return v;
				}
			}
		default:
			return v;
	}
}




int solve(){
	while(xy.size() > K){
		string s = "right";
		if(area(remove(xy,"left")) < area(remove(xy,s))) s = "left";
		if(area(remove(xy,"top")) < area(remove(xy,s))) s = "top";
		if(area(remove(xy,"down")) < area(remove(xy,s))) s = "down";
		xy = remove(xy,s);
	}

	cout << area(xy) << endl;

	return 0;
}

