typedef struct G{
    ll x;
    ll y;
} G;

ll MX = -LINF;
ll MY = -LINF;
ll mx = LINF;
ll my = LINF;

ll calc(vector<G> &g, int n, int k){
    ll MINmens = 8*LINF;
    REP(i,n-k+1) {
        MX = max(g[i].x, g[i+1].x);
        MY = max(g[i].y, g[i+1].y);
        mx = min(g[i].x, g[i+1].x);
        my = min(g[i].y, g[i+1].y);
        for(int j = i+2; j < k; ++j) {
            MX = max(MX, g[j].x);
            MY = max(MY, g[j].y);
            mx = min(mx, g[j].x);
            my = min(my, g[j].y);
            //printf("j = %d, MX = %lld, MY = %lld, mx = %lld, my = %lld\n", j, MX, MY, mx, my);
        }
        ll mens = (MX-mx)*(MY-my);
        //cout << "mens = " << mens << std::endl;
        MINmens = min(MINmens, mens);
    }
    return MINmens;
}


int main(int argc, char const *argv[]) {
