    sort(g.begin(), g.end(), [](const G &A, const G &B) {return A.x < B.x;});
    ll menseki = calc(g, n, k);
    MX = -LINF;
    MY = -LINF;
    mx = LINF;
    my = LINF;
    sort(g.begin(), g.end(), [](const G &A, const G &B) {return A.y < B.y;});
    menseki = min(calc(g, n, k), menseki);
    cout << menseki << std::endl;
    return 0;
}

