void solve(long long N, long long K, std::vector<long long> x, std::vector<long long> y){
    set<LL> ux, uy;
    for(LL i=0; i<N; i++){
        ux.insert(x[i]);
        uy.insert(y[i]);
    }

    LL W=ux.size(), H=uy.size();
    map<LL, LL> kx, ky;
    auto itx=ux.begin(), ity=uy.begin();
    for(int i=0; i<W; i++)kx[*(itx++)]=i+1;
    for(int i=0; i<H; i++)ky[*(ity++)]=i+1;

    vector<vector<LL>> tab(H+1, vector<LL>(W+1, 0));
    for(LL i=0; i<N; i++) {
        tab[kx[x[i]]][ky[y[i]]]++;
    }

    // accumulate
    for(LL i=0; i<=H; i++) {
        for (LL j=1; j <=W; j++) {
            tab[i][j]=tab[i][j-1]+tab[i][j];
        }
    }

    for(LL i=1; i<=H; i++) {
        for (LL j=0; j <=W; j++) {
            tab[i][j]=tab[i-1][j]+tab[i][j];
        }
    }

    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    LL ans = LLONG_MAX;
    for(LL xi1=1; xi1<=W; xi1++){
        for(LL xi2=xi1; xi2<=W; xi2++) {
            for (LL yi1 = 1; yi1 <= H; yi1++) {
                for (LL yi2 = yi1; yi2 <= H; yi2++) {
                    LL k = tab[yi2][xi2]-tab[yi2][xi1-1]-tab[yi1-1][xi2]+tab[yi1-1][xi1-1];
                    if(k < K)continue;
                    LL area = (x[xi2-1]-x[xi1-1])*(y[yi2-1]-y[yi1-1]);
                    ans = min(ans, area);
                }
            }
        }
    }

    cout << ans << endl;
}

