#include <bits/stdc++.h>
using namespace std;
using ll = long long;
ll N, K;
pair<ll, ll> xy[60];
ll x[60];
ll y[60];
const ll inf = ((1ULL << 63) - 1);
ll calc(const ll y1, const ll y2) {
  ll width = INT_MAX;
  ll i1 = 0;
  ll i2 = 0;
  ll ct = 0;
  for (ll ix2 = 1; ix2 < N; ++ix2) {
    const ll rx = x[ix2];
    while (i2 < N && xy[i2].first <= rx) {
      if (xy[i2].second <= y2 && xy[i2].second >= y1) {
        ct++;
      }
      i2++;
    }

    while (i1 < i2 && ct > K) {
      if (xy[i1].second <= y2 && xy[i1].second >= y1) {
        ct--;
      }
      i1++;
    }

    if (ct >= K) {
      width = min(width, (rx - xy[i1].first));
    }
  }
  if (width == INT_MAX) return inf;
  return (y2 - y1) * width;
}

int main() {
  cin >> N >> K;
