int main() {
  cin >> N >> K;
  rep(i, 0, N) {
    cin >> x[i] >> y[i];
    p[i] = Pll(x[i], y[i]);
  }

  sort(p, p + N);

  ll ans = numeric_limits<ll>::max();
  rep(i, 0, N - 1) {
    rep(j, 0, N) {
      ll top = p[i].second;
      ll bottom = p[j].second;
      if (bottom > top) continue;

      ll cnt = 0;
      if (bottom <= p[0].second && p[0].second <= top) {
        ++cnt;
      }

      ll r = 1;
      ll right;
      rep(l, 0, N - 1) {
        auto pl = p[l];
        ll left = pl.first;
        bool left_included = false;
        if (bottom <= pl.second && pl.second <= top) {
          left_included = true;
        }

        while (r < N && cnt < K) {
          auto pr = p[r];
          right = pr.first;
          if (bottom <= pr.second && pr.second <= top) {
            ++cnt;
          }
          ++r;
        }
        if (cnt >= K) {
          chmin(ans, (top - bottom) * (right - left));
        }
        if (left_included) {
          --cnt;
        }
      }
    }
  }

  cout << ans << endl;
}

