          for(int c = 0 ; c < n; c++){
            if(x[c] >= o && x[c] <= p && y[c] >= q && y[c] <= r) count++;
          }
          if(count >= k) ans = min(ans, 1LL * (p - o) * (r - q));
        }
      }
    }
  }
  cout << ans << endl;
}

