            for (int k = j + 1; k < points.size(); ++k) {
                for (int l = k + 1; l < points.size(); ++l) {
                    if (containsKPoints(points, points[i], points[j], points[k], points[l], K)) {
                        long long tmpArea = computeArea(points[i], points[j], points[k], points[l]);
						area = min(area, tmpArea);
                    }
                }
