template<class T> struct SegmentTree {
    using F = function<T(T, T)>;
    int n;          // size
    T id;           // identity element
    vector<T> data; // data
    F f;            // operation
    F g;            // update

    // sz : size, f : operation, g : update, def : identity
    SegmentTree(int sz, F f, F g, T id) : n(1), f(f), g(g), id(id) {
        while (n < sz) n *= 2;
        data = vector<T>(2*n-1, id);
    }

    // v : vector, f : operation, g : update, def : identity
    SegmentTree(vector<T> v, F f, F g, T id) : n(1), f(f), g(g), id(id) {
        while (n < (int)v.size()) n *= 2;
        data = vector<T>(2*n-1, id);
        for (int i = 0; i < (int)v.size(); i++) data[i+n-1] = v[i];
        for (int i = n-2; i >=0; i--) data[i] = f(data[i*2+1], data[i*2+2]);
    }

    // update data[i] to x
    void update (int i, T x) {
        i += n - 1;
        assert(i < data.size());
        data[i] = g(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = f(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    // query [a, b)
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return id;
        if (a <= l && r <= b) return data[k];
        T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return f(vl, vr);
    }

    T operator[] (int i) const { return data[i + n - 1]; }

};

long long solve_x (int n, int k, vector<position>& data) {
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; i++) tie(x[i], y[i]) = data[i];
    auto f1 = [](long long a, long long b) { return max(a, b); };
    auto f2 = [](long long a, long long b) { return min(a, b); };
    auto g  = [](long long a, long long b) { return b; };
    SegmentTree<long long> sg1(y, f1, g, -INF);
    SegmentTree<long long> sg2(y, f2, g, INF);
    long long s = INT64_MAX;
    for (int i = k; i <= n; i++) {
        long long w = abs(x[i-k] - x[i-1]);
        long long u = sg1.query(i-k, i), d = sg2.query(i-k, i);
        long long h = abs(u - d);
        long long surface = w * h;
        if (s > surface) s = surface;
    }
    return s;
}

long long solve_y (int n, int k, vector<position>& data) {
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; i++) tie(x[i], y[i]) = data[i];
    auto f1 = [](long long a, long long b) { return max(a, b); };
    auto f2 = [](long long a, long long b) { return min(a, b); };
    auto g  = [](long long a, long long b) { return b; };
    SegmentTree<long long> sg1(x, f1, g, -INF);
    SegmentTree<long long> sg2(x, f2, g, INF);
    long long s = INT64_MAX;
    for (int i = k; i <= n; i++) {
        long long h = abs(y[i-k] - y[i-1]);
        long long l = sg1.query(i-k, i), r = sg2.query(i-k, i);
        long long w = abs(l - r);
        long long surface = w * h;
        if (s > surface) s = surface;
    }
    return s;
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<position> data(n), dx, dy;
    for (auto& e : data) cin >> e.first >> e.second;
    sort(data.begin(), data.end());

    long long s1 = solve_x(n, k, data);
    for (auto&e : data) swap(e.first, e.second);
    sort(data.begin(), data.end());
    for (auto&e : data) swap(e.first, e.second);
    long long s2 = solve_y(n, k, data);

    long long ans = min(s1, s2);
    assert(ans > 0);
    cout << ans << endl;
    return 0;
}

