const ll MOD = 1000000007;
const ll INF = (ll)1e15;

pll G[60];

int main()
{
    int N, K;
    cin >> N >> K;
    REP(i, N)
    {
        cin >> G[i].first >> G[i].second;
    }
    sort(G, G + N, [](pll a, pll b) { return a.first == b.first ? a.second < b.second : a.first < b.first; });

    ll min = (1e18 * 4);
    REP(f, N)
    {
        FOR(l, N, f)
        {
            if (l - f + 1 < K)
                continue;
            pll ming = pll(INF, INF), maxg = pll(-INF, -INF);
            REP(i, l - f + 1)
            {
                ming.first = std::min(ming.first, G[f + i].first);
                ming.second = std::min(ming.second, G[f + i].second);
                maxg.first = std::max(maxg.first, G[f + i].first);
                maxg.second = std::max(maxg.second, G[f + i].second);
            }
            min = std::min(min, (abs(maxg.first - ming.first) * abs(maxg.second - ming.second)));
        }
    }
    cout << min << endl;
    return 0;
}

