const int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
const ll INF = 9 * 1e18;
const ll MOD = 1e9 + 7;

void solve(long long N, long long K, std::vector<long long> x,
           std::vector<long long> y) {
  ll ans = INF;
  rep(xl, 0, N) {
    rep(xr, 0, N) {
      rep(yu, 0, N) {
        rep(yd, 0, N) {
          ll xld = x[xl];
          ll yld = y[yd];
          ll xru = x[xr];
          ll yru = y[yu];

          if (xld > xru) {
            continue;
          }

          if (yld > yru) {
            continue;
          }

          ll cnt = 0;
          rep(i, 0, N) {
            if (xld <= x[i] && x[i] <= xru && yld <= y[i] && y[i] <= yru) {
              cnt++;
            }
          }

          if (cnt >= K) {
            ans = min(ans, (xld - xru) * (yld - yru));
          }
        }
      }
    }
  }
  print(ans);
}

int main() {
