class D {
	int n, k;
	vvi loc;
	vvi memo;

public:
	D()
	{
		cin >> n >> k;
		loc.resize(n, vi(2, 0));
		memo.resize(n, vi(4, 0));

		REP(i, n)
		{
			int x, y; cin >> x >> y; x--; y--;
			loc[i][0] = x;
			loc[i][1] = y;
		}
	}

	void solve()
	{

		REP(i, n)
			REP(j, n)
		{
			if (i == j)
				continue;

			if (loc[i][0] > loc[j][0])
				++memo[i][0];
			else
				++memo[i][1];

			if (loc[i][1] < loc[j][1])
				++memo[i][3];
			else
				++memo[i][2];
		}

		ll ans{ LLMAX };

		REP(i, n)
			REP(j, n)
		{
			int cnt = n;

			if (loc[i][0] < loc[j][0])
			{
				cnt -= memo[i][0];
				cnt -= memo[j][1];
			}
			else
			{
				cnt -= memo[i][1];
				cnt -= memo[j][0];
			}

			if (loc[i][1] < loc[j][1])
			{
				cnt -= memo[j][3];
				cnt -= memo[i][2];
			}
			else
			{
				cnt -= memo[i][3];
				cnt -= memo[j][2];
			}


			if (k <= cnt)
				chmin(ans, (ll)abs(loc[i][0] - loc[j][0]) * abs(loc[i][1] - loc[j][1]));
		}


		cout << ans << endl;

	}
};


