// 50 * 6, *6は座標圧縮で増える分
#define MAX_N 310

int field[MAX_N][MAX_N];

vector<int> compress(const vector<int>& v, map<int,int>& invert) {
    vector<int> xs;
    for (int i=0; i<v.size(); i++) {
        for (int d=-1; d<=1; d++) {
            xs.push_back(v[i] + d);
        }
    }
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());

    vector<int> res;
    for (int i=0; i<v.size(); i++) {
        int nx = find(xs.begin(), xs.end(), v[i]) - xs.begin();
        res.push_back(nx);
    }

    // 逆引き
    for (int i=0; i<xs.size(); i++) {
        invert[i] = xs[i];
    }
    return res;
}

// (x1,y1)が左上、(x2,y2)が右下
int countPoint(int x1, int y1, int x2, int y2) {
    int res = 0;
    res += field[y2][x2];
    if (x1 > 0) res -= field[y2][x1-1];
    if (y1 > 0) res -= field[y1-1][x2];
    if (x1 > 0 && y1 > 0) res += field[y1-1][x1-1];
    return res;
}

// 左上(x1,y2), 右下(x2,y2) どちらも座標圧縮された座標
long long calcRectangleArea(int x1, int y1, int x2, int y2, const map<int,int>& ix, const map<int,int>& iy) {
    return abs((long long)ix.at(x1) - (long long)ix.at(x2)) * abs((long long)iy.at(y1) - (long long)iy.at(y2));
}

int main() {
    int N, K;
    cin >> N >> K;
    vector<int> x(N), y(N);
    map<int,int> invert_x, invert_y;

    for (int i=0; i<N; i++) {
        cin >> x[i] >> y[i];
    }
    vector<int> cx = compress(x, invert_x);
    vector<int> cy = compress(y, invert_y);

    for (int i=0; i<N; i++) {
        field[cy[i]][cx[i]]++;
    }

    // 累積和
    for (int i=1; i<MAX_N; i++) {
        field[0][i] += field[0][i-1];
        field[i][0] += field[i-1][0];
    }
    for (int i=1; i<MAX_N; i++) {
        for (int j=1; j<MAX_N; j++) {
            field[i][j] += field[i-1][j] + field[i][j-1] - field[i-1][j-1];
        }
    }

    // 適当に長方形を選ぶ
    int W = 0;
    int H = 0;
    for (int i=0; i<cx.size(); i++) W = max(W, cx[i]);
    for (int i=0; i<cy.size(); i++) H = max(H, cy[i]);


    long long sum = LLONG_MAX;
    for (int y1=0; y1<=H; y1++) {
        for (int x1=0; x1<=W; x1++) {
            for (int y2=y1+1; y2<=H; y2++) {
                for (int x2=x1+1; x2<=W; x2++) {
                    int k = countPoint(x1,y1,x2,y2);
                    if (K <= k) {
                        long long s = calcRectangleArea(x1, y1, x2, y2, invert_x, invert_y);
                        sum = min(sum, s);
                    }
                }
            }
        }
    }

    cout << sum << endl;

    return 0;
}

