	long long ans=(long long)(x[n]-x[1])*(y[n]-y[1]);
	for(int i=1;i<=n;i++)
	for(int j=i+1;j<=n;j++)
	for(int p=1;p<=n;p++)
	for(int q=p+1;q<=n;q++)
	{
		int sum=0;
		for(int k=1;k<=n;k++)
		if(e[k].x<=x[j]&&e[k].x>=x[i]&&e[k].y>=y[p]&&e[k].y<=y[q])	sum++;
		if(sum>=k)	ans=min(ans,(long long )(x[j]-x[i])*(y[q]-y[p]));	
	}
	printf("%lld\n",ans);
