struct Point {
    s64 x;
    s64 y;
    Point(s64 xx, s64 yy) : x(xx), y(yy) {}
};

s64 N;
s64 K;

vector<Point> P;
vector<s64> XS;
vector<s64> YS;

s64 area(s64 ximin, s64 ximax, s64 yimin, s64 yimax)
{
    s64 xmin = XS[ximin];
    s64 xmax = XS[ximax];
    s64 ymin = YS[yimin];
    s64 ymax = YS[yimax];

    return (xmax-xmin) * (ymax-ymin);
}

bool is_ok(s64 ximin, s64 ximax, s64 yimin ,s64 yimax)
{
    s64 xmin = XS[ximin];
    s64 xmax = XS[ximax];
    s64 ymin = YS[yimin];
    s64 ymax = YS[yimax];

    return ALL(count_if, P, [xmin, xmax, ymin, ymax](const Point& p) {
        return xmin <= p.x && p.x <= xmax && ymin <= p.y && p.y <= ymax;
    }) >= K;
}

void solve()
{
    ALL(sort, XS);
    ALL(sort, YS);

    s64 ans = INF;

    FOR(ximin, 0, N) {
        FOR(ximax, ximin+1, N) {
            FOR(yimin, 0, N) {
                FOR(yimax, yimin+1, N) {
#ifdef DEBUG
                    DPRINTLN(XS[ximin], XS[ximax], YS[yimin], YS[yimax]);
#endif
                    if(is_ok(ximin, ximax, yimin, yimax)) {
                        chmin(ans, area(ximin, ximax, yimin, yimax));
                    }
                }
            }
