int main() {
    i64 N, K; cin >> N >> K;
    using P = pair<i64, i64>;
    vector<P> point(N);
    map<i64, i64> mpX, mpY;
    REP(i, N) {
        cin >> point[i].first >> point[i].second;
        mpX[point[i].first] = 0;
        mpY[point[i].second] = 0;
    }

    vector<i64> xvals;
    vector<i64> yvals;
    for (auto &p : mpX) {
        p.second = xvals.size();
        xvals.pb(p.first);
    }
    for (auto &p : mpY) {
        p.second = yvals.size();
        yvals.pb(p.first);
    }

    i64 W = xvals.size() * 2;
    i64 H = yvals.size() * 2;
    vector<vector<i64>> G(H, vector<i64>(W, 0));
    REP(i, N) {
        i64 x = mpX[point[i].first] * 2;
        i64 y = mpY[point[i].second] * 2;
        G[x][y] = 1;
    }

    vector<vector<i64>> C(H + 1, vector<i64>(W + 1, 0));
    REP(y, H) {
        REP(x, W) {
            C[y + 1][x + 1] = C[y][x + 1] + C[y + 1][x] - C[y][x] + G[y][x];
        }
    }

    i64 mins = numeric_limits<i64>::max();
    REP(i, N) REP(j, N) REP(k, N) REP(l, N) {
        vector<i64> xs, ys;
        xs.pb(point[i].first);
        ys.pb(point[i].second);

        xs.pb(point[j].first);
        ys.pb(point[j].second);

        xs.pb(point[k].first);
        ys.pb(point[k].second);

        xs.pb(point[l].first);
        ys.pb(point[l].second);

        sort(xs.begin(), xs.end());
        sort(ys.begin(), ys.end());
        i64 minx, miny, maxx, maxy;
        minx = xs[0], miny = ys[0];
        maxx = *(xs.rbegin()), maxy = *(ys.rbegin());

        i64 clx, cly, crx, cry;
        clx = mpX[minx] * 2;
        cly = mpY[miny] * 2;
        crx = mpX[maxx] * 2;
        cry = mpY[maxy] * 2;
        i64 cnt = C[cry + 1][crx + 1] - C[cry + 1][clx] - C[cly][crx + 1] + C[cly][clx];
        if (cnt >= K) {
            i64 dx = abs(maxx - minx);
            i64 dy = abs(maxy - miny);
            if (dx * dy > 0) chmin(mins, dx * dy);
        }
    }

    cout << mins << endl;

    return 0;
}

