using namespace std;

int K, N;
long long x[50], y[50];
long long rect_min;

void ysearch(long long x_low, long long x_high) {
  int cnt;
  long long rect, y_low, y_high;

  for (int i = 0; i < N - 1; i++) {
    for (int j = i + 1; j < N; j++) {
      cnt = 0;
      if (y[i] < y[j]) {
        y_low = y[i];
        y_high = y[j];
      } else {
        y_low = y[j];
        y_high = y[i];
      }

      for (int n = 0; n < N; n++) {
        if (x[n] >= x_low && x[n] <= x_high && y[n] >= y_low && y[n] <= y_high) {
          cnt++;
        }
      }
      if (cnt >= K) {
        rect = (x_high - x_low) * (y_high - y_low);
        if (rect_min == -1 || rect < rect_min) {
          rect_min = rect;
        }
      }
    }
  }
}

void xsearch() {
  int cnt;
  long long x_low, x_high;

  for (int i = 0; i < N - 1; i++) {
    for (int j = i + 1; j < N; j++) {
      cnt = 0;
      if (x[i] < x[j]) {
        x_low = x[i];
        x_high = x[j];
      } else {
        x_low = x[j];
        x_high = x[i];
      }
      for (int n = 0; n < N; n++) {
        if (x[n] >= x_low && x[n] <= x_high) {
          cnt++;
        }
      }
      if (cnt >= K) {
        ysearch(x_low, x_high);
      }
    }
  }
}

int main() {
