signed main() {
  int N, K; 
  cin >> N >> K;

  vector<int> x(N), y(N);
  REP(i, N) cin >> x[i] >> y[i];

  auto ok = [&](int x1, int y1, int x2, int y2){
    int cnt = 0;
    REP(i, N){
      if(IN(x1, x[i], x2+1) && IN(y1, y[i], y2+1)) cnt++;
    }
    return cnt >= K;
  };

  auto sum = [](int x1, int y1, int x2, int y2){
    return (x2-x1)*(y2-y1);
  };


  int ans;
  [&]{
    REP(i, N) FOR(j, i+1, N){
      int x1 = min(x[i], x[j]);
      int x2 = max(x[i], x[j]);
      int y1 = min(y[i], y[j]);
      int y2 = max(y[i], y[j]);
      if(ok(x1, y1, x2, y2)){
        ans = sum(x1, y1, x2, y2);
        return;
      }
    }
  }();
  REP(i, N) FOR(j, i+1, N){
    int x1 = min(x[i], x[j]);
    int x2 = max(x[i], x[j]);
    int y1 = min(y[i], y[j]);
    int y2 = max(y[i], y[j]);
    if(ok(x1, y1, x2, y2)) chmin(ans, sum(x1, y1, x2, y2));
  }
  REP(i, N) FOR(j, i+1, N) FOR(k, j+1, N){
    int x1 = min(min(x[i], x[j]), x[k]);
    int x2 = max(max(x[i], x[j]), x[k]);
    int y1 = min(min(y[i], y[j]), y[k]);
    int y2 = max(max(y[i], y[j]), y[k]);
    if(ok(x1, y1, x2, y2)) chmin(ans, sum(x1, y1, x2, y2));
  }

  cout << ans << "\n";

  return 0;
}

