void _dfs(int g,int cnt){
	if(cnt==K){
		if((rx-lx)*(uy-dy)<ans)ans=(rx-lx)*(uy-dy);
		return;
	}
	//if(N+cnt+1<K+g)return;
	if((rx-lx)*(uy-dy)>ans)return;
	long long r=rx,l=lx,u=uy,d=dy;
	if(p[g].x<lx)lx=p[g].x;
	if(p[g].x>rx)rx=p[g].x;
	if(p[g].y<dy)dy=p[g].y;
	if(p[g].y>uy)uy=p[g].y;
	_dfs(g+1,cnt+1);
	rx=r,lx=l,uy=u,dy=d;
	_dfs(g+1,cnt);
	rx=r,lx=l,uy=u,dy=d;
	return;
}	


