bool lesss(P &x, P &y){return x.second < y.second;}

int main(){
  int n, k, i, j, l;
  long long ans = MAX;
  P p[55];
  scanf("%d%d", &n, &k);
  for(i = 0; i < n; i++) scanf("%d%d", &p[i].first, &p[i].second);
  sort(p, p+n);
  for(i = 0; i+k <= n; i++){
    for(j = k; i + j <= n; j++){
      int p2[55];
      for(l = 0; l < k; l++) p2[l] = p[i+l].second;
      sort(p2, p2+k, lesss);
      int a = p[i].second, b = p[i+j-1].second;
      if(a > b) swap(a, b);
      for(l = 0; l+k <= i+j && p2[l+k-1] < b; l++);
      for(l; l+k <= i+j && p2[l] >= a; l++)
        ans = min(ans, (long long)(b-a)*(p2[l+k-1] - p2[l]));
    }
  }
  printf("%lld\n", ans);
}

