const LL inf = 1e9;
const int maxn = 55;
int N,K;
LL x[maxn],y[maxn];

bool inside(
    const int i, const LL x1, const LL x2, const LL y1, const LL y2)
{ return x1 <= x[i] && x[i] <= x2 && y1 <= y[i] && y[i] <= y2; }

int main()
{
    while (cin >> N >> K) {
        FOR(i,0,N)
            cin >> x[i] >> y[i];
        LL ans = 2*inf*2*inf;
        FOR(i,0,N) FOR(j,i+1,N) FOR(k,0,N) FOR(h,k+1,N) {
            LL X[] = { x[i], x[j] };
            LL Y[] = { y[k], y[h] };
            if (X[0] > X[1])
                swap(X[0],X[1]);
            if (Y[0] > Y[1])
                swap(Y[0],Y[1]);
            const LL A = (X[1]-X[0])*(Y[1]-Y[0]);
            if (0 < A) {
                int cnt = 0;
                FOR(ii,0,N) 
                    cnt += inside(ii,X[0],X[1],Y[0],Y[1]);
                if (cnt >= K)
                    ans = min(ans,A);
            }
        }
        cout << ans << endl;
    }
    return 0;
}

