  vector<pair<int,int> > DATA(N);
  for (int i = 0; i < N; i++)
  {
    cin>>DATA[i].first >> DATA[i].second;
  }
  sort(ALL(DATA));
  int ANS = I64_MAX;
  for (int i = 0; i < N; i++)
  {
    for (int j = i+1; j < N; j++)
    {
      int X1,X2,Y1,Y2;

      for (int k = 0; k < N; k++)
      {
        if((i != k && j != k ) || true)
        {
          X1 = min(min(DATA[i].first,DATA[j].first),DATA[k].first);
          Y1 = min(min(DATA[i].second,DATA[j].second),DATA[k].second);
          X2 = max(max(DATA[i].first,DATA[j].first),DATA[k].first);
          Y2 = max(max(DATA[i].second,DATA[j].second),DATA[k].second);
          int COUNT = 0;
          for (int l = 0; l < N; l++)
          {
            if(DATA[l].first >= X1 && DATA[l].first <= X2 && DATA[l].second >= Y1 && DATA[l].second <= Y2)
            {
              COUNT++;
            }

          }
          if(COUNT >= K)
          {
            chmin(ANS,(X2 - X1)*(Y2 - Y1));

          }

        }
      }

    }


  }
      cout<<ANS<<endl;

  return;
}
