}

void Insert(ll ny){
	seq[++seq[0]] = ny;
	ll p = seq[0];
	while(p > 1LL && seq[p] < seq[p - 1]) swap(seq[p],seq[p - 1]),p--;
}


int GetW(ll seq[]){
	ll res = ma;
	for(ll i = 1;i <= seq[0];i++){
		if(i + m - 1LL > seq[0]) break;
		res = min(res,seq[i + m - 1LL] - seq[i]);
	}
	return res;
}

void Slove(){
	ll ans = ma;
	m = k;
	a[0].x = a[n + 1].x = ma;
	for(ll i = 1;i <= n - m + 1;i++){
		if(a[i].x == a[i - 1].x) continue;
		ll cnt  = 1;
		seq[0] = 0;
		seq[++seq[0]] = a[i].y;
		for(ll j = i + 1;j <= n;j++){
			Insert(a[j].y);
			cnt++;
			if(cnt >= m && a[j].x < a[j + 1].x){
				ll h = a[j].x - a[i].x;
				ll w = GetW(seq);
				ans = min(ans,h * w);
			}
		}
	}
	if(n == 1) ans = 0;
	printf("%lld\n",ans);
}

