    for(int i=0; i<N; i++){
        cin >> X[i] >> Y[i];
        xm[X[i]] = Y[i];
        ym[Y[i]] = X[i];
    }

    sort(X.begin(), X.end());
    sort(Y.begin(), Y.end());
    ll ans = 4 * (1LL<<60);



    for(ll i=0; i<N; i++){
        for(ll j=0; j<N; j++){
            for(ll k=0; k<N; k++){
