#define NodeType int
#define ValueType int
typedef class csNode NODE;
typedef class csPath PATH;
typedef class csEdge EDGE;
class csPath{
public:
	NodeType To;
	ValueType Dist;
	PATH *prev, *next;
};
class csEdge{
public:
	NodeType f, t;
	ValueType d;
};
class csNode{
	PATH *path_tmp;
	int finished;
public:
	csNode(){
		nPath = 0;
	}

	PATH *path_head, *path_tail;
	int nPath;

	inline void Add(NodeType to, ValueType d);
	inline PATH *GetFirstPath(){
		if(nPath == 0) return NULL;
		finished = 0;
		path_tmp = path_head;
		return path_tmp;
	};
	inline PATH *GetNextPath(){
		if(finished) return NULL;
		path_tmp = path_tmp->next;
		if(path_tmp == path_tail) finished = 1;
		return path_tmp;
	}
};

class csTree{
public:
	csTree(){
		nPathPool = 0;
	}

	void Make();

	PATH PathPool[100010*2];
	int nPathPool;
	inline PATH *Get(){
		PATH *ret = &PathPool[nPathPool++];
		ret->prev = ret->next = NULL;
		ret->To = -1;
		return ret;
	}
	int nNode;
	NODE Node[100010];
	int nEdge;
	EDGE Edge[100010];
};
csTree Tree;

inline void csNode::Add(NodeType to, ValueType d){
	PATH *p = Tree.Get();
	p->To = to;
	p->Dist = d;
	if(nPath == 0){
		path_head = path_tail = p;
	}
	else{
		path_tail->next = p;
		p->prev = path_tail;
		path_tail = p;
	}
	++nPath;
}

inline void csTree::Make(){
	csEdge *p;
	NodeType f, t;
	ValueType d;
	fi(nEdge){
		f = Edge[i].f;
		t = Edge[i].t;
		d = Edge[i].d;
