int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, K;
	cin >> N >> K;
	pair<int, int> p[N], p2[N];
	rep(i, 0, N) {
		int x, y;
		cin >> x >> y;
		p[i] = make_pair(x, y);
		p2[i] = make_pair(y, x);
	}

	sort(p, p + N);
	sort(p2, p2 + N);

	ll rsl = 0;
	rep(i, 0, N - K + 1) {
		vector<int> vx, vy, vx2, vy2;
		rep(j, 0, K) {
			vx.push_back(p[i + j].first);
			vy.push_back(p[i + j].second);
			vy2.push_back(p2[i + j].first);
			vx2.push_back(p2[i + j].second);
		}
		vsort(vx);
		vsort(vy);
		vsort(vx2);
		vsort(vy2);
		ll dx = abs(vx[0] - vx[K - 1]);
		ll dy = abs(vy[0] - vy[K - 1]);
		ll tmp = 1ll * dx * dy;
		ll dx2 = abs(vx2[0] - vx2[K - 1]);
		ll dy2 = abs(vy2[0] - vy2[K - 1]);
		ll tmp2 = 1ll * dx2 * dy2;
		if(i == 0) {
			rsl = tmp;
			rsl = min(rsl, tmp2);
		}
		else {
			rsl = min(rsl, min(tmp, tmp2));
		}
	}

	cout << rsl << endl;
}

