int main()
{
  uint64_t N, K;
  cin >> N >> K;

  vector<int64_t> x(N), y(N);
  vector<Point> p(N);

  for (uint64_t n = 0; n < N; ++n) {
    cin >> p[n];

    x[n] = p[n].x;
    y[n] = p[n].y;
  }

  sort(x.begin(), x.end());
  sort(y.begin(), y.end());

  uint64_t s_min = 1e+10;
  for (uint64_t ix = 0; ix < N; ++ix) {
    int64_t x_min = x[ix];
    for (uint64_t iy = 0; iy < N; ++iy) {
      int64_t y_min = y[iy];
      for (uint64_t jx = ix + 1; jx < N; ++jx) {
        int64_t x_max = x[jx];
        for (uint64_t jy = iy + 1; jy < N; ++jy) {
