const ll INF = 1e+19;

ll calc_min_area(const vector<pair<ll, ll>>& positions, int N, int K)
{
    ll area = INF;

    for (int i = 0; i <= N - K; ++i) {
        ll min_x = INF;
        ll min_y = INF;
        ll max_x = -INF;
        ll max_y = -INF;

        for (int j = i; j < i + K; ++j) {
            ll x = positions[j].first;
            ll y = positions[j].second;

            min_x = min(min_x, x);
            max_x = max(max_x, x);
            min_y = min(min_y, y);
            max_y = max(max_y, y);
        }

        area = min(area, (max_x - min_x) * (max_y - min_y));
    }

    return area;
}

int main()
{
    int N, K;
    cin >> N >> K;

    vector<pair<ll, ll>> positions;

    for (int i = 0; i < N; ++i) {
        ll xi, yi;
        cin >> xi >> yi;
        positions.emplace_back(xi, yi);
    }

    sort(begin(positions), end(positions));
    ll ans1 = calc_min_area(positions, N, K);

    sort(begin(positions), end(positions), [](const auto& p1, const auto& p2) {
        return p1.second < p2.second;
    });
    ll ans2 = calc_min_area(positions, N, K);

    cout << min(ans1, ans2) << endl;

    return 0;
}

