points ps;

bool out_of_bound(point& p, point& p1, point& p2){
    if (p.x < p1.x || p2.x < p.x) return true;
    if (p.y < p1.y || p2.y < p.y) return true;
    return false;
}

void solve(){
    rep(i, n){
        ll x, y; in2(x, y);
        ps.pb({x, y});
    }

    answer = INF * 4;
    rep(i1, n - 1) For(i2, i1 + 1, n){
        ll x1 = min({ps[i1].x, ps[i2].x});
        ll x2 = max({ps[i1].x, ps[i2].x});
        ll y1 = min({ps[i1].y, ps[i2].y});
        ll y2 = max({ps[i1].y, ps[i2].y});
        point p1 = {x1, y1}, p2 = {x2, y2};
        ll cnt = 0;
        rep(i, n) if (!out_of_bound(ps[i], p1, p2)) cnt++;
        if (cnt >= k) chmin(answer, (x2 - x1) * (y2 - y1));
    }

    rep(i1, n - 2) For(i2, i1 + 1, n - 1) For(i3, i2 + 1, n){
        ll x1 = min({ps[i1].x, ps[i2].x, ps[i3].x});
        ll x2 = max({ps[i1].x, ps[i2].x, ps[i3].x});
        ll y1 = min({ps[i1].y, ps[i2].y, ps[i3].y});
        ll y2 = max({ps[i1].y, ps[i2].y, ps[i3].y});
        point p1 = {x1, y1}, p2 = {x2, y2};
        ll cnt = 0;
        rep(i, n) if (!out_of_bound(ps[i], p1, p2)) cnt++;
        if (cnt >= k) chmin(answer, (x2 - x1) * (y2 - y1));
    }

    rep(i1, n - 3) For(i2, i1 + 1, n - 2) For(i3, i2 + 1, n - 1) For(i4, i3 + 1, n){
        ll x1 = min({ps[i1].x, ps[i2].x, ps[i3].x, ps[i4].x});
        ll x2 = max({ps[i1].x, ps[i2].x, ps[i3].x, ps[i4].x});
        ll y1 = min({ps[i1].y, ps[i2].y, ps[i3].y, ps[i4].y});
        ll y2 = max({ps[i1].y, ps[i2].y, ps[i3].y, ps[i4].y});
        point p1 = {x1, y1}, p2 = {x2, y2};
        ll cnt = 0;
        rep(i, n) if (!out_of_bound(ps[i], p1, p2)) cnt++;
        if (cnt >= k) chmin(answer, (x2 - x1) * (y2 - y1));
    }

    prl(answer);
}

