void solv() {
	int n, k;
	cin >> n >> k;
	ll x[55], y[55];
	ll sx[55], sy[55];
	for (size_t i = 0; i < n; i++)
	{
		cin >> x[i] >> y[i];
		sx[i] = x[i];
		sy[i] = y[i];
		yp[y[i]].push_back(x[i]);
	}

	sort(sx, sx + n);
	sort(sy, sy + n);
	ll res = -1;
	for (size_t fx = 0; fx < n; fx++)
	{
		for (size_t tx = fx + 1; tx < n; tx++)
		{
			ll lx = sx[fx];
			ll rx = sx[tx];
			int ty = 1;
			int c = 0;
			ll cp[55];

			for (size_t fy = 0; fy < n; fy++)
			{
				ll uy = sy[fy];
				if (fy == 0) {
					cp[0] = calc(lx, rx, uy);
					c += cp[0];
				}
				else {
					c -= cp[fy - 1];
				}
				for (; ty < n; ty++)
				{
					if (fy == ty) ty++;
					ll ly = sy[ty];
					cp[ty] = calc(lx, rx, sy[ty]);
					c += cp[ty];
					if (c >= k) {
						ll val = (rx - lx) * (ly - uy);
						if (res == -1) {
							res = val;
						}
						else res = min(val, res);
						ty++;
						break;
					}
				}
			}
		}
	}
	cout << res << endl;
}

