		LL min_x = xy[i].first;
		LL min_y = xy[i].second;
		for (int j = i; j < i + K; ++j)
		{
			max_x = std::max(max_x, xy[j].first);
			max_y = std::max(max_y, xy[j].second);
			min_x = std::min(min_x, xy[j].first);
			min_y = std::min(min_y, xy[j].second);
		}
		LL res = (max_x - min_x) * (max_y - min_y);
		ans = std::min(ans, res);
	}

	out << ans << std::endl;
	return 0;
}

