void solve() {
	int N, K; cin >> N >> K;
	vector<pii> ps;
	REP(i, N) {
		int x, y; cin >> x >> y;
		ps.emplace_back(x, y);
	}
	sort(ALL(ps));

	int res = inf;
	REP(i, N) {
		priority_queue<int> ysmax;
		int mi = inf;
		FOR(j, i, N) {
			if (ysmax.size() < K) {
				ysmax.push(ps[j].second);
				mi = min(ps[j].second, mi);
				if (ysmax.size() == K) {
					res = (ysmax.top() - mi)*(ps[j].first - ps[i].first);
				}
				continue;
			}
			ysmax.push(ps[j].second);
			mi = min(ps[j].second, mi);
			ysmax.pop();
			res = min(res, (ysmax.top() - mi)*(ps[j].first - ps[i].first));
		}
	}

	cout << res << endl;
}

