void search_ans(long long step, vector<pair<long long, long long> > &b){
    if(step == n + 1){
        long long x1 = 1e9, y1 = 1e9, x2 = -1e9, y2 = -1e9;
        for(int i = 0; i < k; ++i){
            x1 = min(x1, b[i].first);
            y1 = min(y1, b[i].second);
            x2 = max(x2, b[i].first);
            y2 = max(y2, b[i].second);
        }
        long double s = (x2 - x1) * (y2 - y1);
        ans = min(ans, s);
        return;
    }
    if(b.size() == k) search_ans(step + 1, b);
    else if(k - b.size() == n - step){
        b.push_back(a[step]);
        search_ans(step + 1, b);
        b.pop_back();
    }
    else{
        search_ans(step + 1, b);
        b.push_back(a[step]);
        search_ans(step + 1, b);
        b.pop_back();
    }
}


