std::ostream &operator<<(std::ostream &dest, __int128_t value) {
  std::ostream::sentry s(dest);
  if (s) {
    __uint128_t tmp = value < 0 ? -value : value;
    char buffer[128];
    char *d = std::end(buffer);
    do {
      --d;
      *d = "0123456789"[tmp % 10];
      tmp /= 10;
    } while (tmp != 0);
    if (value < 0) {
      --d;
      *d = '-';
    }
    int len = std::end(buffer) - d;
    if (dest.rdbuf()->sputn(d, len) != len) {
      dest.setstate(std::ios_base::badbit);
    }
  }
  return dest;
}

void solve()
{
	long long int N, K;
	cin >> N >> K;
	vector<P> p(N);
	for (int i = 0; i < N; ++i)
	{
		cin >> p[i].first >> p[i].second;
	}
	__int128 ans = 1e36;
	for (int i = 0; i < N; ++i)
	{
		for (int j = 0; j < N; ++j)
		{
			P p1 = p[i];
			P p2 = p[j];
			__int128 xMin = min(p1.first, p2.first);
			__int128 xMax = max(p1.first, p2.first);
			__int128 yMin = min(p1.second, p2.second);
			__int128 yMax = max(p1.second, p2.second);
			long long int cnt = 0;
			for (int k = 0; k < N; ++k)
			{
				if (xMin <= p[k].first && p[k].first <= xMax && yMin <= p[k].second && p[k].second <= yMax)
				{
					++cnt;
				}
			}
			if (cnt >= K)
			{
				ans = min(ans, (xMax - xMin) * (yMax - yMin));
			}
		}
	}
	cout << ans << endl;
}

