using namespace std;

struct BinaryIndexedTree {
  BinaryIndexedTree(size_t h, size_t w) : h(h), w(w), v(h + 1, vector<int>(w + 1, 0)) {}
  BinaryIndexedTree(size_t n) : h(n), w(n), v(n + 1, vector<int>(n + 1, 0)) {}

  size_t h, w;
  vector<vector<int>> v;

  long long sum(int y, int x) {
    long long ret = 0;
    for (int i = y; i; i -= i & -i)
      for (int j = x; j; j -= j & -j) ret += v[i][j];

    return ret;
  }

  long long sum(int y1, int x1, int y2, int x2) {
    return sum(y1, x1) - sum(y1, x2) - sum(y2, x1) + sum(y2, x2);
  }

  void add(int y, int x, int d) {
    for (int i = y; i <= h; i += i & -i)
      for (int j = x; j <= w; j += j & -j) v[i][j] += d;
  }
};

int main() {
