    unordered_map<ll, ll> xmp, ymp;

    for (int i = 0; i < N; i++) {
        cin >> X[i] >> Y[i];
        xmp.insert(make_pair(X[i], Y[i]));
        ymp.insert(make_pair(Y[i], X[i]));
