    for (int i = 0; i < N; i++) {
        for (int j = K - 1; i + j < N; j++) {
            ll lx = X[i];
            ll rx = X[i + j];
            ll uy = max(xmp[X[i]], xmp[X[i + j]]);
            ll ly = min(xmp[X[i]], xmp[X[i + j]]);
            int ui = lower_bound(Y, Y + N, uy) - Y;
            int li = lower_bound(Y, Y + N, ly) - Y;
            int contain = 0;
            for (int k = 0; k < N; k++) {
                ll x = ymp[Y[k]];
                if (Y[k] <= uy && Y[k] >= ly && x >= lx && x <= rx) {
                    contain++;
                }
            }
            //cout << "contain = " << contain << "\n";
            while (contain < K) {
                int tmpui = ui;
                int tmpli = li;
                if (ui < N - 1) {
                    tmpui++;
                    while (true) {
                        ll x = ymp[Y[tmpui]];
                        if (x <= rx && x >= lx) {
                            break;
