                        tmpli--;
                    }
                }
                if (ui < N - 1 && li > 1) {
                    if (ly - Y[tmpli] > Y[tmpui] - uy) {
                        uy = Y[tmpui];
                        ui = tmpui;
                    } else {
                        ly = Y[tmpli];
                        li = tmpli;
                    }
                } else if (ui < N - 1) {
                    uy = Y[tmpui];
                    ui = tmpui;
                } else {
                    ly = Y[tmpli];
                    li = tmpli;
                }
                contain++;
            }
            //cout << "i = " << i << ", j = " << j << ", rx = " << rx << ", lx = " << lx << ", uy = " << uy << ", ly = " << ly << "\n";
            ans = min(ans, (rx - lx) * (uy - ly));
