void solve() {
  int N, K; cin >> N >> K;
  vi32 x(N), y(N);
  rep(i, N) cin >> x[i] >> y[i];

  set<pair<int, int>> se;
  rep(i, N) se.emplace(x[i], y[i]);

  vi32 ox = x, oy = y;
  sort(all(ox)), sort(all(oy));
  vector<vi32> sums(N + 1, vi32(N + 1));
  rep(i, N) rep(j, N) {
    int a = 0;
    int x = ox[i], y = oy[j];
    if (se.count(make_pair(x, y))) a = 1;
    sums[i + 1][j + 1] = sums[i][j + 1] + sums[i + 1][j] - sums[i][j] + a;
  }

  i64 ans = numeric_limits<i64>::max();
  rep(i, N) rep(j, N) reps(k, N) reps(l, N) {
    if (i >= k || j >= l) continue;
    int c = sums[k][l] - sums[i][l] - sums[k][j] + sums[i][j];
    if (c < K) continue;
    amin(ans, (i64) (ox[k - 1] - ox[i]) * (oy[l - 1] - oy[j]));
  }
  cout << ans << '\n';
}

