typedef long long int LL;

const LL inf = 1123456789;
LL N, K;
std::vector<LL>x, y;
std::vector<std::vector<std::pair<std::pair<LL, LL>, std::pair<LL, LL>>>>memo;

// ((minX,minY),(maxX,maxY))
std::pair<std::pair<LL, LL>, std::pair<LL, LL>> dp(LL i, LL j)
{
	if (j == 0) return std::make_pair(std::make_pair(inf, inf), std::make_pair(-inf, -inf));
	if (i < 0) return std::make_pair(std::make_pair(-inf, -inf), std::make_pair(inf, inf));
	auto res1 = dp(i - 1, j - 1);
	res1.first.first = std::min(res1.first.first, x[i]);
	res1.first.second = std::min(res1.first.second, y[i]);
	res1.second.first = std::max(res1.second.first, x[i]);
	res1.second.second = std::max(res1.second.second, y[i]);
	auto res2 = dp(i - 1, j);
	auto s1 = (res1.second.first - res1.first.first)*(res1.second.second - res1.first.second);
	auto s2 = (res2.second.first - res2.first.first)*(res2.second.second - res2.first.second);
	return memo[i][j] = (s1 <= s2 ? res1 : res2);
}

int main()
{
	in >> N >> K;
	x.resize(N); y.resize(N); memo.resize(N);
	rep(i, memo.size()) memo[i].resize(K + 1);
	rep(i, N) in >> x[i] >> y[i];
	auto ans = dp(N - 1, K);
	out << (ans.second.first - ans.first.first)*(ans.second.second - ans.first.second) << std::endl;
	return 0;
}

