bool isCompose(int x1,int y1,int x2,int y2,int k,int n) {
    int num = 0;
    for(int i = 0;i < n;i++) {
        if((X[i] >= x1 && X[i] <= x2 && Y[i] >= y1 && Y[i] <= y2) ||
               (X[i] >= x1 && X[i] <= x2 && Y[i] <= y1 && Y[i] >= y2))
            num++;
    }

    return num >= k;
}

Int Calc(int n,int k)
{
    Int sum = 0;
    sum = ~sum;
    for(int i = 0;i < n - 1;i++) {
        for(int j = i+1;j < n;j++) {
            for(int l = 0;l < n - 1;l ++) {
                for(int m = l+1;m < n;m++) {
                    int x1,x2,y1,y2;
                    x1 = X[i];
                    x2 = X[j];
                    y1 = Y[l];
                    y2 = Y[m];

                    if(isCompose(x1,y1,x2,y2,k,n)) {
                        sum = min(sum,((Int)abs(x2 - x1))*((Int)abs(y2 - y1)));
                    }
                }
            }
        }
    }

    return sum;
}

