typedef long long ll;
typedef pair<ll,ll> pt;
vector<ll> x, y;

bool inside(pt p1, pt p2, pt p) {
  pt a(min(p1.x, p2.x), min(p1.y, p2.y));
  pt b(max(p1.x, p2.x), max(p1.y, p2.y));
  if (p.x < a.x) return false;
  if (p.x > b.x) return false;
  if (p.y < a.y) return false;
  if (p.y > b.y) return false;
  return true;
}

int main() {
  int n, k;
  scanf("%d %d", &n, &k);
  x.resize(n);
  y.resize(n);
  for (int i = 0; i < n; i++) {
    scanf("%lld %lld", &x[i], &y[i]);
  }
  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  ll result = LLONG_MAX;
  for (int i1 = 0; i1 < n; i1++) {
    for (int i2 = i1; i2 < n; i2++) {
      for (int j1 = 0; j1 < n; j1++) {
        for (int j2 = j1; j2 < n; j2++) {
          int counter = 0;
          for (int l = 0; l < n; l++) {
            if (inside(pt(x[i1], y[j1]), pt(x[i2], y[j2]), pt(x[l], y[l]))) {
              counter++;
            }
          }
          if (counter >= k) {
            result = min(result, (x[i2] - x[i1]) * (y[j2] - y[j1]));
          }
        }
      }
    }
  }
  printf("%lld\n", result);
  return 0;
}

