ll solve() {
	int n = ri(), K = ri();
	vpii P(n);
	rep(i, n) {
		P[i].X = ri();
		P[i].Y = ri();
	}
	sort(all(P));

	auto check = [&](ll a) -> bool {
		rep(i, n) {
			// i が左
			ll lef = P[i].X;
			rep(j, n) {
				// j が下
				ll bot = P[j].Y;
				rep(k, i+1, n) {
					ll rig = P[k].X;
					ll w = rig - lef;
					ll h = a / w;
					ll top = bot + h;

					int cnt = 0;
					rep(l, n) {
						if (lef <= P[l].X && P[l].X <= rig) {
							if (bot <= P[l].Y && P[l].Y <= top) {
								cnt++;
							}
						}
					}
					if (cnt >= K) {
						return 1;
					}
				}
			}
		}
		return false;
	};
	ll ng = 0;
	ll ok = 5e18;

	while (abs(ok - ng) > 1) {
		ll mid = (ok + ng) / 2;
		bool c = check(mid);
		//out(ok, ng, mid, c);
		if (c) ok = mid;
		else ng = mid;
	}
	return ok;
}

