    rep(i,n){
        rep(j,i){
            for(int k=j+1;k<=i;k++){
                Pair p=(Pair){min(x[j],x[k]),max(x[j],x[k]),min(y[j],y[k]),max(y[j],y[k])};
                if(area(p)<area(dp[i+1][2])) dp[i+1][2]=p;
            }
        }
    }
