    for (int i = 0; i < N; i++) {
        std::cin >> X[i] >> Y[i];

        int dx[] = {-1, -1, 0, +1, +1};
        int dy[] = {-1, +1, 0, -1, +1};

        for (int j = 0; j < 5; j++) {
            int nx = X[i] + dx[j];
            int ny = Y[i] + dy[j];
            ps.emplace_back(nx, ny);
        }
    }

    int n = ps.size();
    int64 min_area = LLONG_MAX;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int xi = ps[i].first, yi = ps[i].second;
            int xj = ps[j].first, yj = ps[j].second;

            if (xi == xj || yi == yj) {
                continue;
            }

            if (xi > xj) std::swap(xi, xj);
            if (yi > yj) std::swap(yi, yj);

            int in_count = 0;
