                if (xi <= X[k] && X[k] <= xj && yi <= Y[k] && Y[k] <= yj) {
                    in_count++;
                }
            }

            if (in_count >= K) {
                min_area = std::min(min_area, (int64)(yj - yi) * (xj - xi));
            }
        }
    }

    std::cout << min_area << std::endl;
