    void BSort(int n)
    {
        int ok = 0;
        while (!ok) {
            ok = 1;
            for (int i = 1; i < n; ++i)
            if (x[i] > x[i + 1]) {
                swap(x[i], x[i + 1]);
                swap(y[i], y[i + 1]);
                ok = 0;
            }
        }
    }

    int min_3(int a, int b, int c, int d)
    {
        return min(min(min(a, b), c), d);
    }

    int max_3(int a, int b, int c, int d)
    {
        return max(max(max(a, b), c), d);
    }

    int ind_x(int border, int i, int j, int o, int l)
    {
        if (border == x[i])
            return i;
        if (border == x[j])
            return j;
        if (border == x[o])
            return o;
        if (border == x[l])
            return l;
        return 0;
    }

    int ind_y(int border, int i, int j, int o, int l)
    {
        if (border == y[i])
            return i;
        if (border == y[j])
            return j;
        if (border == y[o])
            return o;
        if (border == y[l])
            return l;
        return 0;
    }

    int main()
    {
        int n, k, first, cell_cnt[51][51] = {0};
        long long small_area, area;

        cin >> n >> k;
        for (int i = 1; i <= n; ++i)
            cin >> x[i] >> y[i];
        BSort(n);

        for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            for (int o = 1; o <= n; ++o)
                if (x[o] <= x[i] && y[o] <= y[j])
                    cell_cnt[i][j]++;
        }

        long long left_m, down_m, right_m, up_m;
        int left_i, down_i, right_i, up_i;
        first = 1;
        for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
        for (int o = 1; o <= n; ++o)
        for (int l = 1; l <= n; ++l) {
            left_m = min_3(x[i], x[j], x[o], x[l]);
            left_i = ind_x(left_m, i, j, o, l);

            down_m = min_3(y[i], y[j], y[o], y[l]);
            down_i = ind_y(down_m, i, j, o, l);

            right_m = max_3(x[i], x[j], x[o], x[l]);
            right_i = ind_x(right_m, i, j, o, l);

            up_m = max_3(y[i], y[j], y[o], y[l]);
            up_i = ind_y(up_m, i, j, o, l);

            if (cell_cnt[right_i][up_i] - cell_cnt[left_i - 1][up_i] - cell_cnt[right_i][down_i] + cell_cnt[left_i - 1][down_i] + 1 >= k) {
                area = (right_m - left_m) * (up_m - down_m);
                if (first) {
                    small_area = area;
                    first = 0;
                }
                else
                    small_area = min(small_area, area);
            }
        }
        cout << small_area;
        return 0;
    }

