int N, K;
ll x[55], y[55];

int countRectInnerPoint(ll minX, ll minY, ll maxX, ll maxY)
{
    int cnt = 0;
    rep(i, N) {
        if (x[i] >= minX
                && x[i] <= maxX
                && y[i] >= minY
                && y[i] <= maxY) {

            ++cnt;
        }
    }
    return cnt;
}


signed main()
{
    cin.tie(0), ios::sync_with_stdio(false);

    ll minX, minY, maxX, maxY;

    cin >> N >> K;

    rep(i, N) {
        cin >> x[i] >> y[i];
    }

    ll ans = LINF;

    // i,k = x   j,l = y
    for (int i=0; i<N; ++i) {
        for (int j=0; j<N; ++j) {
            for (int k=i+1; k<N; ++k) {
                for (int l=j+1; l<N; ++l) {
                    minX = min(x[i], x[k]);
                    maxX = max(x[i], x[k]);
                    minY = min(y[j], y[l]);
                    maxY = max(y[j], y[l]);
                    if (countRectInnerPoint(minX, minY, maxX, maxY) >= K) {
                        ans = min(ans, (maxX-minX) * (maxY - minY));
                    }
                }
            }
        }
    }

    outl(ans);

}

