void solve(ll N, ll K, vector<ll> x, vector<ll> y) {
  ll res = 5e18;
  REP(i,N) REP(j,N) {
    ll top = y[i], bot = y[j];
    if (top > bot) continue;
    vector<ll> z;
    REP(k,N) if (top <= y[k] && y[k] <= bot) z.push_back(x[k]);
    sort(ALL(z));
    REP(k,int(z.size())-K+1) {
      chmin(res, (bot - top) * (z[k+K-1] - z[k]));
    }
  }
  cout << res << endl;
}

