          ll ly = min({y[i], y[j], y[k]});
          ll lx = min({x[i], x[j], x[k]});
          ll ry = max({y[i], y[j], y[k]});
          ll rx = max({x[i], x[j], x[k]});
          ll s = max(ry - ly, 1ll) * max(rx - lx, 1ll);
          chmin(ans, s);
        }
      }
    }
    cout << ans << endl;
    return 0;
  }
  REP(i, ch) {
    REP(j, cw) {
      cum[i+1][j+1] = cum[i+1][j] + cum[i][j+1] - cum[i][j] + mp[{i, j}];
    }
  }
  ll ans = linf * 5;
  REP(i, n) {
    REP_FROM(j,  i+1, n) {
      REP_FROM(k, j+1, n) {
        REP_FROM(l, k+1, n) {
          ll ly = min({y[i], y[j], y[k], y[l]});
          ll lx = min({x[i], x[j], x[k], x[l]});
          ll ry = max({y[i], y[j], y[k], y[l]});
          ll rx = max({x[i], x[j], x[k], x[l]});
