int n, k;

vector<pair<int, int>> points;

long long const inf = LLONG_MAX;

long long getInterior(int x1, int y1, int x2, int y2) {

	long long leftx = min(x1, x2);
	long long lefty = min(y1, y2);
	long long rightx = max(x1, x2);
	long long righty = max(y1, y2);

	int cnt = 0;
	for (int i = 0; i < n; ++i) {
		int x = points[i].first;
		int y = points[i].second;
		if (x >= leftx && x <= rightx && y >= lefty && y <= righty)
			++cnt;
	}

	if (cnt >= k) {
		return (rightx - leftx) * (righty - lefty);
	} else
		return LLONG_MAX; 

}

int main() {
	cin.tie(nullptr);
	ios_base::sync_with_stdio(false);

	cin >> n >> k;

	points.resize(n);

	for (int i = 0; i < n; ++i) {
		cin >> points[i].first >> points[i].second;
	}

	long long answer = inf;

	vector<pair<int, int>> iterate(n * n);
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			iterate[i * n + j] = make_pair(points[i].first, points[j].second);
		}
	}

	for (int left = 0; left < n * n; ++left) {
		for (int right = 0; right < n * n; ++right) {
			answer = min(answer, getInterior(iterate[left].first, iterate[left].second, iterate[right].first, iterate[right].second));
		}
	}

	cout << answer << endl;

	return 0;
}

