using i64=int64_t;

void solve(){
    int N,K;
    cin >> N >> K;

    vector<i64> x(N),y(N),xs,ys;
    rep(i,0,N){
        cin >> x[i] >> y[i];
        xs.push_back(x[i]);
        ys.push_back(y[i]);
    }

    sort(begin(xs),end(xs));
    sort(begin(ys),end(ys));

    auto count_points=[&](i64 x1,i64 y1,i64 x2,i64 y2){
        int res=0;
        rep(i,0,N) if(x1<=x[i] and x[i]<=x2 and y1<=y[i] and y[i]<=y2) ++res;
        return res;
    };

    i64 ans=inf64;
    rep(i,0,N) rep(j,i+1,N) rep(k,0,N){
        int lb=k-1,ub=N;
        while(ub-lb>1){
            int mid=(lb+ub)/2;
            if(count_points(xs[i],ys[k],xs[j],ys[mid])>=K) ub=mid;
            else lb=mid;
        }
        if(ub<N) ans=min(ans,(xs[j]-xs[i])*(ys[ub]-ys[k]));
    }

    cout << ans << endl;
}

