ll N, K;
pair<ll, ll> xy[60];
ll x[60];
ll y[60];
const ll inf = ((1ULL << 63) - 1);
ll calc(const ll y1, const ll y2) {
  ll ret = inf;
  assert(y1 < y2);
  vector<ll> p;
  for(int i = 0; i < N; ++i) {
    if (xy[i].second <= y2 && xy[i].second >= y1) p.push_back(xy[i].first);
  }
  sort(p.begin(), p.end());
  if (p.size() < K) return inf;
  for(int i = 0; i + K - 1 < p.size(); ++i) {
    ret = min(ret, (y2 - y1) * (p[i + K - 1] - p[i]));

  }

  return ret;
}

int main() {
  cin >> N >> K;
  for (ll i = 0; i < N; ++i) {
    ll a, b;
    cin >> a >> b;
    xy[i] = {a, b};
    x[i] = a;
    y[i] = b;
  }

  sort(xy, xy + N);
  sort(x, x + N);
  sort(y, y + N);
  ll ret = inf;
  for (ll iy1 = 0; iy1 < N; ++iy1) {
    for (ll iy2 = iy1 + 1; iy2 < N; ++iy2) {
      ret = min(ret, calc(y[iy1], y[iy2]));
    }
  }
  cout << ret << endl;
}

