void solve() {
  int N, K; cin >> N >> K;
  vi32 x(N), y(N);
  rep(i, N) cin >> x[i] >> y[i];

  vi32 ox, oy;
  rep(i, N) ox.push_back(x[i]);
  rep(i, N) oy.push_back(y[i]);
  sort(all(ox)), sort(all(oy));

  vector<vi32> sums(N + 1, vi32(N + 1));
  {
    set<pair<int, int>> s;
    rep(i, N) s.emplace(x[i], y[i]);
    rep(i, N) rep(j, N) {
      if (s.count(make_pair(ox[i], oy[j]))) sums[i + 1][j + 1] = 1;
    }
    rep(i, N + 1) rep(j, N) sums[i][j + 1] += sums[i][j];
    rep(i, N) rep(j, N + 1) sums[i + 1][j] += sums[i][j];
  }

  i64 ans = 5e18;

  rep(xl, N) rep(xr, N) rep(yl, N) rep(yr, N) {
    if (xl >= xr || yl >= yr) continue;
    int c = sums[xr + 1][yr + 1] - sums[xr + 1][yl] - sums[xl][yr + 1] + sums[xl][yl];
    if (c < K) continue;
    amin(ans, (i64) (ox[xr] - ox[xl]) * (oy[yr] - oy[yl]));
  }
  cout << ans << '\n';
}

