	rep(i, N) x2i[i2x[i]] = i;
	rep(i, N) y2i[i2y[i]] = i;
	g = vvi(N + 1, vi(N + 1));
	rep(i, N) g[x2i[x[i]] + 1][y2i[y[i]] + 1]++;
	rep2(i, 1, N + 1) rep2(j, 1, N + 1) g[i][j] += g[i][j - 1];
	rep2(i, 1, N + 1) rep2(j, 1, N + 1) g[i][j] += g[i - 1][j];

	ll ans = INF;
	rep(il, N) rep(jd, N) rep2(ir, il + 1, N + 1) {
		if (minsq(il, jd, ir) == INF) continue;
		chmin(ans, minsq(il, jd, ir));
	}
	cout << ans << endl;
}

