    // 簡単のため、要素数を２のべき乗に
    n = 1;
    while (n < n_) n *= 2;

    // すべての値をINT_MAXに
    for(int i=0; i<2 * n - 1; i++) dat[i] = INT_MAX;
  }

  // (0からかぞえて)k番目の値をaに変更
  void update (int k, int a) {
    // 葉の節点
    k += n - 1;
    dat[k] = a;
    // 登りながら更新
    while(k > 0) {
      k = (k - 1) / 2;
      dat[k] = min (dat [k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  // [a, b]の最小値を求める
  // 外からはquery(a, b, 0, 0, n)として呼ぶ
  int query (int a, int b, int k, int l, int r) {
    // [a, b)と[l, r)が交差しなければ INT_MAX
    if(r <= a || b <= l) return INT_MAX;

    // [a, b)と[l, r)を完全に含んでいれば、この節点の値
    if(a <= l && r <= b) return dat[k];
    else {
      // そうでなければ、2つの子の最小値
      int vl = query(a, b, k * 2 + 1, l, (l+r)/2-1);
      int vr = query(a, b, k * 2 + 2, (l+r)/2, r);
      return min (vl, vr);
    }
  }

  int query(int a, int b, int n) {
    return query(a, b, 0, 0, n);
  }
};

class SEGTREE_MAX {
  static const int MAX_N = 10000;

  // セグ木をもつグローバル配列
  int n, dat[2 * MAX_N - 1];

public:

  // 初期化
  void init (int n_) {
    // 簡単のため、要素数を２のべき乗に
    n = 1;
    while (n < n_) n *= 2;

    // すべての値をINT_MAXに
    for(int i=0; i<2 * n - 1; i++) dat[i] = 0;
  }

  // (0からかぞえて)k番目の値をaに変更
  void update (int k, int a) {
    // 葉の節点
    k += n - 1;
    dat[k] = a;
    // 登りながら更新
    while(k > 0) {
      k = (k - 1) / 2;
      dat[k] = max (dat [k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  // [a, b]の最小値を求める
  // 外からはquery(a, b, 0, 0, n)として呼ぶ
  int query (int a, int b, int k, int l, int r) {
    // [a, b)と[l, r)が交差しなければ INT_MAX
    if(r <= a || b <= l) return 0;

    // [a, b)と[l, r)を完全に含んでいれば、この節点の値
    if(a <= l && r <= b) return dat[k];
    else {
      // そうでなければ、2つの子の最小値
      int vl = query(a, b, k * 2 + 1, l, (l+r)/2);
      int vr = query(a, b, k * 2 + 2, (l+r)/2, r);
      return max (vl, vr);
    }
  }

  int query(int a, int b, int n) {
    return query(a, b, 0, 0, n);
  }
};

