  REP(i, n) cin >> a[i].first >> a[i].second;
  sort(a.begin(), a.end());

  SEGTREE b;
  SEGTREE_MAX c;
  b.init(n);
  c.init(n);
  REP(i, n) {
    b.update(i, a[i].second);
    c.update(i, a[i].second);
  }

  int mi = INT_MAX;
  REP(i, n-k+1) {
    mi = min(mi, (a[i+k-1].first - a[i].first) * (c.query(i, i+k, n) - b.query(i, i+k, n)));
  }

