void solve() {
    int n, k;
    cin >> n >> k;
    vector<pair<ll, ll>> a(n);
    for (int i=0; i<n; i++) {
        cin >> a.at(i).first >> a.at(i).second;
    }
    ll sumx = 0, sumy = 0;
    for (int i=0; i<n; i++) {
        sumx += a.at(i).first;
        sumy += a.at(i).second;
    }
    while (n > k) {
        double cx = (double)sumx / n, cy = (double)sumy / n;
        int rm = 0;
        double dis = abs(cx - a.at(0).first) + abs(cy - a.at(0).second);
        for (int i=1; i<n; i++) {
            if (chmax(dis, abs(cx - a.at(i).first) + abs(cy - a.at(i).second))) {
                rm = i;
            }
        }
        sumx -= a.at(rm).first;
        sumy -= a.at(rm).second;
        a.erase(a.begin() + rm);
        n--;
    }
    ll xmin = INF, xmax = -INF, ymin = INF, ymax = -INF;
    for (int i=0; i<n; i++) {
        chmin(xmin, a.at(i).first);
        chmax(xmax, a.at(i).first);
        chmin(ymin, a.at(i).second);
        chmax(ymax, a.at(i).second);
    }
    cout << (xmax - xmin) * (ymax - ymin) << '\n';
}

