    vector<pair<ll,ll>> points(n);
    for(auto &it : points)
        cin>>it.first>>it.second;
    sort(points.begin(),points.end(),comp);
    int ymin=0;
    int ymax=n-1;
    ull area=4999999996900000002;
    while(ymax>=ymin){
        vector<pair<ll,ll>> px(ymax-ymin+1);
        for(int i=0;i<px.size();++i)
            px[i]=points[i+ymin];
