    v[i][1]=y;
  }
  ll bit = (1LL<<2)-1LL;
  vector<vector<ll>> xp,yp;
  for(;bit<(1LL<<N);bit = next_combination(bit)){
    vector<ll> xx;
    for(ll i = 0LL; i < N; i++){
      if(bit&(1LL<<i)) xx.push_back(X[i]);
    }
    sort(xx.begin(),xx.end());
    xp.push_back(xx);
  }
  bit = (1LL<<2)-1;
  for(;bit<(1LL<<N);bit = next_combination(bit)){
    vector<ll> yy;
    for(ll i = 0LL; i < N; i++){
      if(bit&(1LL<<i)) yy.push_back(Y[i]);
    }
