void solve(int n, int k, vector< pair<long long, long long> > xy, vector< pair<long long, long long> > xy2) {
    sort(xy.begin(), xy.end());
    long long ret = 0;
    for (int i = 0; i < n-k+1; i++) {
        long long ymax = xy[i].second;
        long long ymin = xy[i].second;
        for (int j = 0; j < k; j++) {
            if (xy[i+j].second < ymin) {
                ymin = xy[i+j].second;
            }
            if (xy[i+j].second > ymax) {
                ymax = xy[i+j].second;
            }
        }
        if (ret == 0) {
            ret = (long long)(ymax - ymin) * (xy[i+k-1].first - xy[i].first);
        }
        if ((long long)(ymax - ymin) * (xy[i+k-1].first - xy[i].first) < ret) {
            ret = (long long)(ymax - ymin) * (xy[i+k-1].first - xy[i].first);
        }
    }
    sort(xy2.begin(), xy2.end());
    for (int i = 0; i < n-k+1; i++) {
        long long ymax = xy2[i].second;
        long long ymin = xy2[i].second;
        for (int j = 0; j < k; j++) {
            if (xy2[i+j].second < ymin) {
                ymin = xy2[i+j].second;
            }
            if (xy2[i+j].second > ymax) {
                ymax = xy2[i+j].second;
            }
        }
        if ((long long)(ymax - ymin) * (xy2[i+k-1].first - xy2[i].first) < ret) {
            ret = (long long)(ymax - ymin) * (xy2[i+k-1].first - xy2[i].first);
        }
    }

    std::cout << ret << std::endl;
}

