ll count_included_points(ll x1, ll y1, ll x2, ll y2) {
    ll res = 0;
    for (ll i = 0; i < N; i++) {
        ll x = points[i].first;
        ll y = points[i].second;
        if (x1 <= x && x <= x2 && y1 <= y && y <= y2) {
            res++;
        }
    }

    return res;
}

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> K;
