struct MyMain {
	int N = in;
	int K = in;
	pints P = in(N);

	void Run() {
		ints xs(N);
		ints ys(N);
		REP(i, N) {
			xs(i) = P(i).x;
			ys(i) = P(i).y;
		}
		Compress compX(xs);
		Compress compY(ys);

		Imos2 imos(N, N);
		REP(i, N) {
			int cx = compX.OrgIndex2Comp(i);
			int cy = compY.OrgIndex2Comp(i);
			imos.Add(cx, cy, 1);
		}
		imos.Calc();

		int ans = INF;
		REP(y1, N) {
			REP(x1, N) {
				FOR(y2, y1 + 1, N) {
					FOR(x2, x1 + 1, N) {
						int left = x1;
						int right = x2;
						int top = y1;
						int bottom = y2;
						if (right < left) {
							swap(left, right);
						}
						if (bottom < top) {
							swap(top, bottom);
						}
						right++;
						bottom++;

						int cnt = imos.Get(left, top, right, bottom);
						if (cnt < K) {
							continue;
						}

						int orgX1 = compX.Comp2OrgValue(x1);
						int orgY1 = compY.Comp2OrgValue(y1);
						int orgX2 = compX.Comp2OrgValue(x2);
						int orgY2 = compY.Comp2OrgValue(y2);

						int area = abs(orgX1 - orgX2) * abs(orgY1 - orgY2);
						chmin(ans, area);
					}
				}
			}
		}

		out << ans;
	}
};

