  long long ans = (a[n-1]-a[0])*(b[n-1]-b[0]);

  for(int xi = 0; xi < n ; xi++){
    for(int xj = xi + 1; xj < n; xj++){
      for(int yi = 0 ; yi < n ; yi++){
        for(int yj = yi + 1; yj < n ; yj++){
          int count = 0;
          long long o = a[xi];
          long long p = a[xj];
          long long q = b[yi];
          long long r = b[yj];
          for(int c = 0 ; c < n; c++){
            if(x[c] >= o && x[c] <= p && y[c] >= q && y[c] <= r) count++;
          }
          if(count >= k) ans = min(ans, (p - o) * (r - q));
        }
      }
    }
  }
  cout << ans << endl;
}

