                u.push_back(y);
            }
            sort(all(u));
            for(int pos = 0; pos+k-1 < size(u); pos++) {
                chmin(res, (r-l)*(ull)(u[pos+k-1] - u[pos]));
            }
        }
    }
    cout << res << endl;
    return 0;
}

