vector<pair<long long, pair<long long, int>>> xp, yp;

int main(){

    cin.sync_with_stdio(0); cin.tie(0); cout.tie(0);

    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n, k;
    cin >> n >> k;

    for(int i = 0; i < n; ++i){
        long long a, b;
        cin >> a >> b;
        xp.push_back(make_pair(a, make_pair(b, i)));
        yp.push_back(make_pair(b, make_pair(a, i)));
    }

    sort(xp.begin(), xp.end());
    sort(yp.begin(), yp.end());

    long long area = -1;

    for(int xl = 0; xl < n; ++xl){

        long long lx = 1e10, rx = -1e10, LY = 1e10, RY = -1e10;
        bitset<51> taken;
        taken.reset();

        for(int xr = xl; xr < n; ++xr){

            lx = min(lx, xp[xr].first);
            rx = max(rx, xp[xr].first);
            LY = min(LY, xp[xr].second.first);
            RY = max(RY, xp[xr].second.first);

            taken[xp[xr].second.second] = 1;

            bitset<51> ytaken;

            for(int yl = 0; yl < n; ++yl){

                ytaken.reset();

                long long LX = lx, RX = rx, ly = LY, ry = RY;

                for(int yr = yl; yr < n; ++yr){

                    ly = min(ly, yp[yr].first);
                    ry = max(ry, yp[yr].first);
                    LX = min(LX, yp[yr].second.first);
                    RX = max(RX, yp[yr].second.first);

                    ytaken[yp[yr].second.second] = 1;

                    if((ytaken | taken).count() < k)
                        continue;

                    if(area == -1){
                        area = (RX - LX) * (ry - ly);
                    } else {
                        area = min(area, (RX - LX) * (ry - ly));
                    }
                }
            }
        }
    }

    cout << area;

    return 0;
}

