	int64_t res = numeric_limits<int64_t>::max() ;
	for (int32_t start = 0; start + K - 1 < N; start++) {
		int32_t minX = p[start].first;
		int32_t maxX = p[start + K - 1].first;
		int32_t minY = p[start].second;
		int32_t maxY = p[start].second;
