ll check(const deque<pii> &que) {
  vll x, y;
  REP(i, que.size()) {
    x.push_back(que[i].first);
    y.push_back(que[i].second);
  }
  sort(ALL(x));
  sort(ALL(y));
  ll ret = abs(x[0] - x.back()) * abs(y[0] - y.back());
  return ret;
}

void solve(long long N, long long K, vector<long long> x, vector<long long> y) {
  std::vector<pii> v;
  REP(i, N) { v.push_back(pii(x[i], y[i])); }

  sort(ALL(v));

  deque<pii> que;

  REP(i, K) { que.push_back(v[i]); }
  ll ans = check(que);

  for (int i = K; i < N; ++i) {
    que.pop_front();
    que.push_back(v[i]);
    ans = min(ans, check(que));
  }

  cout << ans << endl;
}

