long long calc(int ix, int jx, int iy, int jy) {
	long long x1 = min(xs[ix], xs[jx]);
	long long x2 = max(xs[ix], xs[jx]);
	long long y1 = min(ys[iy], ys[jy]);
	long long y2 = max(ys[iy], ys[jy]);

	int n_inside = 0;
	for (int l = 0; l < n; l++) {
		if (x1 <= xs[l] && xs[l] <= x2 &&
			y1 <= ys[l] && ys[l] <= y2)
		{
			n_inside++;
		}
	}

	if (n_inside < k) {
		return inf;
	}

	return (x2 - x1) * (y2 - y1);
}

