    vector<ll> X(N), Y(N);
    REP(i,N){
        cin >> X[i] >> Y[i];
    }
    vector<ll> CX = compress(X);
    vector<ll> CY = compress(Y);

    ll ans = LLONG_MAX;
    vector<vector<int>> G(N+1,vector<int>(N+1,0));
    REP(i,N){
        G[X[i]+1][Y[i]+1] ++;
    }

    REP(i,N){
        REP(j,N+1){
            G[i+1][j] += G[i][j];
        }
    }
    REP(i,N+1){
        REP(j,N){
            G[i][j+1] += G[i][j];
        }
