			MAXY = max(MAXY, p[i + j].second);
			MINY = min(MINY, p[i + j].second);
		}
		ans = min((MAXX - MINX)*(MAXY - MINY), ans);
	}
	rep(i, n) {
		swap(p[i].first, p[i].second);
	}
	sort(p, p + n);
	rep(i, n - k + 1) {
		ll MINX = INF, MINY = INF, MAXX = 0, MAXY = 0;
		rep(j, k) {
			MAXX = max(MAXX, p[i + j].first);
			MINX = min(MINX, p[i + j].first);
			MAXY = max(MAXY, p[i + j].second);
			MINY = min(MINY, p[i + j].second);
		}
		ans = min((MAXX - MINX)*(MAXY - MINY), ans);
	}
	cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

struct BIT {
  BIT() {}
  BIT(int n) : n(n + 1), v(n + 1, vector<int>(n + 1, 0)) {}

  int n;
  vector<vector<int>> v;

  long long sum(int y, int x) {
    long long ret = 0;
    for (int i = y; i; i -= i & -i) {
      for (int j = x; j; j -= j & -j) {
        ret += v[i][j];
      }
    }

    return ret;
  }

  long long sum(int y1, int x1, int y2, int x2) {
    return sum(y1, x1) - sum(y1, x2) - sum(y2, x1) + sum(y2, x2);
  }

  void add(int y, int x) {
    for (int i = y; i <= n; i += i & -i) {
      for (int j = x; j <= n; j += j & -j) {
        v[i][j]++;
      }
    }
  }
};

int main() {
  int n, K;
  cin >> n >> K;

  vector<long long> x, y, a, b;
  map<long long, int> X, Y;
  for (int i = 0; i < n; ++i) {
    int s, t;
    cin >> s >> t;
    x.push_back(s);
    y.push_back(t);
  }

  a = x;
  b = y;

  sort(a.begin(), a.end());
  sort(b.begin(), b.end());
  for (int i = 0; i < n; ++i) {
    X[a[i]] = i + 1;
    Y[b[i]] = i + 1;
  }

  BIT bit(n);
  for (int i = 0; i < n; ++i) {
    bit.add(Y[y[i]], X[x[i]]);
  }

  long long ans = 5001001001001001001;
  for (int i = 0; i < n; ++i) {
    for (int j = i + 1; j < n; ++j) {
      for (int k = 0; k < n; ++k) {
        for (int l = k + 1; l < n; ++l) {
          if (bit.sum(Y[b[l]], X[a[j]], Y[b[k]] - 1, X[a[i]] - 1) >= K) {
            ans = min(ans, (b[l] - b[k]) * (a[j] - a[i]));
          }
        }
      }
    }
  }

  cout << ans << endl;
}

