ll calc(const ll y1, const ll y2) {
  ll ret = ll(INT_MAX) * INT_MAX;
  int i1 = 0;
  int i2 = 0;
  int ix1 = 0;
  int ct = 0;
  for (int ix2 = 1; ix2 < N; ++ix2) {
    while (i2 < N && xy[i2].first <= x[ix2]) {
      if (xy[i2].second <= y2 && xy[i2].second >= y1) {
        ct++;
      }
      i2++;
    }
    while (i1 < i2 && ct > K) {
      if (xy[i1].second <= y2 && xy[i1].second >= y1) {
        ct--;
      }
      i1++;
    }

    if (ct >= K) {
      ret = min(ret, ll(y2 - y1) * (xy[ix2].first - xy[i1].first));
    }
  }

  return ret;
}
