    if(use <= k){
        dfs(depth + 1, use + 1, max(xmx, vec[depth].first), min(xmn, vec[depth].first), max(ymx, vec[depth].second), min(ymn, vec[depth].second));
    }
    int can_use = n - depth - 1;
    if(k > use + can_use) return;
    dfs(depth + 1, use, xmx, xmn, ymx, ymn);
}

