  sort(y_sorted.begin(), y_sorted.end());
  int minX, minY, maxX, maxY;
  long long min_area = -1ll; // infinity
  // sort pairs of x and y's by other coordinate
  for (int x1=0; x1<n; x1++){
    for (int y1=0; y1<n; y1++){
      for (int x2=x1+1; x2<n; x2++){ // x1+1 because it's not the same point
