          minX = x_sorted[x1]; // lst needs to be sorted so maxX > minX
          minY = y_sorted[y1];
          maxX  = x_sorted[x2];
          maxY = y_sorted[y2];
          int points = 0; 
          for (int i=0; i<n; i++){
            if (x_lst[i] >= minX && x_lst[i] <= maxX){
              if (y_lst[i] >= minY && y_lst[i] <= maxY){
                points++;
              }
            }
          }

          long long area = (long long)(maxX-minX)*(maxY-minY);
          if (points >= pts){
            if (min_area == -1){
              min_area = area;
            }else{
              if (area < min_area){
                min_area = area;
              }
            }
          }
        }
      }
