#include <bits/stdc++.h>
using namespace std;

long long calc_area(vector<pair<long long,long long>> points){
  long long minx=10000000000,miny=10000000000,maxx=-10000000000,maxy=-10000000000;
  for(auto point:points){
    minx=min(minx,point.first);
    miny=min(miny,point.second);
    maxx=max(maxx,point.first);
    maxy=max(maxy,point.second);
  }
  return (maxx-minx)*(maxy-miny);
}

int main(){
  int n,k;
  cin >> n >> k;

  vector<pair<long long,long long>> vec;
  for (int i = 0; i < n; i++)
  {
    long long x,y;
    cin >> x >> y;
    vec.emplace_back(x,y);
  }

  vector<pair<long long,long long>> points(2);
  long long minarea = 1000000000000000000;
  for (int i = 0; i < n; i++)
  {
    for (int j = i+1; j < n; j++)
    {
      vector<pair<long long,long long>> tmp(2);
      tmp[0]=vec[i];
      tmp[1]=vec[j];
      long long tmparea=calc_area(tmp);
      if(tmparea<minarea){
        points[0]=tmp[0];
        points[1]=tmp[1];
        minarea=tmparea;
      }
    }
  }

  long long curarea = minarea;
  long long mindiff = 9000000000000000000;
  while((int)points.size()<k){
    points.emplace_back(0,1);
    for (int i = 0; i < n; i++)
    {
      vector<pair<long long,long long>> tmp = points;
      tmp[tmp.size()-1]=vec[i];
      long long diff = calc_area(tmp) - curarea;
      if(diff!=0 && diff<mindiff){
        mindiff = diff;
        points[points.size()-1] = vec[i];
      }
    }
    curarea+=mindiff;    
    mindiff = 9000000000000000000;
  }

  cout << curarea << endl;
}

