template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }
template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }
int main(){
    ll n,k; cin>>n>>k;
    vector<pair<ll,ll>> coo(n);
    rep(i,n){
        ll x,y; cin>>x>>y;
        coo[i]={x,y};
    }
    sort(coo.begin(),coo.end());
    ll i=0;
    ll res=-1;
    while(i+k-1<n){
        ll left=i, right=i+k-1;
        ll top=-1e9-5, bottom=1e9+5;
        for(ll j=left; j<=right; j++){
            chmax(top,coo[j].second);
            chmin(bottom,coo[j].second);
        }
        ll tmp=(coo[right].first-coo[left].first)*(top-bottom);
        if(res==-1) res=tmp;
        else chmin(res,tmp);
        i++;
    }
    cout<<res<<endl;
    return 0;
}

