	if( x == t.x )
	    return y < t.y;
	return x < t.y;
    }
};

ll k_in(const point a, const point b, const vector<point>& ps, const ll k) {

    ll in = 0;
    ll xmin = min(a.x,b.x), xmax = max(a.x,b.x);
    ll ymin = min(a.y,b.y), ymax = max(a.y,b.y);

    for(auto& e : ps) {
	if( xmin <= e.x and e.x <= xmax and ymin <= e.y and e.y <= ymax )
	    in++;
    }
    if(k <= in)
	return (xmax-xmin)*(ymax-ymin);
    return 1e+18;
}

