int ncr(vector<vector<int>> &v, int n, int r) {
    if (n == r) return v[n][r] = 1;
    if (n == 0) return v[n][r] = 1;
    if (r == 1) return v[n][r] = n;
    return v[n][r] = ncr(v, n - 1, r) + ncr(v, n - 1, r - 1);
}

void combination(vector<vector<int>> &v, int n, int r)
{
    std::string bit_mask(r, 1);
    bit_mask.resize((unsigned long)n, 0);

    int c = 0, j;
    do {
        j = 0;
        for (int i = 0; i < n; i++)
        {
            if (bit_mask[i]) {
                v[c][j++] = i;
            }
        }
        c++;
    } while (std::prev_permutation(bit_mask.begin(), bit_mask.end()));
}

int main() {
    ios::sync_with_stdio(false);

    int n, r;
    cin >> n >> r;
    vector<vector<int>> vncr((unsigned long)n + 1, vector<int>(r + 1, 0));
    vector<vector<int>> vp((unsigned long)n, vector<int>(2,0));
    r(i, 0, n) {
        cin >> vp[i][0] >> vp[i][1];
    }

    long c = ncr(vncr, n, r);
    vector<vector<int>> vc((unsigned long)c, vector<int>((unsigned long)r));

    combination(vc, n, r);

    int maxx, maxy, minx, miny;
    long long mina = INT64_MAX;
    r(i, 0, c) {
        maxx = maxy = INT32_MIN;
        minx = miny = INT32_MAX;

        r(j, 0, r) {
            int cp = vc[i][j];
            maxx = max(maxx, vp[cp][0]);
            minx = min(minx, vp[cp][0]);
            maxy = max(maxy, vp[cp][1]);
            miny = min(miny, vp[cp][1]);
        }

        mina = min(mina, 1LL * (maxx - minx) * (maxy - miny));
    }

    cout << mina;

    return 0;
}

