int N, K;
vi x, y;
vi i2x, i2y;
map<int, int> x2i, y2i;
vvi g;

// [ x[il], x[ir] ) x [ y[jd], y[ju] )の点の個数
int count(int il, int jd, int ir, int ju) {
	assert(0 <= il and il <= ir and ir <= N);
	assert(0 <= jd and jd <= ju and ju <= N);
	return g[ir][ju] - g[ir][jd] - g[il][ju] + g[il][jd];
}
// 左辺のx座標，下辺のy座標，上辺のy座標(のに対応する添字)を固定したときに，長方形がK個以上の点を含むこととなる右辺のx座標(に対応する添字)の最小値
// il,jd,irを固定したときに長方形がK個以上の点を含むようなjuの最小値
int minR(int il, int jd, int ir) {
	int ng = il, ok = N;
	if ((count(il, jd, ir, ok) < K)) return -1;
	while (abs(ok - ng) > 1) {
		int mid = (ng + ok) / 2;
		if (count(il, jd, ir, mid) >= K) ok = mid;
		else ng = mid;
	}
	return ok;
}
// 左辺のx座標，下辺のy座標，上辺のy座標(のに対応する添字)を固定したときに，K個以上の点を含む長方形の面積の最小値(K個以上の点を含まないときはINF)
ll minsq(int il, int jd, int ir) {
	int ju = minR(il, jd, ir);
	if (ju == -1) return INF;
	else {
		ll width = i2x[ir - 1] - i2x[il];
		ll height = i2y[ju - 1] - i2y[jd];
		// dbs(width, height);
		return width * height;
	}
}

int main() {
	// 0-ind
	cin >> N >> K;
	x = y = vi(N);
	i2x = i2y = vi(N);
	rep(i, N) {
		cin >> x[i] >> y[i];
		i2x[i] = x[i]; i2y[i] = y[i];
	}
	sort(all(i2x)); sort(all(i2y));
	rep(i, N) x2i[i2x[i]] = i;
	rep(i, N) y2i[i2y[i]] = i;
	// dbl(x); dbl(i2x); dbl(x2i);
	// dbl(y); dbl(i2y); dbl(y2i);

	g = vvi(N + 1, vi(N + 1));
	rep(i, N) g[x2i[x[i]] + 1][y2i[y[i]] + 1]++; // g[i][j] = (x2i[i] - 1, y2i[j] - 1)に点があるか
	rep2(i, 1, N + 1) rep2(j, 1, N + 1) g[i][j] += g[i][j - 1];
	rep2(i, 1, N + 1) rep2(j, 1, N + 1) g[i][j] += g[i - 1][j];
	// g[i][j] = [x2i[0], y2i[0]) x [x2i[i], y2i[j]) の点の個数
	// dbvv(g);

	ll ans = INF;
	rep(il, N - 1) rep(jd, N - 1) rep2(ir, il, N + 1) {
		if (minsq(il, jd, ir) == INF) continue;
		chmin(ans, minsq(il, jd, ir));
	}
	cout << ans << endl;
}

