#define LL long long
#define MX 55
struct Node
{
    LL x, y;
    bool operator < (const Node &b)const{
        return x<b.x;
    }
}pt[MX];

int k, n;

bool check(LL xa ,LL xb ,LL ya, LL yb,int p)
{
    if (pt[p].x>=xa&&pt[p].x<=xb&&
        pt[p].y>=ya&&pt[p].y<=yb) return 1;
    return 0;
}

LL func(int u, int v)
{
    LL res = INF;
    for (int i=1;i<=n;i++)
    {
        int tot = 0;
        LL minx = min( min(pt[u].y,pt[v].y), pt[i].x);
        LL maxx = max( max(pt[u].y,pt[v].y), pt[i].x);

        LL miny = min( min(pt[u].y,pt[v].y), pt[i].y);
        LL maxy = min( max(pt[u].y,pt[v].y), pt[i].y);
        for (int j=1;j<=n;j++)
        {
            if (check(minx,maxx,miny,maxy,j)) tot++;
        }
        if (tot>=k) res = min(res, (maxy-miny)*(maxx-minx));
    }
    return res;
}

int main()
{
    scanf("%d%d",&n,&k);
    for (int i=1;i<=n;i++)
    {
        scanf("%lld%lld",&pt[i].x, &pt[i].y);
    }
    LL area = INF;
    for (int i=1;i<=n;i++)
        for (int j=1;j<=n;j++)
            area = min(area, func(i,j));
    printf("%lld\n",area);
    return 0;
}

