    REP(a,n) REP(b,n) REP(c,n) REP(d,n) {
        if ( a>=b || c>=d ) continue;
        int cnt=0;
        REP(i,n) {
            if ( v[i].first>=X[a]&&v[i].first<=X[b]&&v[i].second>=Y[c]&&v[i].second<=Y[d] ) cnt++;
        }
        LL x=max((X[b]-X[a]),1LL);
        LL y=max((Y[d]-Y[c]),1LL);
        if ( cnt>=k ) chmin(ans,x*y);
    }
    W(ans);
    return 0;
}

