using namespace std;

typedef long long ll;

const int MAXN = 50;
int N, K;
vector<ll> vecx, vecy;
int sum[MAXN][MAXN];

// rectangle (x1, y1), (x2, y2) contains more than K points or not
bool query(ll x1, ll x2, ll y1, ll y2){
  int pnum;
  if(x1 == 0 && y1 == 0) pnum = sum[x2][y2];
  else if(x1 == 0) pnum = sum[x2][y2] - sum[x2][y1-1];
  else if(y1 == 0) pnum = sum[x2][y2] - sum[x1-1][y2];
  else pnum = sum[x2][y2] - sum[x1-1][y2] - sum[x2][y1-1] + sum[x1-1][y1-1];
  if(pnum >= K) return true;
  return false;
}

int main(){
  cin >> N >> K;
  ll x[N], y[N];
  set<pair<ll, ll> > points;
  for(int i=0;i<N;i++){
    cin >> x[i] >> y[i];
    vecx.push_back(x[i]);
    vecy.push_back(y[i]);
    points.insert(make_pair(x[i], y[i]));
  }
  sort(vecx.begin(), vecx.end());
  sort(vecy.begin(), vecy.end());
  /*
  for(int i=0;i<N;i++) cout << vecx[i] << " ";
  cout << endl;
  */
  bool isPoint[N][N];
  for(int i=0;i<N;i++){
    for(int j=0;j<N;j++){
      pair<ll, ll> p = make_pair(vecx[i], vecy[j]);
      if(points.find(p) != points.end()) isPoint[i][j] = true;
      else isPoint[i][j] = false;
    }
  }
  // calculate cumulative sum
  if(isPoint[0][0]) sum[0][0] = 1;
  else sum[0][0] = 0;
  for(int i=1;i<N;i++){
    if(isPoint[0][i]) sum[0][i] = sum[0][i-1] + 1;
    else sum[0][i] = sum[0][i-1];
  }
  for(int i=1;i<N;i++){
    if(isPoint[i][0]) sum[i][0] = sum[i-1][0] + 1;
    else sum[i][0] = sum[i-1][0];
  }

  for(int i=1;i<N;i++){
    for(int j=1;j<N;j++){
      if(isPoint[i][j]) sum[i][j] = sum[i-1][j] + sum[i][j-1] - sum[i-1][j-1] + 1;
      else sum[i][j] = sum[i-1][j] + sum[i][j-1] - sum[i-1][j-1];
    }
  }
  /*
  for(int i=0;i<N;i++){
    for(int j=0;j<N;j++){
      cout << sum[i][j] << " ";
    }
    cout << endl;
  }
  */
  ll minarea = (vecx[N-1] - vecx[0]) * (vecy[N-1] - vecy[0]);
  for(int x1=0;x1<N;x1++){
    for(int x2=x1+1;x2<N;x2++){
      for(int y1=0;y1<N;y1++){
        for(int y2=y1+1;y2<N;y2++){
          if(query(x1, x2, y1, y2)){
            ll area = abs(vecx[x1] - vecx[x2]) * abs(vecy[y1] - vecy[y2]);
            minarea = min(minarea, area);
          }
        }
      }
    }
  }
  cout << minarea << endl;
}

