			if(x[m]>=min(x[i],x[j])&&x[m]<=max(x[i],x[j])&&y[m]>=min(y[k],y[l])&&y[m]<=max(y[k],y[l])) ans+=1;
		}
		if (ans>=K) {
		  if (area==-1) area = abs((x[i]-x[j])*(y[k]-y[l]));
		  else area = min(area,abs((x[i]-x[j])*(y[k]-y[l])));
		}
	}
      }
    }
  }
  cout << area << endl;
  return 0;
}

