int main() {
  int N, K;
  scanf("%d%d", &N, &K);
  vector<pair<int, int>> points;
  for (int i = 0; i < N; i++) {
    int x, y;
    scanf("%d%d", &x, &y);
    points.push_back(make_pair(x, y));
  }

  uint64_t best = ULLONG_MAX;
  for (int a = 0; a < N; a++) {
    for (int b = a + 1; b < N; b++) {
      for (int c = b + 1; c < N; c++) {
        for (int d = c + 1; d < N; d++) {
          int min_x = INT_MAX;
          int min_y = INT_MAX;
          int max_x = INT_MIN;
          int max_y = INT_MIN;
          auto update = [&](const pair<int, int>& p) {
            min_x = min(min_x, p.first);
            max_x = max(min_x, p.first);
            min_y = min(min_y, p.second);
            max_y = max(max_y, p.second);
          };
          update(points[a]);
          update(points[b]);
          update(points[c]);
          update(points[d]);

          int n = 0;
          for (int e = 0; e < N; e++) {
            int x = points[e].first;
            int y = points[e].second;
            if (min_x <= x && x <= max_x && min_y <= y && y <= max_y)
              n++;
          }

          if (n >= K) {
            uint64_t w = max_x - min_x;
            uint64_t h = max_y - min_y;
            if (best > w * h) {
              best = w * h;
            }
          }
        }
      }
    }
  }

  printf("%lld\n", best);
}

