template <typename T>
struct twodim_fenwick_tree {
    int h, w;
    vector<vector<T>> data;
    twodim_fenwick_tree(int h, int w) : h(h), w(w), data(h+1, vector<T>(w+1)) {}
    void add(int r, int c, T x=1) {
        for (int i = r+1; i <= h; i += i&-i)
            for (int j = c+1; j <= w; j += j&-j) data[i][j] += x;
    }
    T sum(int r, int c) {
        T res = 0;
        for (int i = r; i; i -= i&-i)
            for (int j = c; j; j -= j&-j) res += data[i][j];
        return res;
    }
    T sum(int r1, int c1, int r2, int c2) {
        return sum(r2, c2) - sum(r1, c2) - sum(r2, c1) + sum(r1, c1);
    }
};

template <typename T>
struct compress {
    vector<T> xs;
    compress(const vector<T> vs) {
        xs = vs;
        sort(xs.begin(), xs.end());
        xs.erase(unique(xs.begin(), xs.end()), xs.end());
    }
    vector<int> get(const vector<T> &vs) const {
        vector<int> res;
        transform(vs.begin(), vs.end(), back_inserter(res),
                  [&](const T &x) { return lower_bound(xs.begin(), xs.end(), x) - xs.begin();}
            );
        return res;
    }
    int get(const T &x) const {
        return lower_bound(xs.begin(), xs.end(), x) - xs.begin();
    }
    const T &operator[](int k) const { return xs[k];}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> x(n), y(n);
    rep(i, n) cin >> x[i] >> y[i];
    compress<int> cx(x), cy(y);
    int h = cy.xs.size();
    int w = cx.xs.size();
    twodim_fenwick_tree<int> ft(h, w);

    rep(i, n) {
        ft.add(cy.get(y[i]), cx.get(x[i]));
    }

    ll ans = 5e18;
    for (int y1 = 0; y1 < h; ++y1) {
        for (int y2 = y1+1; y2 < h; ++y2) {
            for (int x1 = 0; x1 < w; ++x1) {
                for (int x2 = x1+1; x2 < w; ++x2) {
                    int sum = ft.sum(y1, x1, y2+1, x2+1);
                    if (sum < k) continue;
                    ll s = 1LL * (cy[y2] - cy[y1]) * (cx[x2] - cx[x1]);
                    chmin(ans, s);
                }
            }
        }
    }
    cout << ans << endl;
}

