    int BX=A[i+K-1].first,SX=A[i].first,BY=A[i].second,SY=A[i].second;
    rep(j,i+1,i+K){
      BY=max(BY,A[j].second);
      SY=min(SY,A[j].second);
    }
    int S=max(1LL,(BY-SY))*max(1LL,(BX-SX))/LLL,Q=max(1LL,(BY-SY))*max(1LL,(BX-SX))%LLL;
    if(S==0)
    ans=min(ans,Q);
    else{
      if(T>S){
        T=S;
        ans=Q;
      }
      else if(T==S){
        if(Q<ans)
          ans=Q;
      }  
    }
  }
  if(T==LLL)
  cout<<ans<<endl;
  else{
    printf("%ld%09ld\n",T,ans);
  }
  }

