    auto filter = [](vector<pair<lint, lint>> p, lint ymin, lint ymax) {
        vector<pair<lint, lint>> v;
        for (auto e: p) {
            if (ymin <= e.snd and e.snd <= ymax) {
                v.emplace_back(e);
            }
        }
        sort(v.begin(), v.end(), [](const pair<lint, lint> p, const pair<lint, lint> q) {
            return p.fst < q.fst;
        });
        return v;
    };

    lint ans = numeric_limits<lint>::max();
    repeat(i, n) repeat(j, n) {
        if (i == j) continue;
        lint ymax = p[i].snd;
        lint ymin = p[j].snd;
        lint ydif = ymax - ymin;
        if (ydif < 0) continue;
        vector<pair<lint, lint>> v = filter(p, ymin, ymax);
        lint xmin = v[0].fst;
        lint xdif = 0;
        lint cnt = 0;
        for (auto e: v) {
            ++cnt;
            if (cnt >= k) {
                xdif = max(xdif, abs(xmin - e.fst));
                ans = min(ans, xdif * ydif);
            }
        }   
    }
    cout << ans << endl;
}

