ll solve(vector<P> r) {
    ll smin = INF;
    for (int i = 0; i < n - k + 1; i++) {
        ll hmin = r[i].second, hmax = r[i].second;
        for (int j = 1; j < k; j++) {
            hmin = min(hmin, r[i + j].second);
            hmax = max(hmax, r[i + j].second);
        }
        smin = min(smin, (hmax - hmin) * (r[i + k - 1].first - r[i].first));
    }
    return smin;
}

