// 内部定数
#define D_VTX_MAX		50										// 最大座標数
#define D_MODE_X		0										// モード - Ｘ基準
#define D_MODE_Y		1										// モード - Ｙ基準

// 内部構造体 - 頂点情報
typedef struct Vtx {
	int miX;													// 座標Ⅹ
	int miY;													// 座標Ｙ
} Vtx;

// 内部変数
static Vtx sz1Vtx[D_VTX_MAX];									// 頂点情報
static int siVCnt;												// 頂点情報数
static int siNCnt;												// 必要頂点数
static long long slMin;											// 最小面積

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
	static FILE *szpFpT, *szpFpA;
#endif

// ソート関数 - Ｘ座標昇順
int
fSortFncX(
	const void *pzpVal1			// <I> 値１
	, const void *pzpVal2		// <I> 値２
)
{
	Vtx *lzpVal1 = (Vtx *)pzpVal1;
	Vtx *lzpVal2 = (Vtx *)pzpVal2;

	// Ｘ座標昇順
	if (lzpVal1->miX > lzpVal2->miX) {
		return(1);
	}
	else if (lzpVal1->miX < lzpVal2->miX) {
		return(-1);
	}

	return 0;
}

// ソート関数 - Ｙ座標昇順
int
fSortFncY(
	const void *pzpVal1			// <I> 値１
	, const void *pzpVal2		// <I> 値２
)
{
	Vtx *lzpVal1 = (Vtx *)pzpVal1;
	Vtx *lzpVal2 = (Vtx *)pzpVal2;

	// Ｙ座標昇順
	if (lzpVal1->miY > lzpVal2->miY) {
		return(1);
	}
	else if (lzpVal1->miY < lzpVal2->miY) {
		return(-1);
	}

	return 0;
}

// 算出
int
fCalc(
	int piMode					// <I> モード
)
{
	int i;

	// ソート
	if (piMode == D_MODE_X) {
		qsort(sz1Vtx, siVCnt, sizeof(Vtx), fSortFncX);
	}
	else {
		qsort(sz1Vtx, siVCnt, sizeof(Vtx), fSortFncY);
	}

	// 初期化
	int liNoS = 0;
	int liNoE = 0;

	// 算出
	while (1) {

		// 必要頂点数
		if (liNoE - liNoS + 1 < siNCnt) {		// 不足

			// 頂点追加
			liNoE++;
			if (liNoE >= siVCnt) {					// 頂点なし
				break;
			}
		}
		else {									// OK

			// 基準座標範囲
			int liBS, liBE;
			if (piMode == D_MODE_X) {
				liBS = sz1Vtx[liNoS].miX;
				liBE = sz1Vtx[liNoE].miX;
			}
			else {
				liBS = sz1Vtx[liNoS].miY;
				liBE = sz1Vtx[liNoE].miY;
			}

			// もう一方の座標範囲
			int liOS = INT_MAX;
			int liOE = INT_MIN;
			for (i = liNoS; i <= liNoE; i++) {

				// 対象値
				int liVal;
				if (piMode == D_MODE_X) {
					liVal = sz1Vtx[i].miY;
				}
				else {
					liVal = sz1Vtx[i].miX;
				}

				// 更新
				if (liOS > liVal) {
					liOS = liVal;
				}
				if (liOE < liVal) {
					liOE = liVal;
				}
			}

			// 面積
			long long llArea = (long long)(liBE - liBS) * (long long)(liOE - liOS);
			if (slMin > llArea) {
				slMin = llArea;
			}

			// 頂点削除
			liNoS++;
		}
	}

	return 0;
}

