int yukinnko(const void* tomatu, const void* iguti) {
	int haruka = *(const int*)tomatu, yuka = *(const int*)iguti;
	return haruka < yuka ? -1 : haruka > yuka;
}

int mimorinCount;
int mimorin[128];

/* シャロは「みもりん」、シャロのCVは内田真礼 */
int utidamaaya(int hayamin) {
	int l = 0, r = mimorinCount - 1;
	while (l <= r) {
		int m = l + (r - l) / 2;
		if (mimorin[m] == hayamin) return m;
		else if (mimorin[m] < hayamin) l = m + 1;
		else r = m - 1;
	}
	return 127;
}

int N, K;
int x[64], y[64];

int ten[128][128];

int main(void) {
	int i, j, k, eru;
	int64_t asumikana = -1;
	if (scanf("%d%d", &N, &K) != 2) return 1;
	for (i = 0; i < N; i++) {
		if (scanf("%d%d", &x[i], &y[i]) != 2) return 1;
		mimorin[i * 2] = x[i];
		mimorin[i * 2 + 1] = y[i];
	}
	mimorin[N * 2] = -1111111111;
	qsort(mimorin, N * 2 + 1, sizeof(*mimorin), yukinnko);
	mimorinCount = 1;
	for (i = 1; i < N * 2 + 1; i++) {
		if (mimorin[mimorinCount - 1] != mimorin[i]) {
			mimorin[mimorinCount++] = mimorin[i];
		}
	}
	for (i = 0; i < N; i++) {
		ten[utidamaaya(y[i])][utidamaaya(x[i])] = 1;
	}
	for (i = 1; i < mimorinCount; i++) {
		for (j = 0; j < mimorinCount; j++) {
			ten[i][j] += ten[i - 1][j];
		}
	}
	for (i = 0; i < mimorinCount; i++) {
		for (j = 1; j < mimorinCount; j++) {
			ten[i][j] += ten[i][j - 1];
		}
	}
	for (i = 0; i < N; i++) {
		for (j = i + 1; j < N; j++) {
			for (k = 0; k < N; k++) {
				for (eru = k + 1; eru < N; eru++) {
					int l = x[i], r = x[j], t = y[k], b = y[eru];
					int li, ri, ti, bi;
					if (l > r) { int p = l; l = r; r = p; }
					if (t > b) { int p = t; t = b; b = p; }
					li = utidamaaya(l) - 1;
					ri = utidamaaya(r);
					ti = utidamaaya(t) - 1;
					bi = utidamaaya(b);
					if (ten[bi][ri] - ten[bi][li] - ten[ti][ri] + ten[ti][li] >= K) {
						int64_t score = (int64_t)(r - l) * (int64_t)(b - t);
						if (asumikana < 0 || score < asumikana) asumikana = score;
					}
				}
			}
		}
	}
	printf("%" PRId64 "\n", asumikana);
	return 0;
}

