}

int main(void){
    int n,k;
    long long tmp,ans=LONG_MAX;
    scanf("%d%d",&n,&k);
    dot_t d[n];
    for (int i=0; i<n; i++){
        scanf("%lld%lld",&d[i].x,&d[i].y);
    }
    qsort (d,n,sizeof(dot_t),sortx);
    for (int i=0; i<n-k+1; i++){
        for (int j=i; j<n-k+1-i; j++){
            long long maxy=d[i].y,miny=d[i].y;
            for (int l=j+1; l<j+i+k; l++){
