#include<stdio.h>
#include<stdlib.h>

void sort(long long *num, long long *num2, int sum){
    int interval = sum / 2;
    int start_num = interval, sort_num;
    long long swap;
    while(1){
        for(int i = start_num; i < sum; i += interval){
            sort_num = i;
            while(1){
                if(num[sort_num] > num[sort_num - interval]) break;
                swap = num[sort_num];
                num[sort_num] = num[sort_num - interval];
                num[sort_num - interval] = swap;
                swap = num2[sort_num];
                num2[sort_num] = num2[sort_num - interval];
                num2[sort_num - interval] = swap;
                sort_num -= interval;
                if(sort_num == (i % interval)) break;
            }
        }
        start_num++;
        if(interval == 1) break;
        if(start_num == (interval * 2)){
            interval = interval / 2;
            start_num = interval;
        }
    }
}

long long AbsV(long long n){
    if(n >= 0) return n;
    if(n < 0) return n * -1;
}

int main(){
    int N, K;
    long long *x, *y, y_max, y_min, xy_min;

    scanf("%d%d", &N, &K);

    x = malloc(sizeof(long long) * N);
    y = malloc(sizeof(long long) * N);

    for(int i = 0; i < N; i++){
        scanf("%lld%lld", &x[i], &y[i]);
    }

    sort(x, y, N);

    xy_min = (AbsV(y[K - 1] - y[0]) * AbsV(x[K - 1] - x[0]));
    for(int i = 0; (i + K - 1) < N; i++){
        y_max = y[i];
        y_min = y[i];
        for(int j = i; j < (i + K); j++){
            if(y_max < y[j]) y_max = y[j];
            if(y_min > y[j]) y_min = y[j];
        }
        if(xy_min > (AbsV(y_max - y_min) * AbsV(x[i + K - 1] - x[i]))){
            xy_min = (AbsV(y_max - y_min) * AbsV(x[i + K - 1] - x[i]));
        }
    }

    printf("%lld\n", xy_min);
    free(x);
    free(y);
    return 0;
}

