struct xy{
		long long x;
		long long y;
};

int compare_intx(const void *a,const void *b){
		struct xy A=*(struct xy*)a,B=*(struct xy*)b;
		if(A.x>B.x)return 1;
		else if(A.x==B.x){
				if(A.y>B.y)return 1;
		}
		return -1;
}

int compare_inty(const void *a,const void *b){
		struct xy A=*(struct xy*)a,B=*(struct xy*)b;
		if(A.y>B.y)return 1;
		else if(A.y==B.y){
				if(A.x>B.x)return 1;
		}
		return -1;
}

