int countC(vector<pair<int, int>>& xy, int xbegin, int xend, int ybegin, int yend) {
	int c = 0;
	for (auto i : xy) {
		if (i.first >= xbegin && i.first <= xend && i.second >= ybegin && i.second <= yend) {
			c++;
		}
	}
	return c;
}

int main() {
