				h=xy[i+l+k-1].x-xy[i].x;
				long long mn=xy[i].y,mx=xy[i].y;
				for(j=1;j<l+k;j++){
						mn=min(mn,xy[j+i].y);
						mx=max(mx,xy[j+i].y);
				}
				w=mx-mn;
				if(ans==-1)ans=h*w;
				ans=min(ans,h*w);
		}
		}
		qsort(xy,n,sizeof(struct xy),compare_inty);
		for(l=0;l+k<=n;l++){
		for(i=0;i+l+k-1<n;i++){
