int
fMain(
	int piTNo					// <I> テスト番号 1～
)
{
	int i, j, k;
	char lc1Buf[1024], lc1Out[1024];

	// データ初期化
	slMin = LLONG_MAX;											// 最小面積

	// テストファイルオープン
#ifdef D_TEST
	sprintf(lc1Buf, ".\\Test\\T%d.txt", piTNo);
	szpFpT = fopen(lc1Buf, "r");
	sprintf(lc1Buf, ".\\Test\\A%d.txt", piTNo);
	szpFpA = fopen(lc1Buf, "r");
	siRes = 0;
#endif

	// 頂点情報数・必要頂点数取得
#ifdef D_TEST
	fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
	fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
	sscanf(lc1Buf, "%d%d", &siVCnt, &siNCnt);

	// 頂点情報取得
	for (i = 0; i < siVCnt; i++) {
#ifdef D_TEST
		fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
		fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
		sscanf(lc1Buf, "%d%d", &sz1Vtx[i].miX, &sz1Vtx[i].miY);
	}

	// ソート
	qsort(sz1Vtx, siVCnt, sizeof(Vtx), fSortFncX);

	// 算出
	for (i = 0; i < siVCnt - siNCnt + 1; i++) {
		for (j = i + siNCnt - 1; j < siVCnt; j++) {

			// Ｙ座標範囲
			int liYS, liYE;
			if (sz1Vtx[i].miY < sz1Vtx[j].miY) {
				liYS = sz1Vtx[i].miY;
				liYE = sz1Vtx[j].miY;
			}
			else {
				liYS = sz1Vtx[j].miY;
				liYE = sz1Vtx[i].miY;
			}

			// 内包頂点数
			int liCnt = j - i - 1;

			// 内包座標リスト
			int li1Y[D_VTX_MAX];
			for (k = 0; k < liCnt; k++) {
				li1Y[k] = sz1Vtx[i + 1 + k].miY;
			}
			qsort(li1Y, liCnt, sizeof(int), fSortFncI);

			// 不要内包頂点削除
			int liNoS = 0;
			int liNoE = liCnt - 1;
			while (liNoE - liNoS + 3 > siNCnt) {

				// 開始側
				int liLenS = liYS - li1Y[liNoS];				// 削除時の減少範囲
				if (liLenS > 0) {								// 削除可能
					if (liNoS < liCnt - 1) {						// 次の点あり
						if (liYS - li1Y[liNoS + 1] > 0) {				// 次の点も削除可能
							liLenS = li1Y[liNoS + 1] - li1Y[liNoS];			// 削除時の減少範囲
						}
					}
				}

				// 終了側
				int liLenE = li1Y[liNoE] - liYE;				// 削除時の減少範囲
				if (liLenE > 0) {								// 削除可能
					if (liNoE > 0) {								// 次の点あり
						if (li1Y[liNoE - 1] - liYE > 0) {				// 次の点も削除可能
							liLenE = li1Y[liNoE] - li1Y[liNoE - 1];			// 削除時の減少範囲
						}
					}
				}

				// 離れた内包頂点を削除
				if (liLenS > liLenE) {
					if (liLenS < 0) {								// なし
						break;
					}
					liNoS++;
				}
				else {
					if (liLenE < 0) {								// なし
						break;
					}
					liNoE--;
				}
			}

			// Ｙ座標範囲 - 更新
			if (liCnt > 0) {								// 内包頂点あり
				if (liYS > li1Y[liNoS]) {
					liYS = li1Y[liNoS];
				}
				if (liYE < li1Y[liNoE]) {
					liYE = li1Y[liNoE];
				}
			}

			// 面積
			long long llArea = (long long)(sz1Vtx[j].miX - sz1Vtx[i].miX) * (long long)(liYE - liYS);
			if (slMin > llArea) {
				slMin = llArea;
			}
		}
	}

	// 結果セット
	sprintf(lc1Out, "%lld\n", slMin);

	// 結果表示
#ifdef D_TEST
	fgets(lc1Buf, sizeof(lc1Buf), szpFpA);
	if (strcmp(lc1Buf, lc1Out)) {
		siRes = -1;
	}
#else
	printf("%s", lc1Out);
#endif

	// テストファイルクローズ
#ifdef D_TEST
	fclose(szpFpT);
	fclose(szpFpA);
#endif

	// テスト結果
#ifdef D_TEST
	if (siRes == 0) {
		printf("OK %d\n", piTNo);
	}
	else {
		printf("NG %d\n", piTNo);
	}
#endif

	return 0;
}

