#define Max(a, b) ((a) > (b) ? (a) : (b))
#define Min(a, b) ((a) > (b) ? (b) : (a))
#define abs(x) ((x) > 0 ? (x) : -(x))
#define MOD (ll)1000000007 //10^9 + 7
#define endl printf("\n")
typedef long long ll;
#define MAX_N (1 << 17)

typedef struct{ll x, y;} point;

int
point_comp(const void *a, const void *b)
{
  point *A = (point *)a, *B = (point *)b;
  if (A->x > B->x) return 1;
  if (A->x < B->x) return -1;
  return 0;
}

int
main(int argc, char *argv[])
{
  int n, k;
  scanf("%d %d", &n, &k);
  point p[100];
  for (int i = 0; i < n; i++) scanf("%lld %lld", &p[i].x, &p[i].y);

  qsort(p, n, sizeof(point), point_comp);

  ll ans = LLONG_MAX;
  for (int i = k - 1; i < n; i++) {
    ll ymin = LLONG_MAX, ymax = LLONG_MIN;
    for (int j = i - k + 1; j <= i; j++) {
      ymin = Min(ymin, p[j].y);
      ymax = Max(ymax, p[j].y);
    }
    ans = Min(ans, (ymax - ymin) * (p[i].x - p[i - k + 1].x));
  }

  printf("%lld\n", ans);

  return 0;
}

fun main(args: Array<String>) = yorukatsu6E()

fun yorukatsu6E() {
    val (n, k) = readLine()!!.split(' ').map { it.toInt() }
    val xyList = (1..n).map { readLine()!!.split(' ').map { it.toLong() } }
        .map { Xy(it[0], it[1]) }

    val xList = xyList.map { it.x }.sorted()
    val yList = xyList.map { it.y }.sorted()

    var answer = Long.MAX_VALUE

    for ((index1, left) in xList.withIndex()) {
        for (right in xList.drop(index1 + 1)) {
            for ((index2, down) in yList.withIndex()) {
                for (up in yList.drop(index2 + 1)) {
                    val inRectangle = xyList.filter { it.y in down..up && it.y in left..right }
                    if (inRectangle.count() >= k) {
                        var minX = Long.MAX_VALUE
                        var maxX = Long.MIN_VALUE
                        var minY = Long.MAX_VALUE
                        var maxY = Long.MIN_VALUE
                        inRectangle.forEach {
                            minX = Math.min(minX, it.x)
                            maxX = Math.max(maxX, it.x)
                            minY = Math.min(minY, it.y)
                            maxY = Math.max(maxY, it.y)
                        }
                        val area = Math.abs(maxX - minX) * Math.abs(maxY - minY)
                        answer = Math.min(answer, area)
                    }
                }
            }
        }
    }

    println(answer)
}

