    val horizontalSorted = pointList.sortedBy { it.x }

    var ans = Long.MAX_VALUE
    for (left in horizontalSorted) {
        for (right in horizontalSorted) {
            if (left.x >= right.x) {
                continue
            }

            for (top in verticalSorted) {
                if (!(top.x in left.x..right.x)) {
                    continue
                }

                for (bottom in verticalSorted) {
                    if (top.y >= bottom.y ||
                        !(bottom.x in left.x..right.x)) {
                        continue
                    }

                    val includedCount = pointList.count {
                        it.x in left.x..right.x
                        && it.y in top.y..bottom.y
                    }

                    if (includedCount < k) {
                        continue
                    }

                    ans = Math.min(ans, (right.x - left.x).toLong() * (bottom.y - top.y).toLong())
                }
            }
        }
    }

    println(ans)
}

