fun solve(N: Int, K: Int, x: LongArray, y: LongArray){
    x.sort()
    y.sort()
    val combs = (0 until N).toSet().combinations(K)
    var ans = Long.MAX_VALUE
    for (comb in combs){
        val xs = comb.map{ x[it] }
        val ys = comb.map{ y[it] }
        val S = (xs.last()!! - xs.first()!!) * (ys.last()!! - ys.first()!!)
        ans = Math.min(ans, S)
    }
    println(ans)
    return
}

fun <T> Collection<T>.powerSet(): Set<Set<T>> = powerSet(this, setOf(setOf()))

private tailrec fun <T> powerSet(left: Collection<T>, acc: Set<Set<T>>): Set<Set<T>> = when {
    left.isEmpty() -> acc
    else -> powerSet(left.drop(1), acc + acc.map { it + left.first() })
}

fun <T> Set<T>.combinations(n: Int): Set<Set<T>> = when {
    n < 0 -> throw Error("n must be positive, but got $n")
    n == 0 -> setOf(setOf())
    n >= size -> setOf(toSet())
    else -> powerSet()
            .filter { it.size == n }
            .toSet()
}

