fun solve() {
    val (n, k) = nextIntList()
    val point = longAry2(n, 2)
    repeat(n) {
        val (x, y) = nextLongList()
        point[it][0] = x
        point[it][1] = y
    }
    val x = longAry(n)
    val y = longAry(n)
    for (i in 0 until n) {
        x[i] = point[i][0]
        y[i] = point[i][1]
    }
    x.sort()
    y.sort()
    var ans = LINF
    for (a in 0 until n - 1) {
        val leftX = x[a]
        for (b in 0 until n - 1) {
            val leftY = y[b]
            for (c in a + 1 until n) {
                val rightX = x[c]
                for (d in b + 1 until n) {
                    val rightY = y[d]
                    var count = 0
                    for (i in 0 until n) {
                        val nowX = point[i][0]
                        val nowY = point[i][1]
                        if (nowX in min(leftX, rightX)..max(leftX, rightX) && nowY in min(leftY, rightY)..max(leftY,rightY)) count++
                    }
                    if (count >= k) {
                        val area = abs(rightX - leftX) * abs(rightY - leftY)
                        ans = min(ans, area)
                    }
                }
            }
        }
    }

    println(ans)

}


