    static class DAxisParallelRectangle {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            long[] x = new long[n];
            long[] y = new long[n];
            for (int i = 0; i < n; i++) {
                x[i] = in.nextInt();
                y[i] = in.nextInt();
            }

            long answer = Long.MAX_VALUE;
            for (int l = 0; l < n; l++) {
                for (int r = l; r < n; r++) {
                    if (x[l] > x[r])
                        continue;
                    List<Long> ys = new ArrayList<>();
                    for (int i = 0; i < n; i++) {
                        if (x[i] <= x[r] && x[i] >= x[l]) {
                            ys.add(y[i]);
                        }
                    }
                    Collections.sort(ys);
                    for (int i = 0; i + k - 1 < ys.size(); i++) {
                        answer = Math.min(answer, (x[r] - x[l]) * (ys.get(i + k - 1) - ys.get(i)));
                    }
                }
            }

            out.println(answer);
        }

    }

