                            if (lx <= x[i] && x[i] <= rx && by <= y[i] && y[i] <= uy) {
                                cnt++;
                            }
                        }
                        // System.out.println("cnt = " + cnt);
                        if (cnt >= k) {
                            long res = Math.abs(rx - lx) * Math.abs(uy - by);
                            ans = Math.min(ans, res);
                        }
                    }
                }
            }
        }
        System.out.println(ans);
    }
}

