import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;
import java.util.StringJoiner;

class Main {

    static PrintWriter out;
    static InputReader sc;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        int K = sc.nextInt();
        Pair[] ps = new Pair[N];
        for (int i = 0; i < N; i++) {
            ps[i] = new Pair(sc.nextInt(), sc.nextInt());
        }
        int[] x = new int[N];
        int[] y = new int[N];
        for (int i = 0; i < N; i++) {
            x[i] = ps[i].first;
            y[i] = ps[i].second;
        }
        Arrays.sort(x);
        Arrays.sort(y);
        long ans = Long.MAX_VALUE / 2;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                for (int k = 0; k < N; k++) {
                    for (int l = k + 1; l < N; l++) {
                        long xmax = x[j], xmin = x[i], ymax = y[l], ymin = y[k];
                        int cnt = 0;
                        for (int m = 0; m < N; m++) {
                            if (xmin <= ps[m].first && ps[m].first <= xmax && ymin <= ps[m].second
                                    && ps[m].second <= ymax) {
                                cnt++;
                            }
                        }
                        if (cnt >= K) {
                            ans = Math.min(ans, (xmax - xmin) * (ymax - ymin));
                        }
                    }
                }
            }
        }
        out.println(ans);
    }

    /**
     * C++のPairと同じ
     */
    public static class Pair implements Comparable<Pair> {
        int first;
        int second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int hashCode() {
            return Integer.valueOf(this.first + this.second).hashCode();
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (!(obj instanceof Pair)) {
                return false;
            }
            Pair pair = (Pair) obj;
            return this.first == pair.first && this.second == pair.second;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.first, o.first);
        }

        @Override
        public String toString() {
            return String.format("{%d,%d}", this.first, this.second);
        }

    }

