        public void solve() {
        	int N = ni();
        	int K = ni();
        	PP[] ppd = new PP[N];
        	int x, y;
        	for (int i = 0; i < N; i++) {
				x = ni();
				y = ni();
				ppd[i] = new PP(x, y);
			}
        	Arrays.sort(ppd, Comparator.comparing(PP::getKey));
        	long ans = 5L * 1000000000 * 1000000000;
        	long X, Y;
        	int minY, maxY, minX, maxX;
        	for (int i = 0; i < N - K + 1; i++) {
        		X = (long)ppd[i+K-1].key - ppd[i].key;
        		minY = 1000000100;
        		maxY = -1000000100;
        		for (int j = i; j < i + K; j++) {
        			minY = Math.min(minY, ppd[j].val);
        			maxY = Math.max(maxY, ppd[j].val);
				}
        		Y = (long)maxY - minY;
        		ans = Math.min(ans, X * Y);
			}
        	Arrays.sort(ppd, Comparator.comparing(PP::getVal));
        	for (int i = 0; i < N - K + 1; i++) {
        		Y = (long)ppd[i+K-1].val - ppd[i].val;
        		minX = 1000000100;
        		maxX = -1000000100;
        		for (int j = i; j < i + K; j++) {
        			minX = Math.min(minX, ppd[j].key);
        			maxX = Math.max(maxX, ppd[j].key);
				}
        		X = (long)maxX - minX;
        		ans = Math.min(ans, X * Y);
			}
        	prn(ans);
        }

