		main.run();
	}

	class P{
		long x;
		long y;
		P(long x,long y){
			this.x=x;
			this.y=y;
		}
	}
	public void run() {
		Scanner sc = new Scanner(System.in);
		int n=sc.nextInt();
		int k=sc.nextInt();
		ArrayList<P> pl = new ArrayList<P>();
		for(int i=0; i<n; i++) {
			P p = new P(sc.nextLong(), sc.nextLong());
			pl.add(p);
		}
		Collections.sort(pl, (x,y)->Long.compare(x.x, y.x));
		long ans = Long.MAX_VALUE;
		for(int i=0; i<n-k+1; i++) {
			P p = pl.get(i);
			long minx = p.x;
			long miny = p.y;
			long maxx = p.x;
			long maxy = p.y;
