		quick_sort(coordy,0,N-1);
		for(int i=0; i<N; i++) {
			for(int j=0; j<N; j++) {
				if(i>=j) {
					for(int k=0; k<N; k++) {
						for(int l=0; l<N; l++) {
							if(k>=l) {
								long minx=coordx[j][0];
								long maxx=coordx[i][0];
