								int num=0;
								for(int m=0; m<N; m++) {
									if(minx<=coordx[m][0] && coordx[m][0]<=maxx) {
										if(miny<=coordx[m][1] && coordx[m][1]<=maxy) {
											num++;
										}
									}
								}
								if(num>=K) {
									MIN_S=Math.min(MIN_S, (maxx-minx)*(maxy-miny));
								}
							}
						}
					}
				}
			}
		}
