                    cnt++;
                }
                long curAns = (((long)r-(long)l)*(curY[up]-curY[low]));
                ans = Math.min(ans,curAns);
            }
        }
        System.out.println(ans);
    }
    private static class myComparator implements Comparator<int[]>{
        public int compare(int[] o1, int[] o2){
            return o1[0]-o2[0];
        }
    }
}

