//					(maxY(points, i, i + k - 1) - minY(points, i, i + k - 1));
////			System.out.println("dx "+(points[i + k - 1].x - points[i].x));
//			System.out.println("i = " + i + " area "+ tmpArea);
//			if(tmpArea < minArea){
//				minArea = tmpArea;
//			}
//		}

		//ガチの全探索
		for(int i = 0; i < n - 1; i++){
			for(int j = i + 1; j < n; j++){
				for(int k = 0; k < n - 1; k++){
					for(int l = 0; l < n; l++){
						long left = x[i];
						long right = x[j];
						long bottom = y[k];
						long top = y[l];

						int count = pointInRect(left, right, top, bottom, points);
//						System.out.println(count);
						if(count >= K){
							long tmpArea = (right - left)*(top - bottom);

							if(tmpArea < minArea){
								minArea = tmpArea;
							}
						}
					}
				}
			}
		}

		System.out.println(minArea);
	}

	static int pointInRect(long left, long right, long top, long bottom, Point[] points){
		int result = 0;

//		System.out.println(left+" "+right+" "+top+" "+bottom);

		for(int i = 0; i < points.length ; i++){
			if(points[i].x >= left && points[i].x <= right
					&& points[i].y >= bottom && points[i].y <= top ){
				result++;
			}
		}

		return result;
	}

	static long minY(Point[] points, int start, int end){
		long min = points[start].y;

		for(int i = start + 1; i <= end; i++){
			if(min > points[i].y){
				min = points[i].y;
			}
		}

		return min;
	}

	static long maxY(Point[] points, int start, int end){
		long max = points[start].y;

		for(int i = start + 1; i <= end; i++){
			if(max < points[i].y){
				max = points[i].y;
			}
		}

		return max;
	}

}

