                    }
                }
                if (area != 0 && cnt == K) {
                    res = Math.min(res, area);
                }
            }
        }
        System.out.println(res);
    }

    private long calcArea(int xl, int xr, int yd, int yu) {
        return (long) Math.abs(xr - xl) * Math.abs(yu - yd);
