        return (Math.min(a.x, Math.min(b.x, c.x)) <= d.x && Math.min(a.y, Math.min(b.y, c.y)) <= d.y &&
                Math.max(a.x, Math.max(b.x, c.x)) >= d.x && Math.max(a.y, Math.max(b.y, c.y)) >= d.y);
    }

