		while (!q.isEmpty()) {
			Node n = q.poll();
			long dist = n.dist;
			for (Edge e : n.es) {
				Node to = ns.get(e.to);
				if (to.dist > dist + 1) {
					to.dist = dist + 1;
					q.add(to);
				}
			}
		}
	}

	long treeDiameter1() {
		dijkstra1(0);
		Node n1 = ns.get(0);

		for (int i = 1; i < n; i++) {
			if (ns.get(i).dist > n1.dist)
				n1 = ns.get(i);
		}

		dijkstra1(n1.idx);

		long diam = 0;
		for (int i = 0; i < n; i++) {
			if (ns.get(i).dist > diam)
				diam = ns.get(i).dist;
		}

		return diam;
	}
}

public class Main {
	private static void solve() {
		int n = nei();
		int K = nei();
		long[][] ps = nls2(n, 2);

		ArrayList<Long> xs = new ArrayList<Long>();
		ArrayList<Long> ys = new ArrayList<Long>();
		for (int i = 0; i < n; i++) {
			xs.add(ps[i][0]);
			ys.add(ps[i][1]);
		}

		long minArea = Long.MAX_VALUE;
		for (int i = 0; i < xs.size(); i++) {
			for (int j = i + 1; j < xs.size(); j++) {
				for (int k = 0; k < ys.size(); k++) {
					for (int l = k + 1; l < ys.size(); l++) {
						long x1 = xs.get(i);
						long x2 = xs.get(j);
						long y1 = ys.get(k);
						long y2 = ys.get(l);
						if (num(n, ps, x1, y1, x2, y2) >= K) {
							long area = (y2 - y1) * (x2 - x1);
							if (area < minArea) {
								minArea = area;
							}
						}
					}
				}
			}
		}
		System.out.println(minArea);
	}

	static int num(int n, long[][] ps, long x1, long y1, long x2, long y2) {
		int num = 0;
		for (int i = 0; i < n; i++) {
			if (ps[i][0] >= x1 && ps[i][0] <= x2 && ps[i][1] >= y1 && ps[i][1] <= y2)
				num++;
		}
		return num;
	}

	static int[] lis(int[] s) {
		int n = s.length;
		int[] dp = new int[n];
		int[] ids = new int[n];
		int[] pids = new int[n];
		dp[0] = s[0];
		int len = 1;
		int lidx = 0;
		for (int i = 1; i < n; i++) {
			int idx = bs(s[i], dp, 0, len);
			dp[idx] = s[i];
			ids[idx] = i;
			if (idx == len) {
				lidx = i;
				len++;
			}
			if (idx > 0)
				pids[i] = ids[idx - 1];
		}
		int[] lis = new int[len];
		lis[len - 1] = s[lidx];
		for (int i = len - 1; i >= 0; i--) {
			lis[i] = s[lidx];
			lidx = pids[lidx];
		}
		return lis;
	}

	static int bs(int a, int[] as, int from, int num) {
		int min = from;
		int max = from + num - 1;
		while (min < max) {
			int mid = min + max >> 1;
			if (as[mid] < a)
				min = mid + 1;
			else if (as[mid] > a)
				max = mid;
			else
				return mid;
		}
		return as[min] < a ? min + 1 : min;
	}

	static int gcd(int x, int y) {
		x = (x ^ x >> 31) - (x >> 31);
		y = (y ^ y >> 31) - (y >> 31);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		int z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static long gcd(long x, long y) {
		x = (x ^ x >> 63) - (x >> 63);
		y = (y ^ y >> 63) - (y >> 63);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		long z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static int lcm(int x, int y) {
		x = (x ^ x >> 31) - (x >> 31);
		y = (y ^ y >> 31) - (y >> 31);
		return x / gcd(x, y) * y;
	}

	static long lcm(long x, long y) {
		x = (x ^ x >> 63) - (x >> 63);
		y = (y ^ y >> 63) - (y >> 63);
		return x / gcd(x, y) * y;
	}

