    static class DAxisParallelRectangle {
        public void solve(int testNumber, Scanner in, PrintWriter out) {

            int n = in.nextInt();
            int k = in.nextInt();
            ArrayList<GridPoint> al = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                al.add(new GridPoint(in.nextInt(), in.nextInt()));
            }

            long res = Long.MAX_VALUE;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int l = 0; l < n; l++) {
                        for (int m = 0; m < n; m++) {
