                                    yIndexes[sy] <= ys[i] && ys[i] <= yIndexes[ty]) {
                                count++;
                            }
                        }
                        if (count >= k) {
                            long area = ((long)xIndexes[tx] - xIndexes[sx]) *
                                    ((long)yIndexes[ty] - yIndexes[sy]);
                            if (area < minArea) {
                                minArea = area;
                            }
                        }
                    }
                }
            }
        }
        System.out.println(minArea);
    }

