import java.io.*;
import java.util.*;

class P {
  final long x;
  final long y;

  P(long x, long y) {
    this.x = x;
    this.y = y;
  }
}

class Solver {
  final int n, k;
  final long[] xs, ys;
  List<P> ps;

  Solver(int n, int k, long[] xs, long[] ys) {
    this.n = n;
    this.k = k;
    this.xs = xs;
    this.ys = ys;
  }

  public long solve() {
    List<P> ps = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      ps.add(new P(xs[i], ys[i]));
    }

    long minArea = Long.MAX_VALUE;
    for (P minYP : ps) {
      List<P> filteredPs1 = new ArrayList<>();
      for (P p : ps) {
        if (p.y >= minYP.y) {
          filteredPs1.add(p);
        }
      }
      if (filteredPs1.size() < k) {
        continue;
      }

      for (P maxYP : filteredPs1) {
        List<P> filteredPs2 = new ArrayList<>();
        for (P p : filteredPs1) {
          if (p.y <= maxYP.y) {
            filteredPs2.add(p);
          }
        }
        if (filteredPs2.size() < k) {
          continue;
        }

        for (P maxXP : filteredPs2) {
          PriorityQueue<Long> queue = new PriorityQueue<>();
          for (P p : filteredPs2) {
            if (p.x <= maxXP.x) {
              queue.add(p.x);
            }
          }
          if (queue.size() < k) {
            continue;
          }
          while (queue.size() > k) {
            queue.poll();
          }
          long minY = minYP.y;
          long maxY = maxYP.y;
          long maxX = maxXP.x;
          long minX = queue.peek();
          long area = (maxX - minX) * (maxY - minY);
          minArea = Math.min(minArea, area);
        }
      }
    }
    return minArea;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    long[] xs = new long[n];
    long[] ys = new long[n];
    for (int i = 0; i < n; i++) {
      xs[i] = reader.nextLong();
      ys[i] = reader.nextLong();
    }
    out.println(new Solver(n, k, xs, ys).solve());
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public String[] nextArray(int n) {
    String[] array = new String[n];
    for (int i = 0; i < n; i++) {
      array[i] = next();
    }
    return array;
  }

  public int[] nextIntArray(int n) {
    int[] array = new int[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextInt();
    }
    return array;
  }

