    static class Solver {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
    		int N = in.nextInt();
    		int K = in.nextInt();
    		long[] x = new long[N];
    		long[] y = new long[N];
    		for(int i=0; i < N; i++) {
    			x[i] = in.nextLong();
    			y[i] = in.nextLong();
    		}
    		long ans = 2000000000L * 2000000000L;
    		int cnt;
    		for(int xi=0; xi < N; xi++) {
        		for(int xj=0; xj < N; xj++) {
            		for(int yi=0; yi < N; yi++) {
                		for(int yj=0; yj < N; yj++) {
                			if(xi == xj && yi == yj)	continue;
		        			cnt = 0;
		        			for(int kk = 0; kk < N; kk++) {
		        				if((Math.min(x[xi], x[xj]) <= x[kk]) && (Math.max(x[xi], x[xj]) >= x[kk])
		                			&& (Math.min(y[yi], y[yj]) <= y[kk]) && (Math.max(y[yi], y[yj]) >= y[kk])) {
		        					cnt++;
		        				}
		        			}
		        			if(cnt == K) {
		        				ans = Math.min(ans, Math.abs(x[xi] - x[xj]) * Math.abs(y[yi] - y[yj]));
		        			}
                		}
            		}
        		}
        	}
    		out.println(ans);
        }
    }

