import java.util.Scanner;

class Main {

    int n, k;
    long[] x, y;

    void solve() {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        k = in.nextInt();
        x = new long[n];
        y = new long[n];
        for(int i = 0; i < n; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
        }
        long ans = Long.MAX_VALUE;
        for(int a = 0; a < n; a++) {
            for(int b = 0; b < n; b++) {
                for(int c = 0; c < n; c++) {
                    for(int d = 0; d < n; d++) {
                        long mx = Math.min(Math.min(x[a], x[b]), Math.min(x[c], x[d]));
                        long my = Math.min(Math.min(y[a], y[b]), Math.min(y[c], y[d]));
                        long Mx = Math.max(Math.max(x[a], x[b]), Math.max(x[c], x[d]));
                        long My = Math.max(Math.max(y[a], y[b]), Math.max(y[c], y[d]));
                        if(count(mx, my, Mx, My) >= k) {
                            ans = Math.min((Mx - mx) * (My - my), ans);
                        }
                    }
                }
            }
        }
        System.out.println(ans);
    }
    int count(long mx, long my, long Mx, long My) {
        int c = 0;
        for(int i = 0; i < n; i++) {
            if(mx <= x[i] && x[i] <= Mx && my <= y[i] && y[i] <= My) {
                c++;
            }
        }
        return c;
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private static final int INF = Integer.MAX_VALUE / 2;

    private static class Point implements Comparable<Point> {
        long x;
        long y;
        public Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
        @Override
        public boolean equals(Object o) {
            if (o instanceof Point) {
                Point that = (Point)o;
                return this.x == that.x && this.y == that.y;
            }
            return false;
        }
        @Override
        public int hashCode() {
            int hashCode = 17;
            hashCode = hashCode * 31 + Long.hashCode(x);
            hashCode = hashCode * 31 + Long.hashCode(y);
            return hashCode;
        }
        @Override
        public int compareTo(Point that) {
            if (this.x < that.x) {
                return -1;
            } else if (this.x > that.x) {
                return 1;
            } else if (this.y < that.y) {
                return -1;
            } else if (this.x > that.x) {
                return 1;
            } else {
                return 0;
            }
        }
        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    private void solve(Scanner sc) {
        int N = sc.nextInt();
        int K = sc.nextInt();
        List<Point> pList = new ArrayList<>();
        long minX = Long.MAX_VALUE;
        long minY = Long.MAX_VALUE;
        long maxX = Long.MIN_VALUE;
        long maxY = Long.MIN_VALUE;
        for (int i = 0; i < N; ++i) {
            long x = sc.nextLong();
            long y = sc.nextLong();
            pList.add(new Point(x, y));
            minX = Math.min(minX, x);
            minY = Math.min(minY, y);
            maxX = Math.max(maxX, x);
            maxY = Math.max(maxY, y);
        }

        while (pList.size() > K) {
            int cntT = 0;
            int cntB = 0;
            int cntL = 0;
            int cntR = 0;
            for (Point p : pList) {
                if (p.x == minX) { ++cntL; }
                if (p.x == maxX) { ++cntR; }
                if (p.y == minY) { ++cntB; }
                if (p.y == maxY) { ++cntT; }
            }
            int cnt = Math.max(Math.max(cntR, cntL), Math.max(cntB, cntT));
            if (cntL == cnt && pList.size() - cntL >= K) {
                for (Iterator<Point> it = pList.iterator(); it.hasNext();) {
                    Point p = it.next();
                    if (p.x == minX) {
                        it.remove();
                    }
                }
            } else if (cntR == cnt && pList.size() - cntR >= K) {
                for (Iterator<Point> it = pList.iterator(); it.hasNext();) {
                    Point p = it.next();
                    if (p.x == maxX) {
                        it.remove();
                    }
                }
            } else if (cntB == cnt && pList.size() - cntB >= K) {
                for (Iterator<Point> it = pList.iterator(); it.hasNext();) {
                    Point p = it.next();
                    if (p.y == minY) {
                        it.remove();
                    }
                }
            } else if (cntT == cnt && pList.size() - cntT >= K) {
                for (Iterator<Point> it = pList.iterator(); it.hasNext();) {
                    Point p = it.next();
                    if (p.y == maxY) {
                        it.remove();
                    }
                }
            } else {
                break;
            }
            minX = Long.MAX_VALUE;
            minY = Long.MAX_VALUE;
            maxX = Long.MIN_VALUE;
            maxY = Long.MIN_VALUE;
            for (Point p : pList) {
                minX = Math.min(minX, p.x);
                minY = Math.min(minY, p.y);
                maxX = Math.max(maxX, p.x);
                maxY = Math.max(maxY, p.y);
            }
        }

        _out.println((maxX - minX) * (maxY - minY));
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;


public class Main {

    int N,K;
    int[] x,y;

    private int cnt(int minx,int maxx,int miny,int maxy) {
        int ret = 0;
        for(int i = 0;i < N;i++) {

            if (minx <= x[i] && x[i] <= maxx && miny <= y[i] && y[i] <= maxy) {
                ret++;
            }
        }

        return ret;
    }

    private long calc(int minx,int maxx,int miny,int maxy) {
        return (long)(maxx - minx) * (long)(maxy - miny);
    }

    private void solve() {
        N = nextInt();
        K = nextInt();
        x = new int[N];
        y = new int[N];
        for(int i = 0;i < N;i++) {
            x[i] = nextInt();
            y[i] = nextInt();
        }

        long ans = Long.MAX_VALUE;

        for(int i = 0;i < N;i++) {
            for(int j = i + 1;j < N;j++) {
                int minx = Math.min(x[i],x[j]);
                int maxx = Math.max(x[i],x[j]);
                int miny = Math.min(y[i],y[j]);
                int maxy = Math.max(y[i],y[j]);

                if (cnt(minx,maxx,miny,maxy) >= K) {
                    ans = Math.min(ans,calc(minx,maxx,miny,maxy));
                }
            }
        }

        for(int i = 0;i < N;i++) {
            for(int j = i + 1;j < N;j++) {
                for(int k = j + 1;k < N;k++) {
                    int minx = Math.min(x[i],Math.min(x[j],x[k]));
                    int maxx = Math.max(x[i],Math.max(x[j],x[k]));
                    int miny = Math.min(y[i],Math.min(y[j],y[k]));
                    int maxy = Math.max(y[i],Math.max(y[j],y[k]));

                    if (cnt(minx,maxx,miny,maxy) >= K) {
                        ans = Math.min(ans,calc(minx,maxx,miny,maxy));
                    }
                }
            }
        }

        for(int i = 0;i < N;i++) {
            for(int j = i + 1;j < N;j++) {
                for(int k = j + 1;k < N;k++) {
                    for(int l = k + 1;l < N;l++) {
                        int minx = Math.min(Math.min(x[i],x[j]), Math.min(x[k],x[l]));
                        int maxx = Math.max(Math.max(x[i],x[j]), Math.max(x[k],x[l]));
                        int miny = Math.min(Math.min(y[i],y[j]), Math.min(y[k],y[l]));
                        int maxy = Math.max(Math.max(y[i],y[j]), Math.max(y[k],y[l]));

                        if (cnt(minx, maxx, miny, maxy) >= K) {
                            ans = Math.min(ans, calc(minx, maxx, miny, maxy));
                        }
                    }
                }
            }
        }

        out.println(ans);
    }
    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    /* Input */
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[4096];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (buflen <= 0)
            return false;
        return true;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if (ch >= '!' && ch <= '~')
            return true;
        return false;
    }

    private int nextByte() {
        if (!hasNextByte())
            return -1;
        return buffer[p++];
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

