        for (int lx = 0; lx < N; lx++)
        {
            for (int rx = lx + 1; rx < N; rx++)
            {
                for (int ly = 0; ly < N; ly++)
                {
                    for (int ry = ly + 1; ry < N; ry++)
                    {
                        int cou = Math.min(rx - lx + 1, ry - ly + 1);
                        if (cou >= K)
                        {
                            res = Math.min(res, (long)(x[rx] - x[lx]) * (y[ry] - y[ly]));
                        }
                    }
                }
            }
        }
        System.out.println(res);
    }

