public class Main {
  private static void solve() {
    int n = ni();
    int k = ni();
    int[][] p = ntable(n, 2);
    Arrays.sort(p, (o1, o2) -> o1[0] - o2[0]);

    long min = Long.MAX_VALUE;
    for (int i = 0; i < n; i ++) {
      for (int j = i + 1; j < n; j ++) {
        long xmin = p[i][0];
        long xmax = p[j][0];

        List<int[]> list = new ArrayList<>();
        for (int s = 0; s < n; s ++) {
          int x = p[s][0];
          if (xmin <= x && x <= xmax) {
            list.add(p[s]);
          }
        }
        Collections.sort(list, (o1, o2) -> o1[1] - o2[1]);
        int m = list.size();

        for (int s = 0; s < m; s ++) {
          if (s + k - 1 >= m) break;

          long ymin = list.get(s)[1];
          long ymax = list.get(s + k - 1)[1];

          long now = (xmax - xmin) * (ymax - ymin);
          min = Math.min(min, now);
        }
      }
    }
    System.out.println(min);
