        int[][] count = new int[N+1][N+1];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                count[i+1][j+1] = count[i][j+1] + count[i+1][j] -count[i][j] + d[i][j];
            }
