import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {
	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		long start = System.currentTimeMillis();
		int n = ir.nextInt();
		int K = ir.nextInt();
		long[] x = new long[n];
		long[] y = new long[n];
		for (int i = 0; i < n; i++) {
			x[i] = ir.nextLong();
			y[i] = ir.nextLong();
		}
		int[][] ct = new int[n][n];
		int[] cx = compress(x);
		int[] cy = compress(y);
		for (int i = 0; i < n; i++) {
			ct[cx[i]][cy[i]]++;
		}
		int[][] sum = toSumArray(ct);
		Arrays.sort(x);
		Arrays.sort(y);
		long res = Long.MAX_VALUE;
		tr(res);
		for (int i = 0; i < n; i++) {
			for (int j = n - 1; j > i; j--) {
				for (int k = 0; k < n; k++) {
					for (int l = n - 1; l > k; l--) {
						if (System.currentTimeMillis() - start >= 1900) {
							out.println(res);
							return;
						}
						if (sum(i, j + 1, k, l + 1, sum) >= K) {
							res = Math.min(res, (x[j] - x[i]) * (y[l] - y[k]));
							tr(res);
						}
					}
				}
			}
		}
		out.println(res);
	}

	public static int[] compress(long[] a) {
		int n = a.length;
		long[] r = a.clone();
		Arrays.sort(r);
		int[] ret = new int[n];
		for (int i = 0; i < n; i++)
			ret[i] = lower_bound(r, 0, n - 1, a[i]);
		return ret;
	}

	public static int lower_bound(long[] a, int fromIndex, int toIndex, long val) {
		if (val > a[toIndex])
			return toIndex + 1;
		if (val <= a[fromIndex])
			return fromIndex;
		int lb = fromIndex - 1, ub = toIndex;
		while (ub - lb > 1) {
			int mid = (ub - lb) / 2 + lb;
			if (a[mid] >= val) {
				ub = mid;
			} else {
				lb = mid;
			}
		}
		return ub;
	}

	static int sum(int a, int b, int c, int d, int[][] s) {
		return s[b][d] - s[b][c] - s[a][d] + s[a][c];
	}

	public static int[][] toSumArray(int[][] a) {
		int h = a.length, w = a[0].length;
		int[][] ret = new int[h + 1][w + 1];
		for (int i = 0; i < h; i++)
			for (int j = 0; j < w; j++)
				ret[i + 1][j + 1] = a[i][j];
		for (int i = 0; i <= h; i++)
			for (int j = 0; j < w; j++)
				ret[i][j + 1] += ret[i][j];
		for (int i = 0; i < h; i++)
			for (int j = 0; j <= w; j++)
				ret[i + 1][j] += ret[i][j];
		return ret;
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		System.err.println(Arrays.deepToString(o));
	}
}

import java.util.*;
import java.util.stream.Collectors;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		Main ins = new Main(in);
		ins.calc();
		ins.showResult();
	}

	int N, K;
	Tuple[] p;
	long result = Long.MAX_VALUE / 2;

	static class Tuple {
		long x, y;

		Tuple(String line) {
			String[] tokens = line.split(" ");
			x = Long.parseLong(tokens[0]);
			y = Long.parseLong(tokens[1]);
		}
	}

	Main(BufferedReader in) throws IOException {
		String[] tokens = in.readLine().split(" ");
		N = Integer.parseInt(tokens[0]);
		K = Integer.parseInt(tokens[1]);
		p = new Tuple[N];
		for (int i = 0; i < N; ++i) {
			p[i] = new Tuple(in.readLine());
		}
		Arrays.parallelSort(p, new Comparator<Tuple>() {
			@Override
			public int compare(Tuple o1, Tuple o2) {
				int result = Long.compare(o1.x, o2.y);
				if (result != 0) {
					return result;
				} else {
					return Long.compare(o1.y, o2.y);
				}
			}
		});
	}

	int count(Tuple p1, Tuple p2, Tuple p3, Tuple p4) {
		Tuple[] array = new Tuple[3];
		array[0] = p2;
		array[1] = p3;
		array[2] = p4;
		long minX = p1.x;
		long minY = p1.y;
		long maxX = p1.x;
		long maxY = p1.y;
		for (int i = 0; i < 3; ++i) {
			minX = Math.min(minX, array[i].x);
			minY = Math.min(minY, array[i].y);
			maxX = Math.max(maxX, array[i].x);
			maxY = Math.max(maxY, array[i].y);
		}
		int c = 0;
		for (int i = 0; i < N; ++i) {
			Tuple point = p[i];
			if (point.x >= minX && point.x <= maxX) {
				if (point.y >= minY && point.y <= maxY) {
					++c;
				}
			}
		}
		return c;
	}

	void calc() {
		for (int i = 0; i < N; ++i) {
			Tuple p1 = p[i];
			for (int j = i; j < N; ++j) {
				Tuple p2 = p[j];
				for (int k = j; k < N; ++k) {
					Tuple p3 = p[k];
					for (int l = k; l < N; ++l) {
						Tuple p4 = p[l];
						int c = count(p1, p2, p3, p4);
						if (c >= K) {
							Tuple[] array = new Tuple[3];
							array[0] = p2;
							array[1] = p3;
							array[2] = p4;
							long minX = p1.x;
							long minY = p1.y;
							long maxX = p1.x;
							long maxY = p1.y;
							for (int m = 0; m < 3; ++m) {
								minX = Math.min(minX, array[m].x);
								minY = Math.min(minY, array[m].y);
								maxX = Math.max(maxX, array[m].x);
								maxY = Math.max(maxY, array[m].y);
							}
							long val = (maxX - minX) * (maxY - minY);
							result = Math.min(result, val);
						}
					}
				}
			}
		}
	}

	void showResult() {
		System.out.println(result);
	}
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int k = sc.nextInt();

		long[][] xy = new long[n][2];
		for (int i = 0; i < n; i++) {
			xy[i][0] = sc.nextInt();
			xy[i][1] = sc.nextInt();
		}

		long answer = Long.MAX_VALUE;

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				for (int l = 0; l < n; l++) {
					for (int m = 0; m < n; m++) {
						long lx = xy[i][0];
						long hx = xy[j][0];
						long ly = xy[l][1];
						long hy = xy[m][1];
						if (lx > hx || ly > hy) continue;
						int count = 0;
						for (int o = 0; o < n; o++) {
							if (xy[o][0] >= lx && xy[o][0] <= hx
									&& xy[o][1] >= ly && xy[o][1] <= hy) {
								count++;
							}
						}
						if (count >= k) answer = Math.min(answer, (hx - lx) * (hy - ly));
					}
				}
			}
		}

		System.out.println(answer);
	}
