import java.util.Scanner;

/**
 *http://abc075.contest.atcoder.jp/tasks/abc075_d
 */
public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		final int N = sc.nextInt();
		final int K = sc.nextInt();
		Point[] points = new Point[N];
		for(int i=0; i<N; i++){
			points[i] = new Point(sc.nextLong(), sc.nextLong());
		}
		sc.close();

		long ans = Long.MAX_VALUE;

		Arrays.sort(points, new Comparator<Point>() {
			public int compare(Point p1, Point p2) {
				return p1.x - p2.x > 0 ? 1 : -1;
			}
		});
		for(int i=0; i<N-K+1; i++){
			long max = 0;
			long min = Long.MAX_VALUE;
			for(int j=i; j<i+K; j++){
				max = Math.max(max, points[j].y);
				min = Math.min(min, points[j].y);
			}
			ans = Math.min((points[i+K-1].x-points[i].x)*(max-min), ans);
		}


		Arrays.sort(points, new Comparator<Point>() {
			public int compare(Point p1, Point p2) {
				return p1.y - p2.y > 0 ? 1 : -1;
			}
		});

		for(int i=0; i<N-K+1; i++){
			long max = 0;
			long min = Long.MAX_VALUE;
			for(int j=i; j<i+K; j++){
				max = Math.max(max, points[j].x);
				min = Math.min(min, points[j].x);
			}
			ans = Math.min((points[i+K-1].y-points[i].y)*(max-min), ans);
		}

		System.out.println(ans);

	}

	static class Point{
		public Point(long x, long y) {
			this.x = x;
			this.y = y;
		}
		long x;
		long y;
	}

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {
	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		long start = System.currentTimeMillis();
		int n = ir.nextInt();
		int K = ir.nextInt();
		long[] x = new long[n];
		long[] y = new long[n];
		for (int i = 0; i < n; i++) {
			x[i] = ir.nextLong();
			y[i] = ir.nextLong();
		}
		int[][] ct = new int[n][n];
		int[] cx = compress(x);
		int[] cy = compress(y);
		for (int i = 0; i < n; i++) {
			ct[cx[i]][cy[i]]++;
		}
		int[][] sum = toSumArray(ct);
		Arrays.sort(x);
		Arrays.sort(y);
		long res = Long.MAX_VALUE;
		tr(res);
		for (int i = 0; i < n; i++) {
			for (int j = i; j < n; j++) {
				for (int k = 0; k < n; k++) {
					for (int l = k; l < n; l++) {
						if (System.currentTimeMillis() - start >= 1950) {
							out.println(res);
							return;
						}
						if (sum(i, j + 1, k, l + 1, sum) >= K) {
							res = Math.min(res, (x[j] - x[i]) * (y[l] - y[k]));
							tr(res);
						}
					}
				}
			}
		}
		out.println(res);
	}

	public static int[] compress(long[] a) {
		int n = a.length;
		long[] r = a.clone();
		Arrays.sort(r);
		int[] ret = new int[n];
		for (int i = 0; i < n; i++)
			ret[i] = lower_bound(r, 0, n - 1, a[i]);
		return ret;
	}

	public static int lower_bound(long[] a, int fromIndex, int toIndex, long val) {
		if (val > a[toIndex])
			return toIndex + 1;
		if (val <= a[fromIndex])
			return fromIndex;
		int lb = fromIndex - 1, ub = toIndex;
		while (ub - lb > 1) {
			int mid = (ub - lb) / 2 + lb;
			if (a[mid] >= val) {
				ub = mid;
			} else {
				lb = mid;
			}
		}
		return ub;
	}

	static int sum(int a, int b, int c, int d, int[][] s) {
		return s[b][d] - s[b][c] - s[a][d] + s[a][c];
	}

	public static int[][] toSumArray(int[][] a) {
		int h = a.length, w = a[0].length;
		int[][] ret = new int[h + 1][w + 1];
		for (int i = 0; i < h; i++)
			for (int j = 0; j < w; j++)
				ret[i + 1][j + 1] = a[i][j];
		for (int i = 0; i <= h; i++)
			for (int j = 0; j < w; j++)
				ret[i][j + 1] += ret[i][j];
		for (int i = 0; i < h; i++)
			for (int j = 0; j <= w; j++)
				ret[i + 1][j] += ret[i][j];
		return ret;
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		System.err.println(Arrays.deepToString(o));
	}
}

import java.util.*;
public class Main {

  public static void main(String[] args) { 
      Scanner sc = new Scanner(System.in);
      int n = sc.nextInt();
      int k = sc.nextInt();
      long[][] cood = new long[n][2];
      for(int i = 0; i < n; i++) {
        cood[i][0] = sc.nextInt();
        cood[i][1] = sc.nextInt();
      }

      long maxArea = Long.MAX_VALUE;
      int cnt = 0;

      for(long[] a : cood) {
        for(long[] b : cood) {
          long downY = Math.min(a[1], b[1]), upY = Math.max(a[1], b[1]);
          for(long[] c : cood) {
              long leftX = Math.min(Math.min(a[0], b[0]), c[0]), 
                  rightX = Math.max(Math.max(a[0], b[0]), c[0]);
              cnt = 0;
              for(long[] p : cood) {
                if(leftX <= p[0] && p[0] <= rightX &&
                  downY <= p[1] && p[1] <= upY
                ) cnt++;
              }
              if(cnt >= k) {
                maxArea = Math.min(maxArea, (rightX - leftX) * (upY - downY));
              }
          }
        }
      }
      System.out.println(maxArea);
  }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        int K = Integer.parseInt(sc.next());
        long INF = 5_000_000_000_000_000_000L;
        ArrayList<int[]> point_x = new ArrayList<int[]>();
        Comparator<int[]> comparator_x = new Comparator<int[]>() {
            @Override
            public int compare(int[] o1, int[] o2) {
                return Integer.compare(o1[0], o2[0]);
            }
        };
        Comparator<int[]> comparator_y = new Comparator<int[]>() {
            @Override
            public int compare(int[] o1, int[] o2) {
                return Integer.compare(o1[1], o2[1]);
            }
        };
        for (int i=0;i<N;i++) {
            int x = Integer.parseInt(sc.next());
            int y = Integer.parseInt(sc.next());
            int[] add = {x, y, i};
            point_x.add(add);
        }
        ArrayList<int[]> point_y = new ArrayList<int[]>(point_x);
        Collections.sort(point_x, comparator_x);
        Collections.sort(point_y, comparator_y);
        // for (int[] array : point_x) {
        //     System.out.println("x " + Arrays.toString(array));
        // }
        // for (int[] array : point_y) {
        //     System.out.println("y " + Arrays.toString(array));
        // }
        long ans = INF;
        for (int wid=2;wid<=K;wid++) {
            for (int i=0;i+wid<=N;i++) {
                int[] flag = new int[N];
                for (int j=i;j<i+wid;j++) {
                    flag[point_x.get(j)[2]]=1;
                }
                for (int j=0;j+wid<=N;j++) {
                    int cnt=0;
                    for (int k=j;k<j+wid;k++) {
                        // System.out.println("k wid " + k + " " + wid);
                        if (flag[point_y.get(k)[2]]==1) {
                            cnt++;
                        }
                    }
                    if (cnt>=K) {
                        ans = Math.min(ans, (long)(point_x.get(i+wid-1)[0]-point_x.get(i)[0])*(point_y.get(j+wid-1)[1]-point_y.get(j)[1]));
                    }
                }
            }
        }
        System.out.println(ans);
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String args[]) {
        try (Scanner in = new Scanner(System.in)) {

            int N = in.nextInt();
            int K = in.nextInt();

            long[] x = new long[N];
            long[] y = new long[N];
            for (int i = 0; i < N; i++) {
                x[i] = in.nextInt();
                y[i] = in.nextInt();
            }

            long area = Long.MAX_VALUE;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (j == i) {
                        continue;
                    }
                    int count = 0;
                    for (int k = 0; k < N; k++) {
                        if (isInside(x[i], y[i], x[j], y[j], x[k], y[k])) {
                            count++;
                        }
                    }
                    if (count >= K) {
                        area = Math.min(area, Math.abs(x[i] - x[j]) * Math.abs(y[i] - y[j]));
                    }
                }
            }

            System.out.println(area);
        }
    }

    private static boolean isInside(long xi, long yi, long xj, long yj, long xk, long yk) {
        if (xk < Math.min(xi, xj) || xk > Math.max(xi, xj)) {
            return false;
        }
        if (yk < Math.min(yi, yj) || yk > Math.max(yi, yj)) {
            return false;
        }
        return true;
    }
}

