public sealed partial class Program
{
    int n, k;
    Tuple<long, long>[] ps;
    long[] xs;
    long[] ys;

    long[] Gen(Func<Tuple<long, long>, long> selector)
    {
        return
            ps
            .Select(selector)
            .Distinct()
            .OrderBy(x => x)
            .ToArray();
    }

    long Solve()
    {
        xs = Gen(p => p.Item1);
        ys = Gen(p => p.Item2);

        var min = long.MaxValue;

        for (var yl = 0; yl < ys.Length; yl++)
        {
            for (var yr = yl + 1; yr < ys.Length; yr++)
            {
                for (var xl = 0; xl < xs.Length; xl++)
                {
                    for (var xr = xl + 1; xr < xs.Length; xr++)
                    {
                        var count = 0;

                        foreach (var p in ps)
                        {
                            var x = p.Item1;
                            var y = p.Item2;
                            if (xs[xl] <= x && x <= xs[xr] && ys[yl] <= y && y <= ys[yr])
                            {
                                count++;
                                if (count >= k)
                                {
                                    var size = (xs[xr] - xs[xl]) * (ys[yr] - ys[yl]);
                                    min = Math.Min(min, size);
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }

        return min;
