        static void Main() {
            var Key = getKeys(' ');
            long N = Key[0];
            long K = Key[1];
            List<Position> Pos = new List<Position>();
            long Max_X = -1000000000;
            long Min_X = 1000000000;
            long Max_Y = -1000000000;
            long Min_Y = 1000000000;
            for (int i = 0; i < N; i++) {
                Key = getKeys(' ');
                Max_X = Math.Max(Max_X, Key[0]);
                Min_X = Math.Min(Min_X, Key[0]);
                Max_Y = Math.Max(Max_Y, Key[1]);
                Min_Y = Math.Min(Min_Y, Key[1]);
                Pos.Add(new Position(Key[0], Key[1]));
            }
            Rect rect = new Rect(new Position(Min_X, Min_Y), new Position(Max_X, Max_Y));
            long MinArea = rect.Area;
            Queue<Rect> rects = new Queue<Rect>();
            rects.Enqueue(rect);
            while (rects.Count > 0) {
                rect = rects.Dequeue();
                //上下左右の方向にトリミングする。
                //トリミング後もK個以上の点を含んでいればキューに入れて最小面積も更新する。
                var r = Trimmed(rect, Direction.Up, Pos);
                if (r != null && CountInside(r, Pos) >= K) {
                    rects.Enqueue(r);
                    MinArea = Math.Min(MinArea, r.Area);
                }
                r = Trimmed(rect, Direction.Down, Pos);
                if (r != null && CountInside(r, Pos) >= K) {
                    rects.Enqueue(r);
                    MinArea = Math.Min(MinArea, r.Area);
                }
                r = Trimmed(rect, Direction.Right, Pos);
                if (r != null && CountInside(r, Pos) >= K) {
                    rects.Enqueue(r);
                    MinArea = Math.Min(MinArea, r.Area);
                }
                r = Trimmed(rect, Direction.Left, Pos);
                if (r != null && CountInside(r, Pos) >= K) {
                    rects.Enqueue(r);
                    MinArea = Math.Min(MinArea, r.Area);
                }
            }
            Console.WriteLine(MinArea);
        }
        enum Direction {Up,Down,Left,Right};
        static int CountInside(Rect rect, List<Position> positions) {
            int count = 0;
            long Left = rect.LowerLeft.X;
            long Right = rect.UpperRight.X;
            long Bottom = rect.LowerLeft.Y;
            long Top = rect.UpperRight.Y;
            for (int i = 0; i < positions.Count; i++) {
                if (Left <= positions[i].X && positions[i].X <= Right && Bottom <= positions[i].Y && positions[i].Y <= Top) {
                    count++;
                }
            }
            return count;
        }
        //指定した方向にRectを狭めていく。これ以上狭くならない場合はnull
        static Rect Trimmed(Rect rect, Direction direction, List<Position> positions) {
            Rect trimmed = new Rect(rect.LowerLeft, rect.UpperRight);
            switch (direction) {
                case Direction.Up://天井を狭める。
                    positions.Sort((x, y) => (int)(y.Y - x.Y));
                    for (int i = 0; i < positions.Count; i++) {
                        if (positions[i].Y < trimmed.UpperRight.Y) {
                            trimmed.UpperRight.Y = positions[i].Y;
                            return trimmed;
                        }
                    }
                    break;
                case Direction.Down:
                    positions.Sort((x, y) => (int)(x.Y - y.Y));
                    for (int i = 0; i < positions.Count; i++) {
                        if (positions[i].Y > trimmed.LowerLeft.Y) {
                            trimmed.LowerLeft.Y = positions[i].Y;
                            return trimmed;
                        }
                    }
                    break;
                case Direction.Left://右から左へ
                    positions.Sort((x, y) => (int)(y.X - x.X));
                    for (int i = 0; i < positions.Count; i++) {
                        if (positions[i].X < trimmed.UpperRight.X) {
                            trimmed.UpperRight.X = positions[i].X;
                            return trimmed;
                        }
                    }
                    break;
                case Direction.Right:
                    positions.Sort((x, y) => (int)(x.X - y.X));
                    for (int i = 0; i < positions.Count; i++) {
                        if (positions[i].X > trimmed.LowerLeft.X) {
                            trimmed.LowerLeft.X = positions[i].X;
                            return trimmed;
                        }
                    }
                    break;
                default:
                    break;
            }
            return null;
        }
    }
    class Rect {
        public Position LowerLeft;
        public Position UpperRight;
        public Rect(Position ll, Position ur) {
            LowerLeft = new Position(ll.X, ll.Y);
            UpperRight = new Position(ur.X, ur.Y);
        }
        public long Area {
            get { return (UpperRight.X - LowerLeft.X) * (UpperRight.Y - LowerLeft.Y); }
        }
        public override string ToString() {
            return "(" + LowerLeft.X + "," + UpperRight.Y + ")" + "-------------------(" + UpperRight.X + "," + UpperRight.Y + ")\n" +
                        "(" + LowerLeft.X + "," + LowerLeft.Y + ")" + "-------------------(" + UpperRight.X + "," + LowerLeft.Y + ")";
        }
    }
    class Position {
        public long X;
        public long Y;
        public override string ToString() {
            return "(" + X + "," + Y + ")";
        }
        public Position(long x,long y) {
            X = x;
            Y = y;
        }
