class Magatro
{
    private int N, K;
    private int[] X, Y;
    private void Scan()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        K = sc.NextInt();
        X = new int[N];
        Y = new int[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = sc.NextInt();
            Y[i] = sc.NextInt();
        }
    }

    private long Ans(int i, int j, int k, int l)
    {
        int MaxX = Math.Max(X[i], Math.Max(X[j], Math.Max(X[k], X[l])));
        int MinX = Math.Min(X[i], Math.Min(X[j], Math.Min(X[k], X[l])));
        int MaxY = Math.Max(Y[i], Math.Max(Y[j], Math.Max(Y[k], Y[l])));
        int MinY = Math.Min(Y[i], Math.Min(Y[j], Math.Min(Y[k], Y[l])));
        int cnt = 0;
        for (int n = 0; n < N; n++)
        {
            bool a = MinX <= X[n] && X[n] <= MaxX;
            bool b = MinY <= Y[n] && Y[n] <= MaxY;
            if (a && b)
            {
                cnt++;
            }
        }
        if (cnt >= K)
        {
            return (long)(MaxX - MinX) * (MaxY - MinY);
        }
        return long.MaxValue;
    }




    public void Solve()
    {
        Scan();

        long ans = long.MaxValue;
        for (int i = 0; i < N; i++)
        {
            for (int j = i; j < N; j++)
            {
                for (int k = j; k < N; k++)
                {
                    for (int l = k; l < N; l++)
                    {
                        ans = Math.Min(ans, Ans(i, j, k, l));
                    }
                }
            }
        }
        Console.WriteLine(ans);
    }

    static public void Main()
    {
        new Magatro().Solve();

    }
}

