// ref. http://codingmelon.com/2015/12/17/range-sum-query-2d-mutable-leetcode-308/
class FenwickTree2D
{
    private int[,] _tree, _ma;

    public FenwickTree2D(int h, int w)
    {
        _tree = new int[h + 1, w + 1];
        _ma = new int[h + 1, w + 1];
    }

    public void Update(int row, int col, int val)
    {
        var delta = val - _ma[row, col];
        _ma[row, col] = val;
        for (var i = row + 1; i <= _ma.GetLength(0); i += i & (-i))
            for (var j = col + 1; j <= _ma.GetLength(1); j += j & (-j)) _tree[i, j] += delta;
    }

    public int SumRegion(int row1, int col1, int row2, int col2)
        => Sum(row2, col2) + Sum(row1 - 1, col1 - 1) - Sum(row2, col1 - 1) - Sum(row1 - 1, col2);

    private int Sum(int row, int col)
    {
        var sol = 0;
        for (var i = row + 1; i > 0; i -= i & (-i))
            for (var j = col + 1; j > 0; j -= j & (-j)) sol += _tree[i, j];
        return sol;
    }
}

static class Program
{
    public static void Main()
    {
        var sw = new StreamWriter(OpenStandardOutput()) { NewLine = "\n" };
#if DEBUG
        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO());
        Out.Flush();
    }

    static void Solve(IO io)
    {
        var n = io.I;
        var k = io.I;
        var x = new long[n];
        var y = new long[n];

        for (var i = 0; i < n; i++)
        {
            x[i] = io.L;
            y[i] = io.L;
        }

        var px = new long[n];
        var py = new long[n];

        var rpx = new Dictionary<long, int>(n);
        var rpy = new Dictionary<long, int>(n);

        {
            var x_ = x.OrderBy(t => t).ToArray();
            var y_ = y.OrderBy(t => t).ToArray();

            for (var i = 0; i < n; i++)
            {
                rpx[px[i] = x_[i]] = i;
                rpy[py[i] = y_[i]] = i;
            }
        }

        var ft = new FenwickTree2D(n, n);
        for (var i = 0; i < n; i++)
            ft.Update(rpx[x[i]], rpy[y[i]], 1);

        var ans = long.MaxValue;

        for (var i = 0; i < n - 1; i++)
            for (var j = i + 1; j < n; j++)
                for (var l = 0; l < n - 1; l++)
                    for (var m = l + 1; m < n; m++)
                        if (ft.SumRegion(i, l, j, m) >= k)
                            ans = Min(ans, (px[j] - px[i]) * (py[m] - py[l]));

        io.Write(ans);
    }
}

