using System;
class Program{
	static int[] s;
	static long x=0,y=0;
	static void Main(){
		s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		long[][] arr=new long[s[0]][];
		long[,] m=new long[s[0],2];
		long ans=long.MaxValue;
		for(int i=0;i<s[0];i++){
			arr[i]=Array.ConvertAll(Console.ReadLine().Split(),long.Parse);
			m[i,0]=arr[i][0];
			m[i,1]=arr[i][1];
		}
		for(int i=0;i<s[0];i++){
			x=m[i,0];
			y=m[i,1];
			Array.Sort(arr,ca);
			long a=long.MaxValue,b=long.MaxValue,c=long.MinValue,d=long.MinValue;
			for(int j=0;j<s[1];j++){
				a=Math.Min(arr[j][0],a);
				b=Math.Min(arr[j][1],b);
				c=Math.Max(arr[j][0],c);
				d=Math.Max(arr[j][1],d);
			}
			ans=Math.Min(ans,(c-a)*(d-b));
		}
		Console.WriteLine("{0}",ans);
	}
	static int ca(long[] a,long[] b){
		if(Math.Abs(x-a[0])+Math.Abs(y-a[1])>Math.Abs(x-b[0])+Math.Abs(y-b[1])){return 1;}
		else if(Math.Abs(x-a[0])+Math.Abs(y-a[1])<Math.Abs(x-b[0])+Math.Abs(y-b[1])){return -1;}
		else{return 0;}
	}
}

using System;
using System.Text;
using System.Collections.Generic;
using static System.Math;
using System.Linq;
using static System.Array;

namespace AtcoderExpress
{


    class Program
    {

        static void Main(string[] args)
        {
            var NK = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            var N = NK[0];
            var K = NK[1];
            var points = new List<Tuple<long, long>>();
            for (int i = 0; i < N; i++)
            {
                var XY = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
                var X = XY[0];
                var Y = XY[1];
                points.Add(new Tuple<long, long>(X, Y));
            }

            //X座標でのソート
            points = points.OrderBy(tuple => tuple.Item1).ToList();
            var ans = long.MaxValue;
            //左端を1番目からN-1番目まで動かす
            for (int i = 0; i < N; i++)
            {
                //右端の範囲を設定
                for (int j = i; j < N; j++)
                {
                    var left = points[i];
                    var right = points[j];

                    long xmin = Min(left.Item1, right.Item1);
                    long xmax = Max(left.Item1, right.Item1);
                    long ymin = Min(left.Item2, right.Item2);
                    long ymax = Max(left.Item2, right.Item2);

                    //y座標の高さの決定
                    for (int m = i; m <= j; m++)
                    {
                        var yza = points[m];
                        ymin = Min(ymin, yza.Item2);
                        ymax = Max(ymax, yza.Item2);
                        long rec = (xmax - xmin) * (ymax - ymin);
                        //y座標の範囲にK個以上座標があるかどうかの検索
                        var CumPoint = 0L;
                        for (int k = i; k <= j; k++)
                        {
                            if (points[k].Item2 <= ymax && points[k].Item2 >= ymin)
                            {
                                CumPoint++;
                            }
                        }

                        if (CumPoint >= K && rec < ans)
                        {
                            ans = rec;
                        }
                    }

                }
            }
            Console.WriteLine(ans);
        }


    }
}

