			SortedList<P<ll,ll>,ll> yl = new SortedList<P<ll, ll>, ll>(Comparer<P<ll, ll>>.Create((x,y)=>x.B.CompareTo(y.B)));
			for (int i = 0; i < n; i++)
			{
