public class CumulativeSum2D {
	private long[][] _data, _lazyadd;
	private int _lazyix, _lazyiy;

	public CumulativeSum2D(long sizeX, long sizeY){
		_data = new long[sizeX+1][];
		_lazyadd = new long[sizeX][];
		for(int i=0;i<sizeX;i++) {
			_data[i] = new long[sizeY+1];
			_lazyadd[i] = new long[sizeY];
		}
		_data[sizeX] = new long[sizeY+1];
		_lazyix = _lazyadd.Length;
		_lazyiy = _lazyadd[0].Length;
	}
	public CumulativeSum2D(long[][] val) : this(val.Length, val[0].Length){
		for(int i=0;i<val.Length;i++) for(int j=0;j<val[i].Length;j++) 
			_data[i+1][j+1] = val[i][j]+_data[i][j+1]+_data[i+1][j]-_data[i][j];
	}
	public void Add(long kx, long ky, long val){
		for(int i=(int)kx+1;i<_data.Length;i++) for(int j=(int)ky+1;j<_data[i].Length;j++) 
			_data[i][j] += val;
	}
	public void AddLazy(long kx, long ky, long val) {
		if(kx<_lazyix) _lazyix = (int)kx;
		if(ky<_lazyiy) _lazyiy = (int)ky;
		_lazyadd[kx][ky] += val;
	}
	private void build(){
		if(_lazyadd.Length<=_lazyix && _lazyadd[0].Length<=_lazyiy) return;
		long[] lz1d = new long[_lazyadd[0].Length];
		for(int i=_lazyix+1;i<_data.Length;i++) {
			long lzsum = 0;
			for(int j=_lazyiy+1;j<_data[i].Length;j++) {
				lzsum += _lazyadd[i-1][j-1];
				lz1d[j-1] += lzsum;
				_data[i][j] += lz1d[j-1];
				_lazyadd[i-1][j-1] = 0;
			}
		}
		_lazyix = _lazyadd.Length;
		_lazyiy = _lazyadd[0].Length;
	}
	public long Sum(long kx, long ky) {
		build();
		return _data[kx+1][ky+1];
	}
	// 閉開区間[x1:x2),[y1:y2)で囲まれた長方形エリアの累積和を計算
	public long Sum(long x1, long y1, long x2, long y2) {
		build();
		return (_data[x2][y2]-_data[x1][y2]-_data[x2][y1]+_data[x1][y1]);
	}

}
















