using System;
using System.Linq;

class Program
{
    static int N;
    static int K;
    static int[] x;
    static int[] y;

    static void Main()
    {
        /* 入力の受け取り */
        int[] input = Console.ReadLine().Split().Select(int.Parse).ToArray();
        N = input[0];
        K = input[1];
        x = new int[N];
        y = new int[N];
        for (int i = 0; i < N; i++)
        {
            input = Console.ReadLine().Split().Select(int.Parse).ToArray();
            x[i] = input[0];
            y[i] = input[1];
        }

        /* a,c in xかつb,d in y の場合を全探索 */
        long ans = long.MaxValue;
        foreach (var a in x)
        {
            foreach (var c in x)
            {
                foreach (var b in y)
                {
                    foreach (var d in y)
                    {
                        if (Judge(a, b, c, d))
                            ans = Math.Min(ans, (long)(c - a) * (b - d));
                    }
                }
            }
        }
        Console.WriteLine(ans);
    }

    /* 左上の座標が(a,b), 右下の座標が(c,d)の長方形が、K個以上の点を含むか */
    static bool Judge(int a, int b, int c, int d)
    {
        if (a >= c || d >= b) return false;
        int count = 0;
        for (int i = 0; i < N; i++)
        {
            int xi = x[i];
            int yi = y[i];
            if (a <= xi && xi <= c && d <= yi && yi <= b)
                count++;
        }
        if (count >= K) return true;
        return false;
    }
}

