class Program
{
    static void Main()
    {
        //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        new Program().solve();
        Out.Flush();
    }
    Scanner cin = new Scanner();
    readonly int[] dd = { 0, 1, 0, -1, 0 };
    readonly int mod = 1000000007;
    readonly string alfa = "abcdefghijklmnopqrstuvwxyz";
    readonly string ALFA = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    int N, K;
    void solve()
    {
        N = cin.nextint;
        K = cin.nextint;
        var X = new int[N];
        var Y = new int[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = cin.nextint;
            Y[i] = cin.nextint;
        }
        Array.Sort(X, Y);
        var ans = long.MaxValue;
        if (K == 2)
        {
            for (int i = 0; i < N; i++)
            {
                for (int j = i + 1; j < N; j++)
                {
                    ans = Math.Min(ans, (long)(X[j] - X[i]) * Math.Abs(Y[j] - Y[i]));
                }
            }
        }
        if (K == 3)
        {
            for (int i = 0; i < N; i++)
            {
                for (int j = i + 1; j < N; j++)
                {
                    for (int k = j + 1; k < N; k++)
                    {
                        int lx = X[i];
                        int rx = X[k];
                        int hy = Math.Min(Math.Min(Y[i], Y[j]), Y[k]);
                        int ly = Math.Max(Math.Max(Y[i], Y[j]), Y[k]);
                        ans = Math.Min(ans, (long)(rx - lx) * (ly - hy));
                    }
                }
            }

        }


        if (K >= 4)
        {

            for (int i = 0; i < N; i++)
            {
                for (int j = i + 1; j < N; j++)
                {
                    for (int k = j + 1; k < N; k++)
                    {
                        for (int l = k + 1; l < N; l++)
                        {
                            int lx = X[i];
                            int rx = X[l];
                            int hy = Math.Min(Math.Min(Y[i], Y[j]), Math.Min(Y[k], Y[l]));
                            int ly = Math.Max(Math.Max(Y[i], Y[j]), Math.Max(Y[k], Y[l]));
                            int cnt = 0;
                            for (int r = 0; r < N; r++)
                            {
                                if (lx <= X[r] && X[r] <= rx && hy <= Y[r] && Y[r] <= ly)
                                {
                                    cnt++;
                                }
                            }
                            if (cnt >= K)
                            {
                                ans = Math.Min(ans, (long)(rx - lx) * (ly - hy));
                            }
                        }
                    }
                }
            }

        }
        WriteLine(ans);

    }

}

