class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;



    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int K = cin.nextInt();
        int[] x = new int[N];
        int[] y = new int[N];
        for (int i = 0; i < N; i++)
        {
            x[i] = cin.nextInt();
            y[i] = cin.nextInt();
        }

        long ans = long.MaxValue;

        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                for (int k = 0; k < N; k++)
                {
                    for (int l = 0; l < N; l++)
                    {
                        int minx = x[i];
                        int miny = y[j];
                        int maxx = x[k];
                        int maxy = y[l];
                        if (minx > maxx) continue;
                        if (miny > maxy) continue;
                        long S = (long)(maxx - minx) * (long)(maxy - miny);
                        if (ans <= S) continue;

                        int tmp = 0;
                        for (int p = 0; p < N; p++)
                        {
                            if (x[p] <= maxx && x[p] >= minx && y[p] <= maxy && y[p] >= miny) tmp++;
                        }
                        if (tmp >= K) ans = S;
                    }
                }
            }
        }
        Console.WriteLine(ans);
    }
}



