using System.Linq;
using static Input;

public class Prog
{
    private const int INF = 1000000007;
    private const long INFINITY = 9223372036854775807;
    public static void Main()
    {
        int N = NextInt();
        int K = NextInt();
        long[] x = new long[N];
        long[] y = new long[N];
        for (int i = 0; i < N; i++)
        {
            x[i] = NextInt();
            y[i] = NextInt();
        }
        long ans = INFINITY;
        for (int i = 0; i < N; i++)
        {
            //始点選択
            int count = 1;
            bool[] done = Enumerable.Repeat(true, N).ToArray();
            done[i] = false;
            //現時点での地点
            long x1 = x[i];
            long x2 = x[i];
            long y1 = y[i];
            long y2 = y[i];
            while (count != K)
            {
                int k = 0;
                long min = INFINITY;
                for (int j = 0; j < N; j++)
                {
                    if (!done[j]) continue;
                    //使う場合のRect計算
                    long xi = Math.Min(x1, x[j]);
                    long xa = Math.Max(x2, x[j]);
                    long yi = Math.Min(y1, y[j]);
                    long ya = Math.Max(y2, y[j]);
                    long r = (xa - xi) * (ya - yi);
                    if (r < min) { min = r; k = j; }
                }
                done[k] = false;
                x1 = Math.Min(x1, x[k]);
                x2 = Math.Max(x2, x[k]);
                y1 = Math.Min(y1, y[k]);
                y2 = Math.Max(y2, y[k]);
                count++;
            }
            long rect = (x2 - x1) * (y2 - y1);
            ans = Math.Min(ans, rect);
        }
        Console.WriteLine(ans);
    }
}

