public class D
{
	public static void Main()
	{
		string[] args;

		args = Console.ReadLine().Split(' ');
		int N = Int32.Parse(args[0]);
		int K = Int32.Parse(args[1]);

		List<Pair> pairs = new List<Pair>(N);
		List<long> xRank = new List<long>(N);
		List<long> yRank = new List<long>(N);
		for(int i = 0; i < N; i++)
		{
			args = Console.ReadLine().Split(' ');
			long x = Int64.Parse(args[0]);
			long y = Int64.Parse(args[1]);
			pairs.Add(new Pair(x,y));
			xRank.Add(x);
			yRank.Add(y);
		}
		xRank.Sort();
		yRank.Sort();

		int[,] plot = new int[N+1,N+1];
		foreach(Pair pair in pairs)
		{
			int ix = xRank.BinarySearch(pair.X) + 1;
			int iy = yRank.BinarySearch(pair.Y) + 1;
			plot[ix,iy] = 1;
		}			

		int[,] csum = new int[N+1,N+1];
		for(int iy = 1; iy <= N; iy++)
			for(int ix = 1; ix <= N; ix++)
				csum[ix,iy] += csum[ix-1,iy] + plot[ix,iy];

		for(int iy = 1; iy <= N; iy++)
			for(int ix = 1; ix <= N; ix++)
				csum[ix,iy] += csum[ix,iy-1];

		long minArea = Int64.MaxValue;
		for(int ilx = 1; ilx <= N - 1; ilx++)
		{
			long lx = xRank[ilx - 1];
			for(int irx = ilx + 1; irx <= N; irx++)
			{
				long rx = xRank[irx - 1];
				for(int idy = 1; idy <= N - 1; idy++)
				{
					long dy = yRank[idy - 1];
					for(int iuy = idy + 1; iuy <= N; iuy++)
					{
						long uy = yRank[iuy - 1];
						int numVertices = 
							csum[irx,iuy] + csum[ilx-1, idy-1] - 
							csum[ilx-1,iuy] - csum[irx,idy-1];
						if(numVertices < K)
							continue;

						long area = (rx - lx) * (uy - dy);
						minArea = Math.Min(minArea, area);
					}
				}
			}
		}

		Console.WriteLine(minArea);
	}
}

