    public static long getMin(long[] a, int k)
    {
        var aL = new List<long>();
        var n = a.Length;
        Array.Sort(a);
        for (int i = 0; i <= n - k; i++)
            aL.Add(a[i + k - 1] - a[i]);
        return aL.Min();
    }
