                Int64 x = (Int64)int.Parse(s[0]);
                PointXs.Add( x );
                xList.Add(x);
                Int64 y = (Int64)int.Parse(s[1]);
                PointYs.Add( y );
                yList.Add(y);
            }

            //座標をソート
            xList.Sort();
            yList.Sort();

            UInt64 minArea = UInt64.MaxValue;
            for(int xi = 0; xi < N; ++xi)//矩形の端点のx座標について.
            {
                for (int xj = xi+1; xj < N; ++xj)//もう一方の端点のx座標について
                {
                    var lx = xList[xi];//矩形の左のX座標
                    var rx = xList[xj];//右

                    for (int yi = 0; yi < N; ++yi)//矩形の端点のy座標について
                    {
                        for (int yj = yi+1; yj < N; ++yj)//もう一方の端点のy座標について
                        {
                            var by = yList[yi];//下
                            var uy = yList[yj];//上

                            //その矩形が内包する点の数を計算
                            int num = 0;
                            for(int i = 0; i < N; ++i)
                            {
                                if(lx <= PointXs[i] && PointXs[i] <= rx &&
                                   by <= PointYs[i] && PointYs[i] <= uy)
                                {
                                    ++num;
                                }
                            }

                            if(num >= K)
                            {
                                UInt64 area = (UInt64)((rx - lx) * (uy - by));
                                minArea = Math.Min(minArea, area);
                            }
                        }
                    }
                }
            }
            Console.WriteLine("{0}",minArea);
        }
    }
