	public class Program
	{
		static void Main(string[] args)
		{
			var nk = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nk[0];
			int k = nk[1];
			var positions = new XY[n];
			for (int i = 0; i < n; i++) {
				var xy = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
				positions[i] = new XY { X = xy[0], Y = xy[1] };
			}

			long ans = long.MaxValue;
			for (int x = 0; x < n; x++) {
				for (int y = 0; y < n; y++) {
					for (int x2 = 0; x2 < n; x2++) {
						if (x == x2) {
							continue;
						}

						for (int y2 = 0; y2 < n; y2++) {
							if (y == y2) {
								continue;
							}


							long left = positions[x].X < positions[x2].X 
								? positions[x].X : positions[x2].X;
							long right = positions[x].X < positions[x2].X
								? positions[x2].X : positions[x].X;
							long bottom = positions[y].Y < positions[y2].Y
								? positions[y].Y : positions[y2].Y;
							long top = positions[y].Y < positions[y2].Y
								? positions[y2].Y : positions[y].Y;
							int count = 0;
							for (int i = 0; i < n; i++) {
								var pos = positions[i];
								if (pos.X >= left && pos.X <= right && pos.Y >= bottom && pos.Y <= top) {
									++count;
								}
							}

							if (count >= k) {
								long area = (right - left) * (top - bottom);
								ans = Math.Min(ans, area);
							}
						}
					}
				}
			}

			Console.WriteLine(ans);
		}

