namespace ABC
{
    class ABC075D
    {
        static void Main(string[] args)
        {
            string[] str = Console.ReadLine().Split(' ');
            int N = int.Parse(str[0]);//全点数
            int K = int.Parse(str[1]);//包含してほしい点数
            var PointXs = new List<UInt64>(N);
            var PointYs = new List<UInt64>(N);
            for (int i = 0; i < N; ++i)
            {
                string[] s = Console.ReadLine().Split(' ');
                PointXs.Add( (UInt64)int.Parse(s[0]) );
                PointYs.Add( (UInt64)int.Parse(s[1]) );
            }

            UInt64 minArea = UInt64.MaxValue;
            for(int xi = 0; xi < PointXs.Count; ++xi)//矩形の端点のx座標について.
            {
                for (int xj = xi+1; xj < PointXs.Count; ++xj)//もう一方の端点のx座標について
                {
                    var _lx = PointXs[xi];
                    var _rx = PointXs[xj];

                    UInt64 lx = Math.Min(_lx, _rx);//矩形の左のX座標
                    UInt64 rx = Math.Max(_lx, _rx);//右

                    for (int yi = 0; yi < PointYs.Count; ++yi)//矩形の端点のy座標について
                    {
                        for (int yj = yi+1; yj < PointYs.Count; ++yj)//もう一方の端点のy座標について
                        {
                            var _by = PointYs[yi];
                            var _uy = PointYs[yj];
                            UInt64 by = Math.Min(_by, _uy);//下
                            UInt64 uy = Math.Max(_by, _uy);//上

                            //その矩形が内包する点の数を計算
                            int num = 0;
                            for(int i = 0; i < N; ++i)
                            {
                                if(lx <= PointXs[i] && PointXs[i] <= rx && by <= PointYs[i] && PointYs[i] <= uy)
                                {
                                    ++num;
                                }
                            }

                            if(num >= K)
                            {
                                UInt64 area = (rx - lx) * (uy - by);
                                minArea = Math.Min(minArea, area);
                            }
                        }
                    }
                }
            }
            Console.WriteLine("{0}",minArea);
        }
    }
}

