namespace ABC075D
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;
            var K = RInt;

            //座標圧縮
            var x1 = new List<long>();
            var y1 = new List<long>();

            for (int i = 0; i < N; i++)
            {
                x1.Add(RInt);
                y1.Add(RInt);
            }

            var toValueX = x1.Distinct().OrderBy(x => x).ToArray();
            var toValueY = y1.Distinct().OrderBy(x => x).ToArray();

            var indexFromValueTableX = toValueX.Select((value, index) => new { value, index }).ToDictionary(p => p.value, p => p.index);
            var indexFromValueTableY = toValueY.Select((value, index) => new { value, index }).ToDictionary(p => p.value, p => p.index);

            int countX = indexFromValueTableX.Count;
            int countY = indexFromValueTableY.Count;

            var x2 = x1.Select(v => indexFromValueTableX[v]).ToArray();
            var y2 = y1.Select(v => indexFromValueTableY[v]).ToArray();

            //累積和O(N^3)
            int[,] map = new int[countX, countY];
            for (int i = 0; i < N; i++)
            {
                map[x2[i], y2[i]]++;
            }

            Draw2D(map);

            int[,] comb = new int[countX + 1, countY + 1];
            for (int i = 0; i < countX; i++)
            {
                for (int j = 0; j < countY; j++)
                {
                    comb[i + 1, j + 1] = map[i, j] + comb[i + 1, j] + comb[i, j + 1] - comb[i, j];
                }
            }

            Draw2D(comb);

            long ans = long.MaxValue;
            for (int i = 0; i < countX; i++)
            {
                for (int j = 0; j < countY; j++)
                {
                    for (int k = i; k < countX; k++)
                    {
                        for (int l = j; l < countY; l++)
                        {
                            int count = comb[k + 1, l + 1] - comb[k + 1, j] - comb[i, l + 1] + comb[i, j];
                            if (count < K) continue;

                            long area = (toValueX[k] - toValueX[i]) * (toValueY[l] - toValueY[j]);
                            ans = Math.Min(ans, area);
                        }
                    }
                }
            }

            Console.WriteLine(ans);
        }


    }


