            Point[] points = new Point[N];
            for (int i = 0; i < N; i++)
            {
                points[i] = new Point(i, cin.ReadInt, cin.ReadInt);
            }

            Array.Sort(points, (a, b) =>
            {
                if (a.X - b.X < 0) return -1;
                if (a.X - b.X > 0) return 1;

                return a.Y - b.Y;
            });

            long[] posXByXComp = new long[N];
            long[] posYByYComp = new long[N];

            for (int i = 0; i < N; i++)
            {
                points[i].XComp = i;
                posXByXComp[i]  = points[i].X;
            }

            Array.Sort(points, (a, b) =>
            {
                if (a.Y - b.Y < 0) return -1;
                if (a.Y - b.Y > 0) return 1;

                return a.X - b.X;
            });

            for (int i = 0; i < N; i++)
            {
                points[i].YComp = i;
                posYByYComp[i]  = points[i].Y;
            }

            int[][] T = JagArray2D<int>(N + 1, N + 1);

            for (int i = 0; i < N; i++)
            {
                int xComp = points[i].XComp;
                int yComp = points[i].YComp;

                T[yComp + 1][xComp + 1]++;
            }

            for (int i = 1; i <= N; i++)
            {
                for (int j = 1; j <= N; j++)
                {
                    T[i][j] += T[i][j - 1];
                }
            }

            for (int i = 1; i <= N; i++)
            {
                for (int j = 1; j <= N; j++)
                {
                    T[i][j] += T[i - 1][j];
                }
            }

            long minArea = long.MaxValue;

            for (int i = 1; i <= N; i++)
            {
                for (int j = 1; j <= N; j++)
                {
                    for (int k = i; k <= N; k++)
                    {
                        for (int l = j; l <= N; l++)
                        {
                            int count = T[k][l] + T[i - 1][j - 1] - T[k][j - 1] - T[i - 1][l];

                            if (count < K) continue;

                            long area = (posYByYComp[k-1] - posYByYComp[i-1]) * (posXByXComp[l-1] - posXByXComp[j-1]);

                            minArea = Math.Min(minArea, area);
                        }
                    }
                }
            }

            cou.WriteLine(minArea);
        }

