        long min = (long)4e18;
        for(int i = 0; i < N; ++i)
        {
          for(int j = i + K; j <= N; ++j)
          {
            var dx = XY[j - 1].Item1 - XY[i].Item1;
            var Y = XY.Skip(i).Take(j - i).Select(x => x.Item2).OrderBy(x => x).ToArray();
            var mindy = (long)2e18;
            for(int k = 0; k <= j - i - K; ++k)
