    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int K = re.i();
        long[] X = new long[N];
        long[] Y = new long[N];
        for(int i=0;i<N;i++){
            X[i] = re.i();
            Y[i] = re.i();
        }
        Compression XC = new Compression(X);
        Compression YC = new Compression(Y);
        int[,] Map = new int[XC.size,YC.size];
        for(int i=0;i<N;i++){
            Map[XC.ToPoint(X[i]),YC.ToPoint(Y[i])]++;
        }
        for(int i=0;i<XC.size;i++){
            for(int j=0;j<YC.size;j++){
                if(i != 0){
                    Map[i,j] += Map[i-1,j];
                }
                if(j != 0){
                    Map[i,j] += Map[i,j-1];
                }
                if(i != 0 && j != 0){
                    Map[i,j] -= Map[i-1,j-1];
                }
            }
        }
        long count = 4000000000000000000;
        for(int i=0;i<XC.size;i++){
            for(int j=i;j<XC.size;j++){
                for(int k=0;k<YC.size;k++){
                    for(int l=k;l<YC.size;l++){
                        int c = Map[j,l];
                        if(i != 0){
                            c -= Map[i-1,l];
                        }
                        if(k != 0){
                            c -= Map[j,k-1];
                        }
                        if(i != 0 && k != 0){
                            c += Map[i-1,k-1];
                        }
                        if(c >= K){
                            count = Math.Min(count,(XC.A[j]-XC.A[i])*(YC.A[l]-YC.A[k]));
                        }
                    }
                }
            }
        }
        sb.Append(count+"\n");
    }
}
class Compression{
    public int size;
    public long[] A;
    public Compression(long[] a){
        long[] b = new long[a.Length];
        for(int i=0;i<a.Length;i++){
            b[i] = a[i];
        }
        a = b;
        Array.Sort(a);
        List<long> AL = new List<long>();
        AL.Add(a[0]);
        for(int i=1;i<a.Length;i++){
            if(a[i] != a[i-1]){
                AL.Add(a[i]);
            }
        }
        A = AL.ToArray();
        size = A.Length;
    }
    public int ToPoint(long X){
        int bf = 0;
        int bl = size-1;
        while(bf != bl){
            int bc = (bf+bl)/2;
            if(A[bc] >= X){
                bl = bc;
            }
            else{
                bf = bc+1;
            }
        }
        return bf;
    }
    public long Value(int i){
        return A[i];
    }
}
