class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var K = sc.ReadInt();
        var XY = new (long, long)[N];
        for (int i = 0; i < N; i++)
        {
            var x = sc.ReadInt();
            var y = sc.ReadInt();
            XY[i] = (x, y);
        }
        var ans = long.MaxValue;
        {
            Array.Sort(XY);
            for (int i = 0; i < N - K + 1; i++)
            {
                var width = Math.Abs(XY[i].Item1 - XY[i + K - 1].Item1);
                var height = Math.Abs(
                    XY.Skip(i).Take(K).Max(xy => xy.Item2) - XY.Skip(i).Take(K).Min(xy => xy.Item2)
                );
                ans = Math.Min(ans, width * height);
            }
        }
        {
            Array.Sort(XY, (a, b) => a.Item2.CompareTo(b.Item2));
            for (int i = 0; i < N - K + 1; i++)
            {
                var height = Math.Abs(XY[i].Item2 - XY[i + K - 1].Item2);
                var width = Math.Abs(
                    XY.Skip(i).Take(K).Max(xy => xy.Item1) - XY.Skip(i).Take(K).Min(xy => xy.Item1)
                );
                ans = Math.Min(ans, width * height);
            }
        }
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
