namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            long[] x = new long[N], y = new long[N];
            for (var i = 0; i < N; ++i)
            {
                var xy = Sarray();
                x[i] = xy[0];
                y[i] = xy[1];
            }

            var men = long.MaxValue;
            for (var i1 = 0; i1 < N; ++i1)
            {
                for (var i2 = 0; i2 < N; ++i2)
                {
                    for (var i3 = 0; i3 < N; ++i3)
                    {
                        for (var i4 = 0; i4 < N; ++i4)
                        {
                            var xld = Min(x[i4], Min(x[i3], Min(x[i2], x[i1])));
                            var yld = Min(y[i4], Min(y[i3], Min(y[i2], y[i1])));
                            var xru = Max(x[i4], Max(x[i3], Max(x[i2], x[i1])));
                            var yru = Max(y[i4], Max(y[i3], Max(y[i2], y[i1])));
                            var n = 0L;
                            for (var k = 0; k < N; ++k)
                            {
                                if ((xld <= x[k] && x[k] <= xru) &&
                                    (yld <= y[k] && y[k] <= yru))
                                    ++n;
                            }
                            if (K <= n)
                                men = Min(men, (xru - xld) * (yru - yld));
                        }
                    }
                }
            }
            WriteLine(men);
        }
    }
}

