        public void Solve()
        {
            int N = cin.ReadInt;
            int K = cin.ReadInt;

            long[] X = new long[N];
            long[] Y = new long[N];

            // Point[] points = new Point[N];
            for (int i = 0; i < N; i++)
            {
                X[i] = cin.ReadLong;
                Y[i] = cin.ReadLong;
            }

            var compX = new CoordinateCompression(X);
            var compY = new CoordinateCompression(Y);

            int H = compY.Size;
            int W = compX.Size;

            int[][] T = JagArray2D<int>(H + 1, W + 1);
            // int[][] T = JagArray2D<int>(N + 1, N + 1);

            for (int i = 0; i < N; i++)
            {
                int xInd = compX.CalcIndex(X[i]);
                int yInd = compY.CalcIndex(Y[i]);

                T[yInd + 1][xInd + 1]++;
            }

            for (int i = 1; i <= H; i++)
            {
                for (int j = 1; j <= W; j++)
                {
                    T[i][j] += T[i][j - 1];
                }
            }

            for (int i = 1; i <= H; i++)
            {
                for (int j = 1; j <= W; j++)
                {
                    T[i][j] += T[i - 1][j];
                }
            }

            long minArea = long.MaxValue;

            for (int i = 1; i <= H; i++)
            {
                for (int j = 1; j <= W; j++)
                {
                    for (int k = i; k <= H; k++)
                    {
                        for (int l = j; l <= W; l++)
                        {
                            int count = T[k][l] + T[i - 1][j - 1] - T[k][j - 1] - T[i - 1][l];

                            if (count < K) continue;

                            long area = (compY.GetValue(k - 1) - compY.GetValue(i - 1)) * (compX.GetValue(l - 1) - compX.GetValue(j - 1));

                            minArea = Math.Min(minArea, area);
                        }
                    }
                }
            }

            cou.WriteLine(minArea);
        }

        /// <summary>
        /// 座標圧縮
        /// 1軸
        /// 同じ値のものがあれば重複分は消える
        ///
        /// TODO:二次元座標に対応させる
        /// </summary>
        public class CoordinateCompression
        {
            public int    Size; // 圧縮後のサイズ
            public long[] A;    // 圧縮後の配列 同じ値については要素数は減っている

            /// <summary>
            /// NOTE: aInはソート済みでなくてもよい
            /// </summary>
            public CoordinateCompression(long[] aIn)
            {
                // aInをコピー
                int    n = aIn.Length;
                long[] a = new long[n];

                for (int i = 0; i < n; i++)
                {
                    a[i] = aIn[i];
                }

                // 昇順ソート
                Array.Sort(a);

                List<long> list = new List<long>();
                list.Add(a[0]);

                for (int i = 1; i < n; i++)
                {
                    if (a[i] != a[i - 1])
                    {
                        list.Add(a[i]);
                    }
                }

                A = list.ToArray();

                Size = A.Length;
            }

            /// <summary>
            /// 座標値からindexを返す
            /// Sizeを返した場合はすべての点の座標値が与えたxより小さい
            /// </summary>
            public int CalcIndex(long x)
            {
                // LowerBoundを使っても同じだが、少し速い

                int ng = -1;
                int ok = Size;

                while (ok - ng > 1)
                {
                    int mid = ng + (ok - ng) / 2;
                    if (A[mid] >= x)
                    {
                        ok = mid;
                    }
                    else
                    {
                        ng = mid;
                    }
                }

                return ok;
            }

            public long GetValue(int i)
            {
                return A[i];
            }
        }
    }

