public class Hello
{
    public static void Main()
    {
        string[] line = Console.ReadLine().Trim().Split(' ');
        var n = int.Parse(line[0]);
        var k = int.Parse(line[1]);
        var a = new long[n];
        var b = new long[n];
        for (int i = 0; i < n; i++)
        {
            line = Console.ReadLine().Trim().Split(' ');
            a[i] = long.Parse(line[0]);
            b[i] = long.Parse(line[1]);
        }
        var w = getMin(a, k);
        var w2 = getMin(b, k);
        var ret = w * w2;
        Console.WriteLine(ret);
    }
    public static long getMin(long[] a, int k)
    {
        var aL = new List<long>();
        var n = a.Length;
        Array.Sort(a);
        for (int i = 0; i <= n - k; i++)
            for (int j = i + k - 1; j < n; j++)
                aL.Add(a[j] - a[i]);
        return aL.Min();
    }
}

