	static public void Main(string[] args)
	{
		int N, K;
		string[] vals = Console.ReadLine().Split(' ');
		N = int.Parse(vals[0]);
		K = int.Parse(vals[1]);

		int[] x = new int[N+1];
		int[] y = new int[N+1];
		for(int i=1; i<=N; i++)
		{
			vals = Console.ReadLine().Split(' ');
			x[i] = int.Parse(vals[0]);
			y[i] = int.Parse(vals[1]);
		}

		long ans = long.MaxValue;;

		for(int l=1; l<=N; l++)
		{
			for(int r=1; r<=N; r++)
			{
				if(x[l] >= x[r])
					continue;
				for(int t=1; t<=N; t++)
				{
					for(int b=1; b<=N; b++)
					{
						if(y[t] >= y[b])
							continue;
						int count = 0;
						for(int i=1; i<=N; i++)
						{
							if(x[i] >= x[l] && x[i] <= x[r] && y[i] >= y[t] && y[i] <= y[b])
							{
								count++;
							}
						}
						if(count >= K)
						{
							long w = (long)x[r] - (long)x[l];
							long h = (long)y[b] - (long)y[t];
							long m = w * h;
							if(ans > m)
								ans = m;
						}
					}
				}
			}
		}
		Console.WriteLine(ans);
	}
