                    for (int iy = 0; iy < n; iy++)
                    {
                        for (int jy = 0; jy < iy; jy++)
                        {
                            long xmin = Math.Min(x[ix], x[jx]);
                            long xmax = Math.Max(x[ix], x[jx]);
                            long ymin = Math.Min(y[iy], y[jy]);
                            long ymax = Math.Max(y[iy], y[jy]);
                            long cnt = 0;
                            for (int z = 0; z < n; z++)
                            {
                                if (xmin <= x[z] && x[z] <= xmax &&
                                    ymin <= y[z] && y[z] <= ymax)
                                {
                                    cnt++;
                                }
                            }
                            if (cnt >= k)
                            {
                                ans = Math.Min(ans, (xmax - xmin) * (ymax - ymin));
                            }
                        }
                    }

                }
            }

            Console.WriteLine(ans);
        }
    }
}
