        public void Solve()
        {
            int N = cin.ReadInt;
            int K = cin.ReadInt;

            long[] X = new long[N];
            long[] Y = new long[N];

            // Point[] points = new Point[N];
            for (int i = 0; i < N; i++)
            {
                X[i] = cin.ReadLong;
                Y[i] = cin.ReadLong;
            }

            Array.Sort(X);
            Array.Sort(Y);

            var compX = new CoordinateCompression(X);
            var compY = new CoordinateCompression(Y);

            int[][] T = JagArray2D<int>(compY.Size + 1, compX.Size + 1);
            // int[][] T = JagArray2D<int>(N + 1, N + 1);

            for (int i = 0; i < N; i++)
            {
                int xInd = compX.ToIndex(X[i]);
                int yInd = compY.ToIndex(Y[i]);

                T[yInd + 1][xInd + 1]++;
            }

            for (int i = 1; i <= N; i++)
            {
                for (int j = 1; j <= N; j++)
                {
                    T[i][j] += T[i][j - 1];
                }
            }

            for (int i = 1; i <= N; i++)
            {
                for (int j = 1; j <= N; j++)
                {
                    T[i][j] += T[i - 1][j];
                }
            }

            long minArea = long.MaxValue;

            for (int i = 1; i <= N; i++)
            {
                for (int j = 1; j <= N; j++)
                {
                    for (int k = i; k <= N; k++)
                    {
                        for (int l = j; l <= N; l++)
                        {
                            int count = T[k][l] + T[i - 1][j - 1] - T[k][j - 1] - T[i - 1][l];

                            if (count < K) continue;

                            long area = (compY.GetValue(k - 1) - compY.GetValue(i - 1)) * (compX.GetValue(l - 1) - compX.GetValue(j - 1));

                            minArea = Math.Min(minArea, area);
                        }
                    }
                }
            }

            cou.WriteLine(minArea);
        }

        /// <summary>
        /// 座標圧縮
        /// 1軸
        /// 同じ値のものがあれば重複分は消える
        /// </summary>
        public class CoordinateCompression
        {
            public int    Size; // 圧縮後のサイズ
            public long[] A;    // 圧縮後の配列 同じ値については要素数は減っている

            public CoordinateCompression(long[] aIn)
            {
                // aInをコピー
                int    n = aIn.Length;
                long[] a = new long[n];

                for (int i = 0; i < n; i++)
                {
                    a[i] = aIn[i];
                }

                // 昇順ソート
                Array.Sort(a);

                List<long> list = new List<long>();
                list.Add(a[0]);

                for (int i = 1; i < n; i++)
                {
                    if (a[i] != a[i - 1])
                    {
                        list.Add(a[i]);
                    }
                }

                A = list.ToArray();

                Size = A.Length;
            }

            // 返り値がSizeだったら解無し
            public int ToIndex(long x)
            {
                int ng = -1;
                int ok = Size;

                while (ok - ng > 1)
                {
                    int mid = ng + (ok - ng) / 2;
                    if (A[mid] >= x)
                    {
                        ok = mid;
                    }
                    else
                    {
                        ng = mid;
                    }
                }

                return ok;
            }

            public long GetValue(int i)
            {
                return A[i];
            }
        }
    }

