class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var K = sc.ReadInt();
        var XY = new (long, long)[N];
        for (int i = 0; i < N; i++)
        {
            var x = sc.ReadLong();
            var y = sc.ReadLong();
            XY[i] = (x, y);
        }
        var ans = long.MaxValue;
        Array.Sort(XY);
        for (int i = 0; i < N; i++)
        {
            for (int j = i + 1; j < N; j++)
            {
                var sx = XY[i].Item1;
                var ex = XY[j].Item1;
                var target = XY
                    .Where(xy => sx <= xy.Item1 && xy.Item1 <= ex)
                    .OrderBy(xy => xy.Item2)
                    .ToArray();
                if (target.Length < K) continue;
                var width = ex - sx;
                var height = long.MaxValue;
                for (int k = 0; k < target.Length - K + 1; k++)
                {
                    height = Math.Min(height, target[k + K - 1].Item2 - target[k].Item2);
                }
                ans = Math.Min(ans, width * height);
            }
        }
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
