		public class Calc {
			public void Solve() {
				int N = NextInt(), K = NextInt();
				var list = new List<Vector2<long>>();
				var left = new Vector2<long>(int.MaxValue,int.MaxValue);
				var right = new Vector2<long>(int.MinValue,int.MinValue);
				N.REP(i => {
					var line = new Vector2<long>(NextLong(), NextLong());
