				foreach (var line in ordered) {
					if (left.X > line.X) left.X = line.X;
					if (left.Y > line.Y) left.Y = line.Y;
					if (right.X < line.X) right.X = line.X;
					if (right.Y < line.Y) right.Y = line.Y;		
				}
				((right.X-left.X)*(right.Y-left.Y)).WL();
				return;
			}
		}
