          elements.SelectMany((e, i) =>
            elements.Skip(i + 1).GetCombinations(k - 1).Select(c => (new[] { e }).Concat(c)));
    }
}

public struct Point
{
    public long X;
    public long Y;

    public Point(Point p)
    {
        X = p.X;
        Y = p.Y;
    }

    public Point(long x, long y)
    {
        X = x;
        Y = y;
    }

    public static bool operator ==(Point a, Point b)
    {
        return (a.X == b.X && a.Y == b.Y);
    }

    public static bool operator !=(Point a, Point b)
    {
        return !(a == b);
    }

    //objと自分自身が等価のときはtrueを返す
    public override bool Equals(object obj)
    {
        if (!(obj is Point))
        {
            return false;
        }

        Point p = (Point)obj;
        return (X == p.X && Y == p.Y);
    }

    //Equalsがtrueを返すときに同じ値を返す
    public override int GetHashCode()
    {
        return (int)((X << 16) ^ Y);
    }

    public Point Clone()
    {
        return new Point(X, Y);
    }

    public void Reverse()
    {
        X = -X;
        Y = -Y;
    }

    public static Point operator +(Point a, Point b)
    {
        return new Point(a.X + b.X, a.Y + b.Y);
    }

    public static Point operator -(Point a, Point b)
    {
        return new Point(a.X - b.X, a.Y - b.Y);
    }

    public static Point operator *(Point a, int i)
    {
        return new Point(a.X * i, a.Y * i);
    }

    public static Point operator /(Point a, int i)
    {
        return new Point(a.X / i, a.Y / i);
    }
    public static Point operator +(Point a)
    {
        return new Point(+a.X, +a.Y);
    }

    public static Point operator -(Point a)
    {
        return new Point(-a.X, -a.Y);
    }

    public override string ToString()
    {
        return string.Format("({0},{1})", X, Y);
    }
}

class Solution
{
    static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        int n = vals[0];
        int k = vals[1];
        var points = new Point[n];

        for (int i = 0; i < n; i++)
        {
            var vs = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
            var x = vs[0];
            var y = vs[1];
            points[i] = new Point(x, y);
        }

        var minArea = long.MaxValue;

        foreach (var ys in Combination.GetCombinations(points, 2))
        {
            var ay = ys.Min(p => p.Y);
            var by = ys.Max(p => p.Y);
            foreach (var xs in Combination.GetCombinations(points, 2))
            {
                var ax = xs.Min(p => p.X);
                var bx = xs.Max(p => p.X);
                int count = 0;
                foreach (var p in points)
                {
                    if (ax <= p.X && p.X <= bx && ay <= p.Y && p.Y <= by)
                    {
                        count++;
                        if (count >= k)
                        {
                            minArea = Math.Min(minArea, (bx - ax) * (by - ay));
                            break;
                        }
                    }
                }
            }
        }

        Console.WriteLine(minArea);
    }
}

