        {
            line = Console.ReadLine().Trim().Split(' ');
            a[i] = long.Parse(line[0]);
            b[i] = long.Parse(line[1]);
        }
        var aL = new List<long>();
        var bL = new List<long>();
        getMin(a, k, aL);
        getMin(b, k, bL);
        var ret = getAns(aL, bL);
        Console.WriteLine(ret);
    }
    public static long getAns(List<long> a, List<long> b)
    {
        var ret = new List<long>();
        foreach (var x in a)
            foreach (var y in b)
                ret.Add(x * y);
        return ret.Min();
    }

    public static void getMin(long[] a, int k, List<long> aL)
    {
        var n = a.Length;
        Array.Sort(a);
        for (int i = 0; i <= n - k; i++)
            for (int j = i + k - 1; j < n; j++)
                aL.Add(a[j] - a[i]);
    }
}

