                    var y = key / x;
                    for (int l = 0; l < tmp.Length; l++)
                    {
                        var miny = tmp[l][1];
                        var cnt = tmp.Count(t => miny <= t[1] && t[1] <= miny + y);
                        if (cnt >= K)
                        {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
