public class Program
{

	public void Proc()
	{
        int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        this.PointList = new Point[inpt[0]];
        this.MustContain = inpt[1];

        for (int i = 0; i < PointList.Length; i++) {
            long[] pos = Reader.ReadLine().Split(' ').Select(a => long.Parse(a)).ToArray();
            this.PointList[i] = new Point(i, pos[0], pos[1]);
        }

        long flags = this.PointList.Sum(a => a.GetKey());
        long ans = GetAns(flags, this.PointList.ToList());
        Console.WriteLine(ans);

    }

    private Dictionary<long, long> dic = new Dictionary<long, long>();

    private long GetAns(long flags, List<Point> target) {
        if(dic.ContainsKey(flags)) {
            return dic[flags];
        }

        if(target.Count<this.MustContain) {
            return -1;
        }

        long ans = (target.Max(a=>a.X)-target.Min(a=>a.X)) * (target.Max(a=>a.Y)-target.Min(a=>a.Y));

        List<Point> subTarget = new List<Point>();
        subTarget.Add(target.OrderBy(a => a.X).First());
        subTarget.Add(target.OrderByDescending(a => a.X).First());
        subTarget.Add(target.OrderBy(a => a.Y).First());
        subTarget.Add(target.OrderByDescending(a => a.Y).First());

        subTarget.ForEach(a=>{
            List<Point> newTarget = target.Where(b => b.ID != a.ID).ToList();
            long subFlag = flags - a.GetKey();
            long ret = GetAns(subFlag, newTarget);
            if(ret>=0) {
                ans = Math.Min(ans, ret);
            }
        });
        dic[flags] = ans;
        return ans;
    }

    private int MustContain;
    private Point[] PointList;

    private class Point {
        public int ID;
        public long X;
        public long Y;
        public Point(int id, long x, long y) {
            this.X = x;
            this.Y = y;
            this.ID = id;
        }
        public long GetKey() {
            return 1L << this.ID;
        }
    }

