    {
        var N = cr.Int;
        var K = cr.Int;
        var points = cr.Repeat(N).Select(cr => new Point(cr.Int, cr.Int));
        var xs = points.Select((p, i) => new { p.x, i }).OrderBy(p => p.x).Select(p => p.i).ToArray();
        var ys = points.Select((p, i) => new { p.y, i }).OrderBy(p => p.y).Select(p => p.i).ToArray();
        var xb = new int[N];
        var yb = new int[N];
        for (int i = 0; i < N; i++)
        {
            xb[xs[i]] = i;
            yb[ys[i]] = i;
        }
        var plot = NewArray(N, N, 0);
        for (int i = 0; i < N; i++)
            plot[xb[i]][yb[i]] = 1;

        var sums = new Sums2D(plot);
        long min = long.MaxValue;
        for (int l = 0; l < N; l++)
            for (int r = l + 1; r <= N; r++)
                for (int d = 0; d < N; d++)
                    for (int u = d + 1; u <= N; u++)
                        if (sums[l, r, d, u] >= K)
                            UpdateMin(ref min, (long)(points[xs[r - 1]].x - points[xs[l]].x) * (points[ys[u - 1]].y - points[ys[d]].y));
