class Simple {
    int N, K;
    long[] x, y;
    void Solve() {
        //input
        N = io.Int;
        K = io.Int;
        x = new long[N];
        y = new long[N];
        for (int i = 0; i < N;++i){
            x[i] = io.Long;
            y[i] = io.Long;
        }
        //cal
        var ans = long.MaxValue;
        var cand_x = x.OrderBy(v => v).Distinct().ToArray();
        var cand_y = y.OrderBy(v => v).Distinct().ToArray();
        var grid = new Tuple<long, long>[N];
        long top, bot, lef, rig;
        //lef
        for (int i = 0; i < cand_x.Length;++i){
            lef = cand_x[i];
            //rig
            for (int j = 0; j < cand_x.Length-i;++j){
                rig = cand_x[cand_x.Length - 1 - j];
                //bot
                for (int k = 0; k < cand_y.Length;++k){
                    bot = cand_y[k];
                    //top
                    for (int l = 0; l < cand_y.Length-k;++l){
                        top = cand_y[cand_y.Length - 1 - l];
                        //検証
                        var cnt = 0;
                        for (int m = 0; m < N;++m){
                            if(lef<=x[m]&&x[m]<=rig&&bot<=y[m]&&y[m]<=top){
                                cnt++;
                            }
                        }
                        if(cnt>=K){
                            ans = Math.Min(ans,(rig - lef) * (top - bot));
                        }
                    }
                }
            }
        }
        //ret
        Console.WriteLine(ans);
    }
