class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var K = sc.ReadInt();
        var XY = new (long, long)[N];
        for (int i = 0; i < N; i++)
        {
            var x = sc.ReadLong();
            var y = sc.ReadLong();
            XY[i] = (x, y);
        }
        var ans = long.MaxValue;
        {
            Array.Sort(XY);
            for (int i = 0; i < N; i++)
            {
                for (int j = i + K - 1; j < N; j++)
                {
                    var width = XY[j].Item1 - XY[i].Item1;
                    var miny = XY.Skip(i).Take(j - i + 1).Min(xy => xy.Item2);
                    var maxy = XY.Skip(i).Take(j - i + 1).Max(xy => xy.Item2);
                    var height = maxy - miny;
                    ans = Math.Min(ans, width * height);
                }
            }
        }
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
