public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var K = cr.Int;
        var points = cr.Repeat(N).Select(cr => new Point(cr.Int, cr.Int));
        long min = long.MaxValue;
        for (int l = 0; l < points.Length; l++)
            for (int r = l + 1; r < points.Length; r++)
                for (int d = 0; d < points.Length; d++)
                    for (int u = d + 1; u < points.Length; u++)
                    {
                        var xl = points[l].x;
                        var xr = points[r].x;
                        var yd = points[d].y;
                        var yu = points[u].y;
                        if (xl > xr)
                            Swap(ref xl, ref xr);
                        if (yd > yu)
                            Swap(ref yd, ref yu);
                        var cnt = 0;
                        for (int i = 0; i < points.Length; i++)
                        {
                            var p = points[i];
                            if (xl <= p.x && p.x <= xr && yd <= p.y && p.y <= yu)
                                cnt++;
                        }
                        if (cnt >= K)
                            UpdateMin(ref min, (long)(xr - xl) * (yu - yd));
                    }
        return min;
    }
}
struct Point : IEquatable<Point>, IComparable<Point>
{
    public int x;
    public int y;
    public Point(int[] arr) : this(arr[0], arr[1]) { }
    public Point(int x, int y)
    {
        this.x = x;
        this.y = y;
    }

    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public void Deconstruct(out int v1, out int v2) { v1 = x; v2 = y; }
    public static implicit operator Point(Tuple<int, int> tuple) => new Point(tuple.Item1, tuple.Item2);
    public double Distance(Point other) => Math.Sqrt(Distance2(other));
    private long Distance2(Point other)
    {
        var p = other - this;
        return (long)p.x * p.x + (long)p.y * p.y;
    }
    public long Inner(Point other) => (long)x * other.x + (long)y * other.y;
    public long Cross(Point other) => (long)x * other.y - (long)y * other.x;
    public static Point operator +(Point a, Point b) => new Point(a.x + b.x, a.y + b.y);
    public static Point operator -(Point a, Point b) => new Point(a.x - b.x, a.y - b.y);
    public int CompareTo(Point other)
    {
        var xd = this.x.CompareTo(other.x);
        if (xd != 0) return xd;
        return this.y.CompareTo(other.y);
    }

    public bool Equals(Point other) => this.x == other.x && this.y == other.y;
    public override bool Equals(object obj) => obj is Point && Equals((Point)obj);
    public override int GetHashCode() => ((x << 5) + x) ^ y;
    public override string ToString() => $"({x}, {y})";
}

class Sums2D
{
    private int[][] impl;
    public int Length1 { get; }
    public int Length2 { get; }
    public Sums2D(int[][] arr)
    {
        this.Length1 = arr.Length;
        this.Length2 = arr[0].Length;
        impl = NewArray(Length1 + 1, Length2 + 1, 0);
        for (var i = 0; i < Length1; i++)
            for (var j = 0; j < Length2; j++)
                impl[i + 1][j + 1] = impl[i + 1][j] + impl[i][j + 1] - impl[i][j] + arr[i][j];
    }
    public int this[int left, int rightExclusive, int top, int bottomExclusive]
    {
        get
        {
            return impl[rightExclusive][bottomExclusive]
              - impl[left][bottomExclusive]
              - impl[rightExclusive][top]
              + impl[left][top];
        }
    }
}

