namespace AtcoderExpress
{


    class Program
    {

        static void Main(string[] args)
        {
            var NK = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            var N = NK[0];
            var K = NK[1];
            var points = new Tuple<long, long>[N];
            for (int i = 0; i < N; i++)
            {
                var XY = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
                var X = XY[0];
                var Y = XY[1];
                points[i] = new Tuple<long, long>(X,Y); 
            }

            //X座標でのソート
            Array.Sort(points);

            var ans = long.MaxValue;
            //左端を1番目からN-1番目まで動かす
            for (int i = 0; i < N-1; i++)
            {
                //右端の範囲を設定
                for (int j = i+1; j < N; j++)
                {
                    var left = points[i];
                    var right = points[j];

                    long xmin = Min(left.Item1, right.Item1);
                    long xmax = Max(left.Item1, right.Item1);
                    long ymin = Min(left.Item2, right.Item2);
                    long ymax = Max(left.Item2, right.Item2);

                    //y座標の高さの決定
                    for (int m = i; m <= j; m++)
                    {
                        var yza = points[m];
                        ymin = Min(ymin, yza.Item2);
                        ymax = Max(ymax, yza.Item2);
                        long rec = (xmax - xmin) * (ymax - ymin);
                        //y座標の範囲にK個以上座標があるかどうかの検索
                        var CumPoint = 0L;
                        for (int k = i; k <= j; k++)
                        {
                            if (points[k].Item2 <= ymax && points[k].Item2 >= ymin)
                            {
                                CumPoint++;
                            }
                        }

                        if (CumPoint >= K && rec < ans)
                        {
                            ans = rec;
                        }
                    }

                }
            }
            Console.WriteLine(ans);
        }


    }
}

