            public static int NextInt() => int.Parse(NextString());
            public static long NextLong() => long.Parse(NextString());
            public static string NextString()
            {
                if (param.Count == 0) foreach (var item in Console.ReadLine().Split(' ')) param.Enqueue(item);
                return param.Dequeue();
            }
        }
        static public void Main(string[] args)
        {
            var N = Console_.NextInt();
            var K = Console_.NextInt();


            var xtoy = new Dictionary<long, long>();
            var xary = new long[N];
            for (int i = 0; i < N; ++i)
            {
                var x = Console_.NextInt();
                var y = Console_.NextInt();
                xary[i] = x;
                xtoy[x] = y;
            }
            Array.Sort(xary);

            var ans = 0L;
            for (int i = K - 1; i < N; ++i)
            {
                long maxy = 0;
                long miny = 10000000000;
                for (int j = i - K + 1; j <= i; ++j)
                {
                    var y = xtoy[xary[j]];
                    if (maxy < y) maxy = y;
                    if (miny > y) miny = y;
                }
                var tmpans = (maxy - miny) * (xary[i] - xary[i - K + 1]);
                if (ans == 0 || tmpans < ans) ans = tmpans;
            }

            Console.WriteLine(ans);
        }
    }
