class Solution
{
    static long Area(Point[] ps)
    {
        return Area(ps[0], ps[1]);
    }

    static long Area(Point a, Point b)
    {
        var diff = a - b;
        return Math.Abs(diff.X * diff.Y);
    }

    static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        int n = vals[0];
        int k = vals[1];
        var points = new Point[n];

        for (int i = 0; i < n; i++)
        {
            var vs = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
            var x = vs[0];
            var y = vs[1];
            points[i] = new Point(x, y);
        }

        var minArea = long.MaxValue;

        var list = new List<Point[]>();
        foreach (var ys in Combination.GetCombinations(points, 2))
        {
            var ay = ys.Min(p => p.Y);
            var by = ys.Max(p => p.Y);
            foreach (var xs in Combination.GetCombinations(points, 2))
            {
                var ax = xs.Min(p => p.X);
                var bx = xs.Max(p => p.X);
                var rect = new Point[] { new Point(ax, ay), new Point(bx, by) };
                list.Add(rect);
            }
        }
        list.Sort((a, b) => Area(a).CompareTo(Area(b)));

        foreach (var rect in list)
        {
            int count = 0;
            foreach (var p in points)
            {
                if (rect[0].X <= p.X && p.X <= rect[1].X && rect[0].Y <= p.Y && p.Y <= rect[1].Y)
                {
                    count++;
                    if (count >= k)
                    {
                        Console.WriteLine(Area(rect));
                        return;
                    }
                }
            }
        }
    }
}

