        {
            var (N, K) = Read2Longs();
            var points = new List<Point>();
            for (int i = 0; i < N; i++)
            {
                var (x, y) = Read2Longs();
                points.Add(new Point { X = x, Y = y });
            }

            points = points.OrderBy(x => x.X).ToList();
            var min = long.MaxValue;
            for (int i = 0; i < N - 1; i++)
            {
                for (int j = i + 1; j < N; j++)
                {
                    // 点が明らかにK個以下なので
                    if (j - i + 1 < K) continue;

                    var xPoints = points.Skip(i).Take(j - i + 1).OrderBy(x => x.Y).ToList();
                    for (int ii = 0; ii < xPoints.Count - 1; ii++)
                    {
                        for (int jj = 0; jj < xPoints.Count; jj++)
                        {
                            // 点が明らかにK個以下なので
                            if (jj - ii + 1 < K) continue;
                            {
                                var xyPoints = xPoints.Skip(ii).Take(jj - ii + 1).ToList();

                                var rec = Math.Abs(xyPoints.Max(x => x.X) - xyPoints.Min(x => x.X))
                                    * Math.Abs(xyPoints.Max(x => x.Y) - xyPoints.Min(x => x.Y));
                                min = Math.Min(min, rec);
                            }
                        }
                    }
                }
            }

