	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc {
			public void Solve() {
				int N = NextInt(), K = NextInt();
				var X = new Ll();
				var Y = new Ll();

				var list = new List<Tuple<long, long>>();
				N.REP(i => {
					int xi = NextInt(), yi = NextInt();
					X.Add(xi);
					Y.Add(yi);
					list.Add(new Tuple<long, long>(xi,yi));
				});


				X.Sort();
				Y.Sort();
				var min = long.MaxValue;
				for (int i = 0; i < N; i++) {
					for (int j = i+1; j < N; j++) {
						for (int k = 0; k < N; k++) {
							for (var l = k+1; l < N; l++) {
								var left = X[i];
								var right = X[j];
								var top = Y[k];
								var bottom = Y[l];
								var count = list.Count(tuple =>
									tuple.Item1 >= left && tuple.Item1 <= right && tuple.Item2 >= top && tuple.Item2 <= bottom);
								if (count >= K) min = Min(min, Abs(right - left) * Abs(top - bottom));
							}
						}
					}
				}
				min.WL();
				return;
			}
		}

	}
