var n, k int
var X, Y []int

type point struct {
	id, x, y int
}

var points []point

const cmin, cmax = -1000000001, 1000000001

var deletedIdMap map[int]bool

func main() {
	tmp := NextIntsLine()
	n, k = tmp[0], tmp[1]
	deletedIdMap = make(map[int]bool)
	for i := 0; i < n; i++ {
		tmp = NextIntsLine()
		x, y := tmp[0], tmp[1]
		X = append(X, x)
		Y = append(Y, y)
		points = append(points, point{id: i, x: x, y: y})
		deletedIdMap[i] = false
	}

	// 最初だけソートで求める
	sort.Sort(sort.IntSlice(X))
	sort.Sort(sort.IntSlice(Y))
	xMin, xMax, yMin, yMax := X[0], X[len(X)-1], Y[0], Y[len(Y)-1]
	ans := (xMax - xMin) * (yMax - yMin)

	for t := 0; t < (n - k); t++ {
		ans = calcMinimumArea()
	}

	fmt.Println(ans)
}

func calcMinimumArea() int {
	// すべての点について、「ある点を除外したときの最小矩形の面積」を計算し、最小となるものを求める
	minArea := (2 * cmax) * (2 * cmax)
	deletedId := -1
	for didx := 0; didx < len(points); didx++ {
		// 削除されてたらパス
		if b, ok := deletedIdMap[didx]; b && ok {
			continue
		}

		xMin, xMax, yMin, yMax := cmax, cmin, cmax, cmin
		for i := 0; i < len(points); i++ {
			// 削除対象か削除済みの場合はパス
			if didx == i {
				continue
			}
			if b, ok := deletedIdMap[i]; b && ok {
				continue
			}

			p := points[i]
			if xMin > p.x {
				xMin = p.x
			}
			if xMax < p.x {
				xMax = p.x
			}
			if yMin > p.y {
				yMin = p.y
			}
			if yMax < p.y {
				yMax = p.y
			}
		}

		area := (xMax - xMin) * (yMax - yMin)
		if minArea > area {
			minArea = area
			deletedId = didx
		}
	}

	// 削除すべき点を記録する
	deletedIdMap[deletedId] = true

	return minArea
}

