		// 削除されてたらパス
		if _, ok := deletedIdMap[didx]; ok {
			continue
		}

		xMin, xMax, yMin, yMax := cmax, cmin, cmax, cmin
		for i := 0; i < len(points); i++ {
			// 削除対象か削除済みの場合はパス
			if didx == i {
				continue
			}
			if _, ok := deletedIdMap[i]; ok {
				continue
			}

			p := points[i]
			if xMin > p.x {
				xMin = p.x
			}
			if xMax < p.x {
				xMax = p.x
			}
			if yMin > p.y {
				yMin = p.y
			}
			if yMax < p.y {
				yMax = p.y
			}
		}
		area := (xMax - xMin) * (yMax - yMin)
		if minArea > area {
			minArea = area
			deletedId = didx
		}
	}

	// 削除すべき点を記録する
	deletedIdMap[deletedId] = true

	return minArea
}

