	for i := 0; i < n-k; i++ {
		for ii := i + k; ii < n; ii++ {
			yy := make([]int, 0)
			for iii := i; iii < ii+1; iii++ {
				yy = append(yy, points[iii].y)
			}
			sort.Ints(yy)
			min := int64(1) << 62
			for iii := 0; iii+k <= ii-i; iii++ {
				if min > int64(yy[iii+k])-int64(yy[iii]) {
					min = int64(yy[iii+k]) - int64(yy[iii])
				}
			}

			m := int64(points[ii].x-points[i].x) * int64(min)
			if ans == 0 || ans > m {
				ans = m
			}
		}
	}
	fmt.Fprintln(writer, ans)

	writer.Flush()
}

