func main() {
	defer stdout.Flush()
	N := readInt()
	K := readInt()
	mx := make(map[int]bool)
	my := make(map[int]bool)
	m := make(map[int]map[int]int)
	for i := 0; i < N; i++ {
		x := readInt()
		y := readInt()

		mx[x] = true
		my[y] = true

		m2, ok := m[x]
		if !ok {
			m2 = make(map[int]int)
			m[x] = m2
		}
		m2[y]++
	}

	xs := make([]int, 0, N)
	for x := range mx {
		xs = append(xs, x)
	}
	ys := make([]int, 0, N)
	for y := range my {
		ys = append(ys, y)
	}

	sort.Ints(xs)
	sort.Ints(ys)

	s := make([][]int, len(xs)+1)
	for i := range s {
		s[i] = make([]int, len(ys)+1)
	}

	for i := 1; i <= len(xs); i++ {
		for j := 1; j <= len(ys); j++ {
			x := xs[i-1]
			y := ys[j-1]
			s[i][j] = s[i][j-1] + m[x][y]
		}
	}

	for i := 1; i <= len(xs); i++ {
		for j := 1; j <= len(ys); j++ {
			s[i][j] += s[i-1][j]
		}
	}

	sum := func(i, j, k, l int) int {
		return s[k][l] - s[i][l] - s[k][j] + s[i][j]
	}

	inf := int64(1000000001)
	ans := 2 * inf * 2 * inf

	for i := 0; i+2 <= len(xs); i++ {
		for ie := i + 2; ie <= len(xs); ie++ {
			for j := 0; j+2 <= len(ys); j++ {
				for je := j + 2; je <= len(ys); je++ {
					if sum(i, j, ie, je) < K {
						continue
					}
					x := xs[i]
					xe := xs[ie-1]
					y := ys[j]
					ye := ys[je-1]
					ans = min(ans, int64(xe-x)*int64(ye-y))
				}
			}
		}
	}

	println(ans)
}

