func main() {
	defer stdout.Flush()
	N := readInt()
	K := readInt()
	ps := make([]Point, N)
	for i := range ps {
		ps[i].x = readInt64()
		ps[i].y = readInt64()
	}
	qs := make([]Point, N)
	copy(qs, ps)

	inf := int64(1000000001)
	ans := 2 * inf * 2 * inf
	for i := 0; i < N; i++ {
		o := ps[i]
		Sort(qs, func(i, j int) bool {
			return o.Dist2(qs[i]) < o.Dist2(qs[j])
		})
		minX := inf
		maxX := -inf
		minY := inf
		maxY := -inf
		for j := 0; j < K; j++ {
			minX = min(minX, qs[j].x)
			maxX = max(maxX, qs[j].x)
			minY = min(minY, qs[j].y)
			maxY = max(maxY, qs[j].y)
		}
		ans = min(ans, (maxX-minX)*(maxY-minY))
	}

	println(ans)
}

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func max(a, b int64) int64 {
	if a < b {
		return b
	}
	return a
}

func abs(a int64) int64 {
	if a < 0 {
		return -a
	}
	return a
}

type Point struct {
	x, y int64
}

func (p Point) Dist2(q Point) int64 {
	return abs(q.x-p.x) * abs(q.y-p.y)
}

