package main

import (
  "fmt"
  "sort"
)

func main() {
  var N, K int
  fmt.Scan(&N, &K)
//fmt.Println(N, K)
  x   := make([]int, N)
  y   := make([]int, N)
  sox := make([]int, N)
  soy := make([]int, N)
  for i:=0; i < N; i++ {
    fmt.Scan(&x[i], &y[i])
  }
  copy(sox, x)
  copy(soy, y)
  // sort
  sort.Sort(sort.IntSlice(sox))
  sort.Sort(sort.IntSlice(soy))

  // initial max
  ans := (sox[N-1]-sox[0]) * (soy[N-1]-soy[0])

  // check
  for x1:=0; x1 < N; x1++ {
    for x2:=x1+1; x2 < N; x2++ {
      for y1:=0; y1 < N; y1++ {
        for y2 := y1 + 1; y2 < N; y2++ {
			smlx := sox[x1]
            bigx := sox[x2]
            smly := soy[y1]
            bigy := soy[y2]
            count := 0
            for i:=0; i < N; i++ {
              if x[i]>=smlx && x[i]<=bigx && y[i]>=smly && y[i]<=bigy {
                count++
              }
            }
            if count >= K {
				area := (bigx-smlx) * (bigy-smly)
                if ans > area {
                    ans = area
                }
            }
        }
      }
	}
  }

  fmt.Println(ans)
}

