func main() {
	var n, K int
	fmt.Scan(&n, &K)

	xs := make([]Point, n)
	ys := make([]Point, n)
	var x, y int
	for i := 0; i < n; i++ {
		fmt.Scan(&x, &y)
		xs[i] = Point{i, x, y}
		ys[i] = Point{i, x, y}
	}

	sort.Slice(xs, func(i, j int) bool {
		return xs[i].x < xs[j].x
	})
	sort.Slice(ys, func(i, j int) bool {
		return ys[i].y < ys[j].y
	})

	ans := int(1e18 * 4)
	for x1 := 0; x1 < n; x1++ {
		for x2 := x1 + 1; x2 < n; x2++ {
			for y1 := 0; y1 < n; y1++ {
				for y2 := y1 + 1; y2 < n; y2++ {
					x1, x2, y1, y2 := xs[x1].x, xs[x2].x, ys[y1].y, ys[y2].y
					cnt := 0
					for _, p := range xs {
						if x1 <= p.x && p.x <= x2 && y1 <= p.y && p.y <= y2 {
							cnt++
							if K <= cnt {
								ans = min(ans, (x2-x1)*(y2-y1))
								break
							}
						}
					}
				}
			}
		}
	}

	fmt.Println(ans)
}

