const size = 1000000
var reader = bufio.NewReaderSize(os.Stdin,size)
func NextLine() string {
  var line,buffer []byte
  var isPrefix bool = true
  var err error
  for ;isPrefix; {
    line,isPrefix,err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
  }
  return string(buffer)
}
func NextInts() (int,int) {
  var x,y int
  var s []string = strings.Split(NextLine()," ")
  x,_ = strconv.Atoi(s[0])
  y,_ = strconv.Atoi(s[1])
  return x,y
}

func main() {
  var n,k int = NextInts()
  var x,y,px,py []int
  x = make([]int,n)
  y = make([]int,n)
  px = make([]int,n)
  py = make([]int,n)
  for i:=0;i<n;i++ {
    x[i],y[i] = NextInts()
    px[i],py[i] = x[i],y[i]
  }
  sort.Ints(x)
  sort.Ints(y)
  var m int64 = int64(x[n-1]-x[0])*int64(y[n-1]-y[0])
  for ib:=0;ib<n-1;ib++ {
    for it:=ib+1;it<n;it++ {
      for jb:=0;jb<n-1;jb++ {
        for jt:=jb+1;jt<n;jt++ {
          var c int
          for p:=0;p<n;p++ {
            if px[p] < x[ib] || x[it] < px[p] ||
            py[p] < y[jb] || y[jt] < py[p] { c++ }
            if c > n-k { break }
          }
          if c <= n-k {
            var t int64 = int64(x[it]-x[ib])*int64(y[jt]-y[jb])
            if m > t { m = t }
          }
        }
      }
    }
  }
  fmt.Println(m)
}

