func main() {
	N, K := ReadInt(), ReadInt()
	x := make([]int, N)
	y := make([]int, N)
	for i := 0; i < N; i++ {
		x[i], y[i] = ReadInt(), ReadInt()
	}
	ans := math.MaxInt64
	for leftIdx := 0; leftIdx < N; leftIdx++ {
		for rightIdx := 0; rightIdx < N; rightIdx++ {
			for bottomIdx := 0; bottomIdx < N; bottomIdx++ {
				for topIdx := 0; topIdx < N; topIdx++ {
					left, right := x[leftIdx], x[rightIdx]
					bottom, top := y[bottomIdx], y[topIdx]
					if right < left || top < bottom {
						continue
					}

					cnt := 0
					for i := 0; i < N; i++ {
						if left <= x[i] && x[i] <= right && bottom <= y[i] && y[i] <= top {
							cnt++
							if cnt == K {
								continue
							}
						}
					}
					if cnt < K {
						continue
					}
					s := (right - left) * (top - bottom)
					if ans > s {
						ans = s
					}
				}
			}
		}
	}
	fmt.Println(ans)
}

