// I/O
type Scanner struct {
	sc *bufio.Scanner
}

func NewScanner() *Scanner {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, 1024), int(1e+9))
	return &Scanner{sc}
}

func (s *Scanner) nextStr() string {
	s.sc.Scan()
	return s.sc.Text()
}

func (s *Scanner) nextInt() int {
	i, e := strconv.Atoi(s.nextStr())
	if e != nil {
		panic(e)
	}
	return i
}

func (s *Scanner) nextFloat() float64 {
	f, e := strconv.ParseFloat(s.nextStr(), 64)
	if e != nil {
		panic(e)
	}
	return f
}

func (s *Scanner) nextRuneSlice() []rune {
	return []rune(s.nextStr())
}

func (s *Scanner) nextIntSlice(n int) []int {
	res := make([]int, n)
	for i := 0; i < n; i++ {
		res[i] = s.nextInt()
	}
	return res
}

func (s *Scanner) nextFloatSlice(n int) []float64 {
	res := make([]float64, n)
	for i := 0; i < n; i++ {
		res[i] = s.nextFloat()
	}
	return res
}

// Arithmetic
func max(nums ...int) int {
	m := nums[0]
	for _, i := range nums {
		if m < i {
			m = i
		}
	}
	return m
}

func min(nums ...int) int {
	m := nums[0]
	for _, i := range nums {
		if m > i {
			m = i
		}
	}
	return m
}

func abs(x int) int {
	if x > 0 {
		return x
	}
	return -x
}

func pow(x, y int) int {
	res := 1
	for i := 0; i < y; i++ {
		res *= x
	}
	return res
}

func ceil(a, b int) int {
	if a%b == 0 {
		return a / b
	} else {
		return a/b + 1
	}
}

func gcd(a, b int) int {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func lcm(a, b int) int {
	return a / gcd(a, b) * b
}

// Sort
type RuneSlice []rune

func (a RuneSlice) Len() int           { return len(a) }
func (a RuneSlice) Less(i, j int) bool { return a[i] < a[j] }
func (a RuneSlice) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }

// Main
const MOD = int(1e+9) + 7
const INF = 1 << 62

type Point struct {
	x, y int
}

type ByX []Point

func (a ByX) Len() int           { return len(a) }
func (a ByX) Less(i, j int) bool { return a[i].x < a[j].x }
func (a ByX) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N, K := sc.nextInt(), sc.nextInt()
	X := make([]int, N)
	Y := make([]int, N)
	P := make([]Point, N)
	for i := 0; i < N; i++ {
		x, y := sc.nextInt(), sc.nextInt()
		X[i] = x
		Y[i] = y
		P[i] = Point{x, y}
	}
	sort.Ints(X)
	sort.Ints(Y)
	sort.Sort(ByX(P))
	ans := INF
	for y1 := 0; y1 < N; y1++ {
		for y2 := y1; y2 < N; y2++ {
			for x1 := 0; x1 < N; x1++ {
				target := []Point{}
				for i := 0; i < N; i++ {
					p := P[i]
					if X[x1] <= p.x && Y[y1] <= p.y && p.y <= Y[y2] {
						target = append(target, p)
					}
				}
				count := 0
				idx := 0
				for x2 := x1; x2 < N; x2++ {
					for idx < len(target) && target[idx].x <= X[x2] {
						count++
						idx++
					}
					if count == K {
						x := max(1, X[x2]-X[x1])
						y := max(1, Y[y2]-Y[y1])
						//fmt.Fprintln(wtr, "equal K", X[x2], X[x1], Y[y2], Y[y1], x*y)
						if x*y < ans {
							ans = x * y
						}
						break
					}
				}
			}
		}
	}

	fmt.Fprintln(wtr, ans)
}

