const UNI = 100000;
class Int {
  num = [0, 0, 0, 0];
  setValue(v: number): Int {
    for (let i = 0; i < 4; i++) {
      this.num[i] = v % UNI;
      v = (v / UNI) | 0;
    }
    return this;
  }
  less(that: Int): Boolean {
    for (let i = 3; i >= 0; i--) {
      if (this.num[i] < that.num[i]) {
        return true;
      } else if (this.num[i] > that.num[i]) {
        return false;
      }
    }
    return false;
  }
  sub(that: Int): Int {
    let ret = new Int();
    let car = 0;
    for (let i = 0; i < 4; i++) {
      ret.num[i] = this.num[i] - that.num[i] - car;
      if (ret.num[i] < 0){
        car = 1;
        ret.num[i] += UNI;
      } else {
        car = 0;
      }
    }
    return ret;
  }
  mul(that: Int): Int {
    let ret = new Int();
    let car = 0;
    for (let i = 0; i < 4; i++) {
      ret.num[i] += car;
      for (let j = 0; j < 4; j++) {
        ret.num[i+j] += this.num[i] * that.num[j];
      }
      car = (ret.num[i] / UNI) | 0;
      ret.num[i] %= UNI;
    }
    return ret;
  }
  toString(): string {
    let s = '';
    for (let i = 3; i >= 0; i--) {
      if (s.length === 0) {
        if (this.num[i] > 0) {
          s = this.num[i].toString();
        }
      } else {
        let n = '0000' + this.num[i].toString();
        s += n.substring(n.length - 5);
      }
    }
    return s.length === 0 ? '0' : s;
  }
}
