        foreach(m ; 0..N){
            if(x[i] <= x2[m] && x2[m] <= x[j] && y[k] <= y2[m] && y2[m] <= y[l]){
                count++;
            }
        }
        if(count >= K){
            s = min(s, (x[j] - x[i]) * (y[j] - y[i]));
        }
    }
    s.writeln;
}

