struct UnionFind
{
	void init(long n) { par = new long[](n); foreach (i; 0..n) par[i] = i; }
	long root(long i) { return par[i] == i ? i : (par[i] = root(par[i])); }
	bool same(long i, long j) { return root(i) == root(j); }
	void unite(long i, long j) { i = root(i); j = root(j); if (i == j) return; par[i] = j; }
	long[] par;
}

void main()
{
	auto N = RD!long;
	auto K = RD!long;
	long[] x, y;
	foreach (i; 0..N)
	{
		x ~= RD!long;
		y ~= RD!long;
	}
	long[] ans;
	foreach (i; 0..N)
	{
		foreach (j; i..N)
		{
			foreach (k; j..N)
			{
				auto xb = min(min(x[i], x[j]), x[k]);
				auto xe = max(max(x[i], x[j]), x[k]);
				auto yb = min(min(y[i], y[j]), y[k]);
				auto ye = max(max(y[i], y[j]), y[k]);
				long cnt;
				foreach (l; 0..N)
				{
					if (INSIDE(x[l], xb, xe+1) && INSIDE(y[l], yb, ye+1))
						++cnt;
				}
				if (cnt >= K) ans ~= (xe - xb) * (ye - yb);
			}
		}
	}
	ans.sort();

	writeln(ans[0]);
	stdout.flush();
}

