struct Coord
{
    long x, y;

    this(long x, long y)
    {
        this.x = x, this.y = y;
    }

    Coord opBinary(string op)(Coord that)
    if (op == "+")
    {
        return Coord(this.x + that.x, this.y + that.y);
    }

    Coord opBinary(string op)(Coord that)
    if (op == "-")
    {
        return Coord(this.x - that.x, this.y - that.y);
    }

    bool check(Coord l, Coord r)
    {
        return l.x <= this.x && this.x <= r.x && l.y <= this.y && this.y <= r.y;
    }

    long area()
    {
        return this.x * this.y;
    }
}

