int readint() {
    return readln.chomp.to!int;
}

int[] readints() {
    return readln.split.map!(to!int).array;
}

long calc(int k, int[][] ps) {
    ps.sort!((a, b) => a[0] < b[0]); // x 座標でソート

    long ans = long.max;
    auto n = ps.length;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (j - i + 1 < k)
                continue;

            // 範囲内(i .. j)の点を y 座標でソート
            int[] ys;
            for (int m = i; m <= j; m++)
                ys ~= ps[m][1];
            ys.sort();

            int[] us;
            for (int m = 0; m < ys.length; m++) {
                if (us.length >= k)
                    us = us[1 .. $];
                us ~= ys[m];

                if (us.length >= k) { // k 個の点を含むので長方形の面積を計算
                    long x = ps[j][0] - ps[i][0];
                    long y = us[$ - 1] - us[0];
                    ans = min(ans, x * y);
                }
            }
        }
    }
    return ans;
}

void main() {
    auto nk = readints;
    int n = nk[0], k = nk[1];

    int[][] ps;
    for (int i = 0; i < n; i++) {
        auto p = readints;
        ps ~= p;
    }
    writeln(calc(k, ps));
}

