auto solve( long k, long[ 2 ][] xys )
{
	auto xs = new long[ xys.length ];
	auto ys = new long[ xys.length ];
	foreach( ref x, ref y, xy; lockstep( xs, ys, xys ) )
	{
		x = xy[ 0 ];
		y = xy[ 1 ];
	}
	xs.sort();
	ys.sort();

	auto ans = long.max;
	foreach( xi, xa; xs )
	{
		foreach( xb; xs[ xi .. $ ] )
		{
			foreach( yi, ya; ys )
			{
				foreach( yb; ys[ yi .. $ ] )
				{
					auto c = 0L;
					foreach( xy; xys )
					{
						c += ( xa <= xy[ 0 ] && xy[ 0 ] <= xb && ya <= xy[ 1 ] && xy[ 1 ] <= yb );
						if( c == k )
						{
							ans = min( ans, ( xb - xa ) * ( yb - ya ) );
							break;
						}
					}
				}
			}
		}
	}
	return ans;
}

