from sequtils import filterIt

let
  (N, K) = input(int, 2)
  points: seq[tuple[x, y: int]] = inputs(int, 2, N)

proc count(l, r, d, u: int): int =
  points.filterIt(points[l].x <= it.x and it.x <= points[r].x and
                  points[d].y <= it.y and it.y <= points[u].y).len

var result = int.high
for l in 0..<N:
  for r in 0..<N:
    for d in 0..<N:
      for u in 0..<N:
        if points[l].x <= points[r].x and points[d].y <= points[u].y:
          let count = count(l, r, d, u)
          if count >= K:
            result = min(result, (points[r].x - points[l].x) * (points[u].y - points[d].y))

echo result

