  let vl = v.len
  var res = newSeq[T](vl)
  var stk = newSeq[tuple[i, j: int]]()
  for i in countdown(vl-1, 0): stk.add((0, i))
  while stk.len > 0:
    let a = stk.pop
    res[a.i] = v[a.j]
    if a.i == n-1: yield res
    else:(for i in countdown(vl-1, 0): stk.add((a.i+1, i)))
