def point_compress(points):
    x_points = sorted([x for x, y in points])
    y_points = sorted([y for x, y in points])
    points_compressed = []
    for x, y in points:
        points_compressed.append([bisect_left(x_points, x), bisect_left(y_points, y)])
    return points_compressed


