# AtCoder Beginner Contest 075
# D - Axis-Parallel Rectangle

from sys import stdin

def nPointsInRect(x0, y0, x1, y1, points):
  return len([p for p in points
              if x0 <= p[0] <= x1 and y0 <= p[1] <= y1])

def solve(K, points):
  xs = sorted([p[0] for p in points])  # sorted x-coordinates
  ys = sorted([p[1] for p in points])  # sorted y-coordinates
  minArea = (xs[-1] - xs[0]) * (ys[-1] - ys[0])  # the biggest rect
  for i in range(len(ys)):
    y0 = ys[i]
    for y1 in ys[i + K - 1:]:
      for j in range(len(xs)):
        x0 = xs[j]
        for x1 in xs[j + K - 1:]:
          if nPointsInRect(x0, y0, x1, y1, points) >= K:
            area = (x1 - x0) * (y1 - y0)
            minArea = min(minArea, area)
  return minArea

def splitToInt(line):
  words = line.strip().split()
  return [int(w) for w in words]

