import sys

inf = float('inf')

def calc_s(x: "List[int]", y: "List[int]"):
    return (max(x) - min(x)) * (max(y) - min(y))


def solve(N: int, K: int, x: "List[int]", y: "List[int]"):
    for i in range(N-K):
        s_min = inf
        todel = None
        for j in range(N-i):
            s_temp = calc_s(x[:j] + x[j+1:], y[:j] + y[j+1:])
            if s_temp < s_min:
                s_min = s_temp
                todel = j
        del x[todel]
        del y[todel]

    print(calc_s(x, y))
    return


