import itertools


def det_rect_area(n, k, points):
    area = float("inf")
    # 点の直積から2点選んで，それを長方形の対角とする
    xs = (p[0] for p in points)
    ys = (p[1] for p in points)
    all_points = itertools.product(xs, ys)
    for (x1, y1), (x2, y2) in itertools.combinations(all_points, 2):
        min_x, max_x = min(x1, x2), max(x1, x2)
        min_y, max_y = min(y1, y2), max(y1, y2)
        # その中にk個以上の点が入るか？
        num_inc_rects = 0
        for x, y in points:
            if min_x <= x <= max_x and min_y <= y <= max_y:
                num_inc_rects += 1
        if num_inc_rects >= k:
            area = min(area, (max_x - min_x) * (max_y - min_y))
    return area


def main():
    n, k = (int(x) for x in input().split())
    points = [tuple(int(x) for x in input().split()) for _ in range(n)]
    print(det_rect_area(n, k, points))


