    ans = (x_sorted[N - 1] - x_sorted[0]) * (y_sorted[N - 1] - y_sorted[0])

    # 全探索
    for xi in range(N):
        for xj in range(xi + 1, N):
            for yi in range(N):
                for yj in range(yi + 1, N):
                    num = 0
                    left = x_sorted[xi]
