import sys

def area(px,py):
  return (px[1]-px[0])*(py[1]-py[0])

def isInRect(x, px, py):
  return x[0]<=px[1] and x[0]>=px[0] and x[1]<=py[1] and x[1]>=py[0]

def searchMinArea(p, N, K):
  validAreas = []
  for pw in range(N-1):
    for pe in range(pw+1, N):
      for ps in range(N-1):
        for pn in range(ps+1, N):
          ppx = [p[pw][0], p[pe][0]]
          ppy = [p[ps][1], p[pn][1]]
          px = [min(ppx), max(ppx)]
          py = [min(ppy), max(ppy)]
          pInRect = [pid for pid in range(N) if isInRect(p[pid], px, py)]
          if len(pInRect)>=K:
            validAreas.append(area(px, py))
  return min(validAreas)


