import bisect as bs
from collections import namedtuple

Area = namedtuple('Area', ['xinf', 'xsup', 'yinf', 'ysup'])

def tuple_int(iterable):
    return tuple(map(int, iterable.split()))

def insert_xy(line):
    x, y = map(int, line.split())
    X.insert(bs.bisect_left(X,x), x)
    Y.insert(bs.bisect_left(Y,y), y)
    return X, Y

def S_with_K_plots(X, Y, K):
    result = []
    for x, y in product(combinations(X,2), combinations(Y,2)):
        area = Area(xinf=min(x),xsup=max(x),yinf=min(y),ysup=max(y))
        S = (area.xsup-area.xinf)*(area.ysup-area.yinf)
        if count_plots(area) == K:
            result.append(S)
    return result

def count_plots(area):
    is_in_the_area = lambda x: is_in_area(x, area)
    return sum(map(is_in_the_area, plots))

def is_in_area(plot, area):
    between = lambda a, b, c:True if b <= a <= c else False
    x, y = plot
    x1, x2, y1, y2 = area
    if between(x, x1, x2) and between(y, y1, y2):
        return 1
    else:
        return 0

