def d_axis_parallel_rectangle(N, K, P):
    x_array, y_array = [], []  # 点のx,y座標
    for x, y in P:
        x_array.append(x)
        y_array.append(y)

    x_array = sorted(x_array)
    y_array = sorted(y_array)

    # すべての点を内部に含む、最大の面積を持つ矩形が初期値
    ans = (x_array[N - 1] - x_array[0]) * (y_array[N - 1] - y_array[0])

    # 全探索
    for xi in range(N):
        for xj in range(xi + 1, N):
            for yi in range(N):
                for yj in range(yi + 1, N):
                    num = 0
                    left = x_array[xi]
                    right = x_array[xj]
                    bottom = y_array[yi]
                    top = y_array[yj]

                    for i in range(N):
                        if left <= x_array[i] and x_array[i] <= right and bottom <= y_array[i] and y_array[i] <= top:
                            num += 1
                            if num == K:
                                ans = min(ans, (right - left) * (top - bottom))
                                break
    return ans

