def acc2(grid):
    H = len(grid); W = len(grid[0])
    for i in range(H):
        for j in range(W-1):
            grid[i][j+1] += grid[i][j]
    for j in range(W):
        for i in range(H-1):
            grid[i+1][j] += grid[i][j]
    ngrid = [[0]*(W+1)]
    for i in range(H):
        line = [0] + grid[i]
        ngrid.append(line)
    return ngrid

