def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, K, XY):
    X = sorted(map(lambda x: x[0], XY))
    Y = sorted(map(lambda x: x[1], XY))

    ans = sys.maxsize
    for lx in X:
        for rx in X[::-1]:
            if lx > rx:
                break
            for by in Y:
                for ty in Y[::-1]:
                    if by > ty:
                        break

                    # print(lx, rx, by, ty)
                    k = 0
                    for x, y in XY:
                        if lx <= x <= rx and by <= y <= ty:
                            k += 1
                    # print(k)
                    if k >= K:
                        ans = min(ans, (rx-lx)*(ty-by))
                    else:
                        break

    return ans


