import heapq


class Rect:
    def __init__(self, xy):
        self.xy = set(xy)

    def excluded(self, p):
        return Rect((q for q in self.xy if q != p))


    def __lt__(self, other):
        return self.get_score() < other.get_score()

    def __len__(self):
        return len(self.xy)

    def get_x_max(self):
        return max(self.xy, key=lambda t: t[0])

    def get_x_min(self):
        return min(self.xy, key=lambda t: t[0])

    def get_y_max(self):
        return max(self.xy, key=lambda t: t[1])

    def get_y_min(self):
        return min(self.xy, key=lambda t: t[1])

    def get_score(self):
        return (self.get_x_max()[0] - self.get_x_min()[0]) * (self.get_y_max()[1] - self.get_y_min()[1])

    def __str__(self):
        return str(self.xy)



