def solve(N, K, XYs):
    ans = 10 ** 19 + 1
    Ys = [y for x, y in XYs]
    Xs = [x for x, y in XYs]
    for y1 in Ys:
        for y2 in Ys:
            if y1 >= y2:
                continue
            for x1 in Xs:
                for x2 in Xs:
                    if x1 >= x2:
                        continue
                    y1, y2 = min(y1, y2), max(y1, y2)
