from operator import itemgetter
import sys
def main(N, K, P):
    X = sorted(map(itemgetter(0), P))
    Y = sorted(map(itemgetter(1), P))
    Xd, Yd = dict(), dict()
    for i, (x, y) in enumerate(zip(X, Y)):
        Xd[x] = i
        Yd[y] = i

    C = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y in P:
        i, j = Xd[x] + 1, Yd[y] + 1
        C[i][j] += 1
    for i in range(1, N + 1):
        for j in range(N):
            C[i][j + 1] += C[i][j]
    for j in range(1, N + 1):
        for i in range(N):
            C[i + 1][j] += C[i][j]

