def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, M, XY):
    XY.sort(key=itemgetter(1))
    XY.sort()
    # print(XY)

    ans = INF
    for i, (x, y) in enumerate(XY):
        yl = [y]
        for j in range(i+1, N):
            x2, y2 = XY[j]
            yl.append(y2)
            if len(yl) >= M:
                yl.sort()
                ans = min(ans, (x2-x)*(yl[-1]-yl[0]))
                for k in range(M-len(yl)):
                    ans = min(ans, (x2-x)*(yl[k+M-1]-yl[k]))
    return ans


