import sys
from sys import stdin
input = stdin.readline


def solve(points, N, K):
    max_x = float('-inf')
    max_y = float('-inf')
    min_x = float('inf')
    min_y = float('inf')
    remove = N - K
    if remove == 0:
        for x, y in points:
            if x > max_x:
                max_x = x
            if x < min_x:
                min_x = x
            if y > max_y:
                max_y = y
            if y < min_y:
                min_y = y
        return (max_x - min_x) * (max_y - min_y)

    while remove:
        max_x = float('-inf')
        max_y = float('-inf')
        min_x = float('inf')
        min_y = float('inf')

        distance = [float('inf')] * len(points)
        for x, y in points:
            if x > max_x:
                max_x = x
            if x < min_x:
                min_x = x
            if y > max_y:
                max_y = y
            if y < min_y:
                min_y = y
        c_x = (max_x + min_x) / 2
        c_y = (max_y + min_y) / 2

        for i, (x, y) in enumerate(points):
            d = (x - c_x)**2 + (y - c_y)**2
            distance[i] = d

        max_d = max(distance)
        ind = distance.index(max_d)
        points.pop(ind)
        remove -= 1


    max_x = float('-inf')
    max_y = float('-inf')
    min_x = float('inf')
    min_y = float('inf')

    for x, y in points:
        if x > max_x:
            max_x = x
        if x < min_x:
            min_x = x
        if y > max_y:
            max_y = y
        if y < min_y:
            min_y = y

    return (max_x - min_x) * (max_y - min_y)



def main(args):
    N, K = map(int, input().split())
    points = []
    for _ in range(N):
        points.append([int(x) for x in input().split()])

    points.sort()
    #points.sort(key=lambda x: x[1])
    result = solve(points, N, K)
    print(result)







