import sys
from operator import itemgetter
input = sys.stdin.readline

def main():
  n, k = map(int, input().split())
  point = [[int(x) for x in input().split()] for _ in range(n)]
  point.sort()
  point = [[x[0], x[1], i] for i, x in enumerate(point)]
  point.sort(key=itemgetter(1))
  point = [[x[0], x[1], x[2], i] for i, x in enumerate(point)]

  count_sum = [[0]*(n+1) for _ in range(n+1)]
  for i in range(n):
    for j in range(n):
      count_sum[i+1][j+1] += count_sum[i+1][j]+count_sum[i][j+1]-count_sum[i][j]
      if point[i][2] == j:
        count_sum[i+1][j+1] += 1

  key_x = dict()
  key_y = dict()
  for i in range(n):
    a, b, c, d = point[i]
    key_x[a] = c+1
    key_y[b] = d+1

  ans = pow(10, 18)*4
  for a in range(n):
    for b in range(n):
      for c in range(n):
        for d in range(n):
          x, y = [point[a][0], point[b][0], point[c][0], point[d][0]], [point[a][1], point[b][1], point[c][1], point[d][1]]
          x1, x2, y1, y2 = min(x), max(x), min(y), max(y)
          i1, i2, j1, j2 = key_x[x1], key_x[x2], key_y[y1], key_y[y2]
          count = count_sum[i2][j2]-count_sum[i1-1][j2]-count_sum[i2][j1-1]+count_sum[i1-1][j1-1]
          if count < k:
            continue
          sub = (x2-x1)*(y2-y1)
          if ans > sub:
            ans = sub

  print(ans)


if __name__ == "__main__":
  main()

