#辺集合の生成する長方形の四辺を計算
def calc(edges):
        minX=INF
        minY=INF
        maxX=-INF
        maxY=-INF
        for edge in edges:
                if edge[0]<minX:
                        minX=edge[0]
                if edge[0]>maxX:
                        maxX=edge[0]
                if edge[1]<minY:
                        minY=edge[1]
                if edge[1]>maxY:
                        maxY=edge[1]
        return judge(minX,minY,maxX,maxY)


#辺集合を作って、計算に回す
def produceEdges(edges,last):
        #print(edges)
        #四辺が決まってたら、計算に回す
        if len(edges)==min(4,K):
                return calc(edges)
        #決まってないなら、辺集合を生成
        ans=INF
        for i in range(last,N):
                edges.append(xy[i])
                ans=min(ans,produceEdges(edges,i+1))
                edges.pop(-1)
        return ans

