def LI_(): return [int(x)-1 for x in input().split()]
def LF(): return [float(x) for x in input().split()]
def LS(): return input().split()

def resolve():
    N, K = LI()
    xy = [LI() for _ in range(N)]

    # x, y全ての重複あり組み合わせに対して含まれる点の個数を算出する

    x_cnt = collections.Counter([i[0] for i in xy])
    x_coordinate = list(x_cnt.keys())
    x_coordinate.sort()
    y_cnt = collections.Counter([i[1] for i in xy])
    y_coordinate = list(y_cnt.keys())
    y_coordinate.sort()

    ans = INF
    for x0, x1 in itertools.combinations_with_replacement(x_coordinate, 2):
        for y0, y1 in itertools.combinations_with_replacement(y_coordinate, 2):
            cnt = len([(i, j) for i, j in xy if x0 <= i <= x1 and y0 <= j <= y1])
            if cnt >= K:
                ans = min((x1 - x0) * (y1 - y0), ans)

    print(ans)

if __name__ == '__main__':
    resolve()

