import sys
INF = float("inf")


def solve(N: int, K: int, x: "List[int]", y: "List[int]"):
    sx = sorted(x)
    sy = sorted(y)

    m = INF
    for i, x1 in enumerate(sx):
        for j, y1 in enumerate(sy):
            # 始点を固定
            for x2 in sx[i:]:
                for y2 in sy[j:]:
                    # 終点を固定
                    counter = 0
                    for xx, yy in zip(x, y):
                        if (x1 <= xx <= x2) and (y1 <= yy <= y2):
                            counter += 1
                    if counter >= K:
                        area = abs((y2-y1)*(x2-x1))
                        if area < m:
                            m = area
    print(m)
    return


