    xy.sort_by(|a, b| (a.2).partial_cmp(&b.2).unwrap());
    let mut yaxis: Vec<i64> = vec![0; n + 1];
    for i in 0..n {
        xy[i].3 = i + 1;
        yaxis[i + 1] = xy[i].2;
