use std::io;

fn read_line() -> String {
    let mut s = String::new();
    io::stdin().read_line(&mut s).unwrap();
    s.trim().to_owned()
}

fn read_pair() -> (i64, i64) {
    let s = read_line();
    let mut it = s.split_whitespace().map(|s| s.parse().unwrap());
    let h = it.next().unwrap();
    let w = it.next().unwrap();
    (h, w)
}

fn main() {
    let (n, k) = read_pair();
    let ps: Vec<_> = (0..n).map(|_| read_pair()).collect();

    let mut ans = i64::max_value();

    let (mut xs, mut ys): (Vec<_>, Vec<_>) = ps.iter().cloned().unzip();
    xs.sort();
    ys.sort();

    for ix1 in 0..xs.len() {
        for ix2 in (ix1 + 1)..xs.len() {
            for iy1 in 0..ys.len() {
                for iy2 in (iy1 + 1)..ys.len() {
                    let x1 = xs[ix1];
                    let x2 = xs[ix2];
                    let y1 = ys[iy1];
                    let y2 = ys[iy2];

                    let mut cnt = 0;
                    for &(x, y) in ps.iter() {
                        if x1 <= x && x <= x2 && y1 <= y && y <= y2 {
                            cnt += 1;
                            if cnt >= k {
                                break;
                            }
                        }
                    }

                    if cnt >= k {
                        ans = std::cmp::min(ans, (x2 - x1) * (y2 - y1));
                    }
                }
            }
        }
    }

    println!("{}", ans);
}

