    let (x, y): (Vec<i32>, Vec<i32>) = (0..N).map(|_| (stdin.read::<i32>(), stdin.read::<i32>())).unzip();
    let mut acc = vec![vec![0_i32; N + 1]; N + 1];
    let mut xi: Vec<_> = (0..N).map(|i| (x[i], i)).collect();
    let mut yi: Vec<_> = (0..N).map(|i| (y[i], i)).collect();
    xi.sort();
    yi.sort();
    let mut rank_x = vec![0; N];
    let mut rank_y = vec![0; N];
    for i in 0..N {
        rank_x[xi[i].1] = i;
        rank_y[yi[i].1] = i;
    }
    for k in 0..N {
        let i = rank_x[k];
        let j = rank_y[k];
        acc[i + 1][j + 1] += 1;
    }
    for i in 0..N + 1 {
        for j in 0..N {
            acc[i][j + 1] += acc[i][j];
        }
    }
    for i in 0..N {
        for j in 0..N + 1 {
            acc[i + 1][j] += acc[i][j];
        }
    }
    let mut area_min = std::u64::MAX;
    for i1 in 0..N {
        for i2 in i1 + 1..N {
            for j1 in 0..N {
                for j2 in j1 + 1..N {
                    let count_interior = (acc[i2 + 1][j2 + 1] -acc[i2 + 1][j1] - acc[i1][j2 + 1] + acc[i1][j1]) as usize;
                    if count_interior >= K {
                        let area = (xi[i2].0 - xi[i1].0) as u64 * (yi[j2].0 - yi[j1].0) as u64;
                        area_min = std::cmp::min(area_min, area);
                    }
                }
            }
        }
    }
    println!("{}", area_min);
}

