  }
  let mut ans: u64 = std::u64::MAX;
  for &(_, up) in &v {
    for &(_, down) in &v {
      for &(left, _) in &v {
        for &(right, _) in &v {
          let mut tmp = 0;
          for &(i, j) in &v {
