}

fn count(i: i64, j: i64, side1: i64, side2: i64, top1: i64, top2: i64, count: &mut u64) {
  let left = min(side1, side2);
  let right = max(side1, side2);
  let down = min(top1, top2);
  let top = max(top1, top2);

  if left <= i && i <= right && down <= j && j <= top {
    *count += 1;
  }

}

use std::io;
use std::cmp;
use std::collections::BTreeSet;

// read a line(without line feed)
fn read_line() -> String {
    let mut in_str = String::new();
    io::stdin().read_line(&mut in_str).unwrap();
    return in_str.trim().to_string();
}

// read wods on a line
pub fn read_words_in_line() -> Vec<String> {
    let s = read_line();
    return s.split_whitespace().map(|x| x.to_string()).collect::<Vec<String>>()
}

// read type t on a line
pub fn read_t_in_line<T : std::str::FromStr>() -> Vec<T> {
    let mut v : Vec<T> = Vec::new();
    for e in read_words_in_line().iter().map(|x| x.parse::<T>()) {
        if let Ok(r) = e {
            v.push(r);
        }
        else{
            return Vec::new();
        }
    }
    return v;
}

// sort slice
pub fn sort<T : std::cmp::Ord>(slice : &mut [T]) {
    slice.sort();
}
// sort slice by reverse order
pub fn sort_rev<T : std::cmp::Ord>(slice : &mut [T]) {
    slice.sort_by(|x, y| y.cmp(x));
}

pub fn min<T : std::cmp::Ord>(a : T, b : T) -> T{
    return cmp::min(a, b);
}

pub fn max<T : std::cmp::Ord>(a : T, b : T) -> T{
    return cmp::max(a, b);
}


fn contain(minx : i32, miny : i32, maxx : i32, maxy : i32, tx : i32, ty : i32) -> bool {
    return minx <= tx && tx <= maxx && miny <= ty && ty <= maxy;
}

fn main() {

    let n_k = read_t_in_line::<i32>();
    let (n, k) = (n_k[0], n_k[1]);

    let mut xs = vec![];
    let mut ys = vec![];

    let mut x_set : BTreeSet<i32> = BTreeSet::new();
    let mut y_set : BTreeSet<i32> = BTreeSet::new();

    for _ in 0..n {
        let x_y = read_t_in_line::<i32>();
        xs.push(x_y[0]);
        ys.push(x_y[1]);
    }
    for i in 0..n {
        x_set.insert(xs[i as usize]);
        y_set.insert(ys[i as usize]);
    }

    let x_vec = x_set.iter().cloned().collect::<Vec<i32>>();
    let y_vec = y_set.iter().cloned().collect::<Vec<i32>>();

    let mut ans = i64::max_value();

    for i1 in 0..(x_vec.len()) {
        for j1 in i1..(x_vec.len()) {
            let minx = x_vec[i1];
            let maxx = x_vec[j1];
            for i2 in 0..(y_vec.len()) {
                for j2 in i2..(y_vec.len()) {
                    let miny = y_vec[i2];
                    let maxy = y_vec[j2];
                    let mut cnt = 0;
                    for m in 0..n {
                        let x = xs[m as usize];
                        let y = ys[m as usize];
                        if contain(minx, miny, maxx, maxy, x, y) {
                            cnt += 1;
                        }
                    }
                    if cnt >= k {
                        ans = min(ans, (maxx - minx) as i64 * (maxy - miny) as i64);
                    }
                }
            }

        }
    }

    println!("{}", ans);

}

