    size: usize,
    level: usize,
}
#[allow(dead_code)]
impl Wavelet {
    fn new(v: Vec<u64>) -> Wavelet {
        let size = v.len();
        let max = v.iter().fold(0u64, |x, y| u64::max(x, *y));
        let mut level = 0;
        let mut l = 1;
        while l <= max {
            level += 1;
            l <<= 1;
        }
        let mut data = Vec::with_capacity(level);
        for _ in 0..level {
            data.push(BitVector::new(size))
        }
        let mut res = Wavelet {
            data,
            zeros: vec![0; level],
            l_last: HashMap::new(),
            max,
            size,
            level,
        };
        res.build(v);
        res
    }
    fn build(&mut self, mut v: Vec<u64>) {
        for l in 0..self.level {
            let mut zeros = 0;
            let k = self.level - l - 1;
            for i in 0..self.size {
                let b = nth_bit(v[i], k);
                self.data[l].set(i, b);
                if b == 0 {
                    zeros += 1;
                }
            }
            self.data[l].build();
            self.zeros[l] = zeros;
            v.sort_by(|x, y| nth_bit(*x, k).cmp(&nth_bit(*y, k)));
        }
        self.l_last.insert(v[0], 0);
        for i in 1..v.len() {
            if v[i - 1] != v[i] {
                self.l_last.insert(v[i], i);
            }
        }
    }
    fn pos_bit(&self, l: usize, b: i16, i: usize) -> usize {
        if b == 0 {
            self.data[l].rank_bit(0, i) as usize
        } else {
            self.data[l].rank_bit(1, i) as usize + self.zeros[l]
        }
    }
    fn rev_bit(&self, l: usize, b: u16, i: usize) -> usize {
        if b == 0 {
            self.data[l].select(0, i as u64)
        } else {
            self.data[l].select(1, (i - self.zeros[l]) as u64)
        }
    }
    // self[i]
    fn access(&self, mut i: usize) -> u64 {
        let mut res = 0u64;
        for l in 0..self.level {
            let b = self.data[l].get(i);
            res = (res << 1) + b as u64;
            i = self.pos_bit(l, b as i16, i);
        }
        res
    }
    // Count of x in [0, i)
    fn rank(&self, mut i: usize, x: u64) -> usize {
        if self.l_last.get(&x).is_none() {
            return 0;
        }
        for l in 0..self.level {
            let b = nth_bit(x, self.level - l - 1);
            i = self.pos_bit(l, b as i16, i);
        }
        i - self.l_last.get(&x).unwrap()
    }
    // i == Count of x in [0, res)
    fn select(&self, i: usize, x: u64) -> usize {
        if i == 0 {
            return 0;
        }
        assert!(self.l_last.get(&x).is_some());
        assert!(i <= self.rank(self.size, x));
        let ls = self.l_last.get(&x).unwrap();
        let p = ls + i;
        self.rev_pos(p, x)
    }
    /// last pos and x -> first pos
    fn rev_pos(&self, mut p: usize, x: u64) -> usize {
        for l in (0..self.level).rev() {
            let b = nth_bit(x, self.level - l - 1);
            p = self.rev_bit(l, b, p);
        }
        p
    }
    // [l, r] -> [l0, r0) [l1, r1)
    fn split(&self, level: usize, l: usize, r: usize) -> (usize, usize, usize, usize) {
        let kr = self.data[level].rank(r) as usize;
        let kl = self.data[level].rank(l) as usize;
        let ones = kr - kl;
        let zeros = r - l - ones;
        let l0 = l - kl;
        let r0 = l0 + zeros;
        let l1 = self.zeros[level] + kl;
        let r1 = l1 + ones;
        (l0, r0, l1, r1)
    }
    // i-th number from smaller in [l, r)
    fn quantile_pred(&self, mut l: usize, mut r: usize, mut i: usize) -> (usize, u64) {
        assert!(l < r);
        assert!(i < r - l);
        let mut res = 0;
        for t in 0..self.level {
            let (l0, r0, l1, r1) = self.split(t, l, r);
            res <<= 1;
            if i < r0 - l0 {
                l = l0;
                r = r0;
            } else {
                l = l1;
                r = r1;
                res += 1;
                i -= r0 - l0;
            };
        }
        (l + i, res)
    }
    // i-th smaller [l, r)
    fn quantile(&self, l: usize, r: usize, i: usize) -> u64 {
        self.quantile_pred(l, r, i).1
    }
    // pos of i-th smaller [l, r)
    fn quantile_pos(&self, l: usize, r: usize, i: usize) -> usize {
        let (p, x) = self.quantile_pred(l, r, i);
        self.rev_pos(p + 1, x) - 1
    }
    /// top K increasing order -> smaller to larger
    fn topk(&self, l: usize, r: usize, i: usize) -> Vec<(u64, usize)> {
        use std::cmp::Ordering;
        #[derive(Copy, Clone, Eq, PartialEq)]
        struct State {
            l: usize,
            r: usize,
            level: usize,
            value: u64,
        }
        impl Ord for State {
            fn cmp(&self, other: &Self) -> Ordering {
                (self.r - self.l)
                    .cmp(&(other.r - other.l))
                    .then_with(|| other.level.cmp(&self.level))
                    .then_with(|| other.value.cmp(&self.value))
            }
        }
        impl PartialOrd for State {
            fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
                Some(self.cmp(other))
            }
        }
        let mut q = std::collections::BinaryHeap::new();
        q.push(State {
            l,
            r,
            level: 0,
            value: 0,
        });
        let mut res = vec![];
        while let Some(State { l, r, level, value }) = q.pop() {
            if level >= self.level {
                res.push((value, r - l));
                if res.len() >= i {
                    return res;
                }
                continue;
            }
            let (l0, r0, l1, r1) = self.split(level, l, r);
            if l0 < r0 {
                q.push(State {
                    l: l0,
                    r: r0,
                    level: level + 1,
                    value: value << 1,
                })
            }
            if l1 < r1 {
                q.push(State {
                    l: l1,
                    r: r1,
                    level: level + 1,
                    value: (value << 1) + 1,
                })
            }
        }
        res
    }
    // Sum [l, r)
    fn sum(&self, l: usize, r: usize) -> u64 {
        let top = self.topk(l, r, r - l);
        let mut res = 0;
        for (x, c) in top {
            res += x * c as u64;
        }
        res
    }
    // Intersect [l0, r0) [l1, r1) -> [(x, c0, c1)]
    fn intersect(&self, l0: usize, r0: usize, l1: usize, r1: usize) -> Vec<(u64, usize, usize)> {
        if r0 <= l0 || r1 <= l1 {
            return vec![];
        }
        let mut q = std::collections::VecDeque::new();
        q.push_back((l0, r0, l1, r1, 0, 0));
        let mut res = vec![];
        while let Some((l0, r0, l1, r1, level, value)) = q.pop_front() {
            if level >= self.level {
                res.push((value, r0 - l0, r1 - l1));
                continue;
            }
            let (l00, r00, l01, r01) = self.split(level, l0, r0);
            let (l10, r10, l11, r11) = self.split(level, l1, r1);
            if l00 < r00 && l10 < r10 {
                q.push_back((l00, r00, l10, r10, level + 1, value << 1));
            }
            if l01 < r01 && l11 < r11 {
                q.push_back((l01, r01, l11, r11, level + 1, (value << 1) + 1));
            }
        }
        res
    }
    /// x <= [l, r) < y
    fn range_freq(&self, l: usize, r: usize, x: u64, y: u64) -> usize {
        if y <= x {
            return 0;
        }
        let (xlt, _, _) = self.rank_all(l, r, x);
        let (_, _, yge) = self.rank_all(l, r, y - 1);
        r - l - xlt - yge
    }
    /// [l, r) -> (<x, =x, >x)
    fn rank_all(&self, mut l: usize, mut r: usize, x: u64) -> (usize, usize, usize) {
        if r <= l {
            return (0, 0, 0);
        }
        let mut lt = 0;
        let mut mt = 0;
        for t in 0..self.level {
            let b = nth_bit(x, self.level - t - 1);
            let (l0, r0, l1, r1) = self.split(t, l, r);
            if b == 0 {
                mt += r1 - l1;
                l = l0;
                r = r0;
            } else {
                lt += r0 - l0;
                l = l1;
                r = r1;
            }
        }
        (lt, r - l, mt)
    }
    /// max c in [l, r) if x <= c < y
    fn prev(&self, l: usize, r: usize, x: u64, y: u64) -> Option<u64> {
        self.prev_next(l, r, x, y, true)
    }
    /// min c in [l, r) if x <= c < y
    fn next(&self, l: usize, r: usize, x: u64, y: u64) -> Option<u64> {
        self.prev_next(l, r, x, y, false)
    }
    fn prev_next(&self, l: usize, r: usize, x: u64, mut y: u64, prev: bool) -> Option<u64> {
        if !(x < y && l < r && y > 0 && x <= self.max) {
            return None;
        }
        y -= 1;
        if y > self.max {
            y = self.max;
        }
        let mut s = vec![];
        s.push((l, r, 0, 0, true));
        while let Some((l, r, level, v, t)) = s.pop() {
            if level >= self.level {
                if v >= x {
                    return Some(v);
                }
                continue;
            }
            let b = nth_bit(y, self.level - level - 1);
            let (l0, r0, l1, r1) = self.split(level, l, r);
            // if !t, value goes to lower y
            if prev {
                if l0 < r0 {
                    s.push((l0, r0, level + 1, v << 1, t && b == 0))
                }
                if l1 < r1 {
                    // try from bigger
                    if !t || b == 1 {
                        s.push((l1, r1, level + 1, (v << 1) + 1, t))
                    }
                }
            } else {
                if l1 < r1 {
                    if !t || b == 1 {
                        s.push((l1, r1, level + 1, (v << 1) + 1, t))
                    }
                }
                if l0 < r0 {
                    // try from smaller
                    s.push((l0, r0, level + 1, v << 1, t && b == 0))
                }
            }
        }
        None
    }
}
