            wl,
            s2,
            s,
            pos: pos.iter().cloned().collect(),
        }
    }
    fn count(&self, y0: T, x0: T, y1: T, x1: T) -> usize {
        let l = self.s2.shrink_y(y0.clone());
        let r = self.s2.shrink_y(y1.clone());
        let x = self.s.shrink(x0.clone()) as u64;
        let y = self.s.shrink(x1.clone()) as u64;
        self.wl.range_freq(l, r, x, y)
    }
}

