use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n: usize = read();
    let k: usize = read();
    let mut xs = vec![0 as i64; n];
    let mut ys = vec![0 as i64; n];
    for i in 0..n {
        xs[i] = read();
        ys[i] = read();
    }
    let mut sorted_xs = xs.clone();
    let mut sorted_ys = ys.clone();
    sorted_xs.sort();
    sorted_ys.sort();
    let mut ans = 1i64 << 62;
    for yleft in 0..n {
        for yright in yleft + 1..n {
            for xleft in 0..n {
                for xright in xleft + 1..n {
                    let mut sum = 0;
                    for i in 0..n {
                        if sorted_xs[xleft] <= xs[i] && xs[i] <= sorted_xs[xright]
                            && sorted_ys[yleft] <= ys[i]
                            && ys[i] <= sorted_ys[yright]
                        {
                            sum += 1;
                        }
                    }
                    if sum == k {
                        let area = (sorted_xs[xright] - sorted_xs[xleft])
                            * (sorted_ys[yright] - sorted_ys[yleft]);
                        ans = std::cmp::min(ans, area);
                    }
                }
            }
        }
    }
    println!("{}", ans);
}

use std::cmp::{max, min};
