macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, k): (usize, usize) = parse!(it, 2);
    let p: Vec<(i64, i64)> = (0..n).map(|_| parse!(it, 2)).collect();
    let mut cands = vec![];
    for i in 0..n {
        for j in i..n {
            if k == 2 {
                cands.push(vec![p[i], p[j]]);
                continue;
            }
            for k in j..n {
                if k == 3 {
                    cands.push(vec![p[i], p[j], p[k]]);
                    continue;
                }
                for l in k..n {
                    cands.push(vec![p[i], p[j], p[k], p[l]])
                }
            }
        }
    }

    let mut ret = std::i64::MAX;
    for ps in cands {
        let l = ps.iter().min_by_key(|x| x.0).unwrap().0;
        let r = ps.iter().max_by_key(|x| x.0).unwrap().0;
        let u = ps.iter().max_by_key(|x| x.1).unwrap().1;
        let d = ps.iter().min_by_key(|x| x.1).unwrap().1;
        let s = (r - l) * (u - d);
        if p.iter()
            .filter(|&&(x, y)| l <= x && x <= r && d <= y && y <= u)
            .count()
            >= k
        {
            ret = min(s, ret)
        }
    }
    println!("{}", ret);
}

