}
#[allow(dead_code)]
impl<T: Clone + Debug + Ord> RectQuery<T> {
    fn new(pos: &[(T, T)]) -> RectQuery<T> {
        let s2 = Shrink2::new(pos);
        let xs: Vec<T> = pos.as_ref().iter().map(|(_, x)| x.clone()).collect();
        let s: Shrink<T> = Shrink::new(&xs[..]);
        let mut w = vec![0; pos.len()];
        for i in 0..s2.data.len() {
            let r = s.shrink(s2.data[i].1.clone()) as u64;
            w[i] = r;
        }
        let wl = Wavelet::new(w);
        RectQuery {
            wl,
            s2,
            s,
            pos: pos.iter().cloned().collect(),
        }
    }
    /// Count in [y0, y1) [x0, x1)
    fn count(&self, y0: T, x0: T, y1: T, x1: T) -> usize {
        let l = self.s2.shrink_y(y0);
        let r = self.s2.shrink_y(y1);
        let x = self.s.shrink(x0) as u64;
        let y = self.s.shrink(x1) as u64;
        self.wl.range_freq(l, r, x, y)
    }
    /// Count in [y0, y1], [x0, x1]
    fn count_in(&self, y0: T, x0: T, y1: T, x1: T) -> usize {
        //println!("{:?}", self.s2);
        //println!("{:?}", self.s);
        //println!("{:?},{:?} {:?},{:?}", y0, x0, y1, x1);
        let l = self.s2.shrink_y(y0);
        let r = self.s2.shrink_y_upper(y1);
        let x = self.s.shrink(x0) as u64;
        let y = self.s.shrink(x1) as u64 + 1;
        //println!("=> {}-{} {}=<{}", l, r, x, y);
        self.wl.range_freq(l, r, x, y)
    }
}

