#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}
#[allow(dead_code)]
#[derive(Clone, Debug)]
struct BitVector {
    l: Vec<u64>,
    s: Vec<u64>,
    b: Vec<u16>,
    n_ones: u64,
    size: usize,
    indexed: bool,
}
#[allow(dead_code)]
const BIT_L: usize = 512;
#[allow(dead_code)]
const BIT_S: usize = 16;
#[allow(dead_code)]
impl BitVector {
    fn new(size: usize) -> BitVector {
        let l_len = size / BIT_L + 1;
        let len = (size + BIT_S - 1) / BIT_S;
        BitVector {
            l: vec![0; l_len],
            s: vec![0; len + 1],
            b: vec![0; len],
            n_ones: 0,
            size,
            indexed: true,
        }
    }
    fn build(&mut self) {
        let mut n_ones: u64 = 0;
        for i in 0..self.s.len() {
            let l = (i * BIT_S) / BIT_L;
            if (i * BIT_S) % BIT_L == 0 {
                self.l[l] = n_ones;
            }
            self.s[i] = n_ones - self.l[l];
            if i < self.b.len() {
                n_ones += self.b[i].count_ones() as u64;
            }
        }
        self.n_ones = n_ones;
        self.indexed = true;
    }
    /// self[i]
    fn get(&self, i: usize) -> u16 {
        assert!(i < self.size);
        let (block, offset) = (i / BIT_S, i % BIT_S);
        (self.b[block] >> offset) & 1
    }
    /// self[i] = x
    fn set(&mut self, i: usize, x: u16) {
        assert!(i < self.size);
        assert!(x <= 1);
        let (block, offset) = (i / BIT_S, i % BIT_S);
        self.b[block] = if x == 1 {
            self.b[block] | (1 << offset)
        } else {
            self.b[block] & !(1 << offset)
        };
        self.indexed = false;
    }
    /// Count [0, i)
    fn rank(&self, i: usize) -> u64 {
        assert!(self.indexed);
        assert!(i <= self.size, "{} is out of bounds {}", i, self.size);
        let l = i / BIT_L;
        let s = i / BIT_S;
        let b = if i % BIT_S == 0 {
            0
        } else {
            (self.b[s] << BIT_S - (i % BIT_S)).count_ones()
        };
        self.l[l] + self.s[s] as u64 + b as u64
    }
    /// Count of x in [0, i)
    fn rank_bit(&self, x: u16, i: usize) -> u64 {
        assert!(x <= 1);
        if x == 1 {
            self.rank(i)
        } else {
            i as u64 - self.rank(i)
        }
    }
    /// Count of [0, select(x)) == x
    fn select(&self, b: u16, x: u64) -> usize {
        assert!(self.indexed);
        assert!(b <= 1);
        let negb = |b, c, l| if b == 1 { c } else { l as u64 - c };
        let c = if b == 1 {
            self.n_ones
        } else {
            self.size as u64 - self.n_ones
        };
        if c < x {
            return self.size + 1;
        }
        let mut l = 0;
        let mut r = self.l.len();
        while r - l > 1 {
            let m = (r + l) / 2;
            let c = negb(b, self.l[m], m * BIT_L);
            if c < x {
                l = m;
            } else {
                r = m;
            }
        }
        let li = l;
        let sub = x - negb(b, self.l[li], li * BIT_L);
        let mut l = li * BIT_L / BIT_S;
        let mut r = ((li + 1) * BIT_L / BIT_S).min(self.s.len());
        while r - l > 1 {
            let m = (r + l) / 2;
            let c = negb(b, self.s[m], (m * BIT_S) % BIT_L);
            if c < sub {
                l = m;
            } else {
                r = m;
            }
        }
        let si = l;
        let sub = sub - negb(b, self.s[si], (si * BIT_S) % BIT_L);
        for i in 0..=BIT_S {
            let bs = if i == 0 {
                0
            } else {
                (self.b[si] << BIT_S - i).count_ones()
            };
            let k = negb(b, bs as u64, i);
            if k == sub {
                return si * BIT_S + i;
            }
        }
        unreachable!();
    }
}
