struct Shrink<T: Clone + Debug + Ord> {
    data: Vec<T>,
}
#[allow(dead_code)]
impl<T: Clone + Debug + Ord> Shrink<T> {
    fn new(vals: &[T]) -> Shrink<T> {
        let set: std::collections::BTreeSet<T> = vals.into_iter().cloned().collect();
        Shrink {
            data: set.iter().cloned().collect(),
        }
    }
    fn shrink(&self, x: T) -> usize {
        if x > self.data[self.data.len() - 1] {
            return self.data.len();
        }
        if x <= self.data[0] {
            return 0;
        }
        let mut l = 0;
        let mut r = self.data.len();
        while r - l > 1 {
            let m = (r + l) / 2;
            if self.data[m] <= x {
                l = m
            } else {
                r = m
            }
        }
        l
    }
    fn orignal(&self, i: usize) -> T {
        self.data[i].clone()
    }
    fn size(&self) -> usize {
        self.data.len()
    }
}

