fn solve() {
    let (n,k) = get!(usize, usize);
    let xy = get!(isize, isize; n);
    let mut xv = Vec::with_capacity(n);
    let mut yv = Vec::with_capacity(n);

    for &(x,y) in &xy {
        xv.push(x);
        yv.push(y);
    }
    xv.sort();
    yv.sort();

    let mut mn = std::isize::MAX;
    for xi in 0..n {
        for xj in xi+1..n {
            for yi in 0..n {
                for yj in yi+1..n {
                    let xl = xv[xi];
                    let xr = xv[xj];
                    let yl = yv[yi];
                    let yr = yv[yj];
                    let mut count = 0;
                    for i in 0..n {
                        let (x,y) = xy[i];
                        if x >= xl && x <= xr && y >= yl && y <= yr {
                            count += 1;
                        }
                    }
                    if count >= k {
                        mn = min!(mn, (xr-xl)*(yr-yl));
                    }
                }
            }
        }
    }
    println!("{}", mn);

}

