use std::io::*;
use std::str::FromStr;

pub fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n: usize = read();
    let k: usize = read();
    let mut pv: Vec<(i64, i64)> = vec![];
    let mut minv = std::i64::MAX;

    for _ in 0..n {
        let x: i64 = read();
        let y: i64 = read();
        pv.push((x, y));
    }

    for u in 0..n {
        for d in 0..n {
            for r in 0..n {
                for l in 0..n {
                    let up = pv[u].1;
                    let down = pv[d].1;
                    let right = pv[r].0;
                    let left = pv[l].0;
                    if up <= down {
                        continue;
                    }
                    if right <= left {
                        continue;
                    }
                    let mut cnt = 0;
                    for i in 0..n {
                        let pi = pv[i];
                        if pi.1 <= up && pi.1 >= down && pi.0 <= right && pi.0 >= left {
                            cnt += 1;
                        }
                    }
                    if cnt >= k {
                        let sq = (up - down) * (right - left);
                        if sq < minv {
                            minv = sq;
                        }
                    }
                }
            }
        }
    }
    println!("{}", minv);
}

