#[derive(Debug, Clone)]
struct Shrink2<T: Clone + Debug + Ord> {
    data: Vec<(T, T)>,
    data_y: Vec<T>,
}
#[allow(dead_code)]
fn partition_point<T>(data: &[T], ok: &dyn Fn(&T) -> bool) -> usize {
    if !ok(&data[0]) {
        return 0;
    }
    if ok(&data[data.len() - 1]) {
        return data.len();
    }
    let mut l = 0;
    let mut r = data.len();
    while r - l > 1 {
        let m = (r + l) / 2;
        if ok(&data[m]) {
            l = m;
        } else {
            r = m;
        }
    }
    r
}
#[allow(dead_code)]
fn lower_bound<T: Ord>(data: &[T], x: T) -> usize {
    partition_point(data, &|y| y < &x)
}
#[allow(dead_code)]
fn upper_bound<T: Ord>(data: &[T], x: T) -> usize {
    partition_point(data, &|y| y <= &x)
}
#[allow(dead_code)]
impl<T: Clone + Debug + Ord> Shrink2<T> {
    fn new(vals: &[(T, T)]) -> Shrink2<T> {
        let mut x: Vec<(T, T)> = vals.iter().cloned().collect();
        x.sort();
        let ys = x.iter().cloned().map(|(y, _)| y).collect();
        Shrink2 {
            data: x,
            data_y: ys,
        }
    }
    fn shrink(&self, y: T, x: T) -> usize {
        lower_bound(&self.data, (y, x))
    }
    fn shrink_y(&self, y: T) -> usize {
        lower_bound(&self.data_y, y)
    }
    fn shrink_y_upper(&self, y: T) -> usize {
        upper_bound(&self.data_y, y)
    }
    fn orignal(&self, i: usize) -> (T, T) {
        self.data[i].clone()
    }
    fn size(&self) -> usize {
        self.data.len()
    }
}

