    let mut area_min = std::u64::MAX;
    for i1 in 0..N {
        for i2 in i1 + 1..N {
            for j1 in 0..N {
                for j2 in j1 + 1..N {
                    let x1 = std::cmp::min(x[i1], x[i2]);
                    let x2 = std::cmp::max(x[i1], x[i2]);
                    let y1 = std::cmp::min(y[j1], y[j2]);
