                    let count_interior = (0..N).filter(|&k| x1 <= x[k] && x[k] <= x2 && y1 <= y[k] && y[k] <= y2).count();
                    if count_interior >= K {
                        let area = (x2 - x1) as u64 * (y2 - y1) as u64;
