    let mut sorted_xs = xs.clone();
    let mut sorted_ys = ys.clone();
    sorted_xs.sort();
    sorted_ys.sort();
    let mut ans = 1i64 << 62;
    for yleft in 0..n {
        for yright in yleft + 1..n {
            let count_cnt = |xleft: usize, xright: usize| {
                let mut ret = 0;
                for i in 0..n {
                    if sorted_xs[xleft] <= xs[i] && xs[i] <= sorted_xs[xright]
