                if xright < n && count_cnt(xleft, xright) == k {
                    let area = (sorted_xs[xright] - sorted_xs[xleft])
                        * (sorted_ys[yright] - sorted_ys[yleft]);
                    ans = std::cmp::min(ans, area);
                }
                xright += 1;
            }
        }
