fn reads<T>() -> Vec<T>
    where
        T: std::str::FromStr,
        <T as std::str::FromStr>::Err: std::fmt::Debug {
    get_line().split(' ').map(|x| x.parse().unwrap()).collect()
}

fn main() {
    let nk = reads();

    let mut ps = vec![];
    for _ in 0..nk[0] {
        let xy: Vec<i64> = reads();

        ps.push((xy[0], xy[1]));
    }

    ps.sort_by(|lhs, rhs| {
        let res = lhs.0.cmp(&rhs.0);
        if res == std::cmp::Ordering::Equal {
            lhs.1.cmp(&rhs.1)
        }
        else {
            res
        }
    });

    let mut xi = 0;
    let mut xj = 0;
    let mut res = None;
    while ps.len() > xj && ps.len() > xi {
        if nk[1] > xj - xi + 1 {
            xj += 1;
        }
        else {
            let dx = ps[xj].0 - ps[xi].0;

            let mut h = ps[xi].1;
            let mut l = ps[xi].1;
            for i in xi..(xj + 1) {
                if ps[i].1 > h {
                    h = ps[i].1;
                }
                if l > ps[i].1 {
                    l = ps[i].1;
                }
            }

            let dy = h - l;
            let r = dy * dx;
            if let Some(v) = res {
                if v > r {
                    res = Some(r);
                }
            }
            else {
                res = Some(r);
            }

            xi += 1;
        }
    }

    println!("{}", res.unwrap());
}

