        .map(|_| {
            (
                itr.next().unwrap().parse().unwrap(),
                itr.next().unwrap().parse().unwrap(),
            )
        })
        .collect();

    let mut ans = 1i64 << 62;
    for i in 0..n {
        for j in 0..n {
            for k in 0..n {
                for l in 0..n {
                    let R = max(xy[i].0, max(xy[j].0, max(xy[k].0, xy[l].0)));
                    let L = min(xy[i].0, min(xy[j].0, min(xy[k].0, xy[l].0)));
                    let U = max(xy[i].1, max(xy[j].1, max(xy[k].1, xy[l].1)));
                    let D = min(xy[i].1, min(xy[j].1, min(xy[k].1, xy[l].1)));
                    let mut cnt = 0;

                    for a in 0..n {
                        if L <= xy[a].0 && xy[a].0 <= R && D <= xy[a].1 && xy[a].1 <= U {
                            cnt += 1;
                        }
                    }
                    if cnt >= K {
                        ans = min(ans, (R - L) * (U - D));
                    }
                }
            }
        }
    }
    println!("{}", ans);
}

