  let area = |xys: &[(i64,i64)]| {
    let dx = &xys.iter().map(|p|p.0).max().unwrap() - &xys.iter().map(|p|p.0).min().unwrap();
    let dy = &xys.iter().map(|p|p.1).max().unwrap() - &xys.iter().map(|p|p.1).min().unwrap();
    dx * dy
  };
  let ansx = xys.windows(k).map(area).min().unwrap();

  xys.sort_by(|p1,p2|p1.1.cmp(&p2.1));
  let area = |xys: &[(i64,i64)]| {
    let dx = &xys.iter().map(|p|p.0).max().unwrap() - &xys.iter().map(|p|p.0).min().unwrap();
    let dy = &xys.iter().map(|p|p.1).max().unwrap() - &xys.iter().map(|p|p.1).min().unwrap();
