use std::cmp::{min, max};

const INF: usize = 9999999999999999999;

fn proc_r(index: usize, v: &mut Vec<usize>, x: &Vec<usize>, y: &Vec<usize>, n: usize, k: usize) -> usize {
	if index >= n {
		if v.len() < k {
			return INF;
		}

		let mut xmin = INF;
		let mut xmax = 0;
		let mut ymin = INF;
		let mut ymax = 0;
		for i in 0..v.len() {
			xmin = min(xmin, x[v[i]]);
			xmax = max(xmax, x[v[i]]);
			ymin = min(ymin, y[v[i]]);
			ymax = max(ymax, y[v[i]]);
		}
		let ans = (xmax-xmin)*(ymax-ymin);
		if ans == 0 {
			return INF;
		}
		else {
			return ans;
		}
	}
	// 使う
	v.push(index);
	let ans1 = proc_r(index+1, v, x, y, n, k);
	v.pop();

	// 使わない
	let ans2 = proc_r(index+1, v, x, y, n, k);

	return min(ans1, ans2);
}

fn main() {
	input! {
		n: usize,
		k: usize,
		sxy: [(isize, isize); n],
	}

	let mut x = vec![0usize; n];
	let mut y = vec![0usize; n];
	for i in 0..n {
		x[i] = (sxy[i].0 + 1000000000) as usize;
		y[i] = (sxy[i].1 + 1000000000) as usize;
	}

	let mut v: Vec<usize> = vec![];
	let ans = proc_r(0, &mut v, &x, &y, n, k);
	println!("{}", ans);
}

