    let mut sort_v = Vec::new();
    for i in 0..v.len() {
        sort_v.push((v[i], i));
    }
    sort_v.sort();
    sort_v.iter().map(|x| x.1).collect::<Vec<usize>>()
}

fn main() {
    let v: Vec<usize> = read_vec();
    let (n, k) = (v[0], v[1]);
    let mut x = vec![0; n];
    let mut y = vec![0; n];

    for i in 0..n {
        let v = read_vec::<i64>();
        x[i] = v[0];
        y[i] = v[1];
    }
    let sorted_y_indexes = argsort(&y);

    let mut ans = std::i64::MAX;
    for i in 0..n {
        for j in i + 1..n {
            let mut i = i;
            let mut j = j;
            if x[i] > x[j] {
                std::mem::swap(&mut i, &mut j);
            }
            let x1 = x[i];
            let x2 = x[j];
            assert!(x1 <= x2);

            let mut usable_point_indexes = Vec::new();
            for l in 0..n {
                let idx3 = sorted_y_indexes[l];
                if x[idx3] >= x1 && x[idx3] <= x2 {
                    usable_point_indexes.push(idx3);
                }
            }
            assert!(usable_point_indexes.len() >= 2);
            if usable_point_indexes.len() < k {
                continue;
            }

            for l in 0..usable_point_indexes.len() - k + 1 {
                let y1 = y[usable_point_indexes[l]];
                let y2 = y[usable_point_indexes[l + k - 1]];
                ans = min(ans, (x2 - x1) * (y2 - y1));
            }
        }
    }
    println!("{}", ans);
}

