use std::cmp::{min, max};

fn main() {
    input!{
        n: usize,
        k: usize,
        v: [(i64, i64); n]
    }
    let (xs, ys): (Vec<i64>, Vec<i64>) = v.iter().cloned().unzip();
    let xsc = compress(&xs);
    let ysc = compress(&ys);
    let mut tab = vec![vec![0; n + 1]; n + 1];
    for i in 0..n {
        tab[xsc[i] + 1][ysc[i] + 1] += 1;
    }
    for i in 0..n {
        for j in 0..n {
            tab[i + 1][j + 1] += tab[i][j + 1] + tab[i + 1][j] - tab[i][j];
        }
    }
    let mut ans = i64::max_value();
    for i in 0..n {
        for j in i..n {
            for l in j..n {
                for m in l..n {
                    let t = vec![i, j, l, m];
                    let xl = t.iter().cloned().min_by_key(|&x| xs[x]).unwrap();
                    let yl = t.iter().cloned().min_by_key(|&x| ys[x]).unwrap();
                    let xr = t.iter().cloned().max_by_key(|&x| xs[x]).unwrap();
                    let yr = t.iter().cloned().max_by_key(|&x| ys[x]).unwrap();
                    if tab[xsc[xr] + 1][ysc[yr] + 1] + tab[xsc[xl]][ysc[yl]] - tab[xsc[xr] + 1][ysc[yl]] - tab[xsc[xl]][ysc[yr] + 1] < k {
                        continue;
                    }
                    ans = min(ans, (xs[xr] - xs[xl]) * (ys[yr] - ys[yl]));
                }
            }
        }
    }
    println!("{}", ans);
}

fn compress(v: &Vec<i64>) -> Vec<usize> {
    let mut w = v.clone();
    w.sort();
    let mut ret: Vec<usize> = vec![0; v.len()];
    for i in 0..v.len() {
        let mut l = 0;
        let mut r = w.len();
        while l + 1 < r {
            let m = (l + r) / 2;
            if w[m] > v[i] {
                r = m;
            } else {
                l = m;
            }
        }
        ret[i] = l;
    }
    ret
}

