fn solve(k: usize, xys: Vec<(i64, i64)>) -> i64 {
    use std::cmp::{min, max};

    let xs = xys.iter().map(|&(x,y)| x).collect::<Vec<i64>>();
    let ys = xys.iter().map(|&(x,y)| y).collect::<Vec<i64>>();

    let mut min_area = std::i64::MAX;

    for &x1 in xs.iter() {
        for &x2 in xs.iter() {
            for &y1 in ys.iter() {
                for &y2 in ys.iter() {
                    let xmin = min(x1, x2);
                    let xmax = max(x1, x2);
                    let ymin = min(y1, y2);
                    let ymax = max(y1, y2);

                    let cnt = xys.iter().filter(|&&(x, y)|
                                                xmin <= x && x <= xmax &&
                                                ymin <= y && y <= ymax
                    ).count();

                    if cnt >= k {
                        let area = (xmax - xmin) * (ymax - ymin);
                        if area < min_area {
                            min_area = area;
                        }
                    }
                }
            }
        }
    }

    min_area
}

