    for _ in 0..n {
        let coordinate = input!(i64, i64);
        loc.push(coordinate);
    }

    let mut min_area = std::i64::MAX;
    for x1 in 0..n {
        for x2 in (x1 + 1)..n {
            for y1 in 0..n {
                for y2 in (y1 + 1)..n {
                    let mut count = 0;
                    let x_min = if loc[x1].0 < loc[x2].0 {
                        loc[x1].0
                    } else {
