fn main() {
    input! {
        n: usize, k: usize,
        p: [(i64, i64); n]
    };
    let mut best = INF;

    for i in 0..n {
        for j in i+1..n {
            let left = min(p[i].0, p[j].0);
            let right = max(p[i].0, p[j].0);

            let mut inside_points = p.iter().cloned().filter(|p| left <= p.0 && p.0 <= right).collect::<Vec<_>>();
            inside_points.sort_by_key(|&p| p.1);
            let m = inside_points.len();
            if m < k {
                continue;
            }

            for lw in 0..=m-k {
                let left = inside_points[lw..lw+k].iter().fold(INF, |acc, x| min(acc, x.0));
                let right = inside_points[lw..lw+k].iter().fold(-INF, |acc, x| max(acc, x.0));
                let bottom = inside_points[lw].1;
                let top = inside_points[lw+k-1].1;
                best = min(best, (top-bottom)*(right-left));
            }
        }
    }
    println!("{}", best);
}

