    for max_x_k in 0..K+1 {
        for max_y_k in 0..K+1-max_x_k {
            for min_x_k in 0..K+1-max_x_k-max_y_k {
                let min_y_k = K - max_x_k - max_y_k - min_x_k;
                let mut candidates = positions.clone();
                candidates.sort_by(|pre, next| next.0.cmp(&pre.0));
