#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        K: i64,
        xy: [(i64,i64);n],
    }
    let mut x = vec![];
    let mut y = vec![];

    for i in 0..n{
        x.push(xy[i].0);
        y.push(xy[i].1);
    }
    x.sort();
    y.sort();
    let mut ans:i64 = (x[n-1] - x[0])*(y[n-1] - y[0]);
    for i in 0..n {
        for j in 0..n {
            for k in 0..n {
                for l in 0..n {
                    if i==j || k==l {
                        continue;
                    }
                    let x1:i64 = x[i];
                    let x2:i64 = x[j];
                    let y1:i64 = y[k];
                    let y2:i64 = y[l];
                    let mut dot:i64 = 0;
                    for m in 0..n {
                        if x1 <= xy[m].0 && xy[m].0 <= x2 && y1 <= xy[m].1 && xy[m].1 <=y2 {
                            dot+=1;
                        }
                    }
                    if dot >= K {
                        ans = std::cmp::min(ans, (x2-x1)*(y2-y1));
                    }
                }
            }   
        }
    }
    println!("{}", ans);
}

