fn main() {
    input! {
       n: usize,
       k: usize,
       mut point : [(i64,i64);n],
    }

    let mut ans = i64::max_value();

    let mut p = vec![];
    for i in 0..n {
        p.push((point[i].0, point[i].1, i));
    }

    let mut to_x = vec![(0, 0); n];
    let mut to_y = vec![(0, 0); n];

    p.sort_by_key(|x| x.0);
    for i in 0..n {
        to_x[i] = (p[i].0, p[i].2);
    }
    p.sort_by_key(|x| x.1);
    for i in 0..n {
        to_y[i] = (p[i].1, p[i].2);
    }

    p.sort_by_key(|x| x.2);

    let mut b = 0;
    let mut t = 0;
    while b < n {
        t = b + k - 1;
        while t < n {
            let x1 = p[to_x[b].1].0;
            let x2 = p[to_x[t].1].0;
            let mut tmp = vec![];
            for i in b..t + 1 {
                tmp.push(p[to_x[i].1].1);
            }
            mydbg!(tmp);
            let y1 = tmp.iter().min().unwrap();
            let y2 = tmp.iter().max().unwrap();

            mydbg!(x1, x2, y1, y2, (x2 - x1).abs(), (y2 - y1).abs());
            ans = min(ans, (x2 - x1).abs() * (y2 - y1).abs());
            t += 1;
        }
        b += 1;
    }

    while b < n {
        t = b + k - 1;
        while t < n {
            let y1 = p[to_y[b].1].1;
            let y2 = p[to_y[t].1].1;
            let mut tmp = vec![];
            for i in b..t + 1 {
                tmp.push(p[to_y[i].1].0);
            }
            mydbg!(tmp);
            let x1 = tmp.iter().min().unwrap();
            let x2 = tmp.iter().max().unwrap();

            mydbg!(x1, x2, y1, y2, (x2 - x1).abs(), (y2 - y1).abs());
            ans = min(ans, (x2 - x1).abs() * (y2 - y1).abs());
            t += 1;
        }
        b += 1;
    }

    println!("{}", ans);
}

