fn main() {
   input! {
      n: usize,
      k: usize,
      _xy: [(i64, i64); n],
   }
   let mut xy = _xy;
   xy.sort();
   let mut ans = 4e18 as i64;
   for i in 0..n - 1 {
      for j in i + k - 1..n {
         let w = xy[j].0 - xy[i].0;
         let mut ys = vec![];
         for l in i..j + 1 {
            ys.push(xy[l].1);
         }
         let p = j - i + 1;
         ys.sort();
         for l in 0..p - k + 1 {
            let h = ys[l + k - 1] - ys[l];
            ans = std::cmp::min(ans, w * h);
         }
      }
   }
   println!("{}", ans);
}

/// Equivalent to std::lowerbound and std::upperbound in c++
pub trait BinarySearch<T> {
   fn lower_bound(&self, x: &T) -> usize;
   fn upper_bound(&self, x: &T) -> usize;
}
#[allow(dead_code)]
impl<T: Ord> BinarySearch<T> for [T] {
   fn lower_bound(&self, x: &T) -> usize {
      let mut low = 0;
      let mut high = self.len();
      while low != high {
         let mid = (low + high) / 2;
         match self[mid].cmp(x) {
            std::cmp::Ordering::Less => {
               low = mid + 1;
            }
            std::cmp::Ordering::Equal | std::cmp::Ordering::Greater => {
               high = mid;
            }
         }
      }
      low
   }
   fn upper_bound(&self, x: &T) -> usize {
      let mut low = 0;
      let mut high = self.len();
      while low != high {
         let mid = (low + high) / 2;
         match self[mid].cmp(x) {
            std::cmp::Ordering::Less | std::cmp::Ordering::Equal => {
               low = mid + 1;
            }
            std::cmp::Ordering::Greater => {
               high = mid;
            }
         }
      }
      low
   }
}

